const WHATSAPP_QR_MAX_AGE_MS = Math.max(
  Number(process.env.WHATSAPP_QR_MAX_AGE_MS || 60_000),
  30_000,
);

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return !!value && typeof value === "object" && !Array.isArray(value);
}

function parseTimestampMs(value: unknown): number | null {
  if (value instanceof Date) {
    const time = value.getTime();
    return Number.isFinite(time) ? time : null;
  }
  if (typeof value !== "string" || !value.trim()) {
    return null;
  }
  const time = Date.parse(value);
  return Number.isFinite(time) ? time : null;
}

function getConnectionQrCodeGeneratedAt(connection: Pick<ConnectionRow, "sessionData">): string | null {
  const sessionData = connection.sessionData;
  if (!isPlainObject(sessionData)) return null;
  const runtimeDiagnostics = sessionData.runtimeDiagnostics;
  if (!isPlainObject(runtimeDiagnostics)) return null;
  const lastQrCode = runtimeDiagnostics.lastQrCode;
  if (isPlainObject(lastQrCode) && typeof lastQrCode.at === "string" && lastQrCode.at.trim()) {
    return lastQrCode.at.trim();
  }
  return null;
}

function isFreshQrCode(qrCode: string | null | undefined, generatedAt: unknown): boolean {
  if (!qrCode) return false;
  const generatedAtMs = parseTimestampMs(generatedAt);
  if (generatedAtMs === null) return false;
  return Date.now() - generatedAtMs < WHATSAPP_QR_MAX_AGE_MS;
}

function getVisibleGatewayQrGeneratedAt(
  status: GatewayStatus | null | undefined,
  fallbackGeneratedAt: string | Date | null = null,
): string | Date | null {
  const qrCode = status?.qrCode || null;
  if (!qrCode) return null;
  const generatedAt = status?.qrCodeGeneratedAt || fallbackGeneratedAt;
  return isFreshQrCode(qrCode, generatedAt) ? generatedAt : null;
}

function getVisibleGatewayQrCode(
  status: GatewayStatus | null | undefined,
  fallbackGeneratedAt: string | Date | null = null,
): string | null {
  const qrCode = status?.qrCode || null;
  if (!qrCode) return null;
  return getVisibleGatewayQrGeneratedAt(status, fallbackGeneratedAt) ? qrCode : null;
}

function getVisiblePersistedQrGeneratedAt(connection: Pick<ConnectionRow, "qrCode" | "sessionData" | "updatedAt">): string | Date | null {
  if (!connection.qrCode) return null;
  return getConnectionQrCodeGeneratedAt(connection) || connection.updatedAt || null;
}

function getVisiblePersistedQrCode(connection: Pick<ConnectionRow, "qrCode" | "sessionData" | "updatedAt">): string | null {
  const generatedAt = getVisiblePersistedQrGeneratedAt(connection);
  return isFreshQrCode(connection.qrCode, generatedAt) ? connection.qrCode : null;
}

const HARD_GATEWAY_DISCONNECTED_PROVIDER_STATUSES = new Set([
  "auth_failed",
  "close",
  "closed",
  "deleted",
  "disconnected",
  "invalid_session",
  "logged_out",
  "logout",
  "not_connected",
  "pairing_required",
  "qr_required",
  "removed",
]);

function normalizeGatewayVisibleStatus(value?: string | null): string {
  return String(value || "").trim().toLowerCase();
}

function isBaileysGatewayConnectionForVisibleStatus(connection: Pick<ConnectionRow, "provider" | "connectionMethod">): boolean {
  const provider = normalizeGatewayVisibleStatus(connection.provider || "baileys");
  const method = normalizeGatewayVisibleStatus(connection.connectionMethod || "qr");
  return provider === "baileys" && method !== "coexistence";
}

function persistedGatewayConnectionLooksConnectedForVisibleStatus(connection: Pick<ConnectionRow, "provider" | "connectionMethod" | "isConnected" | "providerStatus">): boolean {
  if (!isBaileysGatewayConnectionForVisibleStatus(connection)) {
    return false;
  }

  return connection.isConnected === true;
}

function gatewayStatusLooksConnectedForVisibleStatus(status?: GatewayStatus | null): boolean {
  if (!status) {
    return false;
  }

  return status.isConnected === true;
}

function gatewayStatusLooksHardDisconnectedForVisibleStatus(status?: GatewayStatus | null): boolean {
  if (!status) {
    return false;
  }

  if (status.qrCode) {
    return true;
  }

  return HARD_GATEWAY_DISCONNECTED_PROVIDER_STATUSES.has(
    normalizeGatewayVisibleStatus(status.providerStatus),
  );
}

function shouldHoldGatewayConnectionAsRecoveringForVisibleStatus(
  connection: Pick<ConnectionRow, "provider" | "connectionMethod" | "isConnected" | "providerStatus">,
  status?: GatewayStatus | null,
): boolean {
  if (!status || gatewayStatusLooksConnectedForVisibleStatus(status)) {
    return false;
  }

  const normalizedProviderStatus = normalizeGatewayVisibleStatus(status.providerStatus);
  if (
    normalizedProviderStatus === "recovering" ||
    normalizedProviderStatus === "reconnecting" ||
    normalizedProviderStatus === "connecting"
  ) {
    return isBaileysGatewayConnectionForVisibleStatus(connection);
  }

  if (!persistedGatewayConnectionLooksConnectedForVisibleStatus(connection)) {
    return false;
  }

  return !gatewayStatusLooksHardDisconnectedForVisibleStatus(status);
}

