let pool: Pool | null = null;
let activeDbOperations = 0;
const pendingDbOperations: Array<() => void> = [];

type DbQueueRelease = () => void;

function getEnvInt(name: string, fallback: number, minimum = 0) {
  const raw = Number.parseInt(String(process.env[name] || ""), 10);
  if (!Number.isFinite(raw)) return fallback;
  return Math.max(minimum, raw);
}

function getDbQueueMaxConcurrency() {
  return getEnvInt("PG_QUEUE_MAX_CONCURRENCY", 8, 1);
}

function getDbQueueMaxPending() {
  return getEnvInt("PG_QUEUE_MAX_PENDING", 500, 0);
}

function getDbQueueMaxWaitMs() {
  return getEnvInt("PG_QUEUE_MAX_WAIT_MS", 60000, 250);
}

function createDbQueueError(code: "DB_QUEUE_TIMEOUT" | "DB_QUEUE_OVERLOADED", message: string) {
  const error = new Error(message) as Error & { code?: string };
  error.code = code;
  return error;
}

function releaseDbOperationSlot() {
  activeDbOperations = Math.max(0, activeDbOperations - 1);
  const next = pendingDbOperations.shift();
  if (next) {
    next();
  }
}

function acquireDbOperationSlot(label: string): Promise<DbQueueRelease> {
  const maxConcurrency = getDbQueueMaxConcurrency();
  if (activeDbOperations < maxConcurrency) {
    activeDbOperations += 1;
    return Promise.resolve(releaseDbOperationSlot);
  }

  const maxPending = getDbQueueMaxPending();
  if (pendingDbOperations.length >= maxPending) {
    return Promise.reject(
      createDbQueueError(
        "DB_QUEUE_OVERLOADED",
        `database local queue overloaded before ${label}: active=${activeDbOperations} pending=${pendingDbOperations.length}`,
      ),
    );
  }

  return new Promise((resolve, reject) => {
    let settled = false;
    const start = () => {
      if (settled) return;
      settled = true;
      clearTimeout(timeout);
      activeDbOperations += 1;
      resolve(releaseDbOperationSlot);
    };
    const timeout = setTimeout(() => {
      if (settled) return;
      settled = true;
      const index = pendingDbOperations.indexOf(start);
      if (index >= 0) {
        pendingDbOperations.splice(index, 1);
      }
      reject(
        createDbQueueError(
          "DB_QUEUE_TIMEOUT",
          `database local queue timeout before ${label}: active=${activeDbOperations} pending=${pendingDbOperations.length}`,
        ),
      );
    }, getDbQueueMaxWaitMs());

    pendingDbOperations.push(start);
  });
}

function getDatabaseUrl() {
  const rawDbUrl = process.env.DATABASE_URL || "";
  const directDbUrl = process.env.DATABASE_URL_DIRECT || "";
  let dbUrl = rawDbUrl || directDbUrl;

  if (dbUrl.includes("pooler.supabase.com") && dbUrl.includes(":5432")) {
    dbUrl = dbUrl.replace(":5432", ":6543");
  }

  return dbUrl;
}

function isPgConnectionAcquireTimeout(error: unknown) {
  const message = error instanceof Error ? error.message : String(error || "");
  const code = typeof error === "object" && error ? String((error as any).code || "") : "";
  return (
    /timeout exceeded when trying to connect|max client connections reached|remaining connection slots are reserved|database local queue/i.test(message) ||
    code === "DB_QUEUE_TIMEOUT" ||
    code === "DB_QUEUE_OVERLOADED" ||
    (code === "XX000" && /client connections/i.test(message))
  );
}

function installPoolQueryRetry(targetPool: Pool) {
  const originalQuery = targetPool.query.bind(targetPool) as (...args: any[]) => Promise<unknown>;
  const maxAttempts = Math.max(1, Number.parseInt(process.env.PG_QUERY_RETRY_ATTEMPTS || "5", 10) || 5);
  const baseDelayMs = Math.max(0, Number.parseInt(process.env.PG_QUERY_RETRY_DELAY_MS || "500", 10) || 500);

  (targetPool as any).query = async (...args: any[]) => {
    if (typeof args[args.length - 1] === "function") {
      return originalQuery(...args);
    }

    let lastError: unknown;
    for (let attempt = 1; attempt <= maxAttempts; attempt++) {
      let releaseSlot: DbQueueRelease | null = null;
      try {
        releaseSlot = await acquireDbOperationSlot("pool.query");
        return await originalQuery(...args);
      } catch (error) {
        lastError = error;
        if (!isPgConnectionAcquireTimeout(error) || attempt >= maxAttempts) {
          throw error;
        }
        await wait(baseDelayMs * attempt);
      } finally {
        releaseSlot?.();
      }
    }
    throw lastError;
  };
}

function getPool() {
  if (!pool) {
    const connectionString = getDatabaseUrl();
    if (!connectionString) {
      throw new Error("DATABASE_URL is not configured.");
    }

    pool = new Pool({
      connectionString,
      ssl: { rejectUnauthorized: false },
      max: Number.parseInt(process.env.PG_POOL_MAX || "2", 10) || 2,
      min: 0,
      idleTimeoutMillis: Number.parseInt(process.env.PG_IDLE_TIMEOUT_MS || "10000", 10) || 10_000,
      connectionTimeoutMillis: Number.parseInt(process.env.PG_CONNECTION_TIMEOUT_MS || "8000", 10) || 8_000,
      statement_timeout: 30_000,
      allowExitOnIdle: true,
    });
    installPoolQueryRetry(pool);
  }

  return pool;
}

function getSupabaseAdminClient() {
  const supabaseUrl = (process.env.SUPABASE_URL || process.env.VITE_SUPABASE_URL || "").trim();
  const supabaseServiceKey =
    (process.env.SUPABASE_SERVICE_ROLE_KEY || process.env.SUPABASE_SERVICE_KEY || "").trim();

  if (!supabaseUrl || !supabaseServiceKey) {
    throw new Error("Supabase server credentials are not configured.");
  }

  return createClient(supabaseUrl, supabaseServiceKey);
}

function getSupabaseServerCredentials() {
  const supabaseUrl = (process.env.SUPABASE_URL || process.env.VITE_SUPABASE_URL || "").trim().replace(/\/+$/, "");
  const supabaseServiceKey =
    (process.env.SUPABASE_SERVICE_ROLE_KEY || process.env.SUPABASE_SERVICE_KEY || "").trim();
  if (!supabaseUrl || !supabaseServiceKey) {
    throw new Error("Supabase server credentials are not configured.");
  }
  return { supabaseUrl, supabaseServiceKey };
}

const passwordResetAttempts = new Map<string, number>();

function getPublicAppUrl() {
  return String(
    process.env.PUBLIC_BASE_URL ||
      process.env.VITE_PUBLIC_APP_URL ||
      process.env.APP_URL ||
      process.env.BASE_URL ||
      "https://agentezap.online",
  ).replace(/\/+$/, "");
}

function normalizeResetEmail(value: unknown) {
  return String(value || "").trim().toLowerCase();
}

function isValidResetEmail(value: string) {
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value);
}

function getRequestIp(req: any) {
  const forwarded = String(req.headers["x-forwarded-for"] || "");
  return (forwarded.split(",")[0] || String(req.socket?.remoteAddress || "") || "unknown").trim();
}

function shouldThrottlePasswordReset(req: any, email: string) {
  const key = `${getRequestIp(req)}:${email}`;
  const now = Date.now();
  const previous = passwordResetAttempts.get(key) || 0;
  passwordResetAttempts.set(key, now);
  return now - previous < 60_000;
}

async function sendPasswordResetEmailWithResend(email: string, resetUrl: string) {
  const apiKey = String(process.env.RESEND_API_KEY || process.env.AUTH_RESEND_API_KEY || "").trim();
  if (!apiKey) {
    throw new Error("RESEND_API_KEY is not configured.");
  }

  const html = `<h2>Redefinir senha do AgenteZap</h2>

<p>Olá,</p>

<p>Recebemos uma solicitação para redefinir a senha da sua conta AgenteZap.</p>

<p><a href="${resetUrl}">Redefinir minha senha</a></p>

<p>Se você não pediu isso, ignore este email.</p>

<p>Equipe AgenteZap</p>`;

  const text = `Redefinir senha do AgenteZap

Olá,

Recebemos uma solicitação para redefinir a senha da sua conta AgenteZap.

Redefinir minha senha: ${resetUrl}

Se você não pediu isso, ignore este email.

Equipe AgenteZap`;

  const response = await fetch("https://api.resend.com/emails", {
    method: "POST",
    headers: {
      Authorization: `Bearer ${apiKey}`,
      "Content-Type": "application/json; charset=utf-8",
    },
    body: JSON.stringify({
      from: "AgenteZap <no-reply@auth.agentezap.online>",
      to: [email],
      subject: "Redefina sua senha do AgenteZap",
      html,
      text,
    }),
  });

  if (!response.ok) {
    const detail = await response.text().catch(() => "");
    throw new Error(`Resend password reset failed: ${response.status} ${detail.slice(0, 300)}`);
  }
}

async function handlePasswordResetRequest(req: any, res: any) {
  if (req.method !== "POST") {
    return sendJson(res, 405, { message: "Method not allowed" });
  }

  const body = await readJsonBody(req);
  const email = normalizeResetEmail(body.email);

  if (!isValidResetEmail(email)) {
    return sendJson(res, 400, { message: "Informe um email valido." });
  }

  if (shouldThrottlePasswordReset(req, email)) {
    return sendJson(res, 200, { ok: true });
  }

  try {
    const appUrl = getPublicAppUrl();
    const supabase = getSupabaseAdminClient();
    const { data, error } = await supabase.auth.admin.generateLink({
      type: "recovery",
      email,
      options: {
        redirectTo: `${appUrl}/redefinir-senha`,
      },
    });

    if (error) {
      console.warn("[password-reset] Supabase recovery link not generated:", error.message);
      return sendJson(res, 200, { ok: true });
    }

    const tokenHash = data?.properties?.hashed_token;
    if (!tokenHash) {
      console.warn("[password-reset] Supabase recovery link missing hashed token");
      return sendJson(res, 200, { ok: true });
    }

    const resetUrl = `${appUrl}/redefinir-senha?token_hash=${encodeURIComponent(tokenHash)}&type=recovery`;
    await sendPasswordResetEmailWithResend(email, resetUrl);
  } catch (error) {
    console.error("[password-reset] failed:", error);
  }

  return sendJson(res, 200, { ok: true });
}

