function getGatewayBaseUrl() {
  const explicitUrl = String(process.env.WA_GATEWAY_URL || "").trim();
  if (!explicitUrl && isMonolithRuntime()) {
    throw new Error("WA gateway client is disabled in monolith runtime");
  }
  const rawUrl = (explicitUrl || DEFAULT_GATEWAY_URL).trim().replace(/\/+$/, "");
  if (/^https:\/\/gateway\.agentezap\.online$/i.test(rawUrl)) {
    return `${rawUrl}/gateway`;
  }
  return rawUrl;
}

function getGatewayInternalToken() {
  return (process.env.WA_GATEWAY_INTERNAL_TOKEN || DEFAULT_GATEWAY_INTERNAL_TOKEN).trim();
}

function getGatewayRequestTimeoutMs() {
  const parsed = Number(process.env.WA_GATEWAY_REQUEST_TIMEOUT_MS || "");
  if (!Number.isFinite(parsed) || parsed <= 0) {
    return DEFAULT_GATEWAY_REQUEST_TIMEOUT_MS;
  }

  return Math.max(1_000, Math.floor(parsed));
}

function getGatewayStatusTimeoutMs() {
  return getEnvInt("WA_GATEWAY_STATUS_TIMEOUT_MS", 2500, 500);
}

function getGatewayFollowupStatusTimeoutMs() {
  return getEnvInt("WA_GATEWAY_FOLLOWUP_STATUS_TIMEOUT_MS", 10000, 2500);
}

function getGatewayPresenceTimeoutMs() {
  return getEnvInt("WA_GATEWAY_PRESENCE_TIMEOUT_MS", 2500, 500);
}

async function requestGateway<T>(
  method: string,
  path: string,
  body?: unknown,
  extraHeaders?: Record<string, string>,
  timeoutOverrideMs?: number,
): Promise<T> {
  const timeoutMs = timeoutOverrideMs ?? getGatewayRequestTimeoutMs();
  const controller = new AbortController();
  const timeoutHandle = setTimeout(() => controller.abort(), timeoutMs);

  let response: Response;
  let text = "";
  const gatewayUrl = `${getGatewayBaseUrl()}${path}`;

  try {
    response = await fetch(gatewayUrl, {
      method,
      headers: {
        "content-type": "application/json",
        "x-wa-gateway-token": getGatewayInternalToken(),
        ...(extraHeaders || {}),
      },
      body: body === undefined ? undefined : JSON.stringify(body),
      signal: controller.signal,
    });

    text = await response.text();
  } catch (error) {
    if ((error as any)?.name === "AbortError" || controller.signal.aborted) {
      throw new Error(`Gateway request timed out after ${timeoutMs}ms: ${method} ${path}`);
    }

    throw error;
  } finally {
    clearTimeout(timeoutHandle);
  }

  let payload: any = null;
  if (text) {
    try {
      payload = JSON.parse(text);
    } catch {
      const preview = text.trim().slice(0, 180);
      throw new Error(`Gateway returned non-JSON response (${response.status}) from ${gatewayUrl}: ${preview}`);
    }
  }

  if (!response.ok) {
    throw new Error(
      payload?.message ||
        payload?.error ||
        `Gateway request failed (${response.status})`,
    );
  }

  return payload as T;
}

