function sendGatewayInstanceText(connectionId: string, body: Record<string, unknown>, timeoutOverrideMs?: number) {
  const payload =
    typeof body?.text === "string"
      ? {
          ...body,
          text: normalizeWebOnlyOutgoingLinksForWhatsApp(body.text),
          linkPreview: false,
          detectLinks: false,
        }
      : body;
  return requestGateway<{
    success?: boolean;
    messageId?: string | null;
    conversationId?: string | null;
    remoteJid?: string | null;
    reason?: string | null;
    blocked?: boolean;
    queued?: boolean;
  }>("POST", `/api/integration/instances/${connectionId}/messages/send`, payload, undefined, timeoutOverrideMs);
}

function sendGatewayInstanceMedia(connectionId: string, body: Record<string, unknown>, timeoutOverrideMs?: number) {
  const mediaType = String(body?.type || body?.mediaType || "").toLowerCase();
  const normalizedBody =
    mediaType === "audio"
      ? {
          ...body,
          mimetype: normalizeOutgoingWhatsAppMediaMimeType("audio", String(body?.mimetype || body?.mimeType || "")) || body?.mimetype,
          ptt:
            body?.ptt === undefined
              ? String(normalizeOutgoingWhatsAppMediaMimeType("audio", String(body?.mimetype || body?.mimeType || "")) || "")
                  .toLowerCase() === "audio/ogg; codecs=opus"
              : body.ptt,
        }
      : body;
  return requestGateway<{
    success?: boolean;
    messageId?: string | null;
    conversationId?: string | null;
    remoteJid?: string | null;
    reason?: string | null;
    blocked?: boolean;
  }>("POST", `/api/integration/instances/${connectionId}/messages/send-media`, normalizedBody, undefined, timeoutOverrideMs);
}

