function setBaseHeaders(req: any, res: any) {
  const origin = typeof req.headers.origin === "string" ? req.headers.origin : "";
  if (origin) {
    res.setHeader("Access-Control-Allow-Origin", origin);
    res.setHeader("Access-Control-Allow-Credentials", "true");
    res.setHeader("Vary", "Origin");
  }
  res.setHeader("Access-Control-Allow-Methods", "GET,POST,PUT,PATCH,DELETE,OPTIONS");
  res.setHeader("Access-Control-Allow-Headers", "Content-Type, Authorization");
}

function setNoStore(res: any) {
  res.setHeader("Cache-Control", "private, no-store, no-cache, must-revalidate, max-age=0");
  res.setHeader("Pragma", "no-cache");
  res.setHeader("Expires", "0");
}

function sendJson(res: any, status: number, payload: unknown) {
  res.statusCode = status;
  res.setHeader("Content-Type", "application/json; charset=utf-8");
  res.end(JSON.stringify(payload));
}

function sendText(res: any, status: number, payload: string) {
  res.statusCode = status;
  res.setHeader("Content-Type", "text/plain; charset=utf-8");
  res.end(payload);
}

function sendBinary(res: any, status: number, buffer: Buffer, contentType: string, filename?: string) {
  res.statusCode = status;
  res.setHeader("Content-Type", contentType);
  res.setHeader("Content-Length", String(buffer.length));
  if (filename) {
    res.setHeader("Content-Disposition", `attachment; filename="${filename}"`);
  }
  res.end(buffer);
}

function decodeJwtUser(token: string): JwtUser | null {
  try {
    const parts = token.split(".");
    if (parts.length !== 3) return null;

    const payload = JSON.parse(Buffer.from(parts[1], "base64url").toString("utf8"));
    const now = Math.floor(Date.now() / 1000);

    if (payload.exp && payload.exp < now - 60) {
      return null;
    }

    if (!payload.sub || payload.aud !== "authenticated") {
      return null;
    }

    return {
      id: String(payload.sub),
      email: payload.email ? String(payload.email) : undefined,
    };
  } catch {
    return null;
  }
}

function getBearerToken(req: any) {
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    return "";
  }

  return authHeader.slice(7).trim();
}

function parseCookies(req: any): Record<string, string> {
  const raw = String(req.headers.cookie || "");
  const cookies: Record<string, string> = {};
  for (const part of raw.split(";")) {
    const index = part.indexOf("=");
    if (index === -1) continue;
    const key = part.slice(0, index).trim();
    const value = part.slice(index + 1).trim();
    if (key) {
      cookies[key] = decodeURIComponent(value);
    }
  }
  return cookies;
}

function getAdminSessionSecret() {
  return String(
    process.env.ADMIN_SESSION_SECRET ||
      process.env.SESSION_SECRET ||
      process.env.CRON_SECRET ||
      "agentezap-vercel-admin-session",
  );
}

function signAdminSessionPayload(payload: string) {
  return createHmac("sha256", getAdminSessionSecret()).update(payload).digest("base64url");
}

function createAdminSessionCookie(admin: { id: string; email: string; role: string }) {
  const payload = Buffer.from(
    JSON.stringify({
      id: admin.id,
      email: admin.email,
      role: admin.role,
      exp: Date.now() + 1000 * 60 * 60 * 12,
    }),
  ).toString("base64url");
  const signature = signAdminSessionPayload(payload);
  return `${payload}.${signature}`;
}

function readAdminSession(req: any): { id: string; email: string; role: string } | null {
  const cookie = parseCookies(req).az_admin_session;
  if (cookie && cookie.includes(".")) {
    const [payload, signature] = cookie.split(".", 2);
    const expected = signAdminSessionPayload(payload);
    const providedBuffer = Buffer.from(signature);
    const expectedBuffer = Buffer.from(expected);
    if (
      providedBuffer.length === expectedBuffer.length &&
      timingSafeEqual(providedBuffer, expectedBuffer)
    ) {
      try {
        const parsed = JSON.parse(Buffer.from(payload, "base64url").toString("utf8"));
        if (parsed?.id && parsed?.email && parsed?.role && Number(parsed.exp || 0) >= Date.now()) {
          return {
            id: String(parsed.id),
            email: String(parsed.email),
            role: String(parsed.role),
          };
        }
      } catch {
        return null;
      }
    }
  }

  const sessionAdminId = req.session?.adminId;
  const sessionAdminRole = req.session?.adminRole;
  if (!sessionAdminId || !sessionAdminRole) return null;

  return {
    id: String(sessionAdminId),
    email: String(req.session?.adminEmail || sessionAdminId),
    role: String(sessionAdminRole || "admin"),
  };
}

async function readJsonBody(req: any) {
  try {
    if (req.body && typeof req.body === "object") {
      return req.body;
    }
    if (typeof req.body === "string") {
      const bodyText = req.body.replace(/^\uFEFF/, "");
      return bodyText ? JSON.parse(bodyText) : {};
    }
  } catch (error) {
    console.warn("[vercel-http] req.body unavailable, reading raw JSON body:", error);
  }

  const chunks: Buffer[] = [];
  for await (const chunk of req) {
    chunks.push(Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk));
  }

  if (chunks.length === 0) {
    return {};
  }

  const raw = Buffer.concat(chunks).toString("utf8").replace(/^\uFEFF/, "");
  return raw ? JSON.parse(raw) : {};
}

async function readRawBody(req: any) {
  const chunks: Buffer[] = [];
  for await (const chunk of req) {
    chunks.push(Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk));
  }
  return Buffer.concat(chunks);
}

async function readMultipartFormData(req: any) {
  const raw = await readRawBody(req);
  const headers = new Headers();
  for (const [key, value] of Object.entries(req.headers || {})) {
    if (Array.isArray(value)) {
      headers.set(key, value.join(", "));
    } else if (value !== undefined) {
      headers.set(key, String(value));
    }
  }

  const request = new Request("http://localhost", {
    method: req.method || "POST",
    headers,
    body: raw as any,
  });

  return request.formData();
}

async function getOrCreateUser(user: JwtUser): Promise<UserRow | null> {
  const db = getPool();
  const existing = await db.query("SELECT * FROM users WHERE id = $1 LIMIT 1", [user.id]);
  if (existing.rows[0]) {
    return existing.rows[0] as UserRow;
  }

  const fallbackName = String(user.email || "User").split("@")[0] || "User";
  await db.query(
    `INSERT INTO users (id, email, name, phone)
     VALUES ($1, $2, $3, $4)
     ON CONFLICT (id) DO NOTHING`,
    [user.id, user.email || null, fallbackName, ""],
  );

  const created = await db.query("SELECT * FROM users WHERE id = $1 LIMIT 1", [user.id]);
  return (created.rows[0] as UserRow | undefined) || null;
}

function mapUserForClient(row: UserRow | Record<string, any>) {
  const camel = toCamelRecord(row) || {};
  return {
    ...row,
    ...camel,
    profileImageUrl: row.profile_image_url ?? camel.profileImageUrl ?? null,
    whatsappNumber: row.whatsapp_number ?? camel.whatsappNumber ?? null,
    onboardingCompleted: row.onboarding_completed ?? camel.onboardingCompleted ?? false,
    resellerId: row.reseller_id ?? camel.resellerId ?? null,
    assignedPlanId: row.assigned_plan_id ?? camel.assignedPlanId ?? null,
    signatureEnabled: row.signature_enabled ?? camel.signatureEnabled ?? false,
    documentType: row.document_type ?? camel.documentType ?? null,
    documentNumber: row.document_number ?? camel.documentNumber ?? null,
    businessType: row.business_type ?? camel.businessType ?? null,
    gatewayApiEnabled: row.gateway_api_enabled ?? camel.gatewayApiEnabled ?? false,
    gatewayApiTokenPreview: row.gateway_api_token_preview ?? camel.gatewayApiTokenPreview ?? null,
    gatewayApiLastUsedAt: row.gateway_api_last_used_at ?? camel.gatewayApiLastUsedAt ?? null,
    gatewayApiRotatedAt: row.gateway_api_rotated_at ?? camel.gatewayApiRotatedAt ?? null,
    createdAt: row.created_at ?? camel.createdAt ?? null,
    updatedAt: row.updated_at ?? camel.updatedAt ?? null,
  };
}

function buildAuthUserFallbackForJwt(user: JwtUser) {
  const fallbackName = String(user.email || "User").split("@")[0] || "User";
  return mapUserForClient({
    id: user.id,
    email: user.email || null,
    name: fallbackName,
    phone: "",
  });
}

const authUserCache = new Map<string, { data: ReturnType<typeof mapUserForClient>; expiresAt: number; staleUntil: number }>();
const authUserInflight = new Map<string, Promise<ReturnType<typeof mapUserForClient> | null>>();
const AUTH_USER_CACHE_TTL_MS = 2 * 60 * 1000;
const AUTH_USER_STALE_TTL_MS = 30 * 60 * 1000;

async function getMappedAuthUserForJwt(user: JwtUser) {
  const cached = authUserCache.get(user.id);
  if (cached && cached.expiresAt > Date.now()) {
    return cached.data;
  }

  let inflight = authUserInflight.get(user.id);
  if (!inflight) {
    inflight = getOrCreateUser(user).then((dbUser) => {
      if (!dbUser) return null;
      const mapped = mapUserForClient(dbUser);
      authUserCache.set(user.id, {
        data: mapped,
        expiresAt: Date.now() + AUTH_USER_CACHE_TTL_MS,
        staleUntil: Date.now() + AUTH_USER_STALE_TTL_MS,
      });
      return mapped;
    }).finally(() => {
      authUserInflight.delete(user.id);
    });
    authUserInflight.set(user.id, inflight);
  }

  return inflight;
}

async function handleAuthUser(req: any, res: any) {
  setNoStore(res);

  const token = getBearerToken(req);
  const user = decodeJwtUser(token);
  if (!token || !user) {
    return sendJson(res, 401, { message: "Unauthorized" });
  }

  try {
    const mappedUser = await getMappedAuthUserForJwt(user);
    if (!mappedUser) {
      return sendJson(res, 404, { message: "User not found" });
    }

    return sendJson(res, 200, mappedUser);
  } catch (error) {
    console.error("[vercel-http] auth user failed:", error);
    const cached = authUserCache.get(user.id) as
      | { data: ReturnType<typeof mapUserForClient>; expiresAt: number; staleUntil?: number }
      | undefined;
    if (isPgConnectionAcquireTimeout(error)) {
      if (cached?.data && (cached.staleUntil || 0) > Date.now()) {
        return sendJson(res, 200, { ...cached.data, authDataStale: true });
      }
      return sendJson(res, 503, { message: "Auth temporarily unavailable", temporaryUnavailable: true });
    }
    return sendJson(res, 401, { message: "Unauthorized" });
  }
}

async function handleUserQuickReplies(req: any, res: any, replyId?: string, action?: string) {
  const user = await requireUserOrTeamMember(req, res);
  if (!user) return;
  if (!ensureTeamMemberPermission(user, res, "canUseQuickReplies", "Permissao insuficiente para usar respostas rapidas.")) return;

  try {
    const db = getPool();

    if (!replyId && req.method === "GET") {
      const result = await db.query(
        `
          SELECT
            id,
            user_id AS "userId",
            title,
            content,
            shortcut,
            category,
            usage_count AS "usageCount",
            created_at AS "createdAt",
            updated_at AS "updatedAt"
          FROM user_quick_replies
          WHERE user_id = $1
          ORDER BY created_at ASC, id ASC
        `,
        [user.id],
      );
      return sendJson(res, 200, result.rows);
    }

    if (!replyId && req.method === "POST") {
      const body = await readJsonBody(req);
      const title = String(body.title || "").trim();
      const content = String(body.content || "").trim();
      const shortcut = String(body.shortcut || "").trim() || null;
      const category = String(body.category || "").trim() || null;

      if (!title || !content) {
        return sendJson(res, 400, { message: "Title and content are required" });
      }

      const result = await db.query(
        `
          INSERT INTO user_quick_replies (user_id, title, content, shortcut, category)
          VALUES ($1, $2, $3, $4, $5)
          RETURNING
            id,
            user_id AS "userId",
            title,
            content,
            shortcut,
            category,
            usage_count AS "usageCount",
            created_at AS "createdAt",
            updated_at AS "updatedAt"
        `,
        [user.id, title, content, shortcut, category],
      );
      return sendJson(res, 200, result.rows[0]);
    }

    if (replyId && action === "use" && req.method === "POST") {
      await db.query(
        `
          UPDATE user_quick_replies
          SET usage_count = COALESCE(usage_count, 0) + 1, updated_at = NOW()
          WHERE id = $1 AND user_id = $2
        `,
        [replyId, user.id],
      );
      return sendJson(res, 200, { success: true });
    }

    if (replyId && req.method === "PUT") {
      const body = await readJsonBody(req);
      const title = String(body.title || "").trim();
      const content = String(body.content || "").trim();
      const shortcut = String(body.shortcut || "").trim() || null;
      const category = String(body.category || "").trim() || null;

      if (!title || !content) {
        return sendJson(res, 400, { message: "Title and content are required" });
      }

      const result = await db.query(
        `
          UPDATE user_quick_replies
          SET title = $3, content = $4, shortcut = $5, category = $6, updated_at = NOW()
          WHERE id = $1 AND user_id = $2
          RETURNING
            id,
            user_id AS "userId",
            title,
            content,
            shortcut,
            category,
            usage_count AS "usageCount",
            created_at AS "createdAt",
            updated_at AS "updatedAt"
        `,
        [replyId, user.id, title, content, shortcut, category],
      );

      if (!result.rows[0]) {
        return sendJson(res, 404, { message: "Quick reply not found" });
      }

      return sendJson(res, 200, result.rows[0]);
    }

    if (replyId && req.method === "DELETE") {
      const result = await db.query("DELETE FROM user_quick_replies WHERE id = $1 AND user_id = $2 RETURNING id", [
        replyId,
        user.id,
      ]);

      if (!result.rows[0]) {
        return sendJson(res, 404, { message: "Quick reply not found" });
      }

      return sendJson(res, 200, { success: true });
    }

    return sendJson(res, 405, { message: "Method not allowed" });
  } catch (error) {
    console.error("[vercel-http] user quick replies failed:", error);
    return sendJson(res, 500, { message: "Failed to handle quick replies" });
  }
}

async function handleUserQuickReplyGenerate(req: any, res: any) {
  const user = await requireUserOrTeamMember(req, res);
  if (!user) return;
  if (!ensureTeamMemberPermission(user, res, "canUseQuickReplies", "Permissao insuficiente para usar respostas rapidas.")) return;

  try {
    const body = await readJsonBody(req);
    const title = String(body.title || body.prompt || "").trim();
    if (!title) {
      return sendJson(res, 400, { message: "Title is required" });
    }

    const content = await callWebOnlyLlm({
      userId: user.id,
      model: "mistral-small-latest",
      prompt:
        "Voce e um assistente que cria mensagens prontas para atendimento ao cliente no WhatsApp. Responda apenas com a mensagem pronta, sem explicacoes.",
      message: `Crie uma mensagem profissional, amigavel e concisa para: ${title}`,
      history: [],
      temperature: 0.5,
      maxTokens: 220,
    });

    return sendJson(res, 200, { content: content.trim() });
  } catch (error) {
    console.error("[vercel-http] generate user quick reply failed:", error);
    return sendJson(res, 500, { message: "Failed to generate quick reply" });
  }
}

async function requireJwtUser(req: any, res: any): Promise<JwtUser | null> {
  const token = getBearerToken(req);
  const user = decodeJwtUser(token);
  if (!token || !user) {
    setNoStore(res);
    sendJson(res, 401, { message: "Unauthorized" });
    return null;
  }

  return user;
}

async function resolveTeamMemberUserFromToken(token: string): Promise<AuthenticatedUser | null> {
  if (!token || token.includes(".")) {
    return null;
  }

  const result = await getPool().query(
    `
      SELECT
        tms.member_id,
        tms.expires_at,
        tm.id,
        tm.owner_id,
        tm.name,
        tm.email,
        tm.role,
        tm.permissions,
        tm.is_active,
        tm.signature,
        tm.signature_enabled,
        u.email AS owner_email
      FROM team_member_sessions tms
      JOIN team_members tm ON tm.id = tms.member_id
      LEFT JOIN users u ON u.id = tm.owner_id
      WHERE tms.token = $1
      LIMIT 1
    `,
    [token],
  );

  const row = result.rows[0];
  if (!row || new Date(row.expires_at) < new Date() || row.is_active !== true) {
    return null;
  }

  const permissions = normalizeTeamMemberPermissions(row.permissions || {});
  return {
    id: String(row.owner_id),
    email: row.owner_email ? String(row.owner_email) : undefined,
    isMember: true,
    memberData: {
      id: String(row.id),
      ownerId: String(row.owner_id),
      name: String(row.name || ""),
      email: String(row.email || ""),
      role: String(row.role || "atendente"),
      permissions,
      signature: row.signature || null,
      signatureEnabled: row.signature_enabled === true,
    },
  };
}

async function requireUserOrTeamMember(req: any, res: any): Promise<AuthenticatedUser | null> {
  const token = getBearerToken(req);
  const jwtUser = decodeJwtUser(token);
  if (token && jwtUser) {
    const user: AuthenticatedUser = { ...jwtUser, isMember: false };
    req.user = user;
    return user;
  }

  try {
    const memberUser = await resolveTeamMemberUserFromToken(token);
    if (memberUser) {
      req.user = memberUser;
      return memberUser;
    }
  } catch (error) {
    console.error("[vercel-http] team member auth failed:", error);
  }

  setNoStore(res);
  sendJson(res, 401, { message: "Unauthorized" });
  return null;
}

function isTeamMemberUser(user: AuthenticatedUser | null | undefined): user is Required<Pick<AuthenticatedUser, "memberData">> & AuthenticatedUser {
  return user?.isMember === true && !!user.memberData?.id;
}

function ensureTeamMemberPermission(
  user: AuthenticatedUser,
  res: any,
  permission: keyof TeamMemberPermissions,
  message = "Permissao insuficiente para esta acao.",
) {
  if (!isTeamMemberUser(user)) {
    return true;
  }

  if (user.memberData.permissions?.[permission] === false) {
    sendJson(res, 403, { message });
    return false;
  }

  return true;
}

function getActorAuditId(user: AuthenticatedUser) {
  return isTeamMemberUser(user) ? user.memberData.id : user.id;
}

function getActorAuditName(user: AuthenticatedUser) {
  if (isTeamMemberUser(user)) {
    return user.memberData.name || user.memberData.email || "Membro";
  }
  return user.email || "Usuario";
}

function normalizeNumeric(value: unknown): number | null {
  if (value == null || value === "") {
    return null;
  }

  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : null;
}

const FREE_DAILY_CALIBRATION_LIMIT = 5;
const FREE_DAILY_SIMULATOR_LIMIT = 25;
const KANBAN_UNASSIGNED_STAGE_ID = "__unassigned__";
const INTRO_PROMO_PENDING_SUBSCRIPTION_STATUSES = new Set(["pending", "pending_pix"]);
const INTRO_PROMO_COMPLETED_SUBSCRIPTION_STATUSES = new Set(["active", "expired", "cancelled", "paused"]);
const DEFAULT_CALENDAR_TIMEZONE = "America/Sao_Paulo";
const GOOGLE_IMPORTED_MARKER = "[GOOGLE_IMPORTED]";
const GOOGLE_SCOPES = [
  "https://www.googleapis.com/auth/calendar",
  "https://www.googleapis.com/auth/calendar.events",
  "https://www.googleapis.com/auth/userinfo.email",
];

function toCamelCaseKey(key: string) {
  return key.replace(/_([a-z])/g, (_match, char: string) => char.toUpperCase());
}

function toCamelRecord<T extends Record<string, any>>(row: T | null | undefined) {
  if (!row) {
    return null;
  }

  const output: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(row)) {
    output[toCamelCaseKey(key)] = value;
  }
  return output;
}

function toStringValue(value: unknown, fallback = "") {
  if (value == null) {
    return fallback;
  }
  return String(value);
}

function toNumberValue(value: unknown, fallback = 0) {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : fallback;
}

function normalizeAutoReactivateMinutes(value: unknown): number | null {
  if (value == null || value === "") {
    return null;
  }

  const parsed = Number(value);
  if (!Number.isFinite(parsed) || parsed <= 0) {
    return null;
  }

  return Math.max(1, Math.min(Math.round(parsed), 10080));
}

function toAgentConfigPayload(row: Record<string, unknown> | null | undefined) {
  const payload = toCamelRecord(row || null) as Record<string, unknown> | null;
  if (payload && typeof payload === "object") {
    payload.autoReactivateMinutes = normalizeAutoReactivateMinutes(payload.autoReactivateMinutes);
  }
  return payload;
}

function normalizeCalendarTimeValue(time: string): string {
  const [rawHour = "00", rawMinute = "00", rawSecond = "00"] = String(time || "").split(":");
  return `${rawHour.padStart(2, "0")}:${rawMinute.padStart(2, "0")}:${rawSecond.padStart(2, "0")}`;
}

function buildCalendarDateTimeValue(date: string, time: string): string {
  return `${date}T${normalizeCalendarTimeValue(time)}`;
}

const calendarTimeZoneFormatterCache = new Map<string, Intl.DateTimeFormat>();

function getCalendarTimeZoneFormatter(timeZone: string): Intl.DateTimeFormat {
  const cached = calendarTimeZoneFormatterCache.get(timeZone);
  if (cached) return cached;
  const formatter = new Intl.DateTimeFormat("en-CA", {
    timeZone,
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
    hourCycle: "h23",
  });
  calendarTimeZoneFormatterCache.set(timeZone, formatter);
  return formatter;
}

function readCalendarTimeZoneParts(date: Date, timeZone: string) {
  const parts = getCalendarTimeZoneFormatter(timeZone).formatToParts(date);
  const values: Record<string, number> = {};
  for (const part of parts) {
    if (["year", "month", "day", "hour", "minute", "second"].includes(part.type)) {
      values[part.type] = Number(part.value);
    }
  }
  return {
    year: values.year || 0,
    month: values.month || 0,
    day: values.day || 0,
    hour: values.hour || 0,
    minute: values.minute || 0,
    second: values.second || 0,
  };
}

function formatCalendarLocalDateTime(date: Date, timeZone = DEFAULT_CALENDAR_TIMEZONE): string {
  const parts = readCalendarTimeZoneParts(date, timeZone);
  return [
    `${String(parts.year).padStart(4, "0")}-${String(parts.month).padStart(2, "0")}-${String(parts.day).padStart(2, "0")}`,
    `${String(parts.hour).padStart(2, "0")}:${String(parts.minute).padStart(2, "0")}:${String(parts.second).padStart(2, "0")}`,
  ].join("T");
}

function calendarValueHasExplicitTimeZone(value: string): boolean {
  const normalized = String(value || "").trim();
  if (!normalized) return false;
  if (normalized.endsWith("Z") || normalized.endsWith("z")) return true;
  const plusIndex = normalized.lastIndexOf("+");
  const minusIndex = normalized.lastIndexOf("-");
  const offsetIndex = Math.max(plusIndex, minusIndex);
  const timeSeparatorIndex = normalized.indexOf("T");
  if (offsetIndex <= timeSeparatorIndex) return false;
  const offset = normalized.slice(offsetIndex);
  return offset.length === 6 && offset[3] === ":";
}

function parseCalendarDateTimeWithZone(value: string, timeZone = DEFAULT_CALENDAR_TIMEZONE): Date {
  const normalized = String(value || "").trim();
  if (!normalized) return new Date(Number.NaN);
  if (calendarValueHasExplicitTimeZone(normalized)) return new Date(normalized);

  const [datePart = "", rawTimePart = "00:00:00"] = normalized.split("T");
  const [yearRaw = "", monthRaw = "", dayRaw = ""] = datePart.split("-");
  const [hourRaw = "00", minuteRaw = "00", secondRaw = "00"] = normalizeCalendarTimeValue(rawTimePart).split(":");
  const target = {
    year: Number(yearRaw),
    month: Number(monthRaw),
    day: Number(dayRaw),
    hour: Number(hourRaw),
    minute: Number(minuteRaw),
    second: Number(secondRaw),
  };
  if (Object.values(target).some((part) => Number.isNaN(part))) return new Date(normalized);

  const targetUtcTime = Date.UTC(target.year, target.month - 1, target.day, target.hour, target.minute, target.second);
  let candidateUtcTime = targetUtcTime;
  for (let attempt = 0; attempt < 4; attempt += 1) {
    const observed = readCalendarTimeZoneParts(new Date(candidateUtcTime), timeZone);
    const observedUtcTime = Date.UTC(
      observed.year,
      observed.month - 1,
      observed.day,
      observed.hour,
      observed.minute,
      observed.second,
    );
    const diff = observedUtcTime - targetUtcTime;
    if (diff === 0) return new Date(candidateUtcTime);
    candidateUtcTime -= diff;
  }
  return new Date(candidateUtcTime);
}

function addMinutesToCalendarDateTimeValue(date: string, time: string, minutesToAdd: number): string {
  const result = parseCalendarDateTimeWithZone(buildCalendarDateTimeValue(date, time));
  result.setUTCMinutes(result.getUTCMinutes() + minutesToAdd);
  return formatCalendarLocalDateTime(result);
}

function rangesOverlap(start: Date, end: Date, eventStart: Date, eventEnd: Date): boolean {
  return start < eventEnd && end > eventStart;
}

function formatBrazilDateKey(date: Date): string {
  return formatCalendarLocalDateTime(date).slice(0, 10);
}

function formatBrazilNowLabel(): string {
  return new Date().toLocaleString("pt-BR", {
    timeZone: DEFAULT_CALENDAR_TIMEZONE,
    weekday: "long",
    day: "2-digit",
    month: "long",
    year: "numeric",
    hour: "2-digit",
    minute: "2-digit",
  });
}

function trimForAgenda(value: unknown, maxLength = 200): string {
  const text = String(value || "").replace(/\s+/g, " ").trim();
  return text.length > maxLength ? `${text.slice(0, Math.max(0, maxLength - 1)).trim()}...` : text;
}

function normalizeWebOnlySignatureName(value?: string | null): string | null {
  const normalized = String(value || "").replace(/\s+/g, " ").trim();
  return normalized || null;
}

function stripWebOnlyPromptFormatting(value: string) {
  return String(value || "")
    .replace(/[*_`~]/g, " ")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/\s+/g, " ")
    .trim();
}

function toWebOnlyTitleCase(value: string) {
  return value
    .split(" ")
    .filter(Boolean)
    .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
    .join(" ");
}

function detectWebOnlyAgentSignatureNameFromPrompt(prompt?: string | null): string | null {
  const source = stripWebOnlyPromptFormatting(String(prompt || ""));
  if (!source) return null;

  const genericNames = new Set([
    "agente",
    "agente ia",
    "agente virtual",
    "assistente",
    "assistente ia",
    "assistente virtual",
    "atendente",
    "atendente ia",
    "atendente virtual",
    "chatbot",
    "equipe",
    "ia",
    "inteligencia artificial",
    "suporte",
    "time",
    "vendedor",
    "vendedora",
  ]);
  const patterns = [
    /\bvoce e (?:o |a |um |uma )?([^,.;:\n]+?)(?:,\s*[^.;:\n]+?)?\s+da\b/i,
    /\bsou (?:o |a )?([^,.;:\n]+?)(?:,\s*[^.;:\n]+?)?\s+da\b/i,
  ];

  for (const pattern of patterns) {
    const match = source.match(pattern);
    const candidate = normalizeWebOnlySignatureName(match?.[1] || "");
    if (candidate && !genericNames.has(stripWebOnlyPromptFormatting(candidate).toLowerCase())) {
      return toWebOnlyTitleCase(candidate);
    }
  }

  return null;
}

function resolveAgentSignatureName(options: {
  configuredSignature?: string | null;
  prompt?: string | null;
}): string | null {
  return normalizeWebOnlySignatureName(options.configuredSignature) ||
    detectWebOnlyAgentSignatureNameFromPrompt(options.prompt);
}

function prependWhatsappSignature(text: string, name?: string | null): string {
  const body = String(text || "").trim();
  const signatureName = normalizeWebOnlySignatureName(name);
  if (!body || !signatureName) return body;

  const prefix = `*${signatureName}:*`;
  const escapedName = signatureName.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  const leadingSignaturePattern = new RegExp(
    `^\\s*(?:\\*${escapedName}:\\*|${escapedName}:\\*?)\\s*`,
    "i",
  );
  const strippedBody = body.replace(leadingSignaturePattern, "").trimStart();
  const finalBody = strippedBody || body;
  if (body === prefix || body.startsWith(`${prefix}\n`) || body.startsWith(`${prefix}\r\n`)) {
    return body;
  }

  return `${prefix}\n${finalBody}`;
}

function toBooleanValue(value: unknown, fallback = false) {
  if (value == null) {
    return fallback;
  }
  if (typeof value === "boolean") {
    return value;
  }
  const normalized = String(value).trim().toLowerCase();
  if (normalized === "true" || normalized === "1" || normalized === "yes") {
    return true;
  }
  if (normalized === "false" || normalized === "0" || normalized === "no") {
    return false;
  }
  return fallback;
}

function parseMoneyAmount(value: unknown) {
  if (value == null || value === "") {
    return 0;
  }

  const parsed = Number(String(value).replace(",", "."));
  return Number.isFinite(parsed) ? parsed : 0;
}

function isImplementationPlanType(plan: { tipo?: unknown } | null | undefined) {
  const type = String(plan?.tipo || "").trim();
  return type === "implementacao" || type === "implementacao_mensal";
}

async function hasCompletedSubscriptionHistory(userId: string, excludeSubscriptionId?: string | null) {
  const result = await getPool().query(
    `
      SELECT id, status
      FROM subscriptions
      WHERE user_id = $1
      ORDER BY created_at DESC
    `,
    [userId],
  );

  return result.rows.some((row) => {
    if (excludeSubscriptionId && row.id === excludeSubscriptionId) {
      return false;
    }

    return INTRO_PROMO_COMPLETED_SUBSCRIPTION_STATUSES.has(String(row.status || ""));
  });
}

function shouldPreserveSubscriptionCouponPrice(subscription: { status?: unknown } | null | undefined) {
  return INTRO_PROMO_PENDING_SUBSCRIPTION_STATUSES.has(String(subscription?.status || ""));
}

function normalizeSubscriptionForPublicBilling<T extends { status?: unknown; couponPrice?: unknown } | null>(
  subscription: T,
): T {
  if (!subscription || shouldPreserveSubscriptionCouponPrice(subscription)) {
    return subscription;
  }

  return {
    ...subscription,
    couponPrice: null,
  };
}

async function resolveSubscriptionChargeAmounts(options: {
  userId: string;
  subscriptionId?: string | null;
  plan: { valor?: unknown; valorPrimeiraCobranca?: unknown; tipo?: unknown };
  couponPrice?: unknown;
}) {
  const recurringAmount = options.couponPrice != null
    ? parseMoneyAmount(options.couponPrice)
    : parseMoneyAmount(options.plan?.valor);
  const configuredFirstCharge = parseMoneyAmount(options.plan?.valorPrimeiraCobranca);
  const hasDifferentConfiguredFirstCharge =
    configuredFirstCharge > 0 && configuredFirstCharge !== recurringAmount;

  if (!hasDifferentConfiguredFirstCharge) {
    return {
      recurringAmount,
      firstChargeAmount: recurringAmount,
      hasDifferentFirstCharge: false,
    };
  }

  if (isImplementationPlanType(options.plan)) {
    return {
      recurringAmount,
      firstChargeAmount: configuredFirstCharge,
      hasDifferentFirstCharge: true,
    };
  }

  const introOfferEligible = !(await hasCompletedSubscriptionHistory(
    options.userId,
    options.subscriptionId,
  ));

  return {
    recurringAmount,
    firstChargeAmount: introOfferEligible ? configuredFirstCharge : recurringAmount,
    hasDifferentFirstCharge: introOfferEligible,
  };
}

function resolvePlansCheckoutPaymentAmount(
  subscription: Record<string, any> | null | undefined,
): number | null {
  if (!subscription) {
    return null;
  }

  const metadata = getSubscriptionMetadataRecord(subscription);
  if (String(metadata.createdFrom || "").trim() !== "plans_checkout") {
    return null;
  }

  const checkoutAmountAfterCoupon = parseMoneyAmount(metadata.checkoutAmountAfterCoupon);
  if (checkoutAmountAfterCoupon > 0) {
    return roundCurrencyAmount(checkoutAmountAfterCoupon);
  }

  const checkoutAmount = parseMoneyAmount(metadata.checkoutAmount);
  if (checkoutAmount > 0) {
    return roundCurrencyAmount(checkoutAmount);
  }

  const couponAmount = parseMoneyAmount(subscription.couponPrice ?? subscription.coupon_price);
  if (couponAmount > 0) {
    return roundCurrencyAmount(couponAmount);
  }

  return null;
}

async function getSystemConfigMap(keys: string[]) {
  if (!keys.length) {
    return new Map<string, string>();
  }

  const result = await getPool().query(
    `SELECT chave, valor
     FROM system_config
     WHERE chave = ANY($1::text[])`,
    [keys],
  );

  return new Map<string, string>(
    result.rows.map((row) => [String(row.chave), row.valor == null ? "" : String(row.valor)]),
  );
}

async function setSystemConfigValue(key: string, value: string) {
  await getPool().query(
    `
      INSERT INTO system_config (chave, valor, updated_at)
      VALUES ($1, $2, NOW())
      ON CONFLICT (chave)
      DO UPDATE SET valor = EXCLUDED.valor, updated_at = NOW()
    `,
    [key, value],
  );
}

function normalizeSettingsPhone(value: unknown) {
  if (typeof value !== "string") {
    return null;
  }
  const trimmed = value.trim();
  if (!trimmed) {
    return null;
  }
  const digits = trimmed.replace(/\D/g, "");
  if (!digits) {
    return null;
  }
  return trimmed.startsWith("+") ? `+${digits}` : digits;
}

async function handleUserProfile(req: any, res: any) {
  const user = await requireJwtUser(req, res);
  if (!user) return;

  try {
    const body = await readJsonBody(req);
    const email = typeof body.email === "string" ? body.email.trim().toLowerCase() : undefined;
    const name = typeof body.name === "string" ? body.name.trim() : undefined;
    const phone = normalizeSettingsPhone(body.phone);

    const fields: string[] = [];
    const values: unknown[] = [];

    if (email !== undefined) {
      if (!email || !email.includes("@")) {
        return sendJson(res, 400, { message: "Email invalido" });
      }
      values.push(email);
      fields.push(`email = $${values.length}`);
    }

    if (name !== undefined) {
      if (!name) {
        return sendJson(res, 400, { message: "Nome e obrigatorio" });
      }
      values.push(name);
      fields.push(`name = $${values.length}`);
    }

    if (typeof body.phone === "string" && phone) {
      values.push(phone);
      fields.push(`phone = $${values.length}`);
      values.push(phone);
      fields.push(`whatsapp_number = $${values.length}`);
    }

    if (fields.length === 0) {
      const current = await getPool().query("SELECT * FROM users WHERE id = $1 LIMIT 1", [user.id]);
      return sendJson(res, 200, mapUserForClient(current.rows[0] || { id: user.id }));
    }

    values.push(user.id);
    const result = await getPool().query(
      `
        UPDATE users
        SET ${fields.join(", ")}, updated_at = NOW()
        WHERE id = $${values.length}
        RETURNING *
      `,
      values,
    );

    if (!result.rows[0]) {
      return sendJson(res, 404, { message: "Usuario nao encontrado" });
    }

    return sendJson(res, 200, mapUserForClient(result.rows[0]));
  } catch (error: any) {
    console.error("[vercel-http] user profile update failed:", error);
    return sendJson(res, 500, { message: error?.message || "Falha ao atualizar perfil" });
  }
}

async function handleUserSignature(req: any, res: any) {
  const user = await requireJwtUser(req, res);
  if (!user) return;

  try {
    const body = await readJsonBody(req);
    const signatureRaw = typeof body.signature === "string" ? body.signature.trim() : "";
    const signature = signatureRaw ? signatureRaw.slice(0, 100) : null;
    const signatureEnabled = body.signatureEnabled === true;

    const result = await getPool().query(
      `
        UPDATE users
        SET signature = $1,
            signature_enabled = $2,
            updated_at = NOW()
        WHERE id = $3
        RETURNING *
      `,
      [signature, signatureEnabled, user.id],
    );

    if (!result.rows[0]) {
      return sendJson(res, 404, { message: "Usuario nao encontrado" });
    }

    return sendJson(res, 200, mapUserForClient(result.rows[0]));
  } catch (error: any) {
    console.error("[vercel-http] user signature update failed:", error);
    return sendJson(res, 500, { message: error?.message || "Falha ao atualizar assinatura" });
  }
}

async function handleUserPassword(req: any, res: any) {
  const user = await requireJwtUser(req, res);
  if (!user) return;

  try {
    const body = await readJsonBody(req);
    const currentPassword = typeof body.currentPassword === "string" ? body.currentPassword : "";
    const newPassword = typeof body.newPassword === "string" ? body.newPassword : "";

    if (!currentPassword) {
      return sendJson(res, 400, { message: "Informe a senha atual" });
    }

    if (!newPassword || newPassword.length < 6) {
      return sendJson(res, 400, { message: "A nova senha deve ter pelo menos 6 caracteres" });
    }

    const currentUser = await getPool().query("SELECT id, email FROM users WHERE id = $1 LIMIT 1", [user.id]);
    const email = String(currentUser.rows[0]?.email || user.email || "").trim().toLowerCase();
    if (!email) {
      return sendJson(res, 400, { message: "Usuario nao encontrado" });
    }

    const supabaseUrl = process.env.SUPABASE_URL || process.env.VITE_SUPABASE_URL;
    const serviceKey = process.env.SUPABASE_SERVICE_ROLE_KEY || process.env.SUPABASE_SERVICE_KEY;
    const anonKey = process.env.SUPABASE_ANON_KEY || process.env.VITE_SUPABASE_ANON_KEY;

    if (!supabaseUrl || !serviceKey || !anonKey) {
      return sendJson(res, 500, { message: "Configuracao do servidor incompleta" });
    }

    const anonClient = createClient(supabaseUrl, anonKey, {
      auth: { persistSession: false, autoRefreshToken: false },
    });
    const signInResult = await anonClient.auth.signInWithPassword({
      email,
      password: currentPassword,
    });

    if (signInResult.error || !signInResult.data.user?.id) {
      return sendJson(res, 400, { message: "Senha atual incorreta" });
    }

    const adminClient = createClient(supabaseUrl, serviceKey, {
      auth: { persistSession: false, autoRefreshToken: false },
    });
    const { error: updateError } = await adminClient.auth.admin.updateUserById(
      signInResult.data.user.id,
      { password: newPassword },
    );

    if (updateError) {
      console.error("[vercel-http] Supabase password update failed:", updateError);
      return sendJson(res, 500, { message: "Erro ao alterar senha. Tente novamente." });
    }

    return sendJson(res, 200, { success: true, message: "Senha alterada com sucesso" });
  } catch (error: any) {
    console.error("[vercel-http] user password update failed:", error);
    return sendJson(res, 500, { message: error?.message || "Falha ao alterar senha" });
  }
}

const VAPID_PUBLIC_KEY = "pwa_vapid_public_key";
const VAPID_PRIVATE_KEY = "pwa_vapid_private_key";
const VAPID_SUBJECT_KEY = "pwa_vapid_subject";
const DEFAULT_VAPID_SUBJECT = process.env.WEB_PUSH_SUBJECT || "mailto:suporte@agentezap.online";
const DEFAULT_PUSH_TTL_SECONDS = 6 * 60 * 60;
let configuredVapidFingerprint: string | null = null;

function sanitizePushTopic(value: string | undefined) {
  if (!value) return undefined;
  const safe = value.replace(/[^A-Za-z0-9_-]/g, "").slice(0, 32);
  return safe || undefined;
}

async function getOrCreateVapidKeys() {
  const config = await getSystemConfigMap([VAPID_PUBLIC_KEY, VAPID_PRIVATE_KEY, VAPID_SUBJECT_KEY]);
  const existingPublic = config.get(VAPID_PUBLIC_KEY);
  const existingPrivate = config.get(VAPID_PRIVATE_KEY);
  const subject = config.get(VAPID_SUBJECT_KEY) || DEFAULT_VAPID_SUBJECT;

  if (existingPublic && existingPrivate) {
    return { publicKey: existingPublic, privateKey: existingPrivate, subject };
  }

  const generated = webpush.generateVAPIDKeys();
  const publicKey = existingPublic || generated.publicKey;
  const privateKey = existingPrivate || generated.privateKey;

  await Promise.all([
    setSystemConfigValue(VAPID_PUBLIC_KEY, publicKey),
    setSystemConfigValue(VAPID_PRIVATE_KEY, privateKey),
    setSystemConfigValue(VAPID_SUBJECT_KEY, subject),
  ]);

  return { publicKey, privateKey, subject };
}

async function ensureWebPushConfigured() {
  const vapid = await getOrCreateVapidKeys();
  const fingerprint = `${vapid.publicKey}:${vapid.subject}`;
  if (configuredVapidFingerprint !== fingerprint) {
    webpush.setVapidDetails(vapid.subject, vapid.publicKey, vapid.privateKey);
    configuredVapidFingerprint = fingerprint;
  }
  return vapid;
}

async function handlePwaPublicKey(_req: any, res: any) {
  try {
    const vapid = await ensureWebPushConfigured();
    return sendJson(res, 200, { publicKey: vapid.publicKey });
  } catch (error: any) {
    console.error("[vercel-http] PWA public key failed:", error);
    return sendJson(res, 500, { message: error?.message || "Falha ao carregar chave do PWA" });
  }
}

async function handlePwaSubscriptions(req: any, res: any) {
  const user = await requireJwtUser(req, res);
  if (!user) return;

  try {
    const body = await readJsonBody(req);

    if (req.method === "DELETE") {
      const endpoint = typeof body.endpoint === "string" && body.endpoint.trim() ? body.endpoint.trim() : null;
      if (endpoint) {
        await getPool().query("DELETE FROM web_push_subscriptions WHERE user_id = $1 AND endpoint = $2", [user.id, endpoint]);
      } else {
        await getPool().query("DELETE FROM web_push_subscriptions WHERE user_id = $1", [user.id]);
      }
      return sendJson(res, 200, { success: true });
    }

    const subscription = body.subscription || {};
    const endpoint = String(subscription.endpoint || "").trim();
    const p256dh = String(subscription.keys?.p256dh || "").trim();
    const auth = String(subscription.keys?.auth || "").trim();
    const deviceLabel = typeof body.deviceLabel === "string" ? body.deviceLabel.slice(0, 255) : null;

    if (!endpoint || !p256dh || !auth) {
      return sendJson(res, 400, { message: "Push subscription incompleta" });
    }

    await getPool().query(
      `
        INSERT INTO web_push_subscriptions (
          user_id,
          endpoint,
          p256dh,
          auth,
          user_agent,
          device_label,
          is_active,
          last_seen_at,
          updated_at
        )
        VALUES ($1, $2, $3, $4, $5, $6, TRUE, NOW(), NOW())
        ON CONFLICT (endpoint)
        DO UPDATE SET
          user_id = EXCLUDED.user_id,
          p256dh = EXCLUDED.p256dh,
          auth = EXCLUDED.auth,
          user_agent = EXCLUDED.user_agent,
          device_label = EXCLUDED.device_label,
          is_active = TRUE,
          last_seen_at = NOW(),
          updated_at = NOW()
      `,
      [user.id, endpoint, p256dh, auth, String(req.headers["user-agent"] || ""), deviceLabel],
    );

    return sendJson(res, 200, { success: true });
  } catch (error: any) {
    console.error("[vercel-http] PWA subscription failed:", error);
    return sendJson(res, 400, { message: error?.message || "Falha ao salvar subscription" });
  }
}

async function handlePwaSubscriptionStatus(req: any, res: any) {
  const user = await requireJwtUser(req, res);
  if (!user) return;

  try {
    const body = await readJsonBody(req);
    const endpoint = typeof body.endpoint === "string" && body.endpoint.trim() ? body.endpoint.trim() : null;
    const result = await getPool().query(
      `
        SELECT endpoint, device_label, user_agent, is_active, last_seen_at
        FROM web_push_subscriptions
        WHERE user_id = $1
      `,
      [user.id],
    );

    const subscriptions = result.rows;
    const activeSubscriptions = subscriptions.filter((subscription) => subscription.is_active === true);
    const matched = endpoint ? subscriptions.find((subscription) => subscription.endpoint === endpoint) : null;

    if (matched?.is_active === true) {
      await getPool().query(
        `
          UPDATE web_push_subscriptions
          SET is_active = TRUE, last_seen_at = NOW(), updated_at = NOW()
          WHERE user_id = $1 AND endpoint = $2
        `,
        [user.id, endpoint],
      );
      matched.last_seen_at = new Date();
    }

    return sendJson(res, 200, {
      totalSubscriptions: subscriptions.length,
      totalActiveSubscriptions: activeSubscriptions.length,
      currentEndpointRegistered: Boolean(matched),
      currentEndpointActive: Boolean(matched?.is_active),
      currentDeviceLabel: matched?.device_label || null,
      currentUserAgent: matched?.user_agent || null,
      currentLastSeenAt: matched?.last_seen_at?.toISOString?.() || matched?.last_seen_at || null,
    });
  } catch (error: any) {
    console.error("[vercel-http] PWA subscription status failed:", error);
    return sendJson(res, 400, { message: error?.message || "Falha ao consultar status do push" });
  }
}

async function sendWebPushToUser(userId: string, payload: WebPushPayload) {
  await ensureWebPushConfigured();
  const result = await getPool().query(
    `
      SELECT endpoint, p256dh, auth
      FROM web_push_subscriptions
      WHERE user_id = $1 AND is_active = TRUE
    `,
    [userId],
  );

  if (result.rows.length === 0) {
    return { attempted: 0, delivered: 0 };
  }

  const serializedPayload = JSON.stringify({
    title: payload.title,
    body: payload.body || "",
    tag: payload.tag || "agentezap-push",
    icon: payload.icon || "/pwa-192.png",
    badge: payload.badge || "/pwa-badge.png",
    url: payload.url || "/",
    data: payload.data || {},
    renotify: payload.renotify ?? false,
    requireInteraction: payload.requireInteraction ?? false,
    vibrate: payload.vibrate || [],
    timestamp: payload.timestamp ?? Date.now(),
  });
  const staleEndpoints: string[] = [];
  let delivered = 0;

  await Promise.all(result.rows.map(async (subscription) => {
    try {
      await webpush.sendNotification(
        {
          endpoint: subscription.endpoint,
          keys: {
            p256dh: subscription.p256dh,
            auth: subscription.auth,
          },
        },
        serializedPayload,
        {
          TTL: Number.isFinite(payload.ttlSeconds) ? Math.max(0, Math.trunc(payload.ttlSeconds as number)) : DEFAULT_PUSH_TTL_SECONDS,
          urgency: payload.urgency || "normal",
          topic: sanitizePushTopic(payload.topic),
          timeout: 15_000,
        },
      );
      delivered += 1;
    } catch (error: any) {
      const statusCode = Number(error?.statusCode || 0);
      if (statusCode === 404 || statusCode === 410) {
        staleEndpoints.push(subscription.endpoint);
        return;
      }
      console.error(`[vercel-http] PWA push failed for user ${userId}:`, error?.message || error);
    }
  }));

  if (staleEndpoints.length > 0) {
    await getPool().query(
      "DELETE FROM web_push_subscriptions WHERE user_id = $1 AND endpoint = ANY($2::text[])",
      [userId, staleEndpoints],
    );
  }

  return { attempted: result.rows.length, delivered };
}

async function handlePwaTest(req: any, res: any) {
  const user = await requireJwtUser(req, res);
  if (!user) return;

  try {
    const result = await sendWebPushToUser(user.id, {
      title: "AgenteZap",
      body: "Push do PWA configurado com sucesso.",
      url: "/",
      tag: "agentezap-pwa-test",
      topic: "pwa-test",
      urgency: "high",
      ttlSeconds: 5 * 60,
      renotify: true,
      vibrate: [180, 80, 180],
      timestamp: Date.now(),
    });
    return sendJson(res, 200, { success: true, ...result });
  } catch (error: any) {
    console.error("[vercel-http] PWA test failed:", error);
    return sendJson(res, 500, { message: error?.message || "Falha ao enviar push de teste" });
  }
}

async function getSubscriptionWithPlan(userId: string) {
  const result = await getPool().query(
    `
      SELECT
        s.id,
        s.user_id AS "userId",
        s.plan_id AS "planId",
        s.status,
        s.data_inicio AS "dataInicio",
        s.data_fim AS "dataFim",
        s.pending_receipt AS "pendingReceipt",
        s.canais_usados AS "canaisUsados",
        s.referral_code AS "referralCode",
        s.referral_wallet_applied_amount AS "referralWalletAppliedAmount",
        s.referral_wallet_applied_at AS "referralWalletAppliedAt",
        s.coupon_code AS "couponCode",
        s.coupon_price AS "couponPrice",
        s.mp_subscription_id AS "mpSubscriptionId",
        s.mp_status AS "mpStatus",
        s.mp_init_point AS "mpInitPoint",
        s.external_reference AS "externalReference",
        s.next_payment_date AS "nextPaymentDate",
        s.payer_email AS "payerEmail",
        s.payment_method AS "paymentMethod",
        COALESCE(s.metadata, '{}'::jsonb) AS metadata,
        s.created_at AS "createdAt",
        s.updated_at AS "updatedAt",
        row_to_json(p) AS plan
      FROM subscriptions s
      INNER JOIN plans p
        ON p.id = s.plan_id
      WHERE s.user_id = $1
      ORDER BY
        CASE
          WHEN s.status = 'active' THEN 0
          WHEN s.status = 'pending' THEN 1
          ELSE 2
        END,
        s.created_at DESC
      LIMIT 1
    `,
    [userId],
  );

  const row = result.rows[0];
  if (!row) {
    return null;
  }

  return {
    id: row.id,
    userId: row.userId,
    planId: row.planId,
    status: row.status,
    dataInicio: row.dataInicio,
    dataFim: row.dataFim,
    pendingReceipt: row.pendingReceipt === true,
    canaisUsados: toNumberValue(row.canaisUsados, 0),
    referralCode: row.referralCode,
    referralWalletAppliedAmount: row.referralWalletAppliedAmount,
    referralWalletAppliedAt: row.referralWalletAppliedAt,
    couponCode: row.couponCode,
    couponPrice: shouldPreserveSubscriptionCouponPrice(row) ? row.couponPrice : null,
    mpSubscriptionId: row.mpSubscriptionId,
    mpStatus: row.mpStatus,
    mpInitPoint: row.mpInitPoint,
    externalReference: row.externalReference,
    nextPaymentDate: row.nextPaymentDate,
    payerEmail: row.payerEmail,
    paymentMethod: row.paymentMethod,
    metadata: row.metadata && typeof row.metadata === "object" ? row.metadata : {},
    createdAt: row.createdAt,
    updatedAt: row.updatedAt,
    plan: row.plan ? toCamelRecord(row.plan as Record<string, any>) : null,
  };
}

