async function generateManualPixQRCode(paymentData: {
  planNome: string;
  valor: number;
  subscriptionId: string;
}) {
  const config = await getSystemConfigMap(["pix_key", "merchant_name", "merchant_city"]);
  const pixKeyRaw = config.get("pix_key") || "rodrigoconexao128@gmail.com";
  const merchantNameRaw = config.get("merchant_name") || "RODRIGO MACEDO";
  const merchantCityRaw = config.get("merchant_city") || "COSMORAMA";

  let pixKey = String(pixKeyRaw).replace(/\s+/g, "").trim();
  const cleanKey = pixKey.replace(/\+55/g, "");
  let onlyDigits = cleanKey.replace(/\D/g, "");
  if (onlyDigits.length >= 10 && onlyDigits.length <= 13) {
    if (onlyDigits.length >= 12 && onlyDigits.startsWith("55")) {
      onlyDigits = onlyDigits.substring(2);
    }
    pixKey = `+55${onlyDigits}`;
  }

  const sanitize = (value: string, max: number) =>
    (value || "")
      .normalize("NFD")
      .replace(/[\u0300-\u036f]/g, "")
      .replace(/[^A-Za-z0-9 ]/g, "")
      .replace(/\s+/g, " ")
      .trim()
      .toUpperCase()
      .slice(0, max);

  const tlv = (id: string, value: string) => id + String(value.length).padStart(2, "0") + value;
  const baseId = String(paymentData.subscriptionId || "").replace(/[^A-Za-z0-9]/g, "").toUpperCase();
  const randomSuffix = Math.random().toString(36).toUpperCase().replace(/[^A-Z0-9]/g, "").substring(0, 10);
  const txid = (baseId + randomSuffix).substring(0, 25) || `TX${Date.now().toString().substring(0, 23)}`;
  const amount = Math.max(0.01, Number(paymentData.valor || 0)).toFixed(2);
  const merchantAccountInfo = tlv("26", tlv("00", "br.gov.bcb.pix") + tlv("01", pixKey));
  const payloadBase =
    tlv("00", "01") +
    tlv("01", "11") +
    merchantAccountInfo +
    tlv("52", "0000") +
    tlv("53", "986") +
    tlv("54", amount) +
    tlv("58", "BR") +
    tlv("59", sanitize(merchantNameRaw, 25)) +
    tlv("60", sanitize(merchantCityRaw, 15)) +
    tlv("62", tlv("05", txid));

  const crcInput = `${payloadBase}6304`;
  let crc = 0xffff;
  for (let index = 0; index < crcInput.length; index += 1) {
    crc ^= crcInput.charCodeAt(index) << 8;
    for (let bit = 0; bit < 8; bit += 1) {
      crc = (crc & 0x8000) ? ((crc << 1) ^ 0x1021) : (crc << 1);
      crc &= 0xffff;
    }
  }

  const pixCode = `${crcInput}${crc.toString(16).toUpperCase().padStart(4, "0")}`;
  const pixQrCode = await QRCode.toDataURL(pixCode, {
    errorCorrectionLevel: "M",
    type: "image/png",
    margin: 1,
    width: 300,
  });

  return { pixCode, pixQrCode };
}

