function normalizeStringArray(value: unknown) {
  if (!Array.isArray(value)) {
    return [];
  }

  return value
    .map((item) => String(item ?? "").trim())
    .filter(Boolean);
}

function normalizeNullableString(value: unknown) {
  if (value === null || value === undefined) return null;
  const text = String(value).trim();
  return text ? text : null;
}

function normalizeBoolean(value: unknown) {
  return value === true || value === "true" || value === 1 || value === "1";
}

function normalizeTeamMemberPermissions(raw: any) {
  return {
    canViewConversations: raw?.canViewConversations !== false,
    canSendMessages: raw?.canSendMessages !== false,
    canUseQuickReplies: raw?.canUseQuickReplies !== false,
    canMoveKanban: raw?.canMoveKanban !== false,
    canViewDashboard: raw?.canViewDashboard === true,
    canEditContacts: raw?.canEditContacts === true,
    canViewPhoneNumbers: raw?.canViewPhoneNumbers === true,
  };
}

function toSafeTeamMember(row: any) {
  return {
    id: row.id,
    ownerId: row.ownerId ?? row.owner_id,
    name: row.name,
    email: row.email,
    role: row.role || "atendente",
    permissions: normalizeTeamMemberPermissions(row.permissions || {}),
    isActive: row.isActive ?? row.is_active === true,
    avatarUrl: row.avatarUrl ?? row.avatar_url ?? null,
    signature: row.signature || null,
    signatureEnabled: row.signatureEnabled ?? row.signature_enabled === true,
    lastLoginAt: row.lastLoginAt ?? row.last_login_at ?? null,
    createdAt: row.createdAt ?? row.created_at ?? null,
    updatedAt: row.updatedAt ?? row.updated_at ?? null,
  };
}

function generateRandomPassword(length = 10) {
  return randomBytes(Math.max(8, Math.ceil(length * 0.75)))
    .toString("base64url")
    .replace(/[^a-zA-Z0-9]/g, "")
    .slice(0, length);
}

function normalizeContactListContacts(value: unknown) {
  if (!Array.isArray(value)) {
    return [];
  }

  return value
    .map((entry, index) => {
      const record = entry && typeof entry === "object" ? (entry as Record<string, unknown>) : {};
      const phone = String(record.phone || "").replace(/\D/g, "");
      if (!phone) {
        return null;
      }

      return {
        id: String(record.id || `contact_${Date.now()}_${index}`),
        name: String(record.name || "").trim(),
        phone,
      };
    })
    .filter((entry): entry is { id: string; name: string; phone: string } => Boolean(entry));
}

async function createPromptVersion(userId: string, promptContent: string, editType: string, editSummary: string) {
  const db = getPool();
  const nextVersionResult = await db.query(
    `
      SELECT COALESCE(MAX(version_number), 0) + 1 AS next_version
      FROM prompt_versions
      WHERE user_id = $1
        AND config_type = 'ai_agent_config'
    `,
    [userId],
  );

  const versionNumber = toNumberValue(nextVersionResult.rows[0]?.next_version, 1);
  await db.query(
    `
      UPDATE prompt_versions
      SET is_current = false
      WHERE user_id = $1
        AND config_type = 'ai_agent_config'
    `,
    [userId],
  );

  const insertResult = await db.query(
    `
      INSERT INTO prompt_versions (
        user_id,
        config_type,
        version_number,
        prompt_content,
        edit_summary,
        edit_type,
        is_current,
        created_at
      )
      VALUES ($1, 'ai_agent_config', $2, $3, $4, $5, true, NOW())
      RETURNING id, version_number, prompt_content, is_current
    `,
    [userId, versionNumber, promptContent, editSummary, editType],
  );

  return insertResult.rows[0] || null;
}

async function upsertAgentConfigRecord(userId: string, payload: Record<string, unknown>) {
  const db = getPool();
  const existingResult = await db.query("SELECT * FROM ai_agent_config WHERE user_id = $1 LIMIT 1", [userId]);
  const existing = existingResult.rows[0] || null;

  const mapped: Record<string, unknown> = {};
  if (payload.prompt !== undefined) mapped.prompt = String(payload.prompt || "");
  if (payload.isActive !== undefined) mapped.is_active = payload.isActive === true;
  if (payload.triggerPhrases !== undefined) mapped.trigger_phrases = normalizeStringArray(payload.triggerPhrases);
  if (payload.messageSplitChars !== undefined) mapped.message_split_chars = toNumberValue(payload.messageSplitChars, 400);
  if (payload.responseDelaySeconds !== undefined) mapped.response_delay_seconds = toNumberValue(payload.responseDelaySeconds, 30);
  if (payload.fetchHistoryOnFirstResponse !== undefined) mapped.fetch_history_on_first_response = payload.fetchHistoryOnFirstResponse === true;
  if (payload.pauseOnManualReply !== undefined) mapped.pause_on_manual_reply = payload.pauseOnManualReply === true;
  if (payload.autoReactivateMinutes !== undefined) mapped.auto_reactivate_minutes = normalizeAutoReactivateMinutes(payload.autoReactivateMinutes);
  if (payload.customGreeting !== undefined) mapped.custom_greeting = payload.customGreeting ? String(payload.customGreeting) : null;
  if (payload.customAddress !== undefined) mapped.custom_address = payload.customAddress ? String(payload.customAddress) : null;
  if (payload.greetingVariation !== undefined) mapped.greeting_variation = normalizeBoolean(payload.greetingVariation);
  if (payload.greetingEnabled !== undefined) mapped.greeting_enabled = payload.greetingEnabled === true;
  if (payload.aiSignatureEnabled !== undefined) mapped.ai_signature_enabled = normalizeBoolean(payload.aiSignatureEnabled);
  if (payload.aiSignature !== undefined) mapped.ai_signature = normalizeNullableString(payload.aiSignature);
  if (payload.addressEnabled !== undefined) mapped.address_enabled = payload.addressEnabled === true;
  if (payload.businessHoursEnabled !== undefined) mapped.business_hours_enabled = normalizeBoolean(payload.businessHoursEnabled);
  if (payload.businessHours !== undefined) mapped.business_hours = payload.businessHours && typeof payload.businessHours === "object" ? payload.businessHours : null;
  if (payload.offHoursMessageEnabled !== undefined) mapped.off_hours_message_enabled = normalizeBoolean(payload.offHoursMessageEnabled);
  if (payload.offHoursVariation !== undefined) mapped.off_hours_variation = normalizeBoolean(payload.offHoursVariation);
  if (payload.offHoursMessage !== undefined) mapped.off_hours_message = normalizeNullableString(payload.offHoursMessage);
  if (payload.flowScript !== undefined) mapped.flow_script = payload.flowScript ? String(payload.flowScript) : null;
  if (payload.flowModeActive !== undefined) mapped.flow_mode_active = payload.flowModeActive === true;

  let row;
  if (existing) {
    const entries = Object.entries(mapped);
    if (entries.length === 0) {
      row = existing;
    } else {
      const values: unknown[] = [userId];
      const sets = entries.map(([key, value], index) => {
        values.push(value);
        return `${key} = $${values.length}`;
      });
      sets.push(`updated_at = NOW()`);

      const updateResult = await db.query(
        `UPDATE ai_agent_config SET ${sets.join(", ")} WHERE user_id = $1 RETURNING *`,
        values,
      );
      row = updateResult.rows[0] || existing;
    }
  } else {
    const defaults: Record<string, unknown> = {
      prompt: mapped.prompt ?? "Voce e um assistente virtual prestativo.",
      is_active: mapped.is_active ?? true,
      model: "mistral-large-latest",
      trigger_phrases: mapped.trigger_phrases ?? [],
      message_split_chars: mapped.message_split_chars ?? 400,
      response_delay_seconds: mapped.response_delay_seconds ?? 30,
      fetch_history_on_first_response: mapped.fetch_history_on_first_response ?? false,
      pause_on_manual_reply: mapped.pause_on_manual_reply ?? false,
      auto_reactivate_minutes: mapped.auto_reactivate_minutes ?? null,
      custom_greeting: mapped.custom_greeting ?? null,
      custom_address: mapped.custom_address ?? null,
      greeting_variation: mapped.greeting_variation ?? false,
      greeting_enabled: mapped.greeting_enabled ?? false,
      ai_signature_enabled: mapped.ai_signature_enabled ?? false,
      ai_signature: mapped.ai_signature ?? null,
      address_enabled: mapped.address_enabled ?? false,
      business_hours_enabled: mapped.business_hours_enabled ?? false,
      business_hours: mapped.business_hours ?? null,
      off_hours_message_enabled: mapped.off_hours_message_enabled ?? false,
      off_hours_variation: mapped.off_hours_variation ?? false,
      off_hours_message: mapped.off_hours_message ?? "Ola! No momento estamos fora do horario de atendimento. Retornaremos em breve!",
      flow_script: mapped.flow_script ?? null,
      flow_mode_active: mapped.flow_mode_active ?? false,
    };

    const insertColumns = ["user_id", ...Object.keys(defaults)];
    const insertValues = [userId, ...Object.values(defaults)];
    const placeholders = insertValues.map((_value, index) => `$${index + 1}`);
    const insertResult = await db.query(
      `INSERT INTO ai_agent_config (${insertColumns.join(", ")}) VALUES (${placeholders.join(", ")}) RETURNING *`,
      insertValues,
    );
    row = insertResult.rows[0] || null;
  }

  if (payload.isActive !== undefined) {
    await db.query(
      `
        INSERT INTO business_agent_configs (
          user_id,
          agent_name,
          agent_role,
          company_name,
          is_active,
          created_at,
          updated_at
        )
        VALUES ($1, 'Assistente', 'Assistente Virtual', 'Minha Empresa', $2, NOW(), NOW())
        ON CONFLICT (user_id)
        DO UPDATE SET
          is_active = EXCLUDED.is_active,
          updated_at = NOW()
      `,
      [userId, payload.isActive === true],
    );
  }

  return row;
}

async function handleDailyLimits(req: any, res: any) {
  const user = await requireJwtUser(req, res);
  if (!user) return;

  try {
    const subscription = await getSubscriptionWithPlan(user.id);
    const calibrationStatus = await getPromptEditDailyLimitStatus(user.id, subscription);
    if (isSubscriptionActive(subscription)) {
      return sendJson(res, 200, {
        hasActiveSubscription: true,
        calibration: calibrationStatus,
        simulator: { used: 0, limit: -1, remaining: -1, isLimitReached: false },
      });
    }

    const dailyUsage = await getTodayDailyUsageCounts(user.id);
    const simulatorMessagesCount = toNumberValue(dailyUsage.simulatorMessagesCount, 0);

    return sendJson(res, 200, {
      hasActiveSubscription: false,
      calibration: calibrationStatus,
      simulator: {
        used: simulatorMessagesCount,
        limit: FREE_DAILY_SIMULATOR_LIMIT,
        remaining: Math.max(0, FREE_DAILY_SIMULATOR_LIMIT - simulatorMessagesCount),
        isLimitReached: simulatorMessagesCount >= FREE_DAILY_SIMULATOR_LIMIT,
      },
    });
  } catch (error) {
    console.error("[vercel-http] daily limits failed:", error);
    return sendJson(res, 500, { message: "Failed to fetch daily limits" });
  }
}

async function getTodayDailyUsageCounts(userId: string) {
  const dailyUsageResult = await getPool().query(
    `
      SELECT prompt_edits_count AS "promptEditsCount", simulator_messages_count AS "simulatorMessagesCount"
      FROM daily_usage
      WHERE user_id = $1
        AND usage_date = (NOW() AT TIME ZONE 'America/Sao_Paulo')::date
      ORDER BY usage_date DESC
      LIMIT 1
    `,
    [userId],
  );

  return dailyUsageResult.rows[0] || { promptEditsCount: 0, simulatorMessagesCount: 0 };
}

async function getPromptEditDailyLimitStatus(userId: string, subscription?: any | null) {
  const resolvedSubscription = subscription === undefined ? await getSubscriptionWithPlan(userId) : subscription;
  if (isSubscriptionActive(resolvedSubscription)) {
    return { used: 0, limit: -1, remaining: -1, isLimitReached: false, isUnlimited: true };
  }

  const dailyUsage = await getTodayDailyUsageCounts(userId);
  const promptEditsCount = toNumberValue(dailyUsage.promptEditsCount, 0);

  return {
    used: promptEditsCount,
    limit: FREE_DAILY_CALIBRATION_LIMIT,
    remaining: Math.max(0, FREE_DAILY_CALIBRATION_LIMIT - promptEditsCount),
    isLimitReached: promptEditsCount >= FREE_DAILY_CALIBRATION_LIMIT,
    isUnlimited: false,
  };
}

async function consumePromptEditDailyLimit(userId: string, subscription?: any | null) {
  const resolvedSubscription = subscription === undefined ? await getSubscriptionWithPlan(userId) : subscription;
  if (isSubscriptionActive(resolvedSubscription)) {
    return {
      allowed: true,
      status: { used: 0, limit: -1, remaining: -1, isLimitReached: false, isUnlimited: true },
    };
  }

  const client = await getPool().connect();
  try {
    await client.query("BEGIN");
    await client.query(
      `
        INSERT INTO daily_usage (
          user_id,
          usage_date,
          prompt_edits_count,
          simulator_messages_count,
          created_at,
          updated_at
        )
        VALUES ($1, (NOW() AT TIME ZONE 'America/Sao_Paulo')::date, 0, 0, NOW(), NOW())
        ON CONFLICT (user_id, usage_date) DO NOTHING
      `,
      [userId],
    );

    const currentResult = await client.query(
      `
        SELECT prompt_edits_count AS "promptEditsCount"
        FROM daily_usage
        WHERE user_id = $1
          AND usage_date = (NOW() AT TIME ZONE 'America/Sao_Paulo')::date
        FOR UPDATE
      `,
      [userId],
    );
    const used = toNumberValue(currentResult.rows[0]?.promptEditsCount, 0);
    if (used >= FREE_DAILY_CALIBRATION_LIMIT) {
      await client.query("ROLLBACK");
      return {
        allowed: false,
        status: {
          used,
          limit: FREE_DAILY_CALIBRATION_LIMIT,
          remaining: 0,
          isLimitReached: true,
          isUnlimited: false,
        },
      };
    }

    const updatedResult = await client.query(
      `
        UPDATE daily_usage
        SET prompt_edits_count = prompt_edits_count + 1,
            updated_at = NOW()
        WHERE user_id = $1
          AND usage_date = (NOW() AT TIME ZONE 'America/Sao_Paulo')::date
        RETURNING prompt_edits_count AS "promptEditsCount"
      `,
      [userId],
    );
    await client.query("COMMIT");
    const nextUsed = toNumberValue(updatedResult.rows[0]?.promptEditsCount, used + 1);
    return {
      allowed: true,
      status: {
        used: nextUsed,
        limit: FREE_DAILY_CALIBRATION_LIMIT,
        remaining: Math.max(0, FREE_DAILY_CALIBRATION_LIMIT - nextUsed),
        isLimitReached: nextUsed >= FREE_DAILY_CALIBRATION_LIMIT,
        isUnlimited: false,
      },
    };
  } catch (error) {
    try {
      await client.query("ROLLBACK");
    } catch {
      // Ignore rollback errors and surface the original failure.
    }
    throw error;
  } finally {
    client.release();
  }
}

async function getPrimaryAgentMessagesCount(userId: string) {
  const connections = getAppVisibleConnections(await getConnectionsByUserId(userId));
  const selected = pickPreferredConnection(connections);
  if (!selected) {
    return 0;
  }

  const result = await getPool().query(
    `
      SELECT COUNT(*)::int AS count
      FROM messages m
      INNER JOIN conversations c
        ON c.id = m.conversation_id
      WHERE c.connection_id = $1
        AND m.is_from_agent = true
    `,
    [selected.id],
  );

  return toNumberValue(result.rows[0]?.count, 0);
}

function isSubscriptionActive(subscription: any) {
  if (!subscription) {
    return false;
  }

  const status = String(subscription.status || "").trim().toLowerCase();
  if (status !== "active") {
    return false;
  }

  const endDate = subscription.nextPaymentDate || subscription.dataFim;
  if (!endDate) {
    return true;
  }

  const endTime = new Date(String(endDate)).getTime();
  if (!Number.isFinite(endTime)) {
    return true;
  }

  return endTime >= Date.now();
}

function isSubscriptionExpiredForAccess(subscription: any) {
  if (!subscription) {
    return false;
  }

  const status = String(subscription.status || "").trim().toLowerCase();
  const endDate = subscription.nextPaymentDate || subscription.dataFim;
  if (status === "active") {
    if (!endDate) {
      return false;
    }
    const time = new Date(String(endDate)).getTime();
    return Number.isFinite(time) && time < Date.now();
  }

  if (["expired", "overdue", "blocked", "suspended"].includes(status)) {
    return true;
  }

  if (status === "cancelled" && endDate) {
    const time = new Date(String(endDate)).getTime();
    return Number.isFinite(time) && time < Date.now();
  }

  return false;
}

function getSubscriptionDaysRemaining(subscription: any) {
  const endDate = subscription?.nextPaymentDate || subscription?.dataFim;
  if (!endDate) {
    return subscription ? 9999 : 0;
  }

  const time = new Date(String(endDate)).getTime();
  if (!Number.isFinite(time)) {
    return subscription ? 9999 : 0;
  }

  return Math.max(0, Math.ceil((time - Date.now()) / (1000 * 60 * 60 * 24)));
}

const accessStatusCache = new Map<string, { data: Record<string, unknown>; expiresAt: number; staleUntil: number }>();
const ACCESS_STATUS_CACHE_TTL_MS = 45 * 1000;
const ACCESS_STATUS_STALE_TTL_MS = 10 * 60 * 1000;

function buildTemporaryAccessStatusPayload(cached?: Record<string, unknown>) {
  const base = {
    accessStatus: "temporary_unavailable",
    shouldBlock: false,
    blockReason: null,
    hasSubscription: false,
    subscriptionStatus: null,
    isSubscriptionExpired: false,
    daysRemaining: 0,
    subscriptionEndDate: null,
    planName: null,
    trialMessagesUsed: 0,
    trialMessagesRemaining: FREE_DAILY_SIMULATOR_LIMIT,
    trialMessagesLimit: FREE_DAILY_SIMULATOR_LIMIT,
    trialLimitReached: false,
    resellerInfo: null,
    message: null,
  };

  return {
    ...base,
    ...(cached || {}),
    temporaryUnavailable: true,
    fromStaleCache: Boolean(cached),
    shouldBlock: false,
    blockReason: null,
  };
}

async function applyAddonUpsellOrder(subscription: Record<string, any>) {
  const metadata = getSubscriptionMetadataRecord(subscription);
  const targetSubscriptionId = String(metadata.checkoutTargetSubscriptionId || metadata.targetSubscriptionId || "").trim();
  const purchasedAddonIds = getPurchasedAddonIdsFromSubscription(subscription);
  if (!targetSubscriptionId) {
    return null;
  }

  const targetSubscription = await getSubscriptionByIdWithPlan(targetSubscriptionId, String(subscription.userId || subscription.user_id || "").trim());
  if (!targetSubscription) {
    return null;
  }

  const mergedMetadata = mergeSubscriptionMetadata(targetSubscription as Record<string, any>, {
    selectedAddonIds: Array.isArray(metadata.selectedAddonIds)
      ? metadata.selectedAddonIds.map((id: unknown) => String(id || "").trim()).filter(Boolean)
      : getSubscriptionSelectedAddonIds(targetSubscription as Record<string, any>),
    checkoutTier: metadata.checkoutTier || getSubscriptionMetadataRecord(targetSubscription as Record<string, any>).checkoutTier || "base",
    checkoutPeriod: metadata.checkoutPeriod || getSubscriptionMetadataRecord(targetSubscription as Record<string, any>).checkoutPeriod || null,
    lastAddonUpsellAt: new Date().toISOString(),
    lastAddonUpsellOrderId: subscription.id,
    lastPurchasedAddonIds: Array.isArray(metadata.purchasedAddonIds)
      ? metadata.purchasedAddonIds.map((id: unknown) => String(id || "").trim()).filter(Boolean)
      : [],
  });

  await getPool().query(
    `
      UPDATE subscriptions
      SET metadata = $2::jsonb,
          updated_at = NOW()
      WHERE id = $1
    `,
    [targetSubscription.id, JSON.stringify(mergedMetadata)],
  );

  await getPool().query(
    `
      UPDATE subscriptions
      SET status = 'cancelled',
          pending_receipt = false,
          data_fim = COALESCE(data_fim, NOW()),
          updated_at = NOW()
      WHERE id = $1
    `,
    [subscription.id],
  );

  const targetSubscriptionRecord = targetSubscription as Record<string, any>;
  const refreshedTargetSubscription = await getSubscriptionByIdWithPlan(
    String(targetSubscriptionRecord.id),
    String(targetSubscriptionRecord.userId || targetSubscriptionRecord.user_id || "").trim(),
  );
  const resolvedTargetSubscription = (refreshedTargetSubscription || targetSubscription) as Record<string, any>;
  await syncSpecialistAddonRecords({
    baseSubscription: resolvedTargetSubscription,
    purchasedAddonIds,
    sourceOrderId: String(subscription.id || "").trim() || null,
  });
  return resolvedTargetSubscription;
}

async function buildAccessStatusPayloadForUser(userId: string, subscription?: any | null, agentMessagesCount?: number) {
  const resolvedSubscription = subscription === undefined ? await getSubscriptionWithPlan(userId) : subscription;
  const hasActiveSubscription = isSubscriptionActive(resolvedSubscription);
  const isSubscriptionExpired = isSubscriptionExpiredForAccess(resolvedSubscription);
  const resolvedAgentMessagesCount =
    typeof agentMessagesCount === "number" ? agentMessagesCount : await getPrimaryAgentMessagesCount(userId);
  const trialLimit = FREE_DAILY_SIMULATOR_LIMIT;
  const trialMessagesRemaining = Math.max(0, trialLimit - resolvedAgentMessagesCount);
  const trialLimitReached = !hasActiveSubscription && !isSubscriptionExpired && resolvedAgentMessagesCount >= trialLimit;
  const daysRemaining = getSubscriptionDaysRemaining(resolvedSubscription);
  const accessStatus = hasActiveSubscription ? "active" : isSubscriptionExpired ? "expired" : trialLimitReached ? "blocked" : "trial";
  const blockReason = isSubscriptionExpired ? "subscription_expired" : trialLimitReached ? "trial_limit_reached" : null;

  return {
    accessStatus,
    shouldBlock: Boolean(blockReason),
    blockReason,
    hasSubscription: Boolean(resolvedSubscription),
    subscriptionStatus: resolvedSubscription?.status || null,
    isSubscriptionExpired,
    daysRemaining,
    subscriptionEndDate: resolvedSubscription?.nextPaymentDate || resolvedSubscription?.dataFim || null,
    planName: resolvedSubscription?.plan?.nome || null,
    trialMessagesUsed: resolvedAgentMessagesCount,
    trialMessagesRemaining,
    trialMessagesLimit: trialLimit,
    trialLimitReached,
    resellerInfo: null,
    message: isSubscriptionExpired
      ? "Sua assinatura venceu. Renove para reativar o sistema e a IA."
      : trialLimitReached
      ? "Voce atingiu o limite de mensagens de teste. Assine um plano para continuar."
      : null,
  };
}

async function buildUsagePayloadForUser(userId: string, subscription?: any | null, agentMessagesCount?: number) {
  const resolvedSubscription = subscription === undefined ? await getSubscriptionWithPlan(userId) : subscription;
  const hasActiveSubscription = isSubscriptionActive(resolvedSubscription);
  const isSubscriptionExpired = isSubscriptionExpiredForAccess(resolvedSubscription);
  const resolvedAgentMessagesCount =
    typeof agentMessagesCount === "number" ? agentMessagesCount : await getPrimaryAgentMessagesCount(userId);
  const limit = hasActiveSubscription ? -1 : isSubscriptionExpired ? 0 : FREE_DAILY_SIMULATOR_LIMIT;

  return {
    agentMessagesCount: resolvedAgentMessagesCount,
    limit,
    remaining: hasActiveSubscription ? -1 : isSubscriptionExpired ? 0 : Math.max(0, FREE_DAILY_SIMULATOR_LIMIT - resolvedAgentMessagesCount),
    isLimitReached: isSubscriptionExpired || (!hasActiveSubscription && resolvedAgentMessagesCount >= FREE_DAILY_SIMULATOR_LIMIT),
    hasActiveSubscription,
    planName: resolvedSubscription?.plan?.nome || null,
    blockReason: isSubscriptionExpired
      ? "subscription_expired"
      : !hasActiveSubscription && resolvedAgentMessagesCount >= FREE_DAILY_SIMULATOR_LIMIT
        ? "trial_limit_reached"
        : null,
  };
}

async function handleAccessStatus(req: any, res: any) {
  const user = await requireJwtUser(req, res);
  if (!user) return;

  try {
    const cached = accessStatusCache.get(user.id);
    if (cached && cached.expiresAt > Date.now()) {
      return sendJson(res, 200, cached.data);
    }

    const payload = await buildAccessStatusPayloadForUser(user.id);
    accessStatusCache.set(user.id, {
      data: payload,
      expiresAt: Date.now() + ACCESS_STATUS_CACHE_TTL_MS,
      staleUntil: Date.now() + ACCESS_STATUS_STALE_TTL_MS,
    });
    return sendJson(res, 200, payload);
  } catch (error) {
    console.error("[vercel-http] access status failed:", error);
    if (isPgConnectionAcquireTimeout(error)) {
      const cached = accessStatusCache.get(user.id);
      if (cached?.data && cached.staleUntil > Date.now()) {
        return sendJson(res, 200, buildTemporaryAccessStatusPayload(cached.data));
      }
      return sendJson(res, 200, buildTemporaryAccessStatusPayload());
    }
    return sendJson(res, 500, { message: "Failed to check access status" });
  }
}

