async function buildStatsPayloadForUser(user: AuthenticatedUser, requestedConnectionId = "") {
  const visibleConnections = getAppVisibleConnections(await getConnectionsByUserId(user.id));
  const targetConnections = requestedConnectionId
    ? visibleConnections.filter((connection) => connection.id === requestedConnectionId)
    : visibleConnections;

  if (requestedConnectionId && targetConnections.length === 0) {
    const notFound = new Error("Conexao nao encontrada");
    (notFound as any).statusCode = 404;
    throw notFound;
  }

  const connectionIds = targetConnections.map((connection) => connection.id).filter(Boolean);
  if (connectionIds.length === 0) {
    return {
      totalConversations: 0,
      unreadMessages: 0,
      todayMessages: 0,
      agentMessages: 0,
    };
  }

  const result = await getPool().query(
    `
      WITH target_conversations AS (
        SELECT
          c.id,
          COALESCE(c.unread_count, 0)::int AS unread_count
        FROM conversations c
        WHERE c.connection_id = ANY($1::varchar[])
      )
      SELECT
        (SELECT COUNT(*)::int FROM target_conversations) AS "totalConversations",
        (SELECT COALESCE(SUM(unread_count), 0)::int FROM target_conversations) AS "unreadMessages",
        (
          SELECT COUNT(*)::int
          FROM messages m
          INNER JOIN target_conversations tc ON tc.id = m.conversation_id
          WHERE m.timestamp >= (
            date_trunc('day', NOW() AT TIME ZONE 'America/Sao_Paulo')
            AT TIME ZONE 'America/Sao_Paulo'
          )
        ) AS "todayMessages",
        (
          SELECT COUNT(*)::int
          FROM messages m
          INNER JOIN target_conversations tc ON tc.id = m.conversation_id
          WHERE m.is_from_agent = true
        ) AS "agentMessages"
    `,
    [connectionIds],
  );

  const row = result.rows[0] || {};
  return {
    totalConversations: Number(row.totalConversations || 0),
    unreadMessages: Number(row.unreadMessages || 0),
    todayMessages: Number(row.todayMessages || 0),
    agentMessages: Number(row.agentMessages || 0),
  };
}

async function handleStats(req: any, res: any) {
  const user = await requireUserOrTeamMember(req, res);
  if (!user) return;

  if (isTeamMemberUser(user)) {
    if (user.memberData.permissions.canViewDashboard === false) {
      return sendJson(res, 403, { message: "Permissao insuficiente para visualizar o dashboard." });
    }
    if (user.memberData.permissions.canViewConversations === false) {
      return sendJson(res, 200, {
        totalConversations: 0,
        unreadMessages: 0,
        todayMessages: 0,
        agentMessages: 0,
      });
    }
  }

  try {
    const requestedConnectionId = String(req.query?.connectionId || "").trim();
    return sendJson(res, 200, await buildStatsPayloadForUser(user, requestedConnectionId));
  } catch (error) {
    console.error("[vercel-http] stats failed:", error);
    if ((error as any)?.statusCode === 404) {
      return sendJson(res, 404, { message: "Conexao nao encontrada" });
    }
    return sendJson(res, 500, { message: "Failed to fetch stats" });
  }
}

async function buildUserSuspensionStatusPayload(userId: string) {
  const result = await getPool().query(
    `
      SELECT
        suspended_at AS "suspendedAt",
        suspension_reason AS "reason",
        suspension_type AS "type",
        refunded_at AS "refundedAt",
        refund_amount AS "refundAmount"
      FROM users
      WHERE id = $1
      LIMIT 1
    `,
    [userId],
  );
  const row = result.rows[0];

  if (!row?.suspendedAt) {
    return { suspended: false };
  }

  return {
    suspended: true,
    reason: row.reason || null,
    type: row.type || null,
    suspendedAt: row.suspendedAt,
    refundedAt: row.refundedAt || null,
    refundAmount: row.refundAmount == null ? null : Number(row.refundAmount),
  };
}

