async function buildResellerStatusPayloadForUser(userId: string, subscription?: any | null) {
  const resolvedSubscription = subscription === undefined ? await getSubscriptionWithPlan(userId) : subscription;
  const planType = String(resolvedSubscription?.plan?.tipo || "").trim().toLowerCase();
  const resellerResult = await getPool().query("SELECT * FROM resellers WHERE user_id = $1 LIMIT 1", [userId]);
  const reseller = resellerResult.rows[0] ? toCamelRecord(resellerResult.rows[0]) : null;
  const hasResellerPlan = Boolean(reseller) || (isSubscriptionActive(resolvedSubscription) && planType.includes("revenda"));

  return {
    hasResellerPlan,
    reseller,
  };
}

