async function handleDeliveryConfig(req: any, res: any) {
  const user = await requireJwtUser(req, res);
  if (!user) return;

  try {
    if (req.method === "GET") {
      const result = await getPool().query("SELECT * FROM delivery_config WHERE user_id = $1 LIMIT 1", [user.id]);
      return sendJson(res, 200, result.rows[0] || defaultDeliveryConfig(user.id));
    }

    const body = await readJsonBody(req);
    const fieldMappings: Record<string, string> = {
      isActive: "is_active",
      is_active: "is_active",
      sendToAi: "send_to_ai",
      send_to_ai: "send_to_ai",
      businessName: "business_name",
      business_name: "business_name",
      businessType: "business_type",
      business_type: "business_type",
      menuSendMode: "menu_send_mode",
      menu_send_mode: "menu_send_mode",
      deliveryFee: "delivery_fee",
      delivery_fee: "delivery_fee",
      minOrderValue: "min_order_value",
      min_order_value: "min_order_value",
      estimatedDeliveryTime: "estimated_delivery_time",
      estimated_delivery_time: "estimated_delivery_time",
      deliveryRadiusKm: "delivery_radius_km",
      delivery_radius_km: "delivery_radius_km",
      paymentMethods: "payment_methods",
      payment_methods: "payment_methods",
      acceptsDelivery: "accepts_delivery",
      accepts_delivery: "accepts_delivery",
      acceptsPickup: "accepts_pickup",
      accepts_pickup: "accepts_pickup",
      openingHours: "opening_hours",
      opening_hours: "opening_hours",
      aiInstructions: "ai_instructions",
      ai_instructions: "ai_instructions",
      displayInstructions: "display_instructions",
      display_instructions: "display_instructions",
      whatsappOrderNumber: "whatsapp_order_number",
      whatsapp_order_number: "whatsapp_order_number",
    };
    const updateData: Record<string, unknown> = { updated_at: new Date().toISOString() };
    for (const [key, value] of Object.entries(body || {})) {
      const dbField = fieldMappings[key];
      if (dbField && value !== undefined) {
        updateData[dbField] = value;
      }
    }

    const existing = await getPool().query("SELECT id FROM delivery_config WHERE user_id = $1 LIMIT 1", [user.id]);
    let result;
    if (existing.rows[0]?.id) {
      const columns = Object.keys(updateData);
      const values = Object.values(updateData);
      const assignments = columns.map((column, index) => `${column} = $${index + 1}`).join(", ");
      result = await getPool().query(
        `UPDATE delivery_config SET ${assignments} WHERE user_id = $${columns.length + 1} RETURNING *`,
        [...values, user.id],
      );
    } else {
      const columns = ["user_id", ...Object.keys(updateData)];
      const values = [user.id, ...Object.values(updateData)];
      const placeholders = columns.map((_column, index) => `$${index + 1}`).join(", ");
      result = await getPool().query(
        `INSERT INTO delivery_config (${columns.join(", ")}) VALUES (${placeholders}) RETURNING *`,
        values,
      );
    }

    return sendJson(res, 200, result.rows[0] || defaultDeliveryConfig(user.id));
  } catch (error) {
    console.error("[vercel-http] delivery config failed:", error);
    return sendJson(res, 500, { message: "Failed to fetch delivery config" });
  }
}

function defaultDelivery2Config(userId: string) {
  return {
    id: null,
    user_id: userId,
    is_active: false,
    send_to_ai: true,
    display_name: "Delivery 2.0",
    menu_auto_send_on_greeting: false,
    menu_auto_send_on_request: true,
  };
}

async function handleDelivery2Config(req: any, res: any) {
  const user = await requireJwtUser(req, res);
  if (!user) return;

  try {
    if (req.method === "GET") {
      const result = await getPool().query("SELECT * FROM delivery2_config WHERE user_id = $1 LIMIT 1", [user.id]);
      return sendJson(res, 200, result.rows[0] || defaultDelivery2Config(user.id));
    }

    const body = await readJsonBody(req);
    const fieldMappings: Record<string, string> = {
      isActive: "is_active",
      is_active: "is_active",
      sendToAi: "send_to_ai",
      send_to_ai: "send_to_ai",
      displayName: "display_name",
      display_name: "display_name",
      menuAutoSendOnGreeting: "menu_auto_send_on_greeting",
      menu_auto_send_on_greeting: "menu_auto_send_on_greeting",
      menuAutoSendOnRequest: "menu_auto_send_on_request",
      menu_auto_send_on_request: "menu_auto_send_on_request",
    };
    const updateData: Record<string, unknown> = { updated_at: new Date().toISOString() };
    for (const [key, value] of Object.entries(body || {})) {
      const dbField = fieldMappings[key];
      if (dbField && value !== undefined) {
        updateData[dbField] = value;
      }
    }

    const existing = await getPool().query("SELECT id FROM delivery2_config WHERE user_id = $1 LIMIT 1", [user.id]);
    let result;
    if (existing.rows[0]?.id) {
      const columns = Object.keys(updateData);
      const values = Object.values(updateData);
      const assignments = columns.map((column, index) => `${column} = $${index + 1}`).join(", ");
      result = await getPool().query(
        `UPDATE delivery2_config SET ${assignments} WHERE user_id = $${columns.length + 1} RETURNING *`,
        [...values, user.id],
      );
    } else {
      const insertData = {
        user_id: user.id,
        is_active: false,
        send_to_ai: true,
        display_name: "Delivery 2.0",
        menu_auto_send_on_greeting: false,
        menu_auto_send_on_request: true,
        ...updateData,
      };
      const columns = Object.keys(insertData);
      const values = Object.values(insertData);
      const placeholders = columns.map((_column, index) => `$${index + 1}`).join(", ");
      result = await getPool().query(
        `INSERT INTO delivery2_config (${columns.join(", ")}) VALUES (${placeholders}) RETURNING *`,
        values,
      );
    }

    return sendJson(res, 200, result.rows[0] || defaultDelivery2Config(user.id));
  } catch (error) {
    console.error("[vercel-http] delivery 2 config failed:", error);
    return sendJson(res, 500, { message: "Failed to fetch Delivery 2.0 config" });
  }
}

const DELIVERY2_ANALYSIS_VERSION = "delivery2-v3-agentic-sdk";
const DELIVERY2_ORDER_STATUSES = new Set([
  "pending",
  "confirmed",
  "preparing",
  "ready",
  "out_for_delivery",
  "delivered",
  "cancelled",
]);
const DELIVERY2_OPEN_STATUSES = new Set(["pending", "confirmed", "preparing", "ready", "out_for_delivery"]);

function delivery2Trim(value: unknown, limit = 300) {
  return String(value ?? "").trim().slice(0, Math.max(0, limit));
}

function delivery2Number(value: unknown): number | null {
  if (typeof value === "number" && Number.isFinite(value)) return value;
  const parsed = Number.parseFloat(String(value ?? "").replace(",", "."));
  return Number.isFinite(parsed) ? parsed : null;
}

function delivery2ClampScore(value: unknown) {
  const parsed = Math.round(Number(value || 0));
  if (!Number.isFinite(parsed)) return 0;
  return Math.max(0, Math.min(100, parsed));
}

function delivery2JsonArray(value: unknown): string[] {
  if (!Array.isArray(value)) return [];
  return value.map((entry) => delivery2Trim(entry, 120)).filter(Boolean);
}

const delivery2AgenticOrderItemSchema = z.object({
  name: z.string().default(""),
  quantity: z.number().default(1),
  size: z.string().nullable().default(null),
  unitPrice: z.number().nullable().default(null),
  totalPrice: z.number().nullable().default(null),
  notes: z.string().nullable().default(null),
  selectedOptions: z.array(z.string()).default([]),
  halfAndHalf: z.array(z.string()).default([]),
});

const delivery2AgenticOrderSchema = z.object({
  decision: z.enum(["create_order", "wait_more", "cancel_order"]).default("wait_more"),
  hasFinalizedOrder: z.boolean().default(false),
  status: z.enum(["pending", "not_finalized", "cancelled"]).default("not_finalized"),
  customerName: z.string().nullable().default(null),
  deliveryType: z.enum(["delivery", "pickup"]).nullable().default(null),
  paymentMethod: z.string().nullable().default(null),
  customerAddress: z.string().nullable().default(null),
  customerComplement: z.string().nullable().default(null),
  customerReference: z.string().nullable().default(null),
  notes: z.string().nullable().default(null),
  summary: z.string().default("Pedido analisado pelo Delivery 2.0"),
  evidence: z.array(z.string()).default([]),
  missingFields: z.array(z.string()).default([]),
  subtotal: z.number().nullable().default(null),
  deliveryFee: z.number().nullable().default(null),
  total: z.number().nullable().default(null),
  confidence: z.number().default(0),
  items: z.array(delivery2AgenticOrderItemSchema).default([]),
});

type Delivery2AgenticOrderDecision = z.infer<typeof delivery2AgenticOrderSchema>;

function extractFirstJsonObjectText(raw: string) {
  const text = String(raw || "");
  const start = text.indexOf("{");
  if (start < 0) {
    throw new Error("A IA nao retornou JSON");
  }

  let depth = 0;
  let inString = false;
  let escaped = false;
  for (let index = start; index < text.length; index += 1) {
    const char = text[index];
    if (escaped) {
      escaped = false;
      continue;
    }
    if (char === "\\") {
      escaped = true;
      continue;
    }
    if (char === "\"") {
      inString = !inString;
      continue;
    }
    if (inString) continue;
    if (char === "{") depth += 1;
    if (char === "}") {
      depth -= 1;
      if (depth === 0) {
        return text.slice(start, index + 1);
      }
    }
  }

  throw new Error("JSON incompleto retornado pela IA");
}

function normalizeDelivery2OrderDecision(parsed: Partial<Delivery2AgenticOrderDecision> & Record<string, any>) {
  const rawItems = Array.isArray(parsed.items) ? parsed.items : [];
  const items = rawItems
    .map((item: any) => {
      const quantity = Math.max(1, Math.min(50, Math.round(Number(item?.quantity || 1))));
      const unitPrice = delivery2Number(item?.unitPrice);
      const explicitTotal = delivery2Number(item?.totalPrice);
      return {
        name: delivery2Trim(item?.name, 160),
        quantity,
        size: delivery2Trim(item?.size, 60) || null,
        unitPrice,
        totalPrice: explicitTotal !== null ? explicitTotal : unitPrice !== null ? unitPrice * quantity : null,
        notes: delivery2Trim(item?.notes, 220) || null,
        selectedOptions: delivery2JsonArray(item?.selectedOptions).slice(0, 12),
        halfAndHalf: delivery2JsonArray(item?.halfAndHalf).slice(0, 4),
      };
    })
    .filter((item: any) => item.name);

  const subtotal = delivery2Number(parsed.subtotal) ?? items.reduce((sum: number, item: any) => sum + (item.totalPrice || 0), 0);
  const deliveryFee = delivery2Number(parsed.deliveryFee) ?? 0;
  const total = delivery2Number(parsed.total) ?? subtotal + deliveryFee;
  const decision = parsed.decision === "create_order" || parsed.decision === "cancel_order" || parsed.decision === "wait_more"
    ? parsed.decision
    : parsed.status === "pending"
      ? "create_order"
      : parsed.status === "cancelled"
        ? "cancel_order"
        : "wait_more";
  const status = decision === "cancel_order" || parsed.status === "cancelled"
    ? "cancelled"
    : decision === "create_order" || parsed.status === "pending"
      ? "pending"
      : "not_finalized";

  return {
    decision,
    hasFinalizedOrder: status === "pending" ? true : parsed.hasFinalizedOrder === true,
    status,
    customerName: delivery2Trim(parsed.customerName, 120) || null,
    deliveryType: parsed.deliveryType === "pickup" ? "pickup" : parsed.deliveryType === "delivery" ? "delivery" : null,
    paymentMethod: delivery2Trim(parsed.paymentMethod, 80) || null,
    customerAddress: delivery2Trim(parsed.customerAddress, 240) || null,
    customerComplement: delivery2Trim(parsed.customerComplement, 120) || null,
    customerReference: delivery2Trim(parsed.customerReference, 160) || null,
    notes: delivery2Trim(parsed.notes, 260) || null,
    summary: delivery2Trim(parsed.summary, 260) || "Pedido identificado no atendimento",
    evidence: delivery2JsonArray(parsed.evidence).slice(0, 4),
    missingFields: delivery2JsonArray(parsed.missingFields).slice(0, 8),
    subtotal,
    deliveryFee,
    total,
    confidence: delivery2ClampScore(parsed.confidence),
    items,
  };
}

function mapDelivery2OrderItemRow(row: Record<string, any>) {
  return {
    id: String(row.id || ""),
    orderId: String(row.order_id || ""),
    lineNumber: Number(row.line_number || 0),
    itemName: String(row.item_name || ""),
    quantity: Math.max(1, Number(row.quantity || 1)),
    sizeLabel: row.size_label ? String(row.size_label) : null,
    unitPrice: delivery2Number(row.unit_price),
    totalPrice: delivery2Number(row.total_price),
    notes: row.notes ? String(row.notes) : null,
    selectedOptions: delivery2JsonArray(row.selected_options_json),
    halfAndHalf: delivery2JsonArray(row.half_and_half_json),
  };
}

function mapDelivery2OrderRow(row: Record<string, any>) {
  return {
    id: String(row.id || ""),
    conversationId: String(row.conversation_id || ""),
    connectionId: String(row.connection_id || ""),
    userId: String(row.user_id || ""),
    contactNumber: String(row.contact_number || ""),
    contactName: row.contact_name ? String(row.contact_name) : null,
    customerName: row.customer_name ? String(row.customer_name) : null,
    status: DELIVERY2_ORDER_STATUSES.has(String(row.status || "")) ? String(row.status) : "pending",
    deliveryType: row.delivery_type === "pickup" ? "pickup" : row.delivery_type === "delivery" ? "delivery" : null,
    paymentMethod: row.payment_method ? String(row.payment_method) : null,
    customerAddress: row.customer_address ? String(row.customer_address) : null,
    customerComplement: row.customer_complement ? String(row.customer_complement) : null,
    customerReference: row.customer_reference ? String(row.customer_reference) : null,
    notes: row.notes ? String(row.notes) : null,
    summary: row.summary ? String(row.summary) : null,
    evidence: delivery2JsonArray(row.evidence_json),
    subtotal: delivery2Number(row.subtotal),
    deliveryFee: delivery2Number(row.delivery_fee),
    total: delivery2Number(row.total),
    confidence: delivery2ClampScore(row.confidence),
    finalizedAt: row.finalized_at ? new Date(row.finalized_at).toISOString() : null,
    lastCustomerMessage: row.last_customer_message ? String(row.last_customer_message) : null,
    lastAgentMessage: row.last_agent_message ? String(row.last_agent_message) : null,
    lastAnalyzedAt: row.last_analyzed_at ? new Date(row.last_analyzed_at).toISOString() : null,
    analysisVersion: String(row.analysis_version || DELIVERY2_ANALYSIS_VERSION),
    sourceConnectionName: row.source_connection_name ? String(row.source_connection_name) : null,
    sourceConnectionPhone: row.source_connection_phone ? String(row.source_connection_phone) : null,
    sourceAccountName: row.source_account_name ? String(row.source_account_name) : null,
    sourceAccountEmail: row.source_account_email ? String(row.source_account_email) : null,
    createdAt: row.created_at ? new Date(row.created_at).toISOString() : null,
    updatedAt: row.updated_at ? new Date(row.updated_at).toISOString() : null,
    items: [] as ReturnType<typeof mapDelivery2OrderItemRow>[],
    rawAnalysis: row.raw_analysis && typeof row.raw_analysis === "object" ? row.raw_analysis : {},
  };
}

async function getDelivery2ConnectionIds(userId: string, scopedConnectionId?: string) {
  if (scopedConnectionId) {
    const connection = await getConnectionByIdForUser(userId, scopedConnectionId);
    return connection ? [connection.id] : [];
  }
  return getAppVisibleConnections(await getConnectionsByUserId(userId)).map((connection) => connection.id);
}

async function getDelivery2MenuDigest(userId: string) {
  const result = await getPool().query(
    `
      SELECT
        c.name AS category_name,
        c.half_half_pricing,
        i.name AS item_name,
        i.description AS item_description,
        i.price AS base_price,
        i.promotional_price,
        i.options AS options_json
      FROM menu_items i
      LEFT JOIN menu_categories c ON c.id = i.category_id
      WHERE i.user_id = $1
        AND COALESCE(i.is_available, true) = true
        AND (c.id IS NULL OR COALESCE(c.is_active, true) = true)
      ORDER BY c.display_order ASC NULLS LAST, i.display_order ASC, i.name ASC
    `,
    [userId],
  );

  const grouped = new Map<string, string[]>();
  for (const row of result.rows) {
    const categoryName = delivery2Trim(row.category_name || "Sem categoria", 80) || "Sem categoria";
    const options = Array.isArray(row.options_json) ? row.options_json : [];
    const sizeGroup = options.find((group: any) => delivery2Trim(group?.name, 40).toLowerCase() === "tamanho");
    const sizeText = Array.isArray(sizeGroup?.options)
      ? sizeGroup.options
          .map((option: any) => {
            const optionName = delivery2Trim(option?.name, 40);
            const optionPrice = delivery2Number(option?.price);
            return optionName ? `${optionName}${optionPrice !== null ? ` ${optionPrice.toFixed(2)}` : ""}` : "";
          })
          .filter(Boolean)
          .join(" | ")
      : "";
    const basePrice = delivery2Number(row.promotional_price ?? row.base_price);
    const description = delivery2Trim(row.item_description, 180);
    const halfHalfEnabled = row.half_half_pricing?.enabled === true;
    const parts = [
      `- ${delivery2Trim(row.item_name, 120)}`,
      description ? `ingredientes: ${description}` : "",
      sizeText ? `tamanhos: ${sizeText}` : basePrice !== null ? `preco: ${basePrice.toFixed(2)}` : "",
      halfHalfEnabled ? "meio a meio: sim, cobrar pelo sabor mais caro da mesma categoria e tamanho" : "",
    ].filter(Boolean);

    if (!grouped.has(categoryName)) grouped.set(categoryName, []);
    grouped.get(categoryName)!.push(parts.join(" | "));
  }

  if (grouped.size === 0) return "";
  return Array.from(grouped.entries())
    .map(([categoryName, items]) => `${categoryName}:\n${items.join("\n")}`)
    .join("\n\n");
}

async function getDelivery2RuntimeStateWebOnly(userId: string) {
  const [delivery2Result, legacyResult] = await Promise.all([
    getPool().query("SELECT is_active, send_to_ai, display_name FROM delivery2_config WHERE user_id = $1 LIMIT 1", [userId]),
    getPool().query("SELECT is_active, send_to_ai FROM delivery_config WHERE user_id = $1 LIMIT 1", [userId]),
  ]);
  const delivery2Config = delivery2Result.rows[0] || null;
  const legacyConfig = legacyResult.rows[0] || null;
  const moduleActive = delivery2Config?.is_active === true;
  const trackerRequested = delivery2Config?.send_to_ai !== false;
  const legacyDeliveryActive = legacyConfig?.is_active === true && legacyConfig?.send_to_ai !== false;
  return {
    trackingEnabled: moduleActive && trackerRequested && !legacyDeliveryActive,
    config: delivery2Config,
  };
}

async function fetchDelivery2OrderItemsByOrderIds(orderIds: string[]) {
  if (orderIds.length === 0) return new Map<string, ReturnType<typeof mapDelivery2OrderItemRow>[]>();
  const result = await getPool().query(
    `
      SELECT *
      FROM delivery2_order_items
      WHERE order_id = ANY($1::varchar[])
      ORDER BY line_number ASC, created_at ASC
    `,
    [orderIds],
  );
  const map = new Map<string, ReturnType<typeof mapDelivery2OrderItemRow>[]>();
  for (const row of result.rows) {
    const item = mapDelivery2OrderItemRow(row);
    const current = map.get(item.orderId) || [];
    current.push(item);
    map.set(item.orderId, current);
  }
  return map;
}

async function loadDelivery2OrderById(orderId: string) {
  const result = await getPool().query(
    `
      SELECT
        o.*,
        wc.connection_name AS source_connection_name,
        wc.phone_number AS source_connection_phone,
        u.name AS source_account_name,
        u.email AS source_account_email
      FROM delivery2_orders o
      INNER JOIN whatsapp_connections wc ON wc.id = o.connection_id
      INNER JOIN users u ON u.id = o.user_id
      WHERE o.id = $1
      LIMIT 1
    `,
    [orderId],
  );
  const row = result.rows[0];
  if (!row) return null;
  const order = mapDelivery2OrderRow(row);
  const items = await fetchDelivery2OrderItemsByOrderIds([order.id]);
  order.items = items.get(order.id) || [];
  return order;
}

async function listDelivery2OrdersWebOnly(params: {
  userId: string;
  connectionIds: string[];
  query?: string;
  status?: string;
  startDate?: string;
  endDate?: string;
  limit?: number;
  offset?: number;
}) {
  if (params.connectionIds.length === 0) {
    return { data: [], total: 0, hasMore: false, offset: params.offset || 0, limit: params.limit || 100 };
  }

  const where = ["o.user_id = $1", "o.connection_id = ANY($2::varchar[])"];
  const values: any[] = [params.userId, params.connectionIds];
  const query = delivery2Trim(params.query, 120);
  const status = delivery2Trim(params.status || "all", 40).toLowerCase();
  if (query) {
    values.push(`%${query}%`);
    where.push(`(o.customer_name ILIKE $${values.length} OR o.contact_name ILIKE $${values.length} OR o.contact_number ILIKE $${values.length} OR o.summary ILIKE $${values.length})`);
  }
  if (status !== "all" && DELIVERY2_ORDER_STATUSES.has(status)) {
    values.push(status);
    where.push(`o.status = $${values.length}`);
  }
  if (params.startDate) {
    values.push(params.startDate);
    where.push(`COALESCE(o.finalized_at, o.created_at) >= $${values.length}::timestamp`);
  }
  if (params.endDate) {
    values.push(params.endDate);
    where.push(`COALESCE(o.finalized_at, o.created_at) <= $${values.length}::timestamp`);
  }

  const limit = Math.max(1, Math.min(Number(params.limit || 100), 200));
  const offset = Math.max(0, Number(params.offset || 0));
  const countResult = await getPool().query(`SELECT COUNT(*)::int AS total FROM delivery2_orders o WHERE ${where.join(" AND ")}`, values);
  values.push(limit, offset);
  const rowsResult = await getPool().query(
    `
      SELECT
        o.*,
        wc.connection_name AS source_connection_name,
        wc.phone_number AS source_connection_phone,
        u.name AS source_account_name,
        u.email AS source_account_email
      FROM delivery2_orders o
      INNER JOIN whatsapp_connections wc ON wc.id = o.connection_id
      INNER JOIN users u ON u.id = o.user_id
      WHERE ${where.join(" AND ")}
      ORDER BY COALESCE(o.finalized_at, o.updated_at, o.created_at) DESC, o.created_at DESC
      LIMIT $${values.length - 1}
      OFFSET $${values.length}
    `,
    values,
  );

  const orders = rowsResult.rows.map(mapDelivery2OrderRow);
  const items = await fetchDelivery2OrderItemsByOrderIds(orders.map((order) => order.id));
  for (const order of orders) {
    order.items = items.get(order.id) || [];
  }
  const total = Number(countResult.rows[0]?.total || 0);
  return { data: orders, total, hasMore: offset + orders.length < total, offset, limit };
}

async function getDelivery2OrdersReportWebOnly(params: {
  userId: string;
  connectionIds: string[];
  startDate?: string;
  endDate?: string;
}) {
  if (params.connectionIds.length === 0) {
    return {
      summary: { grossRevenue: 0, ordersCount: 0, averageTicket: 0, cancelledCount: 0 },
      paymentMethods: [],
      dailySales: [],
      deliveryTypes: [],
    };
  }

  const where = ["o.user_id = $1", "o.connection_id = ANY($2::varchar[])"];
  const values: any[] = [params.userId, params.connectionIds];
  if (params.startDate) {
    values.push(params.startDate);
    where.push(`COALESCE(o.finalized_at, o.created_at) >= $${values.length}::timestamp`);
  }
  if (params.endDate) {
    values.push(params.endDate);
    where.push(`COALESCE(o.finalized_at, o.created_at) <= $${values.length}::timestamp`);
  }

  const result = await getPool().query(
    `
      SELECT
        o.status,
        COALESCE(NULLIF(o.payment_method, ''), 'Nao informado') AS payment_method,
        COALESCE(NULLIF(o.delivery_type, ''), 'delivery') AS delivery_type,
        o.total,
        TO_CHAR((COALESCE(o.finalized_at, o.created_at) AT TIME ZONE 'America/Sao_Paulo')::date, 'YYYY-MM-DD') AS sale_day
      FROM delivery2_orders o
      WHERE ${where.join(" AND ")}
      ORDER BY COALESCE(o.finalized_at, o.created_at) ASC
    `,
    values,
  );

  const validRows = result.rows.filter((row) => row.status !== "cancelled");
  const grossRevenue = validRows.reduce((sum, row) => sum + (delivery2Number(row.total) || 0), 0);
  const ordersCount = validRows.length;
  const cancelledCount = result.rows.length - ordersCount;
  const paymentMethods = new Map<string, { method: string; count: number; total: number }>();
  const dailySales = new Map<string, { date: string; orders: number; total: number }>();
  const deliveryTypes = new Map<string, { type: string; count: number; total: number }>();

  for (const row of validRows) {
    const total = delivery2Number(row.total) || 0;
    const method = delivery2Trim(row.payment_method, 80) || "Nao informado";
    const day = delivery2Trim(row.sale_day, 20);
    const type = row.delivery_type === "pickup" ? "Retirada" : "Entrega";
    const payment = paymentMethods.get(method) || { method, count: 0, total: 0 };
    payment.count += 1;
    payment.total += total;
    paymentMethods.set(method, payment);
    const daily = dailySales.get(day) || { date: day, orders: 0, total: 0 };
    daily.orders += 1;
    daily.total += total;
    dailySales.set(day, daily);
    const delivery = deliveryTypes.get(type) || { type, count: 0, total: 0 };
    delivery.count += 1;
    delivery.total += total;
    deliveryTypes.set(type, delivery);
  }

  return {
    summary: {
      grossRevenue,
      ordersCount,
      averageTicket: ordersCount > 0 ? grossRevenue / ordersCount : 0,
      cancelledCount,
    },
    paymentMethods: Array.from(paymentMethods.values()).sort((a, b) => b.total - a.total),
    dailySales: Array.from(dailySales.values()).sort((a, b) => a.date.localeCompare(b.date)),
    deliveryTypes: Array.from(deliveryTypes.values()).sort((a, b) => b.total - a.total),
  };
}

async function getDelivery2ConversationContext(conversationId: string) {
  const conversationResult = await getPool().query(
    `
      SELECT
        c.id AS conversation_id,
        c.connection_id,
        wc.user_id,
        c.contact_number,
        c.contact_name,
        wc.connection_name,
        wc.phone_number AS source_phone_number,
        u.name AS source_account_name,
        u.email AS source_account_email
      FROM conversations c
      INNER JOIN whatsapp_connections wc ON wc.id = c.connection_id
      INNER JOIN users u ON u.id = wc.user_id
      WHERE c.id = $1
      LIMIT 1
    `,
    [conversationId],
  );
  const conversation = conversationResult.rows[0];
  if (!conversation) return null;
  const messagesResult = await getPool().query(
    `
      SELECT from_me, is_from_agent, text, media_caption, media_type, timestamp
      FROM messages
      WHERE conversation_id = $1
      ORDER BY timestamp DESC
      LIMIT 40
    `,
    [conversationId],
  );
  return { conversation, messages: messagesResult.rows.reverse() };
}

function formatDelivery2Transcript(messages: any[]) {
  return messages
    .map((message) => {
      const date = new Date(message.timestamp);
      const time = Number.isNaN(date.getTime())
        ? "sem horario"
        : date.toLocaleString("pt-BR", {
            timeZone: "America/Sao_Paulo",
            day: "2-digit",
            month: "2-digit",
            year: "numeric",
            hour: "2-digit",
            minute: "2-digit",
          });
      const speaker = message.from_me ? (message.is_from_agent ? "IA" : "DONO") : "CLIENTE";
      const body = delivery2Trim(message.text || message.media_caption || "", 700) || (message.media_type ? `[${message.media_type}]` : "(sem texto)");
      return `[${time}] ${speaker}: ${body}`;
    })
    .join("\n");
}

