async function handleAgentConfig(req: any, res: any) {
  const user = await requireJwtUser(req, res);
  if (!user) return;

  try {
    if (req.method === "POST" || req.method === "PUT" || req.method === "PATCH") {
      const body = await readJsonBody(req);
      const existing = await getPool().query("SELECT prompt FROM ai_agent_config WHERE user_id = $1 LIMIT 1", [user.id]);
      const previousPrompt = existing.rows[0]?.prompt ? String(existing.rows[0].prompt) : "";
      const row = await upsertAgentConfigRecord(user.id, body);

      if (body?.prompt !== undefined && String(body.prompt || "") !== previousPrompt) {
        await createPromptVersion(user.id, String(body.prompt || ""), "manual", "Salvo manualmente via editor");
      }

      if (body?.isActive === true || body?.flowModeActive === true) {
        try {
          await getPool().query(
            "UPDATE chatbot_configs SET is_active = false, updated_at = NOW() WHERE user_id = $1",
            [user.id],
          );
        } catch (syncError) {
          console.warn("[vercel-http] failed to disable chatbot_configs after agent config update:", syncError);
        }
      }

      return sendJson(res, 200, toAgentConfigPayload(row || null));
    }

    const result = await getPool().query("SELECT * FROM ai_agent_config WHERE user_id = $1 LIMIT 1", [user.id]);
    return sendJson(res, 200, toAgentConfigPayload(result.rows[0] || null));
  } catch (error) {
    console.error("[vercel-http] agent config failed:", error);
    return sendJson(res, 500, { message: "Failed to fetch agent config" });
  }
}

async function handleAgentFlow(req: any, res: any) {
  const user = await requireJwtUser(req, res);
  if (!user) return;

  try {
    if (req.method === "POST" || req.method === "PUT" || req.method === "PATCH") {
      const body = await readJsonBody(req);
      const row = await upsertAgentConfigRecord(user.id, {
        flowScript: body?.flowScript ?? body?.flow_script ?? null,
        flowModeActive: body?.flowModeActive ?? body?.flow_mode_active ?? false,
      });

      if (body?.flowModeActive === true || body?.flow_mode_active === true) {
        try {
          await getPool().query(
            "UPDATE chatbot_configs SET is_active = false, updated_at = NOW() WHERE user_id = $1",
            [user.id],
          );
        } catch (syncError) {
          console.warn("[vercel-http] failed to disable chatbot_configs after flow update:", syncError);
        }
      }

      return sendJson(res, 200, {
        success: true,
        message: "Fluxo salvo com sucesso",
        config: toCamelRecord(row || null),
      });
    }

    const result = await getPool().query(
      "SELECT flow_script AS \"flowScript\", flow_mode_active AS \"flowModeActive\" FROM ai_agent_config WHERE user_id = $1 LIMIT 1",
      [user.id],
    );
    const row = result.rows[0];
    return sendJson(res, 200, {
      flowScript: row?.flowScript || null,
      flowModeActive: row?.flowModeActive === true,
    });
  } catch (error) {
    console.error("[vercel-http] agent flow failed:", error);
    return sendJson(res, 500, { message: "Failed to fetch agent flow" });
  }
}

const DEFAULT_FLOW2_LEONA_DEFINITION = {
  nodes: [
    {
      id: "start",
      type: "start",
      label: "Inicio do fluxo",
      position: { x: 120, y: 140 },
      data: {
        kind: "start",
        title: "Inicio do fluxo",
        description: "Quando o cliente entrar neste fluxo",
        config: { trigger: "manual" },
      },
    },
  ],
  edges: [],
  viewport: { x: 0, y: 0, zoom: 1 },
};

async function handleAgentFlow2(req: any, res: any) {
  const user = await requireJwtUser(req, res);
  if (!user) return;

  try {
    if (req.method === "POST" || req.method === "PUT" || req.method === "PATCH") {
      const body = await readJsonBody(req);
      const definition =
        body?.definition && typeof body.definition === "object"
          ? body.definition
          : DEFAULT_FLOW2_LEONA_DEFINITION;
      const name = String(body?.name || "Fluxo 2.0").slice(0, 140);
      const selectedNodeId = body?.selectedNodeId ? String(body.selectedNodeId).slice(0, 180) : null;
      const isActive = body?.isActive === true;
      const isArchived = body?.isArchived === true;

      const result = await getPool().query(
        `INSERT INTO flow2_leona_flows (
           user_id, name, is_active, is_archived, definition, selected_node_id, updated_at
         )
         VALUES ($1, $2, $3, $4, $5::jsonb, $6, now())
         ON CONFLICT (user_id)
         DO UPDATE SET
           name = EXCLUDED.name,
           is_active = EXCLUDED.is_active,
           is_archived = EXCLUDED.is_archived,
           definition = EXCLUDED.definition,
           selected_node_id = EXCLUDED.selected_node_id,
           updated_at = now()
         RETURNING
           id,
           user_id AS "userId",
           name,
           is_active AS "isActive",
           is_archived AS "isArchived",
           definition,
           selected_node_id AS "selectedNodeId",
           created_at AS "createdAt",
           updated_at AS "updatedAt"`,
        [user.id, name, isActive, isArchived, JSON.stringify(definition), selectedNodeId],
      );

      if (isActive) {
        try {
          await getPool().query(
            "UPDATE ai_agent_config SET flow_mode_active = false, updated_at = NOW() WHERE user_id = $1",
            [user.id],
          );
        } catch (syncError) {
          console.warn("[vercel-http] failed to disable legacy visual flow after Flow2 activation:", syncError);
        }
      }

      try {
        await ensureFlow2RuntimeTables();
        await getPool().query("DELETE FROM flow2_leona_conversation_states WHERE user_id = $1", [user.id]);
      } catch (stateResetError) {
        console.warn("[vercel-http] failed to reset Flow2 conversation states after save:", stateResetError);
      }

      return sendJson(res, 200, {
        success: true,
        flow: result.rows[0],
      });
    }

    const result = await getPool().query(
      `SELECT
         id,
         user_id AS "userId",
         name,
         is_active AS "isActive",
         is_archived AS "isArchived",
         definition,
         selected_node_id AS "selectedNodeId",
         created_at AS "createdAt",
         updated_at AS "updatedAt"
       FROM flow2_leona_flows
       WHERE user_id = $1
       LIMIT 1`,
      [user.id],
    );

    const row = result.rows[0];
    return sendJson(res, 200, row || {
      id: null,
      userId: user.id,
      name: "Fluxo 2.0",
      isActive: false,
      isArchived: false,
      definition: DEFAULT_FLOW2_LEONA_DEFINITION,
      selectedNodeId: "start",
      createdAt: null,
      updatedAt: null,
    });
  } catch (error) {
    console.error("[vercel-http] agent flow2 failed:", error);
    return sendJson(res, 500, { message: "Failed to fetch Fluxo 2.0" });
  }
}

let flow2RuntimeTableReady: Promise<void> | null = null;

function ensureFlow2RuntimeTables() {
  if (!flow2RuntimeTableReady) {
    flow2RuntimeTableReady = getPool().query(`
      CREATE TABLE IF NOT EXISTS public.flow2_leona_conversation_states (
        id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
        flow_id uuid REFERENCES public.flow2_leona_flows(id) ON DELETE CASCADE,
        user_id uuid NOT NULL,
        conversation_id text NOT NULL,
        current_node_id text,
        status text NOT NULL DEFAULT 'active',
        context jsonb NOT NULL DEFAULT '{}'::jsonb,
        last_input text,
        last_input_at timestamptz,
        created_at timestamptz NOT NULL DEFAULT now(),
        updated_at timestamptz NOT NULL DEFAULT now(),
        CONSTRAINT flow2_leona_conversation_states_status_check
          CHECK (status IN ('active', 'waiting_input', 'ai_handoff', 'completed')),
        CONSTRAINT flow2_leona_conversation_states_unique
          UNIQUE (user_id, conversation_id)
      );

      CREATE INDEX IF NOT EXISTS idx_flow2_leona_states_user_conversation
        ON public.flow2_leona_conversation_states(user_id, conversation_id);
      CREATE INDEX IF NOT EXISTS idx_flow2_leona_states_flow
        ON public.flow2_leona_conversation_states(flow_id);

      ALTER TABLE public.flow2_leona_conversation_states ENABLE ROW LEVEL SECURITY;

      DO $$
      BEGIN
        IF NOT EXISTS (
          SELECT 1 FROM pg_policies
          WHERE schemaname = 'public'
            AND tablename = 'flow2_leona_conversation_states'
            AND policyname = 'flow2_leona_states_select_own'
        ) THEN
          CREATE POLICY flow2_leona_states_select_own
            ON public.flow2_leona_conversation_states
            FOR SELECT TO authenticated
            USING (auth.uid() = user_id);
        END IF;

        IF NOT EXISTS (
          SELECT 1 FROM pg_policies
          WHERE schemaname = 'public'
            AND tablename = 'flow2_leona_conversation_states'
            AND policyname = 'flow2_leona_states_insert_own'
        ) THEN
          CREATE POLICY flow2_leona_states_insert_own
            ON public.flow2_leona_conversation_states
            FOR INSERT TO authenticated
            WITH CHECK (auth.uid() = user_id);
        END IF;

        IF NOT EXISTS (
          SELECT 1 FROM pg_policies
          WHERE schemaname = 'public'
            AND tablename = 'flow2_leona_conversation_states'
            AND policyname = 'flow2_leona_states_update_own'
        ) THEN
          CREATE POLICY flow2_leona_states_update_own
            ON public.flow2_leona_conversation_states
            FOR UPDATE TO authenticated
            USING (auth.uid() = user_id)
            WITH CHECK (auth.uid() = user_id);
        END IF;
      END $$;

      GRANT SELECT, INSERT, UPDATE ON public.flow2_leona_conversation_states TO authenticated;
    `).then(() => undefined);
  }
  return flow2RuntimeTableReady;
}

function normalizeFlow2Nodes(definition: any): any[] {
  return Array.isArray(definition?.nodes)
    ? definition.nodes.filter((node: any) => node && typeof node === "object" && node.id)
    : [];
}

function normalizeFlow2Edges(definition: any): any[] {
  return Array.isArray(definition?.edges)
    ? definition.edges.filter((edge: any) => edge && typeof edge === "object" && edge.source && edge.target)
    : [];
}

function getFlow2NodeKind(node: any) {
  return String(node?.data?.kind || node?.type || "").trim() || "message";
}

function getFlow2NodeConfig(node: any): Record<string, any> {
  const config = node?.data?.config;
  return config && typeof config === "object" && !Array.isArray(config) ? config : {};
}

function getFlow2MenuOptions(config: Record<string, any>): string[] {
  return String(config?.options || "")
    .split(/\r?\n/)
    .map((option) => option.trim())
    .filter(Boolean)
    .slice(0, 8);
}

function normalizeFlow2Text(value: unknown) {
  return String(value || "")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .trim();
}

function normalizeFlow2ConditionRules(config: Record<string, any>) {
  if (Array.isArray(config.conditions)) {
    return config.conditions
      .filter((condition: any) => condition && typeof condition === "object")
      .map((condition: any) => ({
        operator: String(condition.operator || "contains"),
        value: String(condition.value || ""),
      }));
  }

  const matchText = String(config.matchText || config.value || "").trim();
  return matchText ? [{ operator: "contains", value: matchText }] : [];
}

function evaluateFlow2ConditionRule(rule: { operator: string; value: string }, message: string) {
  const normalizedMessage = normalizeFlow2Text(message);
  const normalizedValue = normalizeFlow2Text(rule.value);
  const operator = String(rule.operator || "contains");

  if (operator === "is_empty") return normalizedMessage.length === 0;
  if (operator === "is_not_empty") return normalizedMessage.length > 0;
  if (!normalizedValue) return false;
  if (operator === "not_contains") return !normalizedMessage.includes(normalizedValue);
  if (operator === "equals") return normalizedMessage === normalizedValue;
  if (operator === "starts_with") return normalizedMessage.startsWith(normalizedValue);
  if (operator === "ends_with") return normalizedMessage.endsWith(normalizedValue);
  return normalizedMessage.includes(normalizedValue);
}

function findFlow2NextEdge(edges: any[], source: string, sourceHandle = "next") {
  return (
    edges.find((edge) => edge.source === source && String(edge.sourceHandle || "next") === sourceHandle) ||
    edges.find((edge) => edge.source === source && !edge.sourceHandle && sourceHandle === "next") ||
    null
  );
}

function parseFlow2Seconds(value: unknown) {
  const numeric = Number(value);
  if (!Number.isFinite(numeric) || numeric <= 0) return 0;
  return Math.min(Math.floor(numeric), 300);
}

function appendFlow2TextAction(actions: any[], text: string, delaySeconds: number) {
  const cleanText = String(text || "").trim();
  if (!cleanText) return 0;
  actions.push({
    type: "send_text",
    text: cleanText,
    delay_seconds: delaySeconds > 0 ? delaySeconds : undefined,
    typing_seconds: Math.min(8, Math.max(1, Math.ceil(cleanText.length / 55))),
    flow2: true,
  });
  return 0;
}

function appendFlow2MediaAction(actions: any[], params: {
  mediaType: string;
  url: string;
  caption?: string;
  delaySeconds?: number;
  fileName?: string;
}) {
  const mediaUrl = String(params.url || "").trim();
  if (!mediaUrl) return params.delaySeconds || 0;
  const mediaType = String(params.mediaType || "image").toLowerCase();
  const normalizedType =
    mediaType === "audio" || mediaType === "video" || mediaType === "document" ? mediaType : "image";
  actions.push({
    type: "send_media",
    media_type: normalizedType,
    media_url: mediaUrl,
    caption: String(params.caption || "").trim() || undefined,
    file_name: params.fileName || undefined,
    delay_seconds: params.delaySeconds && params.delaySeconds > 0 ? params.delaySeconds : undefined,
    typing_seconds: normalizedType === "audio" ? 0 : undefined,
    flow2: true,
  });
  return 0;
}

function normalizeFlow2MessageItems(config: Record<string, any>): any[] {
  if (Array.isArray(config.items)) {
    return config.items.filter((item: any) => item && typeof item === "object");
  }
  if (typeof config.text === "string" && config.text.trim()) {
    return [{ type: "text", text: config.text, delaySeconds: config.typingDelaySeconds || 0 }];
  }
  return [];
}

function appendFlow2MessageNodeActions(actions: any[], config: Record<string, any>, delaySeconds: number) {
  let pendingDelay = delaySeconds;
  const items = normalizeFlow2MessageItems(config);
  for (const item of items) {
    const type = String(item.type || "text").toLowerCase();
    if (type === "interval") {
      pendingDelay += parseFlow2Seconds(item.delaySeconds);
      continue;
    }
    if (type === "text") {
      pendingDelay = appendFlow2TextAction(actions, String(item.text || ""), pendingDelay);
      continue;
    }
    if (type === "contact") {
      const contactText = [item.contactName, item.contactPhone].filter(Boolean).join("\n");
      pendingDelay = appendFlow2TextAction(actions, contactText, pendingDelay);
      continue;
    }
    const mediaType = type === "file" ? "document" : type;
    pendingDelay = appendFlow2MediaAction(actions, {
      mediaType,
      url: item.url || item.fileName || "",
      caption: item.text || item.caption || "",
      fileName: item.fileName || undefined,
      delaySeconds: pendingDelay + parseFlow2Seconds(item.delaySeconds),
    });
  }
  return pendingDelay;
}

function evaluateFlow2Condition(config: Record<string, any>, message: string) {
  const rules = normalizeFlow2ConditionRules(config);
  if (rules.length > 0) {
    const logic = String(config.logic || "all") === "any" ? "any" : "all";
    const matched = logic === "any"
      ? rules.some((rule) => evaluateFlow2ConditionRule(rule, message))
      : rules.every((rule) => evaluateFlow2ConditionRule(rule, message));
    return matched ? "yes" : "no";
  }

  const normalizedMessage = normalizeFlow2Text(message);
  const positiveCandidates = ["sim", "quero", "pode", "enviar", "ok", "confirmo", "tenho interesse"];
  if (positiveCandidates.some((candidate) => normalizedMessage.includes(candidate))) return "yes";
  return "no";
}

function evaluateFlow2MenuSelection(config: Record<string, any>, message: string) {
  const normalizedMessage = normalizeFlow2Text(message);
  const options = getFlow2MenuOptions(config);
  const numeric = Number.parseInt(normalizedMessage, 10);
  if (Number.isFinite(numeric) && numeric >= 1 && numeric <= options.length) return `option-${numeric - 1}`;
  const index = options.findIndex((option) => {
    const normalizedOption = normalizeFlow2Text(option);
    return normalizedOption && (normalizedMessage.includes(normalizedOption) || normalizedOption.includes(normalizedMessage));
  });
  return index >= 0 ? `option-${index}` : null;
}

async function loadActiveFlow2ForUser(userId: string) {
  const result = await getPool().query(
    `SELECT
       id,
       user_id AS "userId",
       name,
       is_active AS "isActive",
       is_archived AS "isArchived",
       definition,
       selected_node_id AS "selectedNodeId",
       updated_at AS "updatedAt"
     FROM flow2_leona_flows
     WHERE user_id = $1
       AND is_active = true
       AND COALESCE(is_archived, false) = false
     LIMIT 1`,
    [userId],
  );
  return result.rows[0] || null;
}

async function persistFlow2RuntimeState(state: {
  flowId: string;
  userId: string;
  conversationId: string;
  currentNodeId: string;
  status: string;
  context?: Record<string, any> | null;
  lastInput?: string | null;
}) {
  if (!state.flowId || !state.userId || !state.conversationId || !state.currentNodeId) {
    return;
  }
  await ensureFlow2RuntimeTables();
  await getPool().query(
    `INSERT INTO flow2_leona_conversation_states (
       flow_id, user_id, conversation_id, current_node_id, status, context, last_input, last_input_at, updated_at
     )
     VALUES ($1, $2, $3, $4, $5, $6::jsonb, $7, now(), now())
     ON CONFLICT (user_id, conversation_id)
     DO UPDATE SET
       flow_id = EXCLUDED.flow_id,
       current_node_id = EXCLUDED.current_node_id,
       status = EXCLUDED.status,
       context = EXCLUDED.context,
       last_input = EXCLUDED.last_input,
       last_input_at = EXCLUDED.last_input_at,
       updated_at = now()`,
    [
      state.flowId,
      state.userId,
      state.conversationId,
      state.currentNodeId,
      state.status,
      JSON.stringify(state.context || {}),
      state.lastInput || "",
    ],
  );
}

async function persistFlow2PendingStateFromPayload(payload: any) {
  const pendingState = payload?.flow2PendingState;
  if (!pendingState || typeof pendingState !== "object") {
    return;
  }
  await persistFlow2RuntimeState({
    flowId: String(pendingState.flowId || ""),
    userId: String(pendingState.userId || ""),
    conversationId: String(pendingState.conversationId || ""),
    currentNodeId: String(pendingState.currentNodeId || ""),
    status: String(pendingState.status || "active"),
    context: pendingState.context && typeof pendingState.context === "object" ? pendingState.context : {},
    lastInput: pendingState.lastInput || "",
  });
}

async function runFlow2LeonaRuntimeForUser(params: {
  userId: string;
  message: string;
  conversationId?: string | null;
  contactName?: string | null;
  reset?: boolean;
  deferStatePersistence?: boolean;
}) {
  const flow = await loadActiveFlow2ForUser(params.userId);
  if (!flow) return null;

  await ensureFlow2RuntimeTables();
  const conversationId = String(params.conversationId || `test:${params.userId}`).slice(0, 220);
  if (params.reset) {
    await getPool().query(
      "DELETE FROM flow2_leona_conversation_states WHERE user_id = $1 AND conversation_id = $2",
      [params.userId, conversationId],
    );
  }

  const stateResult = await getPool().query(
    `SELECT
       flow_id AS "flowId",
       current_node_id AS "currentNodeId",
       status,
       context
     FROM flow2_leona_conversation_states
     WHERE user_id = $1 AND conversation_id = $2
     LIMIT 1`,
    [params.userId, conversationId],
  );
  const state = stateResult.rows[0] || null;
  if (state?.status === "ai_handoff") return { handoffToAi: true, alreadyHandedOff: true };
  if (state?.status === "completed") {
    return {
      payload: {
        response: "",
        splitResponses: [],
        mediaActions: [],
        audioResponseMode: "text",
        wouldSendAudio: false,
        wouldSendText: false,
        mode: "flow2_completed",
        flow2State: { status: "completed" },
      },
    };
  }

  const definition = flow.definition && typeof flow.definition === "object"
    ? flow.definition
    : DEFAULT_FLOW2_LEONA_DEFINITION;
  const nodes = normalizeFlow2Nodes(definition);
  const edges = normalizeFlow2Edges(definition);
  const nodesById = new Map(nodes.map((node: any) => [String(node.id), node]));
  const flowChanged = state?.flowId && String(state.flowId) !== String(flow.id);
  const initialNodeId = flowChanged ? "start" : String(state?.currentNodeId || "start");
  let currentNodeId = nodesById.has(initialNodeId) ? initialNodeId : "start";
  let status = String(flowChanged ? "active" : state?.status || "active");
  const actions: any[] = [];
  const internalActions: any[] = [];
  const traversedNodeIds: string[] = [];
  let pendingDelaySeconds = 0;
  let handoffToAi = false;

  for (let guard = 0; guard < 40; guard += 1) {
    const node = nodesById.get(currentNodeId);
    if (!node) {
      status = "completed";
      break;
    }
    traversedNodeIds.push(currentNodeId);
    const kind = getFlow2NodeKind(node);
    const config = getFlow2NodeConfig(node);

    if (kind === "start") {
      const next = findFlow2NextEdge(edges, currentNodeId, "next");
      if (!next) {
        status = "completed";
        break;
      }
      currentNodeId = String(next.target);
      status = "active";
      continue;
    }

    if (kind === "wait") {
      if (status === "waiting_input" && currentNodeId === initialNodeId) {
        const next = findFlow2NextEdge(edges, currentNodeId, "next");
        if (!next) {
          status = "completed";
          break;
        }
        currentNodeId = String(next.target);
        status = "active";
        continue;
      }
      status = "waiting_input";
      break;
    }

    if (kind === "menu") {
      if (status === "waiting_input" && currentNodeId === initialNodeId) {
        const selectedHandle = evaluateFlow2MenuSelection(config, params.message) || "next";
        const next = findFlow2NextEdge(edges, currentNodeId, selectedHandle);
        if (!next) {
          pendingDelaySeconds = appendFlow2TextAction(actions, "Escolha uma das opcoes do menu para continuar.", pendingDelaySeconds);
          status = "waiting_input";
          break;
        }
        currentNodeId = String(next.target);
        status = "active";
        continue;
      }
      const options = getFlow2MenuOptions(config);
      const menuText = options.length > 0
        ? ["Escolha uma opcao:", ...options.map((option, index) => `${index + 1}. ${option}`)].join("\n")
        : "Escolha uma opcao para continuar.";
      pendingDelaySeconds = appendFlow2TextAction(actions, menuText, pendingDelaySeconds);
      status = "waiting_input";
      break;
    }

    if (kind === "condition") {
      const handle = evaluateFlow2Condition(config, params.message);
      const next = findFlow2NextEdge(edges, currentNodeId, handle) || findFlow2NextEdge(edges, currentNodeId, "next");
      if (!next) {
        status = "completed";
        break;
      }
      currentNodeId = String(next.target);
      status = "active";
      continue;
    }

    if (kind === "delay") {
      pendingDelaySeconds += parseFlow2Seconds(config.seconds);
    } else if (kind === "message") {
      pendingDelaySeconds = appendFlow2MessageNodeActions(actions, config, pendingDelaySeconds);
    } else if (kind === "media") {
      pendingDelaySeconds = appendFlow2MediaAction(actions, {
        mediaType: config.mediaType || "image",
        url: config.url || "",
        caption: config.caption || "",
        fileName: config.fileName || undefined,
        delaySeconds: pendingDelaySeconds,
      });
    } else if (kind === "pix") {
      const text = [
        config.recipient ? `Destinatario: ${config.recipient}` : "Pix",
        config.pixKeyType ? `Tipo: ${config.pixKeyType}` : "",
        config.pixKey ? `Chave: ${config.pixKey}` : "",
      ].filter(Boolean).join("\n");
      pendingDelaySeconds = appendFlow2TextAction(actions, text, pendingDelaySeconds);
    } else if (kind === "carousel") {
      const cards = String(config.cards || "").split(/\r?\n/).map((item) => item.trim()).filter(Boolean);
      pendingDelaySeconds = appendFlow2TextAction(actions, cards.length ? cards.join("\n") : "Carrossel sem cards configurados.", pendingDelaySeconds);
    } else if (kind === "tags" || kind === "notification" || kind === "chat-control") {
      internalActions.push({ kind, config });
    } else if (kind === "ai") {
      if (config.handoff === false) {
        internalActions.push({ kind, config });
      } else {
      status = "ai_handoff";
      handoffToAi = true;
      break;
      }
    }

    const next = findFlow2NextEdge(edges, currentNodeId, "next");
    if (!next) {
      status = "completed";
      break;
    }
    currentNodeId = String(next.target);
    status = "active";
  }

  const pendingState = {
    flowId: flow.id,
    userId: params.userId,
    conversationId,
    currentNodeId,
    status,
    context: { internalActions, traversedNodeIds },
    lastInput: params.message,
  };
  const shouldDeferStatePersistence = params.deferStatePersistence === true && actions.length > 0;
  if (!shouldDeferStatePersistence) {
    await persistFlow2RuntimeState(pendingState);
  }

  if (handoffToAi && actions.length === 0) {
    return { handoffToAi: true, flow2State: { status, currentNodeId, traversedNodeIds } };
  }

  const responseText = actions
    .map((action) => String(action.text || action.caption || "").trim())
    .filter(Boolean)
    .join("\n\n");
  return {
    payload: {
      response: responseText,
      splitResponses: [],
      mediaActions: actions,
      audioResponseMode: "text",
      wouldSendAudio: actions.some((action) => String(action.media_type || "").toLowerCase() === "audio"),
      wouldSendText: actions.some((action) => action.type === "send_text"),
      mode: "flow2_runtime",
      handoffToAi: handoffToAi === true,
      flow2PendingState: shouldDeferStatePersistence ? pendingState : null,
      flow2State: {
        flowId: flow.id,
        status,
        currentNodeId,
        traversedNodeIds,
        internalActions,
      },
    },
  };
}

async function handleAgentFlow2Test(req: any, res: any) {
  const user = await requireJwtUser(req, res);
  if (!user) return;

  try {
    const body = await readJsonBody(req);
    const result = await runFlow2LeonaRuntimeForUser({
      userId: user.id,
      message: String(body?.message || ""),
      conversationId: body?.conversationId || body?.conversationKey || `test:${user.id}`,
      contactName: body?.contactName || "Teste",
      reset: body?.reset === true,
    });
    if (!result) {
      return sendJson(res, 200, { success: true, active: false, mode: "flow2_inactive" });
    }
    return sendJson(res, 200, {
      success: true,
      active: true,
      handoffToAi: result.handoffToAi === true,
      ...(result.payload || {}),
      flow2State: result.flow2State || result.payload?.flow2State || null,
    });
  } catch (error: any) {
    console.error("[vercel-http] agent flow2 test failed:", error);
    return sendJson(res, 500, { success: false, message: error?.message || "Failed to test Fluxo 2.0" });
  }
}

function parseWebOnlyBubbleMessages(message: string): string[] {
  const text = String(message || "")
    .replace(/\[\/\s*BOLHA\s*\]/gi, "[BOLHA]")
    .replace(/\[\s*\/?\s*BOLHA\s*$/gi, "[BOLHA]")
    .replace(/\[\/\s*BOLHA/gi, "[BOLHA]")
    .trim();
  if (!text) return [];
  const parts = text
    .split(/\s*\[BOLHA\]\s*/i)
    .map((part) => part.trim())
    .filter(Boolean);
  return normalizeWebOnlyLinkBubbleParts(parts.length > 0 ? parts : [text]);
}

function trimWebOnlyUrlCandidate(candidate: string) {
  return String(candidate || "")
    .trim()
    .replace(/[.,;:!?]+$/g, "")
    .replace(/[)\]}]+$/g, "");
}

function isWebOnlyValidUrl(candidate: string) {
  const value = trimWebOnlyUrlCandidate(candidate);
  if (!value) return false;
  try {
    const parsed = new URL(/^[a-z][a-z0-9+.-]*:\/\//i.test(value) ? value : `https://${value}`);
    return parsed.protocol === "http:" || parsed.protocol === "https:";
  } catch {
    return false;
  }
}

function shouldWebOnlyAddWwwToHost(hostname: string) {
  const host = String(hostname || "").toLowerCase();
  if (!host || host.startsWith("www.") || host === "localhost" || /^\d{1,3}(?:\.\d{1,3}){3}$/.test(host)) {
    return false;
  }
  const labels = host.split(".").filter(Boolean);
  if (labels.length === 2) return true;
  return labels.length === 3 && labels[1].length <= 3 && labels[2].length === 2;
}

function normalizeWebOnlyUrlForWhatsAppNoPreview(candidate: string) {
  const value = trimWebOnlyUrlCandidate(candidate);
  if (!isWebOnlyValidUrl(value)) return value;
  try {
    const parsed = new URL(/^[a-z][a-z0-9+.-]*:\/\//i.test(value) ? value : `https://${value}`);
    const host = shouldWebOnlyAddWwwToHost(parsed.hostname)
      ? `www.${parsed.hostname}`
      : parsed.hostname;
    const port = parsed.port ? `:${parsed.port}` : "";
    const path = parsed.pathname && parsed.pathname !== "/" ? parsed.pathname : "";
    return `${host}${port}${path}${parsed.search || ""}${parsed.hash || ""}`;
  } catch {
    return value.replace(/^https?:\/\//i, "");
  }
}

function replaceWebOnlyOutgoingLinks(text: string, replacer: (url: string) => string) {
  const source = String(text || "");
  const pattern = /(^|[\s([<{])((?:https?:\/\/|www\.)[^\s)\]}>]+|(?:[a-z0-9-]+\.)+[a-z]{2,}(?:\/[^\s)\]}>]*)?)/gi;
  let output = "";
  let cursor = 0;

  for (const match of source.matchAll(pattern)) {
    const prefix = match[1] || "";
    const rawUrl = match[2] || "";
    const start = Number(match.index || 0) + prefix.length;
    const end = start + rawUrl.length;
    const previousChar = start > 0 ? source.charAt(start - 1) : "";
    if (previousChar === "@") continue;

    output += source.slice(cursor, start);
    const trimmed = trimWebOnlyUrlCandidate(rawUrl);
    const trailing = rawUrl.slice(trimmed.length);
    output += replacer(trimmed) + trailing;
    cursor = end;
  }

  output += source.slice(cursor);
  return output;
}

function normalizeWebOnlyOutgoingLinksForWhatsApp(text: string) {
  return replaceWebOnlyOutgoingLinks(text, normalizeWebOnlyUrlForWhatsAppNoPreview);
}

function splitWebOnlyLinksIntoOwnBubbles(part: string): string[] {
  const source = String(part || "").trim();
  if (!source) return [];

  const segments: string[] = [];
  let cursor = 0;
  const pattern = /(^|[\s([<{])((?:https?:\/\/|www\.)[^\s)\]}>]+|(?:[a-z0-9-]+\.)+[a-z]{2,}(?:\/[^\s)\]}>]*)?)/gi;

  for (const match of source.matchAll(pattern)) {
    const prefix = match[1] || "";
    const rawUrl = match[2] || "";
    const urlStart = Number(match.index || 0) + prefix.length;
    const urlEnd = urlStart + rawUrl.length;
    const previousChar = urlStart > 0 ? source.charAt(urlStart - 1) : "";
    if (previousChar === "@") continue;

    const before = source.slice(cursor, urlStart).trim();
    if (before) segments.push(before);

    const urlCandidate = trimWebOnlyUrlCandidate(rawUrl);
    if (isWebOnlyValidUrl(urlCandidate)) {
      segments.push(normalizeWebOnlyUrlForWhatsAppNoPreview(urlCandidate));
      cursor = urlEnd;
      continue;
    }

    segments.push(rawUrl.trim());
    cursor = urlEnd;
  }

  const tail = source.slice(cursor).trim();
  if (tail) segments.push(tail);
  return segments.filter(Boolean);
}

function normalizeWebOnlyLinkBubbleParts(parts: string[]) {
  const normalized = parts.flatMap((part) => splitWebOnlyLinksIntoOwnBubbles(part));
  return normalized;
}

