type WebOnlyAgenticReplyRuntimeResult = {
  text: string;
  trace: Record<string, unknown>;
};

function countReplyQuestions(value: string): number {
  return (String(value || "").match(/\?/g) || []).length;
}

function extractWebOnlyReplyProtectedFacts(value: string): string[] {
  const text = String(value || "");
  const facts = [
    ...(text.match(/https?:\/\/[^\s)]+|www\.[^\s)]+/gi) || []),
    ...(text.match(/\bR\$\s*\d+(?:[.,]\d{2})?\b/gi) || []),
    ...(text.match(/\b\d{1,2}:\d{2}\b/g) || []),
    ...(text.match(/\[[A-Z_]+:[^\]]+\]/g) || []),
  ];
  return Array.from(new Set(facts.map((item) => item.trim()).filter(Boolean))).slice(0, 20);
}

function detectWebOnlyUnsupportedSpecificClaim(candidateText: string, authorizedContext: string): string {
  const candidate = String(candidateText || "");
  const authorized = normalizeForPromptEditGuard(authorizedContext);
  if (!authorized) return "";

  if (/\blink\b/i.test(candidate) && !authorized.includes("link")) {
    return "unsupported_link";
  }

  const durationMatches = candidate.match(/\b\d+\s*(?:minuto|minutos|hora|horas|dia|dias|semana|semanas)\b/gi) || [];
  for (const duration of durationMatches) {
    if (!authorized.includes(normalizeForPromptEditGuard(duration))) {
      return `unsupported_duration:${duration}`;
    }
  }

  const monetaryMatches = candidate.match(/\bR\$\s*\d+(?:[.,]\d{2})?\b/gi) || [];
  for (const amount of monetaryMatches) {
    if (!authorized.includes(normalizeForPromptEditGuard(amount))) {
      return `unsupported_amount:${amount}`;
    }
  }

  return "";
}

function startsWebOnlyWithGreeting(value: string): boolean {
  return /^(ola|oi|bom dia|boa tarde|boa noite|tudo bem)[,!\s]/i.test(normalizeForPromptEditGuard(value));
}

function validateWebOnlyAgenticReplyCandidate(
  originalText: string,
  candidateText: string,
  authorizedContext = "",
  options: { hasPriorAssistant?: boolean; allowCalculatedFactCorrections?: boolean } = {},
) {
  const original = String(originalText || "").trim();
  const candidate = String(candidateText || "").trim();
  if (!candidate) return { ok: false, reason: "empty_candidate" };
  if (candidate.length < Math.min(18, original.length)) return { ok: false, reason: "too_short" };
  if (candidate.length > 1000) return { ok: false, reason: "too_long" };
  if (original.length > 260 && candidate.length > original.length * 2.1) return { ok: false, reason: "too_long" };
  if (options.hasPriorAssistant && !startsWebOnlyWithGreeting(original) && startsWebOnlyWithGreeting(candidate)) {
    return { ok: false, reason: "reintroduced_opening_greeting" };
  }
  if (countReplyQuestions(candidate) > Math.max(1, countReplyQuestions(original) + 1)) {
    return { ok: false, reason: "too_many_questions" };
  }
  if (/```|<prompt|<\/prompt|system prompt|instrucao interna|regras internas/i.test(candidate)) {
    return { ok: false, reason: "leaked_internal_context" };
  }
  if (countPromptMojibakeMarkers(candidate) > countPromptMojibakeMarkers(original)) {
    return { ok: false, reason: "mojibake_increase" };
  }
  const unauthorizedLinks = findWebOnlyUnauthorizedLinks(
    candidate,
    buildWebOnlyAuthorizedLinkKeys({ prompt: authorizedContext }),
  );
  if (unauthorizedLinks.length > 0) {
    return { ok: false, reason: `unauthorized_link:${unauthorizedLinks[0]}` };
  }
  const normalizedCandidate = normalizeForPromptEditGuard(candidate);
  const missingFacts = extractWebOnlyReplyProtectedFacts(original).filter((fact) => {
    if (options.allowCalculatedFactCorrections && /\bR\$\s*\d+(?:[.,]\d{2})?\b|\b\d{1,2}:\d{2}\b/i.test(fact)) {
      return false;
    }
    const normalizedFact = normalizeForPromptEditGuard(fact);
    return normalizedFact && !normalizedCandidate.includes(normalizedFact);
  });
  if (missingFacts.length > 0) {
    return { ok: false, reason: `missing_protected_fact:${missingFacts[0]}` };
  }
  const unsupportedClaim = detectWebOnlyUnsupportedSpecificClaim(candidate, authorizedContext);
  if (
    options.allowCalculatedFactCorrections &&
    /^unsupported_(?:amount|duration):/i.test(unsupportedClaim)
  ) {
    return { ok: true, reason: "calculated_fact_correction" };
  }
  if (unsupportedClaim) {
    return { ok: false, reason: unsupportedClaim };
  }
  return { ok: true, reason: "" };
}

async function optimizeWebOnlyAgentTextResponse(input: {
  userId: string;
  model: string;
  prompt: string;
  message: string;
  history: Array<{ role: "user" | "assistant"; content: string }>;
  responseText: string;
  mediaActions: any[];
  moduleMode: string;
  disabled?: boolean;
  abortSignal?: AbortSignal;
}): Promise<WebOnlyAgenticReplyRuntimeResult> {
  const authorizedContext = [
    input.prompt,
    input.message,
    input.history.slice(-8).map((entry) => entry.content).join("\n"),
  ].join("\n");
  const authorizedLinksForPrompt = Array.from(new Set(
    (authorizedContext.match(/https?:\/\/[^\s)]+|www\.[^\s)]+/gi) || [])
      .map((link) => normalizeWebOnlyUrlForWhatsAppNoPreview(link))
      .filter((link) => isWebOnlyValidUrl(link)),
  )).slice(0, 8);
  const originalText = repairWebOnlyOutgoingText(input.responseText).trim();
  if (input.disabled === true) {
    return { text: originalText, trace: { enabled: false, skipped: "disabled_by_request" } };
  }
  if (!originalText) {
    return { text: originalText, trace: { enabled: false, skipped: "empty_text" } };
  }

  const missingDoorTypeQuestion = buildWebOnlyMissingDoorTypeQuestion({
    message: input.message,
    prompt: input.prompt,
    responseText: originalText,
  });
  if (missingDoorTypeQuestion) {
    return {
      text: missingDoorTypeQuestion,
      trace: {
        enabled: true,
        action: "rewrite",
        reason: "missing_door_type_before_quote",
        moduleMode: input.moduleMode,
      },
    };
  }

  const deterministicM2Correction = buildWebOnlyPromptM2AmountCorrection({
    prompt: input.prompt,
    message: input.message,
    history: input.history,
    responseText: originalText,
  });
  if (deterministicM2Correction) {
    return {
      text: deterministicM2Correction.text,
      trace: {
        enabled: true,
        action: "rewrite",
        reason: "prompt_m2_deterministic_amount_guard",
        invalidAmounts: deterministicM2Correction.invalidAmounts,
        expectedAmount: deterministicM2Correction.expectedAmount,
        expectedAmounts: deterministicM2Correction.expectedAmounts,
        areaM2: deterministicM2Correction.areaM2,
        unitPrice: deterministicM2Correction.unitPrice,
        unitPrices: deterministicM2Correction.unitPrices,
        moduleMode: input.moduleMode,
      },
    };
  }

  const protectedFacts = extractWebOnlyReplyProtectedFacts(originalText);
  const hasPriorAssistant = input.history.some((entry) => entry.role === "assistant" && entry.content.trim());
  const calculatorToolEnabled = shouldUseWebOnlyAgenticCalculatorTool({
    prompt: input.prompt,
    message: input.message,
    responseText: originalText,
  });
  const calculationAudit = calculatorToolEnabled
    ? await runWebOnlyAgenticCalculationAudit({
        userId: input.userId,
        model: input.model,
        prompt: input.prompt,
        message: input.message,
        history: input.history,
        responseText: originalText,
        abortSignal: input.abortSignal,
      }).catch((error: any) => ({
        enabled: false,
        fallback: true,
        lastError: String(error?.message || error).slice(0, 240),
        shouldCalculate: false,
        reason: "calculation_audit_failed",
        operations: [],
        calculation: executeWebOnlyAgenticCalculation({ operations: [] }),
      }))
    : null;
  const priceQuoteAudit = calculatorToolEnabled
    ? await runWebOnlyAgenticPriceQuoteAudit({
        userId: input.userId,
        model: input.model,
        prompt: input.prompt,
        message: input.message,
        history: input.history,
        responseText: originalText,
        abortSignal: input.abortSignal,
      }).catch((error: any) => ({
        enabled: false,
        fallback: true,
        lastError: String(error?.message || error).slice(0, 240),
        raw: null,
        normalized: null,
      }))
    : null;
  const priceQuoteCorrection = buildWebOnlyInvalidPriceQuoteCorrection(
    originalText,
    (priceQuoteAudit as any)?.normalized,
  );
  if (priceQuoteCorrection) {
    return {
      text: priceQuoteCorrection.text,
      trace: {
        enabled: true,
        action: "rewrite",
        reason: "price_quote_calculation_guard",
        calculationAudit,
        priceQuoteAudit,
        invalidAmounts: priceQuoteCorrection.invalidAmounts,
        moduleMode: input.moduleMode,
        questionCountBefore: countReplyQuestions(originalText),
        questionCountAfter: countReplyQuestions(priceQuoteCorrection.text),
      },
    };
  }
  const optimizerTools: WebOnlyAgenticLogicalTool[] = [
    {
      name: "ler_contexto_autorizado",
      purpose: "Confere prompt, historico recente e mensagem atual antes de aceitar ou reescrever a resposta.",
      result: authorizedContext.slice(0, 9000),
    },
    {
      name: "validar_resposta_final",
      purpose: "Lembra as regras de validacao: preservar fatos, usar apenas links autorizados, evitar invencao, evitar saudacao repetida e evitar mojibake.",
      result: {
        protectedFacts,
        authorizedLinks: authorizedLinksForPrompt,
        hasPriorAssistant,
        originalQuestionCount: countReplyQuestions(originalText),
      },
    },
    ...(calculatorToolEnabled
      ? [{
          name: "calcular",
          kind: "calculator" as const,
          purpose: "Executa aritmetica e duracoes de datas/horarios quando o prompt do cliente exige calculo. Use os valores e formulas do prompt/config do tenant; a ferramenta nao contem regra de negocio propria.",
        }]
      : []),
  ];
  const systemPrompt = [
    "Voce e o motor agentico interno do AgenteZap para revisar respostas automaticas antes do envio ao WhatsApp.",
    "Seu trabalho nao e trocar o modulo escolhido, nao e escolher midia, nao e executar fluxo e nao e alterar catalogo.",
    "Revise somente a resposta textual final que ja foi gerada pela IA principal.",
    Array.isArray(input.mediaActions) && input.mediaActions.length > 0
      ? "Ja existem acoes de midia escolhidas por outro modulo. Revise o texto para combinar com essas midias, sem cancelar, inventar ou trocar a midia."
      : "",
    "Se a resposta ja estiver boa, responda JSON com action keep.",
    "Se precisar melhorar, responda JSON com action rewrite e uma resposta final melhor.",
    "Criterios:",
    "- mantenha fatos, valores, links, horarios, nomes de produtos e condicoes que ja aparecem na resposta original;",
    "- use o contexto autorizado do negocio como fonte de verdade;",
    "- nao invente preco, prazo, disponibilidade, endereco, link, produto, regra ou midia;",
    "- nunca crie URL de video, pagina, arquivo ou checkout por conta propria; links so podem vir dos links autorizados do contexto;",
    "- se a resposta disser que vai enviar video/midia e nao houver acao de midia ja escolhida, reescreva sem prometer envio ou explique de forma curta que vai ajudar por mensagem;",
    "- se a resposta original prometer um link, criar conta, cadastro, acesso ou teste, mas a URL estiver faltando, procure nos links autorizados do contexto e reescreva com o link correto;",
    "- se houver um unico link autorizado claramente aplicavel, coloque esse link sozinho na ultima bolha usando [BOLHA], sem frase depois dele;",
    "- se houver varios links autorizados e nao estiver claro qual usar, nao escolha aleatoriamente; responda sem inventar URL ou faca uma pergunta curta;",
    "- se a resposta original trouxer um detalhe especifico que nao aparece no contexto autorizado nem no historico, troque por uma formulacao segura sem esse detalhe;",
    calculatorToolEnabled
      ? "- quando houver calculo de valor, subtotal, total, taxa, quantidade, periodo, horas ou dias, use a ferramenta calcular antes de manter ou reescrever; a formula e os valores continuam vindo do prompt/config do cliente;"
      : "",
    calculatorToolEnabled
      ? "- se a ferramenta calcular provar que um numero da resposta original esta errado, corrija o numero; nao preserve valor errado apenas porque apareceu na resposta original;"
      : "",
    "- reduza confusao e excesso de perguntas; prefira no maximo uma pergunta objetiva por mensagem quando possivel;",
    "- se o cliente demonstrar duvida ou risco, explique de forma curta e segura antes de pedir o proximo passo;",
    "- se o cliente acabou de responder uma opcao, uma pergunta ou uma escolha anterior, NUNCA pergunte a mesma coisa de novo; avance a conversa a partir da resposta dele;",
    "- se a resposta original repetir uma saudacao, pergunta ou estrutura ja usada no historico, reescreva como continuidade objetiva;",
    "- preserve o tom comercial do negocio e responda em portugues do Brasil com acentos corretos; nao transforme voce, la, ate, e, ja, nao em texto sem acento quando a palavra correta for você, lá, até, é, já, não;",
    "- nao mencione prompt, sistema, ferramenta, modelo, API, modulo, bastidor ou regras internas.",
    'Retorne somente JSON valido: {"action":"keep","reason":"ok"} ou {"action":"rewrite","response":"texto final","reason":"motivo curto"}.',
  ].filter(Boolean).join("\n");

  try {
    const agenticRun = await runWebOnlyAgenticTask({
      userId: input.userId,
      task: "reply_text_optimizer",
      model: input.model,
      system: systemPrompt,
      message: [
        "Mensagem atual do cliente:",
        input.message,
        "",
        "Historico recente:",
        input.history.slice(-8).map((entry) => `${entry.role}: ${entry.content}`).join("\n") || "(sem historico)",
        "",
        "Contexto autorizado do negocio/prompt atual:",
        String(input.prompt || "").slice(0, 9000) || "(sem contexto autorizado)",
        "",
        authorizedLinksForPrompt.length
          ? `Links autorizados encontrados no contexto: ${authorizedLinksForPrompt.join(" | ")}`
          : "Links autorizados encontrados no contexto: nenhum",
        "",
        Array.isArray(input.mediaActions) && input.mediaActions.length > 0
          ? [
              "Midias/acoes que ja foram escolhidas por modulo e devem ser respeitadas:",
              input.mediaActions
                .map((action: any, index) =>
                  `${index + 1}. ${[
                    action?.type,
                    action?.media_name || action?.mediaName,
                    action?.caption || action?.text,
                  ].map((part) => String(part || "").trim()).filter(Boolean).join(" | ")}`,
                )
                .join("\n"),
              "",
            ].join("\n")
          : "",
        "Resposta textual original que seria enviada:",
        originalText,
        "",
        calculationAudit
          ? [
              "Contexto de calculo verificado pelo Vercel AI SDK/generateObject:",
              JSON.stringify({
                shouldCalculate: calculationAudit.shouldCalculate,
                reason: calculationAudit.reason,
                operations: calculationAudit.operations,
                result: calculationAudit.calculation,
              }).slice(0, 4000),
              "",
            ].join("\n")
          : "",
        priceQuoteAudit
          ? [
              "Validacao estruturada de orcamento pelo Vercel AI SDK/generateObject:",
              JSON.stringify({
                raw: (priceQuoteAudit as any).raw,
                normalized: (priceQuoteAudit as any).normalized,
              }).slice(0, 4000),
              "",
            ].join("\n")
          : "",
        protectedFacts.length ? `Fatos protegidos que devem continuar se houver rewrite: ${protectedFacts.join(" | ")}` : "",
      ].filter(Boolean).join("\n"),
      history: [],
      temperature: 0.08,
      maxTokens: 700,
      maxSteps: calculatorToolEnabled ? 3 : 2,
      timeoutMs: Math.min(WEB_ONLY_AGENTIC_SDK_TIMEOUT_MS, 8_000),
      abortSignal: input.abortSignal,
      tools: optimizerTools,
      useExecutableTools: calculatorToolEnabled,
      legacyFallback: () => callWebOnlyLlm({
        userId: input.userId,
        model: input.model,
        prompt: systemPrompt,
        message: [
          "Mensagem atual do cliente:",
          input.message,
          "",
          "Historico recente:",
          input.history.slice(-8).map((entry) => `${entry.role}: ${entry.content}`).join("\n") || "(sem historico)",
          "",
          "Contexto autorizado do negocio/prompt atual:",
          String(input.prompt || "").slice(0, 9000) || "(sem contexto autorizado)",
          "",
          authorizedLinksForPrompt.length
            ? `Links autorizados encontrados no contexto: ${authorizedLinksForPrompt.join(" | ")}`
            : "Links autorizados encontrados no contexto: nenhum",
          "",
          "Resposta textual original que seria enviada:",
          originalText,
          "",
          calculationAudit
            ? [
                "Contexto de calculo verificado pelo Vercel AI SDK/generateObject:",
                JSON.stringify({
                  shouldCalculate: calculationAudit.shouldCalculate,
                  reason: calculationAudit.reason,
                  operations: calculationAudit.operations,
                  result: calculationAudit.calculation,
                }).slice(0, 4000),
                "",
              ].join("\n")
            : "",
          priceQuoteAudit
            ? [
                "Validacao estruturada de orcamento pelo Vercel AI SDK/generateObject:",
                JSON.stringify({
                  raw: (priceQuoteAudit as any).raw,
                  normalized: (priceQuoteAudit as any).normalized,
                }).slice(0, 4000),
                "",
              ].join("\n")
            : "",
          protectedFacts.length ? `Fatos protegidos que devem continuar se houver rewrite: ${protectedFacts.join(" | ")}` : "",
        ].filter(Boolean).join("\n"),
        history: [],
        temperature: 0.08,
        maxTokens: 700,
        abortSignal: input.abortSignal,
      }),
    });
    const raw = agenticRun.text;
    const parsed = parseFirstJsonObject(raw);
    const action = String(parsed?.action || "").trim().toLowerCase();
    const calculatorWasUsed =
      didWebOnlyAgenticTaskCallTool(agenticRun.agentTrace, "calcular") ||
      Boolean(calculationAudit?.shouldCalculate) ||
      Boolean((priceQuoteAudit as any)?.normalized?.shouldValidate);
    if (action !== "rewrite") {
      const keepPriceQuoteCorrection = buildWebOnlyInvalidPriceQuoteCorrection(
        originalText,
        (priceQuoteAudit as any)?.normalized,
      );
      if (keepPriceQuoteCorrection) {
        return {
          text: keepPriceQuoteCorrection.text,
          trace: {
            enabled: true,
            action: "rewrite",
            reason: "price_quote_calculation_guard_keep",
            agentic: agenticRun.agentTrace,
            calculationAudit,
            priceQuoteAudit,
            invalidAmounts: keepPriceQuoteCorrection.invalidAmounts,
            moduleMode: input.moduleMode,
            questionCountBefore: countReplyQuestions(originalText),
            questionCountAfter: countReplyQuestions(keepPriceQuoteCorrection.text),
          },
        };
      }
      return {
        text: originalText,
        trace: {
          enabled: true,
          action: "keep",
          reason: String(parsed?.reason || "kept").slice(0, 220),
          agentic: agenticRun.agentTrace,
          calculationAudit,
          priceQuoteAudit,
          moduleMode: input.moduleMode,
          questionCountBefore: countReplyQuestions(originalText),
          questionCountAfter: countReplyQuestions(originalText),
        },
      };
    }

    let candidate = repairWebOnlyOutgoingText(String(parsed?.response || "")).trim();
    let validation = validateWebOnlyAgenticReplyCandidate(originalText, candidate, authorizedContext, {
      hasPriorAssistant,
      allowCalculatedFactCorrections: calculatorWasUsed,
    });
    if (!validation.ok && /^unsupported_/.test(validation.reason)) {
      const repairRun = await runWebOnlyAgenticTask({
        userId: input.userId,
        task: "reply_text_optimizer_repair",
        model: input.model,
        system: systemPrompt,
        message: [
          "A resposta abaixo foi rejeitada por conter detalhe operacional sem base no contexto autorizado.",
          `Motivo da rejeicao: ${validation.reason}`,
          "",
          "Reescreva sem esse detalhe, mantendo a resposta curta, clara e fiel ao contexto.",
          "",
          "Contexto autorizado:",
          String(input.prompt || "").slice(0, 9000) || "(sem contexto autorizado)",
          "",
          authorizedLinksForPrompt.length
            ? `Links autorizados encontrados no contexto: ${authorizedLinksForPrompt.join(" | ")}`
            : "Links autorizados encontrados no contexto: nenhum",
          "",
          "Mensagem atual do cliente:",
          input.message,
          "",
          "Resposta original:",
          originalText,
          "",
          calculationAudit
            ? [
                "Contexto de calculo verificado pelo Vercel AI SDK/generateObject:",
                JSON.stringify({
                  shouldCalculate: calculationAudit.shouldCalculate,
                  reason: calculationAudit.reason,
                  operations: calculationAudit.operations,
                  result: calculationAudit.calculation,
                }).slice(0, 4000),
                "",
              ].join("\n")
            : "",
          "Resposta rejeitada:",
          candidate,
          "",
          'Retorne somente JSON valido: {"action":"rewrite","response":"texto final","reason":"motivo curto"}.',
        ].join("\n"),
        history: [],
        temperature: 0.04,
        maxTokens: 600,
        maxSteps: calculatorToolEnabled ? 3 : 2,
        timeoutMs: Math.min(WEB_ONLY_AGENTIC_SDK_TIMEOUT_MS, 8_000),
        abortSignal: input.abortSignal,
        tools: [
          ...(calculatorToolEnabled
            ? [{
                name: "calcular",
                kind: "calculator" as const,
                purpose: "Executa aritmetica e duracoes de datas/horarios usando os valores e formulas do prompt/config do tenant.",
              }]
            : []),
          {
            name: "remover_detalhe_sem_base",
            purpose: "Remove informacao especifica que nao aparece no contexto autorizado.",
            result: validation.reason,
          },
        ],
        useExecutableTools: calculatorToolEnabled,
        legacyFallback: () => callWebOnlyLlm({
          userId: input.userId,
          model: input.model,
          prompt: systemPrompt,
          message: [
            "A resposta abaixo foi rejeitada por conter detalhe operacional sem base no contexto autorizado.",
            `Motivo da rejeicao: ${validation.reason}`,
            "",
            "Reescreva sem esse detalhe, mantendo a resposta curta, clara e fiel ao contexto.",
            "",
            "Contexto autorizado:",
            String(input.prompt || "").slice(0, 9000) || "(sem contexto autorizado)",
            "",
            authorizedLinksForPrompt.length
              ? `Links autorizados encontrados no contexto: ${authorizedLinksForPrompt.join(" | ")}`
              : "Links autorizados encontrados no contexto: nenhum",
            "",
            "Mensagem atual do cliente:",
            input.message,
            "",
            "Resposta original:",
            originalText,
            "",
            calculationAudit
              ? [
                  "Contexto de calculo verificado pelo Vercel AI SDK/generateObject:",
                  JSON.stringify({
                    shouldCalculate: calculationAudit.shouldCalculate,
                    reason: calculationAudit.reason,
                    operations: calculationAudit.operations,
                    result: calculationAudit.calculation,
                  }).slice(0, 4000),
                  "",
                ].join("\n")
              : "",
            "Resposta rejeitada:",
            candidate,
            "",
            'Retorne somente JSON valido: {"action":"rewrite","response":"texto final","reason":"motivo curto"}.',
          ].join("\n"),
          history: [],
          temperature: 0.04,
          maxTokens: 600,
          abortSignal: input.abortSignal,
        }),
      });
      const repairRaw = repairRun.text;
      const repairParsed = parseFirstJsonObject(repairRaw);
      const repairedCandidate = repairWebOnlyOutgoingText(String(repairParsed?.response || "")).trim();
      if (repairedCandidate) {
        candidate = repairedCandidate;
        const repairCalculatorWasUsed = didWebOnlyAgenticTaskCallTool(repairRun.agentTrace, "calcular");
        validation = validateWebOnlyAgenticReplyCandidate(originalText, candidate, authorizedContext, {
          hasPriorAssistant,
          allowCalculatedFactCorrections: calculatorWasUsed || repairCalculatorWasUsed,
        });
      }
    }
    if (!validation.ok) {
      return {
        text: originalText,
        trace: {
          enabled: true,
          action: "keep",
          reason: "rewrite_rejected",
          agentic: agenticRun.agentTrace,
          calculationAudit,
          priceQuoteAudit,
          validation,
          moduleMode: input.moduleMode,
        },
      };
    }

    let finalPriceQuoteAudit = priceQuoteAudit as any;
    if (!(finalPriceQuoteAudit as any)?.normalized && calculatorToolEnabled) {
      finalPriceQuoteAudit = await runWebOnlyAgenticPriceQuoteAudit({
        userId: input.userId,
        model: input.model,
        prompt: input.prompt,
        message: input.message,
        history: input.history,
        responseText: candidate,
        abortSignal: input.abortSignal,
      }).catch((error: any) => ({
        enabled: false,
        fallback: true,
        lastError: String(error?.message || error).slice(0, 240),
        raw: null,
        normalized: null,
      }));
    }
    const candidatePriceQuoteCorrection = buildWebOnlyInvalidPriceQuoteCorrection(
      candidate,
      (finalPriceQuoteAudit as any)?.normalized,
    );
    if (candidatePriceQuoteCorrection) {
      return {
        text: candidatePriceQuoteCorrection.text,
        trace: {
          enabled: true,
          action: "rewrite",
          reason: "price_quote_calculation_guard_after_optimizer",
          agentic: agenticRun.agentTrace,
          calculationAudit,
          priceQuoteAudit: finalPriceQuoteAudit,
          validation,
          invalidAmounts: candidatePriceQuoteCorrection.invalidAmounts,
          moduleMode: input.moduleMode,
          questionCountBefore: countReplyQuestions(originalText),
          questionCountAfter: countReplyQuestions(candidatePriceQuoteCorrection.text),
        },
      };
    }

    return {
      text: candidate,
      trace: {
        enabled: true,
        action: "rewrite",
        reason: String(parsed?.reason || "improved").slice(0, 220),
        agentic: agenticRun.agentTrace,
        calculationAudit,
        priceQuoteAudit,
        validation,
        moduleMode: input.moduleMode,
        questionCountBefore: countReplyQuestions(originalText),
        questionCountAfter: countReplyQuestions(candidate),
      },
    };
  } catch (error: any) {
    console.warn("[vercel-http] agentic reply optimizer failed; keeping original response:", error?.message || error);
    return {
      text: originalText,
      trace: {
        enabled: true,
        action: "keep",
        reason: "optimizer_failed",
        error: String(error?.message || error).slice(0, 220),
        calculationAudit,
        priceQuoteAudit,
        moduleMode: input.moduleMode,
      },
    };
  }
}

async function runWebOnlyAgentTestForUser(userId: string, body: any) {
  let message = String(body.message || "").trim();
  const abortSignal =
    body?.abortSignal && typeof body.abortSignal === "object" && "aborted" in body.abortSignal
      ? body.abortSignal as AbortSignal
      : undefined;
  const rawMediaItems = Array.isArray(body.mediaItems)
    ? body.mediaItems.slice(0, 10)
    : (body.mediaUrl ? [body] : []);
  if (rawMediaItems.length > 0) {
    const enrichedParts: string[] = [];
    for (const item of rawMediaItems) {
      const enriched = await buildWebOnlyIncomingImageText({
        userId,
        conversationId: body.conversationId || body.conversationKey || body.testConversationKey || null,
        mediaType: item?.mediaType || item?.media_type || body.mediaType || "image",
        mediaUrl: item?.mediaUrl || item?.media_url || item?.url || null,
        mediaUrlOriginal: item?.mediaUrlOriginal || item?.media_url_original || null,
        text: item?.text || item?.caption || "",
        mediaCaption: item?.mediaCaption || item?.media_caption || "",
      }).catch((error) => {
        console.warn("[vercel-http] public test media enrichment failed:", error);
        return String(item?.text || item?.caption || "").trim();
      });
      if (enriched) enrichedParts.push(enriched);
    }
    if (message) enrichedParts.push(message);
    message = enrichedParts.join("\n\n").trim();
  }
  if (!message) {
    return { status: 400, payload: { message: "Mensagem obrigatoria" } };
  }
  if (isIgnorableGatewayIncomingText(message)) {
    return {
      status: 200,
      payload: {
        response: "",
        splitResponses: [],
        mediaActions: [],
        audioResponseMode: "text",
        wouldSendAudio: false,
        wouldSendText: false,
        mode: "ignored_technical_message",
      },
    };
  }

  if (body.skipAccessCheck !== true) {
    const accessStatus = await buildAccessStatusPayloadForUser(userId).catch((error) => {
      console.warn("[vercel-http] agent access check failed:", error?.message || error);
      return null;
    });
    if (accessStatus?.shouldBlock) {
      return {
        status: 402,
        payload: {
          response: "",
          splitResponses: [],
          mediaActions: [],
          audioResponseMode: "text",
          wouldSendAudio: false,
          wouldSendText: false,
          mode: "access_blocked",
          blockReason: accessStatus.blockReason,
          message: accessStatus.message || "Acesso bloqueado. Regularize a assinatura para reativar a IA.",
          accessStatus,
        },
      };
    }
  }

  const history = Array.isArray(body.history) ? body.history : [];
  const conversationHistory = history
    .filter((entry: any) => entry && typeof entry.content === "string")
    .map((entry: any) => ({
      role: entry.role === "assistant" ? "assistant" as const : "user" as const,
      content: String(entry.content || ""),
    }));

  const configResult = await getPool().query(
    `
      SELECT
        aic.prompt,
        aic.model,
        aic.trigger_phrases,
        aic.message_split_chars,
        aic.custom_greeting,
        aic.greeting_variation,
        aic.greeting_enabled,
        aic.custom_address,
        aic.address_enabled,
        aic.business_hours_enabled,
        aic.business_hours,
        aic.off_hours_message_enabled,
        aic.off_hours_variation,
        aic.off_hours_message,
        aic.ai_signature_enabled,
        aic.ai_signature,
        aic.flow_mode_active,
        aic.flow_script,
        bac.company_name AS "businessCompanyName"
      FROM ai_agent_config aic
      LEFT JOIN business_agent_configs bac
        ON bac.user_id = aic.user_id
       AND bac.is_active = true
      WHERE aic.user_id = $1
      LIMIT 1
    `,
    [userId],
  );
  const config = configResult.rows[0];
  const subscriptionPaymentSupportGuardEnabled = shouldApplyWebOnlySubscriptionPaymentSupportGuard(config);
  const notificationConfig = await loadWebOnlyNotificationConfig(userId);

  const contactName = String(body.contactName || "Visitante").trim() || "Visitante";
  const earlyRecognizedCatalogSelectionResponse = buildWebOnlyRecognizedCatalogSelectionResponse(message);
  if (earlyRecognizedCatalogSelectionResponse) {
    const splitResponses = applyWebOnlyTextSettings(earlyRecognizedCatalogSelectionResponse, config);
    return {
      status: 200,
      payload: {
        response: splitResponses.join("\n\n"),
        splitResponses,
        mediaActions: [],
        audioResponseMode: "text",
        wouldSendAudio: false,
        wouldSendText: splitResponses.length > 0,
        mode: "web_catalog_selection",
        catalogSelectionCount: (earlyRecognizedCatalogSelectionResponse.match(/^Item\s+\d+/gmi) || []).length,
      },
    };
  }

  const flow2RuntimeResponse = body.flow2RuntimeEnabled === false
    ? null
    : await runFlow2LeonaRuntimeForUser({
        userId,
        message,
        conversationId: body.conversationId || body.conversationKey || body.testConversationKey || null,
        contactName,
        reset: body.flow2Reset === true,
        deferStatePersistence: body.flow2DeferStatePersistence === true,
      });
  const flow2HandedOffToAi = flow2RuntimeResponse?.handoffToAi === true;
  if (flow2RuntimeResponse?.payload) {
    const flow2Payload: any = flow2RuntimeResponse.payload;
    const manualNotification = detectManualWebOnlyNotification(notificationConfig, {
      clientMessage: message,
      agentMessage: [
        flow2Payload.response,
        ...(Array.isArray(flow2Payload.mediaActions)
          ? flow2Payload.mediaActions.map((action: any) => action?.text || action?.caption || "")
          : []),
      ].join("\n"),
    });
    if (manualNotification) {
      flow2Payload.notification = mergeWebOnlyNotifications(notificationConfig, null, manualNotification);
    }
    return { status: 200, payload: flow2Payload };
  }

  const visualFlowResponse = await buildWebOnlyVisualFlowSimulation({
    userId,
    config,
    body,
    contactName,
  });
  if (visualFlowResponse) {
    const visualPayload: any = visualFlowResponse;
    const manualNotification = detectManualWebOnlyNotification(notificationConfig, {
      clientMessage: message,
      agentMessage: [
        visualPayload.response,
        ...(Array.isArray(visualPayload.splitResponses) ? visualPayload.splitResponses : []),
        ...(Array.isArray(visualPayload.mediaActions)
          ? visualPayload.mediaActions.map((action: any) => action?.text || action?.caption || "")
          : []),
      ].join("\n"),
    });
    if (manualNotification) {
      visualPayload.notification = mergeWebOnlyNotifications(notificationConfig, null, manualNotification);
    }
    return { status: 200, payload: visualPayload };
  }

  if (config?.flow_mode_active === true && !flow2HandedOffToAi) {
    return {
      status: 200,
      payload: {
        response: "",
        splitResponses: [],
        mediaActions: [],
        audioResponseMode: "text",
        wouldSendAudio: false,
        wouldSendText: false,
        mode: "visual_flow_active_no_step",
      },
    };
  }

  if (config && !hasWebOnlyTriggerMatch(config.trigger_phrases, message, conversationHistory)) {
    return {
      status: 200,
      payload: {
        response: "",
        splitResponses: [],
        mediaActions: [],
        audioResponseMode: "text",
        wouldSendAudio: false,
        wouldSendText: false,
        mode: "trigger_blocked",
      },
    };
  }

  const agendamento3AgentResponse = await runAgendamento3AgentForUser({
    userId,
    message,
    history: conversationHistory,
    contactName,
    contactPhone: body.contactPhone || body.contactNumber || body.phone || null,
    conversationId: body.conversationId || body.conversationKey || body.testConversationKey || null,
    commit: body.agendamento3Commit === true || body.commitScheduling === true,
  }).catch((error: any) => {
    console.error("[vercel-http] Agendamento 3.0 agent failed:", error);
    return null;
  });
  if (agendamento3AgentResponse?.handled) {
    const splitResponses = applyWebOnlyTextSettings(agendamento3AgentResponse.response, config);
    return {
      status: 200,
      payload: {
        response: splitResponses.join("\n\n"),
        splitResponses,
        mediaActions: [],
        audioResponseMode: "text",
        wouldSendAudio: false,
        wouldSendText: splitResponses.length > 0,
        mode: "agendamento3",
        agendamento3: agendamento3AgentResponse,
      },
    };
  }

  if (hasWebOnlyPriorAssistantMessage(conversationHistory) && hasWebOnlyCustomerRepetitionComplaint(message)) {
    const splitResponses = applyWebOnlyTextSettings(buildWebOnlyCustomerRepetitionComplaintText(), config);
    return {
      status: 200,
      payload: {
        response: splitResponses.join("\n\n"),
        splitResponses,
        mediaActions: [],
        audioResponseMode: "text",
        wouldSendAudio: false,
        wouldSendText: splitResponses.length > 0,
        mode: "customer_repetition_complaint",
      },
    };
  }

  if (hasWebOnlyPriorAssistantMessage(conversationHistory) && hasWebOnlyCustomerSoftClose(message)) {
    const splitResponses = applyWebOnlyTextSettings(buildWebOnlyCustomerSoftCloseText(), config);
    return {
      status: 200,
      payload: {
        response: splitResponses.join("\n\n"),
        splitResponses,
        mediaActions: [],
        audioResponseMode: "text",
        wouldSendAudio: false,
        wouldSendText: splitResponses.length > 0,
        mode: "customer_soft_close",
      },
    };
  }

  const buildCatalogSelectionOperationalMediaActions = async (responseText: string): Promise<any[]> => {
    const selectionMediaLibrary = await loadWebOnlyAgentMediaLibrary(userId).catch((error) => {
      console.warn("[vercel-http] failed to load media library for catalog selection:", error);
      return [];
    });
    const operationalMediaActions = buildWebOnlyOperationalMediaActions({
      message,
      responseText,
      mediaLibrary: selectionMediaLibrary,
      sentMedias: body.sentMedias,
      contactName,
    });
    return filterWebOnlyMediaActionsByIntentGuards({
      message,
      history: conversationHistory,
      mediaActions: operationalMediaActions,
      mediaLibrary: selectionMediaLibrary,
      subscriptionPaymentSupportGuardEnabled,
    }).kept;
  };

  const exactCatalogSelectionResponse = await buildWebOnlyExactCatalogSelectionResponseFromCodes({
    userId,
    message,
    history: conversationHistory,
  }).catch((error) => {
    console.warn("[vercel-http] exact catalog selection by code failed:", error);
    return null;
  });
  if (exactCatalogSelectionResponse) {
    const mediaActions: any[] = [];
    const splitResponses = applyWebOnlyTextSettings(exactCatalogSelectionResponse, config);
    return {
      status: 200,
      payload: {
        response: splitResponses.join("\n\n"),
        splitResponses,
        mediaActions,
        audioResponseMode: "text",
        wouldSendAudio: false,
        wouldSendText: splitResponses.length > 0,
        mode: "web_catalog_selection_exact",
        catalogSelectionCount: (exactCatalogSelectionResponse.match(/^Item\s+\d+/gmi) || []).length,
      },
    };
  }

  const analyzedImageCatalogSelectionResponse = await buildWebOnlyCatalogSelectionResponseFromAnalyzedImages({
    userId,
    message,
    conversationId: body.conversationId || body.conversationKey || body.testConversationKey || null,
  }).catch((error) => {
    console.warn("[vercel-http] analyzed image catalog selection response failed:", error);
    return null;
  });
  if (analyzedImageCatalogSelectionResponse) {
    const mediaActions: any[] = [];
    const splitResponses = applyWebOnlyTextSettings(analyzedImageCatalogSelectionResponse, config);
    return {
      status: 200,
      payload: {
        response: splitResponses.join("\n\n"),
        splitResponses,
        mediaActions,
        audioResponseMode: "text",
        wouldSendAudio: false,
        wouldSendText: splitResponses.length > 0,
        mode: "web_catalog_selection_image_analysis",
        catalogSelectionCount: (analyzedImageCatalogSelectionResponse.match(/^Item\s+\d+/gmi) || []).length,
      },
    };
  }

  const recognizedCatalogSelectionResponse = buildWebOnlyRecognizedCatalogSelectionResponse(message);
  if (recognizedCatalogSelectionResponse) {
    const mediaActions: any[] = [];
    const splitResponses = applyWebOnlyTextSettings(recognizedCatalogSelectionResponse, config);
    return {
      status: 200,
      payload: {
        response: splitResponses.join("\n\n"),
        splitResponses,
        mediaActions,
        audioResponseMode: "text",
        wouldSendAudio: false,
        wouldSendText: splitResponses.length > 0,
        mode: "web_catalog_selection",
        catalogSelectionCount: (recognizedCatalogSelectionResponse.match(/^Item\s+\d+/gmi) || []).length,
      },
    };
  }

  const grupoOlxAgenticResponse = await runWebOnlyGrupoOlxAgenticCatalogResponse({
    userId,
    message,
    history: conversationHistory,
    contactName,
    model: String(config?.model || "mistral-small-latest"),
  }).catch((error: any) => {
    console.error("[vercel-http] Grupo OLX agentic catalog failed:", error);
    return null;
  });
  if (grupoOlxAgenticResponse?.handled) {
    const splitResponses = applyWebOnlyTextSettings(grupoOlxAgenticResponse.response, config);
    return {
      status: 200,
      payload: {
        response: splitResponses.join("\n\n"),
        splitResponses,
        mediaActions: [],
        audioResponseMode: "text",
        wouldSendAudio: false,
        wouldSendText: splitResponses.length > 0,
        mode: grupoOlxAgenticResponse.mode,
        grupoOlxAgentic: {
          matchedListingCodes: grupoOlxAgenticResponse.matchedListingCodes,
          confidence: grupoOlxAgenticResponse.confidence,
          reason: grupoOlxAgenticResponse.reason,
          trace: grupoOlxAgenticResponse.agentTrace,
        },
        agenticRuntime: grupoOlxAgenticResponse.agentTrace,
      },
    };
  }

  const unifiedAgentResponse = await runUnifiedAgentTestForUser(userId, body);
  if (unifiedAgentResponse) {
    const payload: any = unifiedAgentResponse.payload || {};
    const structuredResponse = parseWebOnlyStructuredAgentResponse(String(payload.response || ""));
    if (structuredResponse.attention) {
      payload.attention = structuredResponse.attention;
      payload.response = structuredResponse.cleanText;
      payload.splitResponses = applyWebOnlyTextSettings(structuredResponse.cleanText, config);
    }
    const taggedNotification = parseWebOnlyNotificationTaggedResponse(String(payload.response || ""));
    if (taggedNotification.notification) {
      payload.response = taggedNotification.cleanText;
      payload.splitResponses = applyWebOnlyTextSettings(taggedNotification.cleanText, config);
    }
    const manualNotification = detectManualWebOnlyNotification(notificationConfig, {
      clientMessage: message,
      agentMessage: [
        payload.response,
        ...(Array.isArray(payload.splitResponses) ? payload.splitResponses : []),
        ...(Array.isArray(payload.mediaActions)
          ? payload.mediaActions.map((action: any) => action?.text || action?.caption || "")
          : []),
      ].join("\n"),
    });
    payload.notification = mergeWebOnlyNotifications(
      notificationConfig,
      payload.notification || taggedNotification.notification,
      manualNotification,
    ) || payload.notification || null;
    const unifiedMediaLibrary = await loadWebOnlyAgentMediaLibrary(userId).catch((error) => {
      console.warn("[vercel-http] unified media library load failed:", error);
      return [];
    });
    const unifiedActivePrompt = body.customPrompt ? String(body.customPrompt) : String(config?.prompt || "");
    let unifiedText = sanitizeWebOnlyFinalCustomerTextArtifacts(String(payload.response || ""));
    let unifiedMediaActions = Array.isArray(payload.mediaActions) ? payload.mediaActions : [];
    const unifiedSafety = reconcileWebOnlyResponseLinksAndMedia({
      text: unifiedText,
      mediaActions: unifiedMediaActions,
      mediaLibrary: unifiedMediaLibrary,
      prompt: unifiedActivePrompt,
      message,
      history: conversationHistory,
      sentMedias: body.sentMedias,
      contactName,
    });
    unifiedText = unifiedSafety.text;
    unifiedMediaActions = unifiedSafety.mediaActions;
    const unifiedIntentGuardedMedia = filterWebOnlyMediaActionsByIntentGuards({
      message,
      history: conversationHistory,
      mediaActions: unifiedMediaActions,
      mediaLibrary: unifiedMediaLibrary,
      sentMedias: body.sentMedias,
      subscriptionPaymentSupportGuardEnabled,
      strictAgenteZapFunnelEnabled: subscriptionPaymentSupportGuardEnabled,
    });
    unifiedMediaActions = unifiedIntentGuardedMedia.kept;
    const unifiedStrictFunnel = applyWebOnlyAgenteZapStrictFunnelGuard({
      enabled: subscriptionPaymentSupportGuardEnabled,
      message,
      history: conversationHistory,
      sentMedias: body.sentMedias,
      text: unifiedText,
      mediaActions: unifiedMediaActions,
      mediaLibrary: unifiedMediaLibrary,
      contactName,
    });
    unifiedText = unifiedStrictFunnel.text;
    unifiedMediaActions = unifiedStrictFunnel.mediaActions;
    unifiedText = sanitizeWebOnlyFinalCustomerTextArtifacts(unifiedText);
    unifiedText = stripWebOnlyMediaActionNamePlaceholders(unifiedText, unifiedMediaActions);
    const unifiedRequiredFinalLines = applyWebOnlyPromptRequiredFinalLines(unifiedText, unifiedActivePrompt);
    unifiedText = unifiedRequiredFinalLines.text;
    payload.mediaActions = unifiedMediaActions;
    payload.splitResponses = applyWebOnlyTextSettings(unifiedText, config);
    payload.response = payload.splitResponses.join("\n\n");
    payload.agenticRuntime = {
      ...(payload.agenticRuntime || {}),
      unifiedResponseSafety: unifiedSafety.trace,
      unifiedMediaIntentGuard: unifiedIntentGuardedMedia.dropped,
      configuredSequentialFunnel: unifiedStrictFunnel.trace,
      promptRequiredFinalLines: unifiedRequiredFinalLines.applied,
    };
    unifiedAgentResponse.payload = payload;
    return unifiedAgentResponse;
  }

  if (!config?.prompt && !body.customPrompt) {
    return {
      status: 200,
      payload: {
        response: "Seu agente ainda nao esta configurado para teste.",
        splitResponses: ["Seu agente ainda nao esta configurado para teste."],
        mediaActions: [],
      },
    };
  }

  const mediaLibrary = await loadWebOnlyAgentMediaLibrary(userId);
  const estampariaStrictModeEnabled = await loadWebOnlyEstampariaStrictModeEnabled(userId).catch((error) => {
    console.warn("[vercel-http] failed to load Estamparia strict mode:", error);
    return false;
  });
  const isFirstAgentResponse = !conversationHistory.some(
    (entry: { role: "user" | "assistant"; content: string }) => entry.role === "assistant",
  ) && !hasWebOnlyGreetingOpeningAlreadySent(body.sentMedias);
  let openingRule = isFirstAgentResponse ? resolveWebOnlyOpeningRule(config, contactName) : null;
  if (
    isFirstAgentResponse &&
    !openingRule &&
    config?.greeting_enabled === true &&
    findWebOnlyGreetingFlow(mediaLibrary)
  ) {
    openingRule = {
      source: "greeting" as const,
      text: "",
      variationEnabled: config.greeting_variation === true,
    };
  }
  if (openingRule) {
    const openingFlowActions = buildWebOnlyGreetingOpeningFlowActions({
      mediaLibrary,
      openingText: openingRule.text,
      contactName,
    });

    if (openingFlowActions.length > 0) {
      const signedActions = mergeWebOnlyMediaActions([], applyWebOnlyActionTextSettings(openingFlowActions, config));
      return {
        status: 200,
        payload: {
          response: "",
          splitResponses: [],
          mediaActions: signedActions,
          audioResponseMode: "text",
          wouldSendAudio: false,
          wouldSendText: signedActions.some((action) => action?.type === "send_text"),
          mode: "opening_flow",
        },
      };
    }

    if (openingRule.source === "off_hours" || isWebOnlySimpleGreetingMessage(message)) {
      const splitResponses = applyWebOnlyTextSettings(openingRule.text, config);
      return {
        status: 200,
        payload: {
          response: splitResponses.join("\n\n"),
          splitResponses,
          mediaActions: [],
          audioResponseMode: "text",
          wouldSendAudio: false,
          wouldSendText: splitResponses.length > 0,
          mode: openingRule.source === "off_hours" ? "off_hours_opening" : "greeting_opening",
        },
      };
    }
  }

  const agendamento2PromptBlock = await buildWebOnlyAgendamento2PromptBlock(userId).catch((error) => {
    console.error("[vercel-http] failed to load Agendamento 2.0 prompt context:", error);
    return "";
  });
  const grupoOlxPromptBlock = await buildWebOnlyGrupoOlxPromptBlock(userId, message, conversationHistory).catch((error) => {
    console.error("[vercel-http] failed to load Grupo OLX prompt context:", error);
    return "";
  });

  const rawResponseText = await callWebOnlyLlm({
    userId,
    model: String(config?.model || "mistral-small-latest"),
    prompt: body.customPrompt ? String(body.customPrompt) : String(config.prompt),
    systemExtra: [
      WEB_ONLY_LINK_BUBBLE_PROMPT,
      WEB_ONLY_WHATSAPP_FORMAT_PROMPT,
      buildWebOnlyAgenticContinuityPromptBlock({
        message,
        history: conversationHistory,
        mediaLibrary,
        sentMedias: body.sentMedias,
      }),
      buildWebOnlyAgentInfoInstruction(config, openingRule, message),
      buildWebOnlyMediaPromptBlock(mediaLibrary),
      buildWebOnlyNotificationPrompt(notificationConfig),
      buildWebOnlyAttentionPromptBlock(),
      agendamento2PromptBlock,
      grupoOlxPromptBlock,
    ].join("\n"),
    message,
    history: conversationHistory,
    sentMedias: body.sentMedias,
    abortSignal,
    finalSystemInstruction: [
      WEB_ONLY_WHATSAPP_FORMAT_PROMPT,
      WEB_ONLY_LINK_BUBBLE_PROMPT,
    ].join("\n"),
  });
  const structuredResponse = parseWebOnlyStructuredAgentResponse(rawResponseText);
  const activePrompt = body.customPrompt ? String(body.customPrompt) : String(config.prompt);
  const preNotificationCleanText = sanitizeWebOnlyPrematureClosingText({
    text: structuredResponse.cleanText,
    message,
    prompt: activePrompt,
  });
  const parsedNotificationResponse = parseWebOnlyNotificationTaggedResponse(preNotificationCleanText);
  const continuityCleanText = stripWebOnlyRepeatedOpeningGreeting(
    parsedNotificationResponse.cleanText,
    conversationHistory,
    hasWebOnlyGreetingOpeningAlreadySent(body.sentMedias),
  );
  const parsedMediaResponse = parseWebOnlyMediaTaggedResponse(
    repairWebOnlyOutgoingText(continuityCleanText),
  );
  let mediaActions: any[] = [];
  let removedDuplicateMediaActionCount = 0;
  if (parsedMediaResponse.actions.length > 0) {
    const sentKeys = getSimulatorSentMediaKeys(body.sentMedias);
    mediaActions = parsedMediaResponse.actions.flatMap((action: any) => {
      const compactName = compactSimulatorMediaName(action?.media_name);
      const normalizedName = normalizeSimulatorMediaName(action?.media_name);
      if (sentKeys.has(compactName) || sentKeys.has(normalizedName)) {
        removedDuplicateMediaActionCount += 1;
        return [];
      }
      return expandWebOnlySimulatorMediaAction(action, mediaLibrary, contactName);
    });
  }
  let cleanText = repairWebOnlyOutgoingText(shouldSuppressWebOnlyTextForActions(parsedMediaResponse.actions, mediaLibrary)
    ? ""
    : parsedMediaResponse.cleanText);
  if (
    estampariaStrictModeEnabled &&
    !cleanText &&
    mediaActions.length === 0 &&
    removedDuplicateMediaActionCount > 0
  ) {
    cleanText = buildWebOnlyEstampariaDuplicateMediaTextFallback(message);
  }
  if (estampariaStrictModeEnabled) {
    cleanText = sanitizeWebOnlyEstampariaFreightResponse(message, cleanText);
  }
  const operationalMediaActions = buildWebOnlyOperationalMediaActions({
    message,
    responseText: cleanText,
    mediaLibrary,
    sentMedias: body.sentMedias,
    contactName,
  });
  mediaActions = mergeWebOnlyMediaActions(mediaActions, operationalMediaActions);
  const contextualMediaActions = buildWebOnlyContextualMediaActions({
    message,
    responseText: cleanText,
    mediaLibrary,
    sentMedias: body.sentMedias,
    contactName,
  });
  mediaActions = mergeWebOnlyMediaActions(mediaActions, contextualMediaActions);
  if (estampariaStrictModeEnabled) {
    const estampariaProductMediaActions = buildWebOnlyEstampariaProductMediaActions({
      message,
      responseText: cleanText,
      mediaLibrary,
      sentMedias: body.sentMedias,
      contactName,
    });
    mediaActions = mergeWebOnlyMediaActions(mediaActions, estampariaProductMediaActions);
  }
  const catalogMediaActions = await buildWebOnlyCatalogMediaActions({
    userId,
    message,
    responseText: cleanText,
    sentMedias: body.sentMedias,
    contactName,
  });
  mediaActions = mergeWebOnlyMediaActions(mediaActions, catalogMediaActions);
  const moduleMode = catalogMediaActions.length > 0 ? "web_catalog_media" : "web_only";
  const mediaArbitrationRuntime = await arbitrateWebOnlyMediaActionsWithAgenticRuntime({
    userId,
    model: String(config?.model || "mistral-small-latest"),
    prompt: activePrompt,
    message,
    history: conversationHistory,
    responseText: cleanText,
    mediaActions,
    mediaLibrary,
    moduleMode,
    sentMedias: body.sentMedias,
    disabled: body.agenticRuntimeEnabled === false,
    abortSignal,
  });
  mediaActions = mediaArbitrationRuntime.mediaActions;
  const intentGuardedMedia = filterWebOnlyMediaActionsByIntentGuards({
    message,
    history: conversationHistory,
    mediaActions,
    mediaLibrary,
    sentMedias: body.sentMedias,
    subscriptionPaymentSupportGuardEnabled,
    strictAgenteZapFunnelEnabled: subscriptionPaymentSupportGuardEnabled,
  });
  mediaActions = intentGuardedMedia.kept;
  const agenticRuntime = await optimizeWebOnlyAgentTextResponse({
    userId,
    model: String(config?.model || "mistral-small-latest"),
    prompt: activePrompt,
    message,
    history: conversationHistory,
    responseText: cleanText,
    mediaActions,
    moduleMode,
    disabled: body.agenticRuntimeEnabled === false,
    abortSignal,
  });
  cleanText = agenticRuntime.text;
  cleanText = stripWebOnlyRepeatedOpeningGreeting(
    cleanText,
    conversationHistory,
    hasWebOnlyGreetingOpeningAlreadySent(body.sentMedias),
  );
  const safetyRuntime = reconcileWebOnlyResponseLinksAndMedia({
    text: cleanText,
    mediaActions,
    mediaLibrary,
    prompt: activePrompt,
    message,
    history: conversationHistory,
    sentMedias: body.sentMedias,
    contactName,
  });
  cleanText = safetyRuntime.text;
  mediaActions = safetyRuntime.mediaActions;
  mediaActions = mergeWebOnlyMediaActions(mediaActions, buildWebOnlyPromisedContextualMediaActions({
    message,
    responseText: cleanText,
    mediaLibrary,
    sentMedias: body.sentMedias,
    existingMediaActions: mediaActions,
    contactName,
  }));
  if (
    subscriptionPaymentSupportGuardEnabled &&
    hasWebOnlySubscriptionPaymentSupportIntent(message)
  ) {
    cleanText = buildWebOnlySubscriptionPaymentSupportText(message);
    mediaActions = [];
  }
  const strictFunnelRuntime = applyWebOnlyAgenteZapStrictFunnelGuard({
    enabled: subscriptionPaymentSupportGuardEnabled,
    message,
    history: conversationHistory,
    sentMedias: body.sentMedias,
    text: cleanText,
    mediaActions,
    mediaLibrary,
    contactName,
  });
  cleanText = strictFunnelRuntime.text;
  mediaActions = strictFunnelRuntime.mediaActions;
  cleanText = sanitizeWebOnlyPrematureClosingText({
    text: cleanText,
    message,
    prompt: activePrompt,
  });
  cleanText = sanitizeWebOnlyFinalCustomerTextArtifacts(cleanText);
  cleanText = stripWebOnlyMediaActionNamePlaceholders(cleanText, mediaActions);
  if (catalogMediaActions.length > 0) {
    cleanText = ensureWebOnlyCatalogMediaTextMentionsSelectedThemes(cleanText, catalogMediaActions);
  }
  const requiredFinalLines = applyWebOnlyPromptRequiredFinalLines(cleanText, activePrompt);
  cleanText = requiredFinalLines.text;
  agenticRuntime.trace = {
    ...agenticRuntime.trace,
    mediaArbitration: mediaArbitrationRuntime.trace,
    responseSafety: safetyRuntime.trace,
    mediaIntentGuard: intentGuardedMedia.dropped,
    subscriptionPaymentSupportGuardEnabled,
    configuredSequentialFunnel: strictFunnelRuntime.trace,
    promptRequiredFinalLines: requiredFinalLines.applied,
  };
  const splitMessages = applyWebOnlyTextSettings(cleanText, config);
  const manualNotification = detectManualWebOnlyNotification(notificationConfig, {
    clientMessage: message,
    agentMessage: splitMessages.join("\n"),
  });
  const notification = mergeWebOnlyNotifications(
    notificationConfig,
    parsedNotificationResponse.notification,
    manualNotification,
  );

  return {
    status: 200,
    payload: {
      response: splitMessages.join("\n\n"),
      splitResponses: splitMessages,
      mediaActions,
      audioResponseMode: "text",
      wouldSendAudio: false,
      wouldSendText: splitMessages.length > 0,
      mode: moduleMode,
      catalogMediaActionsCount: catalogMediaActions.length,
      notification,
      attention: structuredResponse.attention,
      agenticRuntime: agenticRuntime.trace,
    },
  };
}

