function sanitizeApiKey(value: unknown): string {
  return String(value ?? "").replace(/\s+/g, "").trim();
}

function optionalText(value: unknown, fallback = ""): string {
  const text = String(value ?? "").trim();
  return text || fallback;
}

async function loadWebOnlyLlmConfig(userId: string) {
  const keys = [
    "llm_provider",
    "groq_api_key",
    "groq_model",
    "openrouter_api_key",
    "openrouter_model",
    "mistral_api_key",
    "mistral_model",
    "status_nvidia_api_key",
    "blog_nvidia_api_key",
    "nvidia_api_key",
    "nvidia_model",
    "prompt_edit_model",
    "prompt_edit_models",
  ];
  const db = getPool();
  const [globalResult, agentResult] = await Promise.all([
    db.query("SELECT chave, valor FROM system_config WHERE chave = ANY($1::text[])", [keys]),
    db.query("SELECT llm_config FROM ai_agent_config WHERE user_id = $1 LIMIT 1", [userId]),
  ]);

  const map = new Map(globalResult.rows.map((row) => [String(row.chave), row.valor || ""]));
  const base = {
    provider: optionalText(map.get("llm_provider"), "mistral").toLowerCase(),
    mistralApiKey: sanitizeApiKey(process.env.MISTRAL_API_KEY || map.get("mistral_api_key")),
    mistralModel: optionalText(map.get("mistral_model"), "mistral-medium-latest"),
    openrouterApiKey: sanitizeApiKey(process.env.OPENROUTER_API_KEY || map.get("openrouter_api_key")),
    openrouterModel: optionalText(map.get("openrouter_model"), "google/gemma-3-4b-it:free"),
    groqApiKey: sanitizeApiKey(process.env.GROQ_API_KEY || map.get("groq_api_key")),
    groqModel: optionalText(map.get("groq_model"), "openai/gpt-oss-20b"),
    nvidiaApiKey: sanitizeApiKey(
      process.env.NVIDIA_API_KEY ||
        process.env.STATUS_NVIDIA_API_KEY ||
        process.env.BLOG_NVIDIA_API_KEY ||
        map.get("nvidia_api_key") ||
        map.get("status_nvidia_api_key") ||
        map.get("blog_nvidia_api_key"),
    ),
    nvidiaModel: optionalText(map.get("nvidia_model"), "nvidia/llama-3.3-nemotron-super-49b-v1"),
    promptEditModel: optionalText(process.env.PROMPT_EDIT_MODEL || map.get("prompt_edit_model"), ""),
    promptEditModels: optionalText(process.env.PROMPT_EDIT_MODELS || map.get("prompt_edit_models"), ""),
  };

  const override = agentResult.rows[0]?.llm_config;
  if (!override || typeof override !== "object" || override.mode !== "custom") {
    return base;
  }

  return {
    provider: optionalText(override.provider, base.provider).toLowerCase(),
    mistralApiKey: sanitizeApiKey(override.mistralApiKey || base.mistralApiKey),
    mistralModel: optionalText(override.mistralModel, base.mistralModel),
    openrouterApiKey: sanitizeApiKey(override.openrouterApiKey || base.openrouterApiKey),
    openrouterModel: optionalText(override.openrouterModel, base.openrouterModel),
    groqApiKey: sanitizeApiKey(override.groqApiKey || base.groqApiKey),
    groqModel: optionalText(override.groqModel, base.groqModel),
    nvidiaApiKey: sanitizeApiKey(override.nvidiaApiKey || base.nvidiaApiKey),
    nvidiaModel: optionalText(override.nvidiaModel, base.nvidiaModel),
    promptEditModel: optionalText(override.promptEditModel, base.promptEditModel),
    promptEditModels: optionalText(override.promptEditModels, base.promptEditModels),
  };
}

