function combineAbortSignals(signals: Array<AbortSignal | null | undefined>): AbortSignal | undefined {
  const activeSignals = signals.filter((signal): signal is AbortSignal => Boolean(signal));
  if (activeSignals.length === 0) return undefined;
  if (activeSignals.length === 1) return activeSignals[0];

  const nativeAny = (AbortSignal as any).any;
  if (typeof nativeAny === "function") {
    return nativeAny(activeSignals);
  }

  const controller = new AbortController();
  const abortFromSignal = (signal: AbortSignal) => {
    if (controller.signal.aborted) return;
    try {
      controller.abort((signal as any).reason);
    } catch {
      controller.abort();
    }
  };

  for (const signal of activeSignals) {
    if (signal.aborted) {
      abortFromSignal(signal);
      break;
    }
    signal.addEventListener("abort", () => abortFromSignal(signal), { once: true });
  }

  return controller.signal;
}

