async function handleAgentGeneratePrompt(req: any, res: any) {
  const user = await requireJwtUser(req, res);
  if (!user) return;

  try {
    const body = await readJsonBody(req);
    const businessType = String(body.businessType || "custom").trim();
    const businessName = String(body.businessName || "Meu negocio").trim();
    const description = String(body.description || "").trim();
    const additionalInfo = String(body.additionalInfo || "").trim();

    if (!description && !businessName) {
      return sendJson(res, 400, { message: "Descreva o negocio para criar o agente." });
    }

    const localFallback = buildLocalGeneratedAgentPrompt({ businessType, businessName, description, additionalInfo });
    let prompt = localFallback;
    try {
      const generated = await callWebOnlyLlm({
        userId: user.id,
        model: "",
        prompt: [
          "Voce cria prompts de atendimento WhatsApp para o AgenteZap.",
          "Retorne somente o prompt final, sem markdown externo e sem explicacao.",
          "O prompt deve ser completo, claro, em portugues do Brasil e sem caracteres quebrados.",
          "Inclua regras para nao inventar informacoes, confirmar dados importantes e preservar midias/catalogo/fluxos quando existirem.",
        ].join("\n"),
        message: [
          `Tipo: ${businessType}`,
          `Nome: ${businessName}`,
          `Descricao: ${description}`,
          `Informacoes adicionais: ${additionalInfo}`,
        ].join("\n"),
        history: [],
        temperature: 0.2,
        maxTokens: 2200,
        timeoutMs: 10_000,
      });
      const cleanGenerated = extractPromptFinalFromEditResponse(generated).trim();
      if (cleanGenerated.length >= 600 && !hasPromptMojibake(cleanGenerated)) {
        prompt = cleanGenerated;
      }
    } catch (error) {
      console.warn("[vercel-http] generate prompt used local fallback:", {
        reason: classifyPromptEditInternalError(error),
      });
    }

    return sendJson(res, 200, {
      prompt,
      flowCreated: false,
      calibration: {
        calibrated: false,
        reason: "Criado pelo gerador rapido do app.",
      },
    });
  } catch (error: any) {
    console.error("[vercel-http] generate prompt failed:", error);
    return sendJson(res, 500, { message: "Failed to generate prompt" });
  }
}

