async function handleSubscriptionById(req: any, res: any) {
  const user = await requireJwtUser(req, res);
  if (!user) return;

  try {
    const subscriptionId = String(req.params?.subscriptionId || "").trim();
    const subscription = await getSubscriptionByIdWithPlan(subscriptionId, user.id);
    if (!subscription) {
      return sendJson(res, 404, { message: "Subscription not found" });
    }

    const plan = subscription.plan as Record<string, any> | null;
    if (plan) {
      const charge = await resolveSubscriptionChargeAmounts({
        userId: user.id,
        subscriptionId: subscription.id,
        plan,
        couponPrice: subscription.couponPrice,
      });
      subscription.plan = {
        ...plan,
        valorPrimeiraCobranca: charge.hasDifferentFirstCharge ? plan.valorPrimeiraCobranca : null,
      };
    }

    return sendJson(res, 200, subscription);
  } catch (error) {
    console.error("[vercel-http] subscription by id failed:", error);
    return sendJson(res, 500, { message: "Failed to fetch subscription" });
  }
}

