async function handleValidateCoupon(req: any, res: any) {
  try {
    const body = await readJsonBody(req);
    const code = String(body.code || "").trim().toUpperCase();
    const planTipo = String(body.planTipo || "").trim();
    if (!code) {
      return sendJson(res, 400, { message: "Codigo do cupom e obrigatorio", valid: false });
    }

    const result = await getPool().query("SELECT * FROM coupons WHERE UPPER(code) = $1 LIMIT 1", [code]);
    const coupon = result.rows[0];
    if (!coupon) {
      return sendJson(res, 404, { message: "Cupom nao encontrado", valid: false });
    }
    if (coupon.is_active !== true) {
      return sendJson(res, 400, { message: "Cupom expirado ou inativo", valid: false });
    }
    if (coupon.max_uses && Number(coupon.max_uses) > 0 && Number(coupon.current_uses || 0) >= Number(coupon.max_uses)) {
      return sendJson(res, 400, { message: "Cupom esgotado", valid: false });
    }
    if (coupon.valid_until && new Date(coupon.valid_until) < new Date()) {
      return sendJson(res, 400, { message: "Cupom expirado", valid: false });
    }

    const applicablePlans = Array.isArray(coupon.applicable_plans) ? coupon.applicable_plans : null;
    if (planTipo && applicablePlans?.length && !applicablePlans.includes(planTipo)) {
      return sendJson(res, 400, { message: "Cupom nao valido para este plano", valid: false });
    }

    return sendJson(res, 200, {
      valid: true,
      finalPrice: coupon.final_price,
      discountType: coupon.discount_type,
      code: coupon.code,
      applicablePlans,
    });
  } catch (error: any) {
    console.error("[vercel-http] coupon validate failed:", error);
    return sendJson(res, 500, { message: "Erro ao validar cupom", error: error?.message });
  }
}

function generateAddonUpsellCouponCode() {
  const randomToken = Math.random().toString(36).slice(2, 8).toUpperCase();
  return `FLASH${randomToken}`;
}

async function handleCreateAddonUpsellCoupon(req: any, res: any) {
  const user = await requireJwtUser(req, res);
  if (!user) return;

  try {
    const body = await readJsonBody(req);
    const targetSubscriptionId = String(body.checkoutTargetSubscriptionId || "").trim();
    const offerKind = String(body.offerKind || "").trim().toLowerCase();
    if (!targetSubscriptionId) {
      return sendJson(res, 400, { message: "Assinatura base do upsell nao informada." });
    }

    const targetSubscription = await getSubscriptionByIdForAddonUpsell(targetSubscriptionId, user.id);
    if (!targetSubscription) {
      return sendJson(res, 404, { message: "Assinatura base do upsell nao encontrada." });
    }

    const secureCheckout = computeAddonUpsellCheckoutFromBody(
      {
        ...body,
        checkoutMode: "addon_upsell",
      },
      targetSubscription as Record<string, any>,
    );

    if ((secureCheckout.purchasedAddonIds || []).length === 0) {
      return sendJson(res, 400, { message: "Os adicionais selecionados ja estao liberados nesta conta." });
    }

    const planTipo = String(targetSubscription.plan?.tipo || targetSubscription.plan?.periodicidade || "").trim();
    const now = Date.now();
    const validUntil = new Date(now + 15 * 60 * 1000);
    const baseAmount = roundCurrencyAmount(secureCheckout.checkoutAmount);
    let finalPrice = roundCurrencyAmount(baseAmount * 0.9);

    if (offerKind === "pro_flash") {
      const purchasedAddonIds = toSortedAddonIds(secureCheckout.purchasedAddonIds);
      const isProOnlyOffer = purchasedAddonIds.length === 1 && purchasedAddonIds[0] === CHECKOUT_ADDON_IDS.proPackage;
      if (!isProOnlyOffer) {
        return sendJson(res, 400, { message: "A oferta relampago do Pro so pode ser usada no upgrade Pro." });
      }
      finalPrice = 99.99;
    }

    if (finalPrice < 0) {
      finalPrice = 0;
    }
    if (finalPrice > baseAmount) {
      finalPrice = baseAmount;
    }

    const couponCode = generateAddonUpsellCouponCode();
    const metadata = {
      checkoutMode: "addon_upsell",
      targetSubscriptionId,
      eligibleAddonIds: toSortedAddonIds(secureCheckout.purchasedAddonIds),
      checkoutPeriod: secureCheckout.checkoutPeriod,
      offerKind: offerKind || "addon_discount",
      baseAmount: baseAmount.toFixed(2),
      expiresAt: validUntil.toISOString(),
      generatedAt: new Date(now).toISOString(),
    };

    const insert = await getPool().query(
      `
        INSERT INTO coupons (
          code,
          discount_type,
          discount_value,
          final_price,
          is_active,
          max_uses,
          current_uses,
          owner_user_id,
          applicable_plans,
          metadata,
          valid_until,
          created_at,
          updated_at
        )
        VALUES ($1, 'fixed_price', 0, $2, true, 1, 0, $3, $4::jsonb, $5::jsonb, $6, NOW(), NOW())
        RETURNING *
      `,
      [
        couponCode,
        finalPrice.toFixed(2),
        user.id,
        planTipo ? JSON.stringify([planTipo]) : null,
        JSON.stringify(metadata),
        validUntil.toISOString(),
      ],
    );

    return sendJson(res, 200, {
      code: couponCode,
      valid: true,
      ownerUserId: user.id,
      originalPrice: baseAmount,
      finalPrice,
      expiresAt: validUntil.toISOString(),
      purchasedAddonIds: secureCheckout.purchasedAddonIds,
      checkoutPeriod: secureCheckout.checkoutPeriod,
      checkoutTargetSubscriptionId: targetSubscriptionId,
      offerKind: offerKind || "addon_discount",
      coupon: mapCouponRow(insert.rows[0]),
    });
  } catch (error: any) {
    if (error?.code === "23505") {
      return sendJson(res, 409, { message: "Nao foi possivel reservar o cupom. Tente novamente." });
    }
    console.error("[vercel-http] create addon upsell coupon failed:", error);
    return sendJson(res, 500, { message: error?.message || "Falha ao gerar o cupom do upsell." });
  }
}

function mapCouponRow(row: Record<string, any> | null | undefined) {
  if (!row) return null;
  return {
    id: row.id,
    code: row.code,
    discountType: row.discount_type,
    discountValue: row.discount_value,
    finalPrice: row.final_price,
    isActive: row.is_active,
    maxUses: row.max_uses,
    currentUses: row.current_uses,
    ownerUserId: row.owner_user_id ?? null,
    applicablePlans: Array.isArray(row.applicable_plans) ? row.applicable_plans : null,
    metadata: row.metadata && typeof row.metadata === "object" && !Array.isArray(row.metadata) ? row.metadata : {},
    validFrom: row.valid_from,
    validUntil: row.valid_until,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
  };
}

async function handleAdminCoupons(req: any, res: any, couponId?: string) {
  if (!requireAdmin(req, res)) return;
  setNoStore(res);

  try {
    if (req.method === "GET" && !couponId) {
      const result = await getPool().query(`
        SELECT *
        FROM coupons
        ORDER BY created_at DESC NULLS LAST, code ASC
      `);
      return sendJson(res, 200, result.rows.map(mapCouponRow));
    }

    if (req.method === "POST" && !couponId) {
      const body = await readJsonBody(req);
      const code = String(body.code || "").trim().toUpperCase();
      const finalPrice = parseMoneyAmount(body.finalPrice ?? body.final_price);
      const maxUsesRaw = Number.parseInt(String(body.maxUses ?? body.max_uses ?? ""), 10);
      const maxUses = Number.isFinite(maxUsesRaw) && maxUsesRaw > 0 ? maxUsesRaw : null;
      const validUntilRaw = String(body.validUntil ?? body.valid_until ?? "").trim();
      const validUntil = validUntilRaw ? new Date(validUntilRaw) : null;
      const isActive = body.isActive !== false && body.is_active !== false;
      const applicablePlans = Array.isArray(body.applicablePlans ?? body.applicable_plans)
        ? (body.applicablePlans ?? body.applicable_plans).map((value: unknown) => String(value).trim()).filter(Boolean)
        : null;

      if (!code) {
        return sendJson(res, 400, { message: "Codigo do cupom e obrigatorio" });
      }
      if (!(finalPrice > 0)) {
        return sendJson(res, 400, { message: "Preco final invalido" });
      }
      if (validUntil && Number.isNaN(validUntil.getTime())) {
        return sendJson(res, 400, { message: "Data de validade invalida" });
      }

      const insert = await getPool().query(
        `
          INSERT INTO coupons (
            code,
            discount_type,
            discount_value,
            final_price,
            is_active,
            max_uses,
            applicable_plans,
            valid_until,
            created_at,
            updated_at
          )
          VALUES ($1, 'fixed_price', 0, $2, $3, $4, $5::jsonb, $6, NOW(), NOW())
          RETURNING *
        `,
        [
          code,
          finalPrice.toFixed(2),
          isActive,
          maxUses,
          applicablePlans && applicablePlans.length > 0 ? JSON.stringify(applicablePlans) : null,
          validUntil ? validUntil.toISOString() : null,
        ],
      );
      return sendJson(res, 200, mapCouponRow(insert.rows[0]));
    }

    if ((req.method === "PUT" || req.method === "PATCH") && couponId) {
      const body = await readJsonBody(req);
      const updates: string[] = [];
      const params: any[] = [];
      const pushUpdate = (sql: string, value: any) => {
        params.push(value);
        updates.push(`${sql} = $${params.length}`);
      };

      if (body.code !== undefined) {
        const code = String(body.code || "").trim().toUpperCase();
        if (!code) return sendJson(res, 400, { message: "Codigo do cupom e obrigatorio" });
        pushUpdate("code", code);
      }
      if (body.finalPrice !== undefined || body.final_price !== undefined) {
        const finalPrice = parseMoneyAmount(body.finalPrice ?? body.final_price);
        if (!(finalPrice > 0)) return sendJson(res, 400, { message: "Preco final invalido" });
        pushUpdate("final_price", finalPrice.toFixed(2));
      }
      if (body.maxUses !== undefined || body.max_uses !== undefined) {
        const maxUsesRaw = Number.parseInt(String(body.maxUses ?? body.max_uses ?? ""), 10);
        pushUpdate("max_uses", Number.isFinite(maxUsesRaw) && maxUsesRaw > 0 ? maxUsesRaw : null);
      }
      if (body.validUntil !== undefined || body.valid_until !== undefined) {
        const validUntilRaw = String(body.validUntil ?? body.valid_until ?? "").trim();
        const validUntil = validUntilRaw ? new Date(validUntilRaw) : null;
        if (validUntil && Number.isNaN(validUntil.getTime())) {
          return sendJson(res, 400, { message: "Data de validade invalida" });
        }
        pushUpdate("valid_until", validUntil ? validUntil.toISOString() : null);
      }
      if (body.isActive !== undefined || body.is_active !== undefined) {
        const rawIsActive = body.isActive ?? body.is_active;
        pushUpdate("is_active", rawIsActive === true || rawIsActive === "true" || rawIsActive === 1 || rawIsActive === "1");
      }
      if (body.applicablePlans !== undefined || body.applicable_plans !== undefined) {
        const rawPlans = body.applicablePlans ?? body.applicable_plans;
        const applicablePlans = Array.isArray(rawPlans)
          ? rawPlans.map((value: unknown) => String(value).trim()).filter(Boolean)
          : null;
        params.push(applicablePlans && applicablePlans.length > 0 ? JSON.stringify(applicablePlans) : null);
        updates.push(`applicable_plans = $${params.length}::jsonb`);
      }

      if (updates.length === 0) {
        return sendJson(res, 400, { message: "Nenhuma alteracao enviada" });
      }

      params.push(couponId);
      const update = await getPool().query(
        `
          UPDATE coupons
          SET ${updates.join(", ")}, updated_at = NOW()
          WHERE id = $${params.length}
          RETURNING *
        `,
        params,
      );

      if (!update.rows[0]) {
        return sendJson(res, 404, { message: "Cupom nao encontrado" });
      }

      return sendJson(res, 200, mapCouponRow(update.rows[0]));
    }

    if (req.method === "DELETE" && couponId) {
      const deleted = await getPool().query("DELETE FROM coupons WHERE id = $1 RETURNING id", [couponId]);
      if (!deleted.rows[0]) {
        return sendJson(res, 404, { message: "Cupom nao encontrado" });
      }
      return sendJson(res, 200, { success: true });
    }

    return sendJson(res, 405, { message: "Metodo nao permitido" });
  } catch (error: any) {
    if (error?.code === "23505") {
      return sendJson(res, 409, { message: "Ja existe um cupom com este codigo" });
    }
    console.error("[vercel-http] admin coupons failed:", error);
    return sendJson(res, 500, { message: "Erro ao gerenciar cupons", error: error?.message });
  }
}

async function handleValidatePlanCode(req: any, res: any) {
  try {
    const body = await readJsonBody(req);
    const code = String(body.code || "").trim();
    if (!code) {
      return sendJson(res, 400, { valid: false, message: "Codigo nao informado" });
    }

    const result = await getPool().query(
      `
        SELECT *
        FROM plans
        WHERE UPPER(codigo_personalizado) = UPPER($1)
          AND ativo = true
          AND is_personalizado = true
        LIMIT 1
      `,
      [code],
    );
    const plan = toCamelRecord(result.rows[0] || null);
    if (!plan) {
      return sendJson(res, 200, { valid: false, message: "Código de plano não encontrado" });
    }

    return sendJson(res, 200, { valid: true, plan });
  } catch (error) {
    console.error("[vercel-http] plan code validate failed:", error);
    return sendJson(res, 500, { valid: false, message: "Erro ao validar codigo" });
  }
}

