async function handleReferralManualAttribution(req: any, res: any) {
  const user = await requireJwtUser(req, res);
  if (!user) return;

  try {
    const body = await readJsonBody(req);
    const contactName = String(body.contactName || body.name || "").trim();
    const contactEmail = normalizeReferralEmailInput(body.contactEmail || body.email);
    const contactPhone = normalizeReferralPhoneDigits(body.contactPhone || body.phone);
    if (!contactEmail && !contactPhone) {
      return sendJson(res, 400, { message: "Informe o e-mail ou telefone do indicado." });
    }
    if (contactEmail && !isReferralEmail(contactEmail)) {
      return sendJson(res, 400, { message: "E-mail invalido." });
    }
    if (contactPhone && contactPhone.length < 10) {
      return sendJson(res, 400, { message: "Telefone invalido." });
    }

    const db = getPool();
    const selfResult = await db.query(
      `
        SELECT id
        FROM users
        WHERE id = $1
          AND (
            ($2 <> '' AND lower(COALESCE(email, '')) = lower($2))
            OR ($3 <> '' AND regexp_replace(COALESCE(phone, ''), '\\D', '', 'g') = $3)
          )
        LIMIT 1
      `,
      [user.id, contactEmail, contactPhone],
    );
    if (selfResult.rows[0]) {
      return sendJson(res, 400, { message: "Voce nao pode indicar a propria conta." });
    }

    const registeredResult = await db.query(
      `
        SELECT id
        FROM users
        WHERE id <> $1
          AND (
            ($2 <> '' AND lower(COALESCE(email, '')) = lower($2))
            OR ($3 <> '' AND regexp_replace(COALESCE(phone, ''), '\\D', '', 'g') = $3)
          )
        LIMIT 1
      `,
      [user.id, contactEmail, contactPhone],
    );
    if (registeredResult.rows[0]) {
      return sendJson(res, 409, { message: "Esse cliente ja criou conta. Use o link antes do cadastro ou reserve outro contato." });
    }

    const existingPending = await db.query(
      `
        SELECT *
        FROM referral_attributions
        WHERE referred_user_id IS NULL
          AND (
            ($1 <> '' AND lower(COALESCE(referred_email, '')) = lower($1))
            OR ($2 <> '' AND regexp_replace(COALESCE(referred_phone, ''), '\\D', '', 'g') = $2)
          )
        ORDER BY created_at DESC
        LIMIT 1
      `,
      [contactEmail, contactPhone],
    );
    if (existingPending.rows[0]) {
      if (String(existingPending.rows[0].referrer_user_id) !== String(user.id)) {
        return sendJson(res, 409, { message: "Esse contato ja esta reservado em outra indicacao." });
      }
      return sendJson(res, 200, { success: true, attribution: toCamelRecord(existingPending.rows[0]) });
    }

    const profile = await ensureVercelReferralProfile(user.id);
    const sourceChannel = contactEmail && contactPhone ? "manual_contact" : contactEmail ? "manual_email" : "manual_phone";
    const inserted = await db.query(
      `INSERT INTO referral_attributions (
         referral_code, referrer_user_id, referred_email, referred_phone,
         source_channel, source_label, source_url, metadata_json, status
       )
       VALUES ($1, $2, NULLIF($3, ''), NULLIF($4, ''), $5, NULLIF($6, ''), $7, $8::jsonb, 'pending')
       RETURNING *`,
      [
        profile.referral_code,
        user.id,
        contactEmail,
        contactPhone,
        sourceChannel,
        contactName || contactEmail || contactPhone,
        buildReferralShareUrl(profile.referral_code),
        JSON.stringify({ reservedBy: "dashboard_popup", reservedAt: new Date().toISOString() }),
      ],
    );
    await db.query(
      "UPDATE referral_profiles SET total_referrals = total_referrals + 1, updated_at = NOW() WHERE id = $1",
      [profile.id],
    );
    return sendJson(res, 200, { success: true, attribution: toCamelRecord(inserted.rows[0]) });
  } catch (error) {
    console.error("[vercel-http] referral manual attribution failed:", error);
    return sendJson(res, 500, { message: "Falha ao reservar indicacao" });
  }
}

