const AUDIO_RESPONSE_MODES = new Set([
  "first_message_text_audio_then_mirror",
  "audio_on_customer_audio",
  "audio_only",
  "audio_text",
]);

const AUDIO_DAILY_LIMIT = 30;
const AUDIO_VOICE_TYPES = new Set(["female", "male"]);
const EDGE_TTS_VOICE_MAP: Record<string, string> = {
  female: "pt-BR-FranciscaNeural",
  male: "pt-BR-AntonioNeural",
};

function normalizeAudioResponseMode(responseMode: unknown) {
  const value = String(responseMode || "").trim();
  if (value === "audio_first_message_then_customer_audio") {
    return "first_message_text_audio_then_mirror";
  }
  return AUDIO_RESPONSE_MODES.has(value) ? value : "audio_text";
}

function normalizeAudioVoiceType(voiceType: unknown) {
  const value = String(voiceType || "").trim().toLowerCase();
  if (value === "santa" || value === "alex") return "male";
  if (value === "dora") return "female";
  return AUDIO_VOICE_TYPES.has(value) ? value : "female";
}

function normalizeAudioSpeed(speed: unknown, fallback = 1) {
  const parsed = Number(speed);
  return Number.isFinite(parsed) ? parsed : fallback;
}

async function getOrCreateAudioConfig(userId: string) {
  const db = getPool();
  const existing = await db.query(
    `
      SELECT id, user_id, is_enabled, voice_type, response_mode, speed, created_at, updated_at
      FROM audio_config
      WHERE user_id = $1
      LIMIT 1
    `,
    [userId],
  );
  if (existing.rows[0]) return existing.rows[0];

  const created = await db.query(
    `
      INSERT INTO audio_config (user_id, is_enabled, voice_type, response_mode, speed, created_at, updated_at)
      VALUES ($1, false, 'female', 'first_message_text_audio_then_mirror', 1.00, NOW(), NOW())
      RETURNING id, user_id, is_enabled, voice_type, response_mode, speed, created_at, updated_at
    `,
    [userId],
  );
  return created.rows[0];
}

function fallbackAudioUsage(config?: any) {
  const enabled = config?.is_enabled === true;
  return {
    canSend: enabled,
    remaining: enabled ? AUDIO_DAILY_LIMIT : 0,
    limit: AUDIO_DAILY_LIMIT,
    used: 0,
    isUnlimited: false,
  };
}

async function getAudioUsage(userId: string, config?: any) {
  const audioConfig = config || (await getOrCreateAudioConfig(userId));

  if (audioConfig && audioConfig.is_enabled !== true) {
    return {
      canSend: false,
      remaining: 0,
      limit: AUDIO_DAILY_LIMIT,
      used: 0,
      isUnlimited: false,
    };
  }

  const result = await getPool().query(
    `
      SELECT count, daily_limit
      FROM audio_message_counter
      WHERE user_id = $1
        AND date = CURRENT_DATE
      LIMIT 1
    `,
    [userId],
  );
  const counter = result.rows[0];
  const used = toNumberValue(counter?.count, 0);
  const savedLimit = toNumberValue(counter?.daily_limit, AUDIO_DAILY_LIMIT);
  const limit = savedLimit > 0 ? Math.min(savedLimit, AUDIO_DAILY_LIMIT) : AUDIO_DAILY_LIMIT;

  return {
    canSend: used < limit,
    remaining: Math.max(0, limit - used),
    limit,
    used,
    isUnlimited: false,
  };
}

async function incrementAudioUsageCounter(userId: string) {
  const db = getPool();
  const existing = await db.query(
    `
      SELECT id, count
      FROM audio_message_counter
      WHERE user_id = $1
        AND date = CURRENT_DATE
      ORDER BY created_at DESC
      LIMIT 1
    `,
    [userId],
  );
  const counter = existing.rows[0];
  if (!counter) {
    const created = await db.query(
      `
        INSERT INTO audio_message_counter (user_id, date, count, daily_limit, created_at, updated_at)
        VALUES ($1, CURRENT_DATE, 1, $2, NOW(), NOW())
        RETURNING count, daily_limit
      `,
      [userId, AUDIO_DAILY_LIMIT],
    );
    return { canSend: true, used: toNumberValue(created.rows[0]?.count, 1), limit: AUDIO_DAILY_LIMIT, remaining: AUDIO_DAILY_LIMIT - 1 };
  }

  const used = toNumberValue(counter.count, 0);
  if (used >= AUDIO_DAILY_LIMIT) {
    return { canSend: false, used, limit: AUDIO_DAILY_LIMIT, remaining: 0 };
  }

  const updated = await db.query(
    `
      UPDATE audio_message_counter
      SET count = count + 1,
          daily_limit = $2,
          updated_at = NOW()
      WHERE id = $1
      RETURNING count, daily_limit
    `,
    [counter.id, AUDIO_DAILY_LIMIT],
  );
  const nextUsed = toNumberValue(updated.rows[0]?.count, used + 1);
  return {
    canSend: true,
    used: nextUsed,
    limit: AUDIO_DAILY_LIMIT,
    remaining: Math.max(0, AUDIO_DAILY_LIMIT - nextUsed),
  };
}

function mapAudioConfig(config: any) {
  return {
    isEnabled: config?.is_enabled === true,
    voiceType: normalizeAudioVoiceType(config?.voice_type),
    responseMode: normalizeAudioResponseMode(config?.response_mode),
    speed: normalizeAudioSpeed(config?.speed, 1),
  };
}

type GeneratedAudio = {
  buffer: Buffer;
  mimeType: string;
  provider: string;
  fileExtension: string;
};

function normalizeTextForEdgeTts(text: string) {
  let output = String(text || "").replace(/\s+/g, " ").trim();
  const replacements: Array<[RegExp, string]> = [
    [/\bvc\b/gi, "voce"],
    [/\bvcs\b/gi, "voces"],
    [/\btb\b/gi, "tambem"],
    [/\bpq\b/gi, "porque"],
    [/\bq\b/gi, "que"],
    [/\bmsg\b/gi, "mensagem"],
    [/\bwhats\b/gi, "WhatsApp"],
    [/\bzap\b/gi, "WhatsApp"],
    [/\binsta\b/gi, "Instagram"],
    [/\bapp\b/gi, "aplicativo"],
    [/\bapi\b/gi, "A P I"],
    [/\bcpf\b/gi, "C P F"],
    [/\bcnpj\b/gi, "C N P J"],
    [/\bpix\b/gi, "Pix"],
  ];
  for (const [pattern, replacement] of replacements) {
    output = output.replace(pattern, replacement);
  }
  return output
    .replace(/R\$\s*([0-9]+(?:[,.][0-9]+)?)/gi, "$1 reais")
    .replace(/%/g, " por cento ")
    .replace(/&/g, " e ")
    .replace(/https?:\/\/\S+/gi, " link ")
    .replace(/www\.\S+/gi, " link ")
    .replace(/([.!?])\s*/g, "$1\n")
    .replace(/([,;:])\s*/g, "$1 ")
    .replace(/\n{2,}/g, "\n")
    .trim();
}

function phonemizePortugueseBrazil(text: string) {
  const input = normalizeTextForEdgeTts(text)
    .toLowerCase()
    .normalize("NFC");
  if (!input) return "";

  const withMarkers = input
    .replace(/ã/g, "a~")
    .replace(/õ/g, "o~")
    .replace(/[áàâ]/g, "a")
    .replace(/[éè]/g, "e")
    .replace(/ê/g, "e")
    .replace(/[íì]/g, "i")
    .replace(/[óò]/g, "o")
    .replace(/ô/g, "o")
    .replace(/[úù]/g, "u")
    .replace(/ç/g, "s");

  const words = withMarkers.match(/[a-zeo~]+|[0-9]+|[.,!?;:]/g) || [];
  const phonemeWords = words.map((word) => {
    if (/^[.,!?;:]$/.test(word)) return word;
    if (/^[0-9]+$/.test(word)) return word.split("").join(" ");

    let output = word
      .replace(/a~o\b/g, "aÌƒw")
      .replace(/o~es\b/g, "oÌƒjs")
      .replace(/a~es\b/g, "aÌƒjs")
      .replace(/ch/g, "Êƒ")
      .replace(/nh/g, "É²")
      .replace(/lh/g, "li")
      .replace(/qu([eie])/g, "k$1")
      .replace(/gu([eie])/g, "É¡$1")
      .replace(/c([eie])/g, "s$1")
      .replace(/c/g, "k")
      .replace(/g([eie])/g, "Ê’$1")
      .replace(/g/g, "É¡")
      .replace(/j/g, "Ê’")
      .replace(/x/g, "Êƒ")
      .replace(/ss/g, "s")
      .replace(/([aeeioou])s([aeeioou])/g, "$1z$2")
      .replace(/^r/g, "h")
      .replace(/rr/g, "h")
      .replace(/([aeeioou])r([aeeioou])/g, "$1É¾$2")
      .replace(/t([i])\b/g, "Ê§$1")
      .replace(/t([i])/g, "Ê§$1")
      .replace(/d([i])\b/g, "Ê¤$1")
      .replace(/d([i])/g, "Ê¤$1")
      .replace(/l\b/g, "w")
      .replace(/a~/g, "aÌƒ")
      .replace(/o~/g, "oÌƒ")
      .replace(/m\b/g, "Ìƒ")
      .replace(/n\b/g, "Ìƒ");

    output = output
      .replace(/e\b/g, "i")
      .replace(/o\b/g, "u")
      .replace(/([aeeioou])([Ìƒ])/g, "$1$2")
      .replace(/\s+/g, "");

    return output;
  });

  const phonemes = phonemeWords.join(" ").replace(/\s+([.,!?;:])/g, "$1").trim();
  if (!phonemes) {
    throw new Error("Gerador de voz nao conseguiu preparar portugues do Brasil.");
  }
  return phonemes;
}

function getMemoryUsageMb() {
  const memory = process.memoryUsage();
  return {
    rssMb: Math.round(memory.rss / 1024 / 1024),
    heapUsedMb: Math.round(memory.heapUsed / 1024 / 1024),
  };
}

function encodeWavPcm16(samples: Float32Array, sampleRate = 24000) {
  const dataSize = samples.length * 2;
  const buffer = Buffer.alloc(44 + dataSize);
  buffer.write("RIFF", 0);
  buffer.writeUInt32LE(36 + dataSize, 4);
  buffer.write("WAVE", 8);
  buffer.write("fmt ", 12);
  buffer.writeUInt32LE(16, 16);
  buffer.writeUInt16LE(1, 20);
  buffer.writeUInt16LE(1, 22);
  buffer.writeUInt32LE(sampleRate, 24);
  buffer.writeUInt32LE(sampleRate * 2, 28);
  buffer.writeUInt16LE(2, 32);
  buffer.writeUInt16LE(16, 34);
  buffer.write("data", 36);
  buffer.writeUInt32LE(dataSize, 40);
  for (let index = 0; index < samples.length; index += 1) {
    const sample = Math.max(-1, Math.min(1, samples[index] || 0));
    buffer.writeInt16LE(sample < 0 ? sample * 0x8000 : sample * 0x7fff, 44 + index * 2);
  }
  return buffer;
}

function edgeTtsRateFromSpeed(speed: number) {
  const ratePercent = Math.round((speed - 1) * 100);
  return ratePercent >= 0 ? `+${ratePercent}%` : `${ratePercent}%`;
}

async function generateWithGoogleTtsFallback(text: string): Promise<Buffer> {
  const googleTTS: any = await import("google-tts-api");
  if (text.length <= 200) {
    const base64 = await googleTTS.getAudioBase64(text, {
      lang: "pt",
      slow: false,
      host: "https://translate.google.com",
      timeout: 10000,
    });
    return Buffer.from(base64, "base64");
  }

  const parts = await googleTTS.getAllAudioBase64(text, {
    lang: "pt",
    slow: false,
    host: "https://translate.google.com",
    timeout: 10000,
    splitPunct: ".,!?;:",
  });
  return Buffer.concat(parts.map((part: any) => Buffer.from(part.base64, "base64")));
}

async function generateEdgeTtsAudio(text: string, voiceType: string, speed: number): Promise<GeneratedAudio> {
  const startedAt = Date.now();
  const memoryBefore = getMemoryUsageMb();
  const normalizedVoice = normalizeAudioVoiceType(voiceType);
  const voice = EDGE_TTS_VOICE_MAP[normalizedVoice] || EDGE_TTS_VOICE_MAP.female;
  const normalizedText = normalizeTextForEdgeTts(text);
  const rate = edgeTtsRateFromSpeed(Math.max(0.5, Math.min(2, speed || 1)));

  try {
    const [{ promises: fs }, path, os, edgeModule] = await Promise.all([
      import("node:fs"),
      import("node:path"),
      import("node:os"),
      import("edge-tts-node") as Promise<any>,
    ]);
    const tmpDir = path.join(os.tmpdir(), "agentezap-edge-tts");
    await fs.mkdir(tmpDir, { recursive: true });
    const outputFile = path.join(tmpDir, `edge-${Date.now()}-${randomBytes(4).toString("hex")}.mp3`);
    const tts = new edgeModule.MsEdgeTTS({});

    try {
      await tts.setMetadata(
        voice,
        edgeModule.OUTPUT_FORMAT.AUDIO_24KHZ_48KBITRATE_MONO_MP3,
        "pt-BR",
      );
      await tts.toFile(outputFile, normalizedText, { rate, pitch: "+0Hz" });
      const buffer = await fs.readFile(outputFile);
      if (!buffer || buffer.length < 1000) {
        throw new Error(`Audio muito pequeno: ${buffer?.length || 0} bytes`);
      }
      console.info("[vercel-http] edge audio generation metrics", {
        language: "pt-BR",
        voiceType: normalizedVoice,
        textChars: String(text || "").length,
        rate,
        totalMs: Date.now() - startedAt,
        audioBytes: buffer.length,
        memoryBefore,
        memoryAfter: getMemoryUsageMb(),
      });
      return {
        buffer,
        mimeType: "audio/mpeg",
        provider: "edge_tts",
        fileExtension: ".mp3",
      };
    } finally {
      tts.close?.();
      await fs.unlink(outputFile).catch(() => undefined);
    }
  } catch (error) {
    console.warn("[vercel-http] Edge TTS failed, trying Google TTS fallback:", error);
    const buffer = await generateWithGoogleTtsFallback(normalizedText);
    if (!buffer || buffer.length < 1000) {
      throw new Error("Nao foi possivel gerar audio em portugues do Brasil.");
    }
    console.info("[vercel-http] fallback audio generation metrics", {
      language: "pt-BR",
      voiceType: normalizedVoice,
      textChars: String(text || "").length,
      totalMs: Date.now() - startedAt,
      audioBytes: buffer.length,
      memoryBefore,
      memoryAfter: getMemoryUsageMb(),
    });
    return {
      buffer,
      mimeType: "audio/mpeg",
      provider: "google_tts_fallback",
      fileExtension: ".mp3",
    };
  }
}

async function generateAudioPreview(text: string, voiceType: string, speed: number): Promise<GeneratedAudio> {
  return generateEdgeTtsAudio(text, voiceType, speed);
}

async function uploadGeneratedFlow2Audio(userId: string, audio: GeneratedAudio, fileName: string) {
  const bucket = "agent-media";
  const safeFileName = sanitizeStorageFileName(fileName, audio.mimeType);
  const storagePath = [
    "flow2-ai-audio",
    userId,
    `${Date.now()}_${randomBytes(4).toString("hex")}_${safeFileName}`,
  ].join("/");
  const supabase = await ensurePublicStorageBucket(bucket);
  const upload = await supabase.storage.from(bucket).upload(storagePath, audio.buffer, {
    contentType: audio.mimeType,
    upsert: false,
  });
  if (upload.error) throw upload.error;
  return {
    storageUrl: buildPublicStorageUrl(bucket, storagePath),
    fileName: safeFileName,
    fileSize: audio.buffer.length,
    mimeType: audio.mimeType,
    mediaType: "audio",
    provider: audio.provider,
  };
}

async function handleAudioConfig(req: any, res: any) {
  const user = await requireJwtUser(req, res);
  if (!user) return;

  try {
    if (req.method === "PUT") {
      const body = await readJsonBody(req);
      const updates: string[] = [];
      const values: unknown[] = [];
      const pushUpdate = (column: string, value: unknown, cast = "") => {
        values.push(value);
        updates.push(`${column} = $${values.length}${cast}`);
      };

      if (body.speed !== undefined) {
        const speed = normalizeAudioSpeed(body.speed, Number.NaN);
        if (!Number.isFinite(speed) || speed < 0.5 || speed > 2.0) {
          return sendJson(res, 400, { message: "Velocidade deve ser entre 0.5 e 2.0" });
        }
        pushUpdate("speed", speed, "::numeric");
      }

      if (body.voiceType !== undefined) {
        const voiceType = normalizeAudioVoiceType(body.voiceType);
        if (!AUDIO_VOICE_TYPES.has(voiceType)) {
          return sendJson(res, 400, { message: "Tipo de voz invalido." });
        }
        pushUpdate("voice_type", voiceType);
      }

      if (body.responseMode !== undefined) {
        const responseMode = normalizeAudioResponseMode(body.responseMode);
        if (!AUDIO_RESPONSE_MODES.has(responseMode)) {
          return sendJson(res, 400, { message: "Modo de resposta invalido" });
        }
        pushUpdate("response_mode", responseMode);
      }

      if (body.isEnabled !== undefined) {
        pushUpdate("is_enabled", body.isEnabled === true);
      }

      let config = await getOrCreateAudioConfig(user.id);
      if (updates.length > 0) {
        values.push(user.id);
        const updated = await getPool().query(
          `
            UPDATE audio_config
            SET ${updates.join(", ")}, updated_at = NOW()
            WHERE user_id = $${values.length}
            RETURNING id, user_id, is_enabled, voice_type, response_mode, speed, created_at, updated_at
          `,
          values,
        );
        config = updated.rows[0] || config;
      }

      return sendJson(res, 200, { success: true, config: mapAudioConfig(config) });
    }

    const config = await getOrCreateAudioConfig(user.id);
    const usage = await getAudioUsage(user.id, config).catch((error) => {
      console.warn("[vercel-http] audio usage unavailable while loading config:", error?.message || error);
      return fallbackAudioUsage(config);
    });
    return sendJson(res, 200, { config: mapAudioConfig(config), usage });
  } catch (error: any) {
    console.error("[vercel-http] audio config failed:", error);
    return sendJson(res, 500, { message: error?.message || "Erro ao buscar configuracao de audio" });
  }
}

async function handleAudioUsage(req: any, res: any) {
  const user = await requireJwtUser(req, res);
  if (!user) return;

  try {
    const config = await getOrCreateAudioConfig(user.id);
    const usage = await getAudioUsage(user.id, config).catch((error) => {
      console.warn("[vercel-http] audio usage unavailable:", error?.message || error);
      return fallbackAudioUsage(config);
    });
    return sendJson(res, 200, usage);
  } catch (error: any) {
    console.error("[vercel-http] audio usage failed:", error);
    return sendJson(res, 500, { message: error?.message || "Erro ao buscar uso de audio" });
  }
}

async function handleAudioPreview(req: any, res: any, useSavedConfig: boolean) {
  const user = await requireJwtUser(req, res);
  if (!user) return;

  try {
    const body = await readJsonBody(req);
    const config = useSavedConfig ? await getOrCreateAudioConfig(user.id) : null;
    const text = String(
      body.text ||
        (useSavedConfig
          ? "Ola! Este e um teste da configuracao de voz para o seu agente de atendimento."
          : "Este e um exemplo de como a voz do seu assistente vai soar com esta configuracao."),
    ).slice(0, 600);
    const speed =
      body.speed !== undefined
        ? normalizeAudioSpeed(body.speed, Number.NaN)
        : normalizeAudioSpeed(config?.speed, 1);
    if (!Number.isFinite(speed) || speed < 0.5 || speed > 2.0) {
      return sendJson(res, 400, { message: "Velocidade deve ser entre 0.5 e 2.0" });
    }

    const voiceType = normalizeAudioVoiceType(body.voiceType ?? config?.voice_type);
    const audio = await generateAudioPreview(text, voiceType, speed);
    const filename = `${useSavedConfig ? "test_audio" : "preview_audio"}${audio.fileExtension}`;
    return sendBinary(res, 200, audio.buffer, audio.mimeType, filename);
  } catch (error: any) {
    console.error("[vercel-http] audio preview failed:", error);
    return sendJson(res, 500, { message: "Erro ao gerar preview", error: error?.message || String(error) });
  }
}

async function handleFlow2GenerateAudio(req: any, res: any) {
  const user = await requireJwtUser(req, res);
  if (!user) return;

  try {
    const body = await readJsonBody(req);
    const text = String(body.text || "").trim().slice(0, 900);
    if (!text) return sendJson(res, 400, { message: "Texto obrigatorio para gerar audio." });

    const usage = await getAudioUsage(user.id, { is_enabled: true }).catch(() => ({
      canSend: true,
      remaining: AUDIO_DAILY_LIMIT,
      limit: AUDIO_DAILY_LIMIT,
      used: 0,
      isUnlimited: false,
    }));
    if (!usage.canSend) {
      return sendJson(res, 429, { message: "Limite diario de 30 audios atingido.", usage });
    }

    const config = await getOrCreateAudioConfig(user.id).catch(() => null);
    const voiceType = normalizeAudioVoiceType(body.voiceType ?? config?.voice_type);
    const speed = normalizeAudioSpeed(body.speed ?? config?.speed, 1);
    if (!Number.isFinite(speed) || speed < 0.5 || speed > 2.0) {
      return sendJson(res, 400, { message: "Velocidade deve ser entre 0.5 e 2.0" });
    }

    const audio = await generateAudioPreview(text, voiceType, speed);
    const baseName = `flow2-audio-${voiceType}${audio.fileExtension}`;
    const uploaded = await uploadGeneratedFlow2Audio(user.id, audio, baseName);
    const counter = await incrementAudioUsageCounter(user.id);
    return sendJson(res, 200, {
      success: true,
      ...uploaded,
      voiceType,
      speed,
      usage: {
        used: counter.used,
        remaining: counter.remaining,
        limit: counter.limit,
        canSend: counter.canSend,
        isUnlimited: false,
      },
    });
  } catch (error: any) {
    console.error("[vercel-http] flow2 audio generation failed:", error);
    return sendJson(res, 500, { message: error?.message || "Erro ao gerar audio do Flow2." });
  }
}

async function handleFollowupConfig(req: any, res: any) {
  const user = await requireJwtUser(req, res);
  if (!user) return;

  try {
    if (req.method === "PUT") {
      const body = await readJsonBody(req);
      const existing = await getPool().query("SELECT id FROM followup_configs WHERE user_id = $1 LIMIT 1", [user.id]);
      const has = (key: string) => Object.prototype.hasOwnProperty.call(body, key);

      if (existing.rows[0]) {
        const updates: string[] = [];
        const values: unknown[] = [];
        const pushUpdate = (column: string, value: unknown, cast = "") => {
          values.push(value);
          updates.push(`${column} = $${values.length}${cast}`);
        };

        if (has("isEnabled")) pushUpdate("is_enabled", body.isEnabled === true);
        if (has("maxAttempts")) pushUpdate("max_attempts", toNumberValue(body.maxAttempts, 8));
        if (has("intervalsMinutes")) pushUpdate("intervals_minutes", JSON.stringify(Array.isArray(body.intervalsMinutes) ? body.intervalsMinutes : []), "::jsonb");
        if (has("businessHoursStart")) pushUpdate("business_hours_start", toStringValue(body.businessHoursStart, "09:00"));
        if (has("businessHoursEnd")) pushUpdate("business_hours_end", toStringValue(body.businessHoursEnd, "18:00"));
        if (has("businessDays")) pushUpdate("business_days", JSON.stringify(Array.isArray(body.businessDays) ? body.businessDays : [1, 2, 3, 4, 5]), "::jsonb");
        if (has("respectBusinessHours")) pushUpdate("respect_business_hours", body.respectBusinessHours !== false);
        if (has("tone")) pushUpdate("tone", toStringValue(body.tone, "consultivo"));
        if (has("formalityLevel")) pushUpdate("formality_level", toNumberValue(body.formalityLevel, 5));
        if (has("useEmojis")) pushUpdate("use_emojis", body.useEmojis !== false);
        if (has("importantInfo")) pushUpdate("important_info", JSON.stringify(Array.isArray(body.importantInfo) ? body.importantInfo : []), "::jsonb");
        if (has("infiniteLoop")) pushUpdate("infinite_loop", body.infiniteLoop !== false);
        if (has("infiniteLoopMinDays")) pushUpdate("infinite_loop_min_days", toNumberValue(body.infiniteLoopMinDays, 15));
        if (has("infiniteLoopMaxDays")) pushUpdate("infinite_loop_max_days", toNumberValue(body.infiniteLoopMaxDays, 30));
        if (has("followupAudioMode")) {
          const mode = toStringValue(body.followupAudioMode, "text_only");
          if (!["text_only", "audio_only", "alternate_text_audio", "random_text_audio"].includes(mode)) {
            return sendJson(res, 400, { message: "Modo de audio do follow-up invalido" });
          }
          pushUpdate("followup_audio_mode", mode);
        }

        if (updates.length > 0) {
          values.push(user.id);
          await getPool().query(
            `UPDATE followup_configs SET ${updates.join(", ")}, updated_at = NOW() WHERE user_id = $${values.length}`,
            values,
          );
        }
      } else {
        const payload = {
          isEnabled: body.isEnabled === true,
          maxAttempts: toNumberValue(body.maxAttempts, 8),
          intervalsMinutes: Array.isArray(body.intervalsMinutes) ? body.intervalsMinutes : [10, 30, 180, 1440, 2880, 4320, 10080, 21600],
          businessHoursStart: toStringValue(body.businessHoursStart, "09:00"),
          businessHoursEnd: toStringValue(body.businessHoursEnd, "18:00"),
          businessDays: Array.isArray(body.businessDays) ? body.businessDays : [1, 2, 3, 4, 5],
          respectBusinessHours: body.respectBusinessHours !== false,
          tone: toStringValue(body.tone, "consultivo"),
          formalityLevel: toNumberValue(body.formalityLevel, 5),
          useEmojis: body.useEmojis !== false,
          importantInfo: Array.isArray(body.importantInfo) ? body.importantInfo : [],
          infiniteLoop: body.infiniteLoop !== false,
          infiniteLoopMinDays: toNumberValue(body.infiniteLoopMinDays, 15),
          infiniteLoopMaxDays: toNumberValue(body.infiniteLoopMaxDays, 30),
          followupAudioMode: toStringValue(body.followupAudioMode, "text_only"),
        };
        if (!["text_only", "audio_only", "alternate_text_audio", "random_text_audio"].includes(payload.followupAudioMode)) {
          return sendJson(res, 400, { message: "Modo de audio do follow-up invalido" });
        }
        await getPool().query(
          `
            INSERT INTO followup_configs (
              user_id, is_enabled, max_attempts, intervals_minutes, business_hours_start,
              business_hours_end, business_days, respect_business_hours, tone, formality_level,
              use_emojis, important_info, infinite_loop, infinite_loop_min_days,
              infinite_loop_max_days, followup_audio_mode, updated_at
            )
            VALUES ($1,$2,$3,$4::jsonb,$5,$6,$7::jsonb,$8,$9,$10,$11,$12::jsonb,$13,$14,$15,$16,NOW())
          `,
          [
            user.id,
            payload.isEnabled,
            payload.maxAttempts,
            JSON.stringify(payload.intervalsMinutes),
            payload.businessHoursStart,
            payload.businessHoursEnd,
            JSON.stringify(payload.businessDays),
            payload.respectBusinessHours,
            payload.tone,
            payload.formalityLevel,
            payload.useEmojis,
            JSON.stringify(payload.importantInfo),
            payload.infiniteLoop,
            payload.infiniteLoopMinDays,
            payload.infiniteLoopMaxDays,
            payload.followupAudioMode,
          ],
        );
      }
    }

    const result = await getPool().query("SELECT * FROM followup_configs WHERE user_id = $1 LIMIT 1", [user.id]);
    const row = result.rows[0];
    return sendJson(
      res,
      200,
      row
        ? {
            id: row.id,
            userId: row.user_id,
            isEnabled: row.is_enabled === true,
            maxAttempts: toNumberValue(row.max_attempts, 8),
            intervalsMinutes: Array.isArray(row.intervals_minutes) ? row.intervals_minutes : [],
            businessHoursStart: row.business_hours_start || "09:00",
            businessHoursEnd: row.business_hours_end || "18:00",
            businessDays: Array.isArray(row.business_days) ? row.business_days : [1, 2, 3, 4, 5],
            respectBusinessHours: row.respect_business_hours !== false,
            tone: row.tone || "consultivo",
            formalityLevel: toNumberValue(row.formality_level, 5),
            useEmojis: row.use_emojis !== false,
            importantInfo: Array.isArray(row.important_info) ? row.important_info : [],
            infiniteLoop: row.infinite_loop !== false,
            infiniteLoopMinDays: toNumberValue(row.infinite_loop_min_days, 15),
            infiniteLoopMaxDays: toNumberValue(row.infinite_loop_max_days, 30),
            followupAudioMode: row.followup_audio_mode || "text_only",
          }
        : {
            id: "",
            userId: user.id,
            isEnabled: false,
            maxAttempts: 8,
            intervalsMinutes: [10, 30, 180, 1440, 2880, 4320, 10080, 21600],
            businessHoursStart: "09:00",
            businessHoursEnd: "18:00",
            businessDays: [1, 2, 3, 4, 5],
            respectBusinessHours: true,
            tone: "consultivo",
            formalityLevel: 5,
            useEmojis: true,
            importantInfo: [],
            infiniteLoop: true,
            infiniteLoopMinDays: 15,
            infiniteLoopMaxDays: 30,
            followupAudioMode: "text_only",
          },
    );
  } catch (error) {
    console.error("[vercel-http] followup config failed:", error);
    return sendJson(res, 500, { message: "Failed to fetch followup config" });
  }
}

async function handleFollowupReorganize(req: any, res: any) {
  const user = await requireJwtUser(req, res);
  if (!user) return;

  try {
    const configResult = await getPool().query(
      `
        SELECT *
        FROM followup_configs
        WHERE user_id = $1
          AND is_enabled = true
        LIMIT 1
      `,
      [user.id],
    );
    const config = configResult.rows[0];
    if (!config) {
      return sendJson(res, 200, {
        success: true,
        disabled: true,
        reorganized: 0,
        skipped: 0,
        message: "Follow-up global desativado. Nenhuma conversa foi reorganizada.",
      });
    }

    const limit = Math.max(1, Math.min(Number.parseInt(String(req.query?.limit || "2000"), 10) || 2000, 5000));
    const conversationsResult = await getPool().query(
      `
        SELECT
          c.id,
          c.connection_id AS "connectionId",
          c.contact_number AS "contactNumber",
          c.owner_phone_number AS "conversationOwnerPhoneNumber",
          c.owner_phone_verified_at AS "conversationOwnerPhoneVerifiedAt",
          c.owner_phone_source AS "conversationOwnerPhoneSource",
          c.contact_name AS "contactName",
          c.remote_jid AS "remoteJid",
          c.jid_suffix AS "jidSuffix",
          c.followup_stage AS "followupStage",
          c.next_followup_at AS "nextFollowupAt",
          c.followup_disabled_reason AS "followupDisabledReason",
          c.last_message_time AS "lastMessageTime",
          c.last_message_from_me AS "lastMessageFromMe",
          wc.user_id AS "userId",
          wc.connection_name AS "connectionName",
          wc.phone_number AS "connectionPhoneNumber",
          wc.session_data #>> '{runtimeDiagnostics,lastForceReset,at}' AS "connectionLastForceResetAt",
          wc.session_data #>> '{runtimeDiagnostics,lastLogout,at}' AS "connectionLastLogoutAt",
          wc.is_connected AS "connectionIsConnected",
          wc.provider,
          wc.connection_method AS "connectionMethod",
          wc.provider_status AS "providerStatus",
          $2::int AS "maxAttempts",
          $3::jsonb AS "intervalsMinutes",
          $4::text AS "businessHoursStart",
          $5::text AS "businessHoursEnd",
          $6::jsonb AS "businessDays",
          $7::boolean AS "respectBusinessHours",
          $8::boolean AS "infiniteLoop",
          $9::int AS "infiniteLoopMinDays",
          $10::int AS "infiniteLoopMaxDays"
        FROM conversations c
        INNER JOIN whatsapp_connections wc ON wc.id = c.connection_id
        WHERE wc.user_id = $1
          AND c.followup_active = true
        ORDER BY COALESCE(c.next_followup_at, c.last_message_time, c.updated_at, c.created_at) ASC
        LIMIT $11
      `,
      [
        user.id,
        Math.max(1, Number(config.max_attempts || 8)),
        JSON.stringify(parseFollowupJsonArray(config.intervals_minutes).length ? parseFollowupJsonArray(config.intervals_minutes) : [10, 30, 180, 1440, 2880, 4320, 10080, 21600]),
        String(config.business_hours_start || "09:00"),
        String(config.business_hours_end || "18:00"),
        JSON.stringify(parseFollowupJsonArray(config.business_days).length ? parseFollowupJsonArray(config.business_days) : [1, 2, 3, 4, 5]),
        config.respect_business_hours !== false,
        config.infinite_loop !== false,
        Math.max(1, Number(config.infinite_loop_min_days || 15)),
        Math.max(1, Number(config.infinite_loop_max_days || 30)),
        limit,
      ],
    );

    const summary = {
      success: true,
      scanned: conversationsResult.rows.length,
      reorganized: 0,
      skipped: 0,
      waitingConnection: 0,
      pausedClientLast: 0,
      excluded: 0,
      ignoredGroups: 0,
      completed: 0,
      recoveredOwnerPhone: 0,
      failed: 0,
      errors: [] as Array<{ conversationId: string; message: string }>,
      message: "Reorganizacao concluida",
    };

    let offsetMinutes = 1;
    const now = new Date();

    for (const conversation of conversationsResult.rows) {
      try {
          // Manual reorganization does not send messages. Send-time locking stays in the cron.
          if (isGroupConversationRow(conversation)) {
            await getPool().query(
              `
                UPDATE conversations
                SET next_followup_at = NULL,
                    followup_disabled_reason = 'Follow-up automatico nao esta disponivel para grupos.',
                    updated_at = NOW()
                WHERE id = $1
              `,
              [conversation.id],
            );
            summary.skipped += 1;
            summary.ignoredGroups += 1;
            continue;
          }

          const canonicalSibling = await findWebOnlyCanonicalPhoneSibling(conversation);
          if (canonicalSibling) {
            await disableDuplicateLidFollowup(conversation, canonicalSibling);
            summary.skipped += 1;
            continue;
          }

          if (await isNumberExcludedForUser(user.id, conversation.contactNumber, true)) {
            await getPool().query(
              `
                UPDATE conversations
                SET next_followup_at = NULL,
                    followup_disabled_reason = $2,
                    updated_at = NOW()
                WHERE id = $1
              `,
              [conversation.id, WEB_ONLY_FOLLOWUP_EXCLUDED_REASON],
            );
            summary.skipped += 1;
            summary.excluded += 1;
            continue;
          }

          if (!normalizeFollowupPhone(conversation.conversationOwnerPhoneNumber)) {
            const ownerRecovered = await tryBackfillFollowupOwnerPhoneFromCurrentSession(conversation);
            if (ownerRecovered) {
              summary.recoveredOwnerPhone += 1;
            }
          }

          const connectionState = await resolveFollowupConversationConnectionState(conversation);
          if (!connectionState.available) {
            await deferWebOnlyFollowupUntilConnection(
              conversation,
              connectionState.reason || WEB_ONLY_FOLLOWUP_WAITING_CONNECTION_REASON,
            );
            summary.skipped += 1;
            summary.waitingConnection += 1;
            continue;
          }

          const latestMessage = await loadWebOnlyLatestRealFollowupMessage(conversation.id);
          if (!latestMessage || latestMessage.fromMe !== true) {
            await getPool().query(
              `
                UPDATE conversations
                SET next_followup_at = NULL,
                    followup_disabled_reason = $2,
                    updated_at = NOW()
                WHERE id = $1
              `,
              [conversation.id, WEB_ONLY_FOLLOWUP_CLIENT_LAST_REASON],
            );
            summary.skipped += 1;
            summary.pausedClientLast += 1;
            continue;
          }

          if (isWebOnlyUnconfirmedOutgoingStatus(latestMessage.status)) {
            await getPool().query(
              `
                UPDATE conversations
                SET next_followup_at = NULL,
                    followup_disabled_reason = $2,
                    updated_at = NOW()
                WHERE id = $1
              `,
              [conversation.id, WEB_ONLY_FOLLOWUP_OUTGOING_CONFIRMATION_REASON],
            );
            summary.skipped += 1;
            continue;
          }

          const historyRows = await loadWebOnlyFollowupMessageHistory(conversation.id);
          const terminalState = detectWebOnlyFollowupTerminalState(historyRows);
          if (terminalState.shouldStop) {
            await getPool().query(
              `
                UPDATE conversations
                SET followup_active = false,
                    next_followup_at = NULL,
                    followup_disabled_reason = $2,
                    updated_at = NOW()
                WHERE id = $1
              `,
              [conversation.id, `${WEB_ONLY_FOLLOWUP_CONCLUDED_REASON} ${terminalState.reason}`.slice(0, 240)],
            );
            summary.skipped += 1;
            continue;
          }

          const maxSentStage = await loadWebOnlyMaxSentFollowupStage(user.id, conversation.id);
          const targetStage = maxSentStage >= 0 ? maxSentStage + 1 : Math.max(0, Number(conversation.followupStage || 0));
          conversation.followupScheduleBaseTime = latestMessage.timestamp || conversation.lastMessageTime || null;
          const schedule = resolveWebOnlyReorganizedFollowupSchedule(conversation, targetStage, now, offsetMinutes);

          if (schedule.completed || !schedule.nextDate) {
            await getPool().query(
              `
                UPDATE conversations
                SET followup_active = false,
                    next_followup_at = NULL,
                    followup_disabled_reason = 'Sequencia completa',
                    updated_at = NOW()
                WHERE id = $1
              `,
              [conversation.id],
            );
            summary.completed += 1;
            summary.skipped += 1;
            continue;
          }

          await getPool().query(
            `
              UPDATE conversations
              SET followup_stage = $2,
                  next_followup_at = $3,
                  followup_disabled_reason = NULL,
                  updated_at = NOW()
              WHERE id = $1
            `,
            [conversation.id, schedule.stage, schedule.nextDate.toISOString()],
          );
          summary.reorganized += 1;
          offsetMinutes += 1;
      } catch (error) {
        summary.failed += 1;
        summary.skipped += 1;
        if (summary.errors.length < 10) {
          summary.errors.push({
            conversationId: String(conversation?.id || ""),
            message: String((error as any)?.message || error).slice(0, 220),
          });
        }
        console.error("[vercel-http] followup reorganize conversation failed:", {
          conversationId: conversation?.id,
          error,
        });
      }
    }

    return sendJson(res, 200, {
      ...summary,
    });
  } catch (error) {
    console.error("[vercel-http] followup reorganize failed:", error);
    return sendJson(res, 500, { message: "Failed to reorganize follow-up queue" });
  }
}

async function handleFollowupConversationTrigger(req: any, res: any) {
  const user = await requireJwtUser(req, res);
  if (!user) return;

  const conversationId = String(req.params?.conversationId || "").trim();
  try {
    const conversation = await getConversationForUser(user.id, conversationId);
    if (!conversation) {
      return sendJson(res, 404, { message: "Conversation not found" });
    }
    if (isGroupConversationRow(conversation)) {
      return sendJson(res, 400, { message: "Follow-up automatico nao esta disponivel para grupos." });
    }
    const canonicalSibling = await findWebOnlyCanonicalPhoneSibling(conversation);
    if (canonicalSibling) {
      const reason = await disableDuplicateLidFollowup(conversation, canonicalSibling);
      return sendJson(res, 409, {
        success: false,
        blocked: true,
        reason: "duplicate_lid_conversation",
        message: reason,
        canonicalConversationId: canonicalSibling.id,
      });
    }

    const connectionState = await resolveFollowupConversationConnectionState(conversation);
    if (!connectionState.available) {
      return sendJson(res, 409, {
        success: false,
        blocked: true,
        reason: "connection_unavailable",
        message: connectionState.reason,
        connectionId: conversation.connectionId,
        connectionPhoneNumber: conversation.connectionPhoneNumber,
      });
    }

    const result = await getPool().query(
      `
        UPDATE conversations
        SET followup_active = true,
            next_followup_at = NOW(),
            followup_disabled_reason = NULL,
            updated_at = NOW()
        WHERE id = $1
          AND EXISTS (
            SELECT 1
            FROM whatsapp_connections wc
            WHERE wc.id = conversations.connection_id
              AND wc.user_id = $2
          )
        RETURNING id
      `,
      [conversationId, user.id],
    );
    if (!result.rows[0]) {
      return sendJson(res, 404, { message: "Conversation not found" });
    }
    const jobResult = await runWebOnlyUserFollowupJob({ conversationId });
    return sendJson(res, 200, {
      success: true,
      message: "Follow-up processado para esta conversa",
      result: jobResult,
    });
  } catch (error) {
    console.error("[vercel-http] followup trigger failed:", error);
    return sendJson(res, 500, { message: "Failed to trigger follow-up" });
  }
}

async function handleFollowupStats(req: any, res: any) {
  const user = await requireJwtUser(req, res);
  if (!user) return;

  try {
    const logsResult = await getPool().query(
      `
        SELECT
          COUNT(*) FILTER (WHERE status = 'sent')::int AS "totalSent",
          COUNT(*) FILTER (WHERE status = 'failed')::int AS "totalFailed",
          COUNT(*) FILTER (WHERE status = 'cancelled')::int AS "totalCancelled",
          COUNT(*) FILTER (WHERE status = 'skipped')::int AS "totalSkipped"
        FROM user_followup_logs
        WHERE user_id = $1
      `,
      [user.id],
    );

    const pendingResult = await getPool().query(
      `
        SELECT
          COUNT(*) FILTER (WHERE followup_active = true AND next_followup_at IS NOT NULL)::int AS pending,
          COUNT(*) FILTER (
            WHERE followup_active = true
              AND next_followup_at IS NOT NULL
              AND DATE(next_followup_at AT TIME ZONE 'America/Sao_Paulo') = DATE(NOW() AT TIME ZONE 'America/Sao_Paulo')
          )::int AS "scheduledToday"
        FROM conversations c
        INNER JOIN whatsapp_connections wc
          ON wc.id = c.connection_id
        WHERE wc.user_id = $1
          AND COALESCE(wc.is_connected, false) = true
          AND COALESCE(NULLIF(wc.provider_status, ''), 'connected') IN ('connected', 'open', 'ready', 'authenticated')
          AND NULLIF(regexp_replace(COALESCE(c.owner_phone_number, ''), '\\D', '', 'g'), '') IS NOT NULL
          AND regexp_replace(COALESCE(c.owner_phone_number, ''), '\\D', '', 'g') = regexp_replace(COALESCE(wc.phone_number, ''), '\\D', '', 'g')
      `,
      [user.id],
    );

    return sendJson(res, 200, {
      totalSent: toNumberValue(logsResult.rows[0]?.totalSent, 0),
      totalFailed: toNumberValue(logsResult.rows[0]?.totalFailed, 0),
      totalCancelled: toNumberValue(logsResult.rows[0]?.totalCancelled, 0),
      totalSkipped: toNumberValue(logsResult.rows[0]?.totalSkipped, 0),
      pending: toNumberValue(pendingResult.rows[0]?.pending, 0),
      scheduledToday: toNumberValue(pendingResult.rows[0]?.scheduledToday, 0),
      scheduledThisWeek: 0,
      scheduledThisMonth: 0,
    });
  } catch (error) {
    console.error("[vercel-http] followup stats failed:", error);
    return sendJson(res, 500, { message: "Failed to fetch followup stats" });
  }
}

