async function handleProductsConfig(req: any, res: any) {
  const user = await requireJwtUser(req, res);
  if (!user) return;

  try {
    if (req.method === "PUT") {
      const body = await readJsonBody(req);
      await getPool().query(
        `
          INSERT INTO products_config (
            user_id, is_active, send_to_ai, image_variations_enabled,
            ai_instructions, display_instructions, updated_at
          )
          VALUES ($1,$2,$3,$4,$5,$6,NOW())
          ON CONFLICT (user_id) DO UPDATE SET
            is_active = EXCLUDED.is_active,
            send_to_ai = EXCLUDED.send_to_ai,
            image_variations_enabled = EXCLUDED.image_variations_enabled,
            ai_instructions = EXCLUDED.ai_instructions,
            display_instructions = EXCLUDED.display_instructions,
            updated_at = NOW()
        `,
        [
          user.id,
          body.isActive === true || body.is_active === true,
          body.sendToAi === true || body.send_to_ai === true,
          body.imageVariationsEnabled === true || body.image_variations_enabled === true,
          body.aiInstructions || body.ai_instructions || "",
          body.displayInstructions || body.display_instructions || "",
        ],
      );
    }
    const [configResult, countResult] = await Promise.all([
      getPool().query("SELECT * FROM products_config WHERE user_id = $1 LIMIT 1", [user.id]),
      getPool().query("SELECT COUNT(*)::int AS count FROM products WHERE user_id = $1", [user.id]),
    ]);
    const row = configResult.rows[0];
    return sendJson(res, 200, {
      id: row?.id || null,
      user_id: user.id,
      userId: user.id,
      is_active: row?.is_active === true,
      isActive: row?.is_active === true,
      send_to_ai: row?.send_to_ai === true,
      sendToAi: row?.send_to_ai === true,
      image_variations_enabled: row?.image_variations_enabled === true,
      imageVariationsEnabled: row?.image_variations_enabled === true,
      ai_instructions: row?.ai_instructions || "",
      aiInstructions: row?.ai_instructions || "",
      display_instructions: row?.display_instructions || "",
      displayInstructions: row?.display_instructions || "",
      has_products: Number(countResult.rows[0]?.count || 0) > 0,
      hasProducts: Number(countResult.rows[0]?.count || 0) > 0,
      product_count: Number(countResult.rows[0]?.count || 0),
      productCount: Number(countResult.rows[0]?.count || 0),
      created_at: row?.created_at || null,
      updated_at: row?.updated_at || null,
    });
  } catch (error) {
    console.error("[vercel-http] products config failed:", error);
    return sendJson(res, 500, { message: "Failed to process products config" });
  }
}

function resolvePublicAppOrigin() {
  return String(
    process.env.PUBLIC_APP_URL ||
      process.env.APP_URL ||
      process.env.BASE_URL ||
      process.env.FRONTEND_URL ||
      "https://agentezap.online",
  ).trim().replace(/\/+$/, "");
}

async function getGoogleOAuthConfig() {
  const sharedRedirectUri = String(process.env.GOOGLE_CALENDAR_SHARED_REDIRECT_URI || "").trim()
    || `${resolvePublicAppOrigin()}/api/meta-formulario/google/callback`;
  const sharedClientId = String(process.env.GOOGLE_CLIENT_ID || "").trim();
  const sharedClientSecret = String(process.env.GOOGLE_CLIENT_SECRET || "").trim();
  if (sharedClientId && sharedClientSecret) {
    return { clientId: sharedClientId, clientSecret: sharedClientSecret, redirectUri: sharedRedirectUri };
  }

  const result = await getPool().query(
    `
      SELECT google_client_id, google_client_secret
      FROM meta_form_google_configs
      WHERE google_client_id IS NOT NULL
        AND google_client_secret IS NOT NULL
      ORDER BY updated_at DESC NULLS LAST, created_at DESC NULLS LAST
      LIMIT 1
    `,
  );
  const row = result.rows[0];
  const dbClientId = String(row?.google_client_id || "").trim();
  const dbClientSecret = String(row?.google_client_secret || "").trim();
  if (dbClientId && dbClientSecret) {
    return { clientId: dbClientId, clientSecret: dbClientSecret, redirectUri: sharedRedirectUri };
  }

  const calendarClientId = String(process.env.GOOGLE_CALENDAR_CLIENT_ID || "").trim();
  const calendarClientSecret = String(process.env.GOOGLE_CALENDAR_CLIENT_SECRET || "").trim();
  const calendarRedirectUri = String(process.env.GOOGLE_CALENDAR_REDIRECT_URI || "").trim()
    || `${resolvePublicAppOrigin()}/api/google-calendar/callback`;
  if (calendarClientId && calendarClientSecret) {
    return { clientId: calendarClientId, clientSecret: calendarClientSecret, redirectUri: calendarRedirectUri };
  }
  return null;
}

async function createGoogleOAuthClient() {
  const config = await getGoogleOAuthConfig();
  if (!config) {
    throw new Error("Google Calendar nao esta configurado no servidor.");
  }
  return new google.auth.OAuth2(config.clientId, config.clientSecret, config.redirectUri);
}

type GoogleCalendarOAuthState = {
  module?: string;
  userId: string;
  returnTo?: string;
  appOrigin?: string;
};

function normalizeGoogleCalendarReturnTo(value: unknown, fallback = "/agendamento-3") {
  const text = normalizeMetaFormText(value);
  if (!text || !text.startsWith("/") || text.startsWith("//") || text.includes("\\") || text.startsWith("/api/")) {
    return fallback;
  }
  return text;
}

function appendGoogleCalendarOAuthResult(returnTo: string, params: Record<string, string>) {
  const [path, hash = ""] = returnTo.split("#", 2);
  const [pathname, query = ""] = path.split("?", 2);
  const search = new URLSearchParams(query);
  for (const [key, value] of Object.entries(params)) {
    search.set(key, value);
  }
  return `${pathname}${search.toString() ? `?${search.toString()}` : ""}${hash ? `#${hash}` : ""}`;
}

function inferGoogleCalendarReturnTo(req: any) {
  const explicit = normalizeGoogleCalendarReturnTo(req.query?.returnTo || req.query?.return_to, "");
  if (explicit) return explicit;

  try {
    const referer = normalizeMetaFormText(req.headers?.referer || req.headers?.referrer);
    if (referer) {
      const parsed = new URL(referer);
      return normalizeGoogleCalendarReturnTo(`${parsed.pathname}${parsed.search}${parsed.hash}`);
    }
  } catch {
    // Ignore malformed referer and use the default route.
  }
  return "/agendamento-3";
}

function encodeGoogleCalendarState(userId: string, options?: { returnTo?: string; appOrigin?: string }) {
  const payload = Buffer.from(JSON.stringify({
    module: "google_calendar",
    userId,
    returnTo: normalizeGoogleCalendarReturnTo(options?.returnTo),
    appOrigin: normalizeMetaFormText(options?.appOrigin),
    ts: Date.now(),
  })).toString("base64url");
  const signature = createHmac("sha256", getAdminSessionSecret()).update(payload).digest("base64url");
  return `${payload}.${signature}`;
}

function decodeGoogleCalendarState(rawState: string): GoogleCalendarOAuthState | null {
  const [payload, signature] = String(rawState || "").split(".", 2);
  if (!payload || !signature) return null;
  const expected = createHmac("sha256", getAdminSessionSecret()).update(payload).digest("base64url");
  const providedBuffer = Buffer.from(signature);
  const expectedBuffer = Buffer.from(expected);
  if (providedBuffer.length !== expectedBuffer.length || !timingSafeEqual(providedBuffer, expectedBuffer)) {
    return null;
  }
  try {
    const parsed = JSON.parse(Buffer.from(payload, "base64url").toString("utf8"));
    if (!parsed?.userId || Date.now() - Number(parsed.ts || 0) > 1000 * 60 * 30) return null;
    return {
      module: normalizeMetaFormText(parsed.module) || undefined,
      userId: String(parsed.userId),
      returnTo: normalizeGoogleCalendarReturnTo(parsed.returnTo),
      appOrigin: normalizeMetaFormText(parsed.appOrigin) || undefined,
    };
  } catch {
    return null;
  }
}

async function persistGoogleCalendarTokens(userId: string, tokens: any, metadata?: Record<string, unknown>) {
  const db = getPool();
  const scope = JSON.stringify({
    provider: "google",
    ...(metadata || {}),
    savedAt: new Date().toISOString(),
  });
  const expiryDate = tokens.expiry_date ? new Date(Number(tokens.expiry_date)) : null;
  const values = [
    userId,
    tokens.access_token || null,
    tokens.refresh_token || null,
    tokens.token_type || "Bearer",
    expiryDate,
    scope,
  ];
  const existing = await db.query(`SELECT id FROM google_calendar_tokens WHERE user_id = $1 ORDER BY updated_at DESC NULLS LAST LIMIT 1`, [userId]);
  if (existing.rows[0]?.id) {
    await db.query(
      `
        UPDATE google_calendar_tokens
        SET access_token = COALESCE($2, access_token),
            refresh_token = COALESCE($3, refresh_token),
            token_type = $4,
            expiry_date = $5,
            scope = $6,
            updated_at = NOW()
        WHERE id = $7 AND user_id = $1
      `,
      [...values, existing.rows[0].id],
    );
    return;
  }
  await db.query(
    `
      INSERT INTO google_calendar_tokens (
        user_id, access_token, refresh_token, token_type, expiry_date, scope, updated_at
      )
      VALUES ($1,$2,$3,$4,$5,$6,NOW())
    `,
    values,
  );
}

async function getGoogleCalendarTokenRow(userId: string) {
  const result = await getPool().query(
    `
      SELECT *
      FROM google_calendar_tokens
      WHERE user_id = $1
      ORDER BY updated_at DESC NULLS LAST
    `,
    [userId],
  );
  return result.rows.find((row: any) => !isLegacyMatonCalendarTokenRow(row)) || null;
}

async function getLegacyMatonCalendarTokenRow(userId: string) {
  const result = await getPool().query(
    `
      SELECT *
      FROM google_calendar_tokens
      WHERE user_id = $1
      ORDER BY updated_at DESC NULLS LAST
    `,
    [userId],
  );
  return result.rows.find((row: any) => isLegacyMatonCalendarTokenRow(row)) || null;
}

async function getGoogleCalendarClientForUser(userId: string) {
  const row = await getGoogleCalendarTokenRow(userId);
  if (!row || (!row.access_token && !row.refresh_token)) {
    throw new Error("Google Calendar nao conectado.");
  }
  const oauth2Client = await createGoogleOAuthClient();
  oauth2Client.setCredentials({
    access_token: row.access_token || undefined,
    refresh_token: row.refresh_token || undefined,
    token_type: row.token_type || "Bearer",
    expiry_date: row.expiry_date ? new Date(row.expiry_date).getTime() : undefined,
  });
  oauth2Client.on("tokens", (tokens) => {
    persistGoogleCalendarTokens(userId, tokens).catch((error) => {
      console.warn("[vercel-http] failed to persist refreshed Google tokens:", error);
    });
  });
  return oauth2Client;
}

function parseGoogleTokenMetadata(scope: unknown) {
  if (scope && typeof scope === "object") {
    return scope as Record<string, any>;
  }
  try {
    const parsed = JSON.parse(String(scope || "{}"));
    return parsed && typeof parsed === "object" ? parsed as Record<string, any> : {};
  } catch {
    return {};
  }
}

const LEGACY_MATON_TOKEN_TYPE = "maton_api_key";

function isLegacyMatonCalendarTokenRow(row: any) {
  const metadata = parseGoogleTokenMetadata(row?.scope);
  return String(row?.token_type || "").toLowerCase() === LEGACY_MATON_TOKEN_TYPE
    || String(metadata.provider || "").toLowerCase() === "maton";
}

function canWriteGoogleCalendar(calendar: any) {
  return calendar?.accessRole === "owner" || calendar?.accessRole === "writer";
}

function pickDefaultGoogleCalendarId(calendars: any[]) {
  return calendars.find((calendar) => calendar.primary && canWriteGoogleCalendar(calendar))?.id
    || calendars.find((calendar) => canWriteGoogleCalendar(calendar))?.id
    || calendars[0]?.id
    || "primary";
}

async function listGoogleCalendars(oauth2Client: any) {
  const calendar = google.calendar({ version: "v3", auth: oauth2Client });
  const response = await calendar.calendarList.list({ maxResults: 250 });
  return (response.data.items || []).map((item: any) => ({
    id: item.id,
    summary: item.summary,
    primary: item.primary === true,
    accessRole: item.accessRole,
    timeZone: item.timeZone,
    selected: item.selected === true,
  })).filter((item: any) => item.id && item.summary);
}

async function getGoogleUserEmail(oauth2Client: any) {
  try {
    const oauth2 = google.oauth2({ version: "v2", auth: oauth2Client });
    const response = await oauth2.userinfo.get();
    return response.data.email || undefined;
  } catch {
    return undefined;
  }
}

async function getSelectedGoogleCalendarId(userId: string) {
  const result = await getPool().query(
    `SELECT google_calendar_id FROM scheduling_config WHERE user_id = $1 ORDER BY updated_at DESC NULLS LAST LIMIT 1`,
    [userId],
  );
  return String(result.rows[0]?.google_calendar_id || "").trim() || undefined;
}

const CONFIG_JSONB_COLUMNS = new Set([
  "available_days",
  "blocked_slots",
  "reminder_times",
  "reminder_flow",
  "agenda_business_hours",
]);

function valueForConfigColumn(column: string, value: unknown) {
  if (!CONFIG_JSONB_COLUMNS.has(column)) return value;
  if (typeof value === "string") {
    try {
      JSON.parse(value);
      return value;
    } catch {
      return JSON.stringify(value);
    }
  }
  return JSON.stringify(value ?? null);
}

async function upsertSchedulingConfigForUser(userId: string, updates: Record<string, unknown>) {
  const keys = Object.keys(updates);
  if (!keys.length) return;
  const values = [userId, ...keys.map((key) => valueForConfigColumn(key, updates[key]))];
  const existing = await getPool().query(`SELECT id FROM scheduling_config WHERE user_id = $1 ORDER BY updated_at DESC NULLS LAST LIMIT 1`, [userId]);
  if (existing.rows[0]?.id) {
    await getPool().query(
      `
        UPDATE scheduling_config
        SET ${keys.map((key, index) => `${key} = $${index + 2}`).join(", ")},
            updated_at = NOW()
        WHERE id = $${keys.length + 2} AND user_id = $1
      `,
      [...values, existing.rows[0].id],
    );
    return;
  }
  await getPool().query(
    `
      INSERT INTO scheduling_config (user_id, ${keys.join(", ")}, updated_at)
      VALUES ($1, ${keys.map((_key, index) => `$${index + 2}`).join(", ")}, NOW())
    `,
    values,
  );
}

async function getGoogleCalendarStatusForUser(userId: string) {
  if (!(await getGoogleOAuthConfig())) {
    return {
      connected: false,
      isConnected: false,
      configured: false,
      provider: "google",
      providerLabel: "Google",
      checked: true,
      calendars: [],
    };
  }
  const row = await getGoogleCalendarTokenRow(userId);
  if (!row || (!row.access_token && !row.refresh_token)) {
    const legacyMatonRow = await getLegacyMatonCalendarTokenRow(userId);
    if (legacyMatonRow) {
      const metadata = parseGoogleTokenMetadata(legacyMatonRow.scope);
      return {
        connected: false,
        isConnected: false,
        configured: true,
        provider: "google",
        providerLabel: "Google",
        email: metadata.email || metadata.googleEmail,
        selectedCalendarId: metadata.primaryCalendarId || await getSelectedGoogleCalendarId(userId),
        checked: false,
        calendars: [],
        error: "Esta conexao e antiga. Reconecte o Google Calendar direto pelo AgenteZap para ativar a sincronizacao.",
      };
    }
    return {
      connected: false,
      isConnected: false,
      configured: true,
      provider: "google",
      providerLabel: "Google",
      checked: true,
      calendars: [],
    };
  }

  const metadata = parseGoogleTokenMetadata(row.scope);
  try {
    const oauth2Client = await getGoogleCalendarClientForUser(userId);
    const calendars = await listGoogleCalendars(oauth2Client);
    const configuredCalendarId = await getSelectedGoogleCalendarId(userId);
    const selectedCalendarId = calendars.some((calendar: any) => calendar.id === configuredCalendarId)
      ? configuredCalendarId
      : pickDefaultGoogleCalendarId(calendars);
    return {
      connected: true,
      isConnected: true,
      configured: true,
      provider: "google",
      providerLabel: "Google",
      email: metadata.googleEmail || metadata.email || await getGoogleUserEmail(oauth2Client),
      selectedCalendarId,
      calendars,
      checked: true,
    };
  } catch (error: any) {
    return {
      connected: false,
      isConnected: false,
      configured: true,
      provider: "google",
      providerLabel: "Google",
      email: metadata.googleEmail || metadata.email,
      selectedCalendarId: metadata.selectedCalendarId,
      calendars: [],
      checked: false,
      error: error?.message || "Falha ao validar conexao Google.",
    };
  }
}

function readGoogleEventDateTime(eventDateTime?: any): Date | null {
  if (!eventDateTime) return null;
  if (eventDateTime.dateTime) {
    return parseCalendarDateTimeWithZone(String(eventDateTime.dateTime), eventDateTime.timeZone || DEFAULT_CALENDAR_TIMEZONE);
  }
  if (eventDateTime.date) {
    return parseCalendarDateTimeWithZone(`${eventDateTime.date}T00:00:00`, eventDateTime.timeZone || DEFAULT_CALENDAR_TIMEZONE);
  }
  return null;
}

function isBusyGoogleEvent(event: any) {
  return event?.status !== "cancelled" && event?.transparency !== "transparent";
}

function getGoogleEventInternalAppointmentId(event: any) {
  const direct = event?.extendedProperties?.private?.internalAppointmentId;
  if (direct) return String(direct);
  const description = String(event?.description || "");
  const match = description.match(/ID interno:\s*([a-zA-Z0-9_-]+)/);
  return match?.[1] || "";
}

async function listGoogleCalendarEventsForUser(userId: string, startDate: Date, endDate: Date, options?: { updatedMin?: Date }) {
  const oauth2Client = await getGoogleCalendarClientForUser(userId);
  const calendar = google.calendar({ version: "v3", auth: oauth2Client });
  const calendarId = await getSelectedGoogleCalendarId(userId) || "primary";
  const response = await calendar.events.list({
    calendarId,
    timeMin: startDate.toISOString(),
    timeMax: endDate.toISOString(),
    updatedMin: options?.updatedMin?.toISOString(),
    singleEvents: true,
    orderBy: options?.updatedMin ? undefined : "startTime",
    showDeleted: Boolean(options?.updatedMin),
    maxResults: 2500,
  });
  return { calendarId, events: response.data.items || [] };
}

async function listGoogleCalendarBusyWindowsForUser(userId: string, startDateTime: string, endDateTime: string, options?: { excludeEventId?: string }) {
  const start = parseCalendarDateTimeWithZone(startDateTime);
  const end = parseCalendarDateTimeWithZone(endDateTime);
  const { events } = await listGoogleCalendarEventsForUser(userId, start, end);
  const windows = events
    .filter(isBusyGoogleEvent)
    .filter((event: any) => event.id !== options?.excludeEventId)
    .map((event: any) => {
      const eventStart = readGoogleEventDateTime(event.start);
      const eventEnd = readGoogleEventDateTime(event.end);
      if (!eventStart || !eventEnd || !rangesOverlap(start, end, eventStart, eventEnd)) return null;
      return {
        eventId: event.id,
        summary: event.summary || "Evento sem titulo",
        startDateTime: eventStart.toISOString(),
        endDateTime: eventEnd.toISOString(),
      };
    })
    .filter(Boolean);
  return { success: true, windows };
}

function buildGoogleCalendarEventResource(appointment: any, serviceDurationMinutes = 60) {
  const startDateTime = buildCalendarDateTimeValue(appointment.appointmentDate, appointment.appointmentTime);
  const endDateTime = addMinutesToCalendarDateTimeValue(
    appointment.appointmentDate,
    appointment.appointmentTime,
    serviceDurationMinutes,
  );
  return {
    summary: `Agendamento - ${appointment.clientName}`,
    description: [
      `Cliente: ${appointment.clientName}`,
      `Telefone: ${appointment.clientPhone || ""}`,
      appointment.serviceName ? `Servico: ${appointment.serviceName}` : "",
      appointment.location ? `Endereco: ${appointment.location}` : "",
      appointment.notes ? `Notas: ${appointment.notes}` : "",
      ...(Array.isArray(appointment.extraDetails) ? appointment.extraDetails : []),
      "--- Agendado via AgentZap ---",
      `ID interno: ${appointment.id}`,
    ].filter(Boolean).join("\n"),
    location: appointment.location || undefined,
    start: { dateTime: startDateTime, timeZone: DEFAULT_CALENDAR_TIMEZONE },
    end: { dateTime: endDateTime, timeZone: DEFAULT_CALENDAR_TIMEZONE },
    colorId: "2",
    extendedProperties: {
      private: {
        source: "agentezap",
        internalAppointmentId: appointment.id,
      },
    },
  };
}

async function checkGoogleCalendarAvailabilityForUser(userId: string, startDateTime: string, endDateTime: string, options?: { excludeEventId?: string; failOpen?: boolean }) {
  try {
    const result = await listGoogleCalendarBusyWindowsForUser(userId, startDateTime, endDateTime, {
      excludeEventId: options?.excludeEventId,
    });
    const conflict = result.windows[0] as any;
    if (conflict) {
      return {
        available: false,
        checked: true,
        conflictEvent: conflict.summary,
        conflictEventId: conflict.eventId,
      };
    }
    return { available: true, checked: true };
  } catch (error: any) {
    return {
      available: options?.failOpen !== false,
      checked: false,
      error: error?.message || "Falha ao consultar a agenda Google.",
    };
  }
}

async function syncAppointmentToGoogleCalendar(userId: string, appointment: any, serviceDurationMinutes = 60) {
  try {
    const resource = buildGoogleCalendarEventResource(appointment, serviceDurationMinutes);
    const oauth2Client = await getGoogleCalendarClientForUser(userId);
    const calendar = google.calendar({ version: "v3", auth: oauth2Client });
    const calendarId = await getSelectedGoogleCalendarId(userId) || "primary";

    if (appointment.googleEventId) {
      await calendar.events.patch({
        calendarId,
        eventId: appointment.googleEventId,
        requestBody: resource,
      });
      return { success: true, eventId: appointment.googleEventId };
    }
    const created = await calendar.events.insert({ calendarId, requestBody: resource });
    return { success: true, eventId: created.data.id || undefined };
  } catch (error: any) {
    console.error("[vercel-http] Google appointment sync failed:", error);
    return { success: false, error: error?.message || "Falha ao sincronizar agendamento no Google." };
  }
}

async function removeAppointmentFromGoogleCalendar(userId: string, googleEventId: string) {
  try {
    const oauth2Client = await getGoogleCalendarClientForUser(userId);
    const calendar = google.calendar({ version: "v3", auth: oauth2Client });
    const calendarId = await getSelectedGoogleCalendarId(userId) || "primary";
    await calendar.events.delete({ calendarId, eventId: googleEventId });
    return { success: true };
  } catch (error: any) {
    return { success: false, error: error?.message || "Falha ao remover evento Google." };
  }
}

function googleEventToLocalAppointmentFields(event: any) {
  const startDate = readGoogleEventDateTime(event.start);
  const endDate = readGoogleEventDateTime(event.end);
  if (!startDate || !endDate) return null;
  const startLocal = formatCalendarLocalDateTime(startDate);
  const endLocal = formatCalendarLocalDateTime(endDate);
  const title = trimForAgenda(event.summary || "Compromisso Google", 180) || "Compromisso Google";
  const description = trimForAgenda(event.description || "", 1500);
  return {
    clientName: title,
    clientPhone: "google-calendar",
    serviceName: title,
    appointmentDate: startLocal.slice(0, 10),
    startTime: startLocal.slice(11, 19),
    endTime: endLocal.slice(11, 19),
    durationMinutes: Math.max(1, Math.round((endDate.getTime() - startDate.getTime()) / 60000)),
    location: trimForAgenda(event.location || "", 400) || null,
    clientNotes: description || null,
  };
}

function isGoogleImportedAppointment(internalNotes: unknown) {
  return String(internalNotes || "").startsWith(GOOGLE_IMPORTED_MARKER);
}

async function applyGoogleEventToLocalSchedule(userId: string, event: any) {
  const eventId = String(event?.id || "").trim();
  if (!eventId) return;
  const internalAppointmentId = getGoogleEventInternalAppointmentId(event);
  const existing = await getPool().query(
    `
      SELECT id, conversation_id, internal_notes
      FROM appointments
      WHERE user_id = $1
        AND (google_event_id = $2 OR ($3 <> '' AND id = $3))
      ORDER BY updated_at DESC NULLS LAST
      LIMIT 1
    `,
    [userId, eventId, internalAppointmentId],
  );
  const existingRow = existing.rows[0];

  if (event.status === "cancelled") {
    if (existingRow) {
      await getPool().query(
        `UPDATE appointments SET status = 'cancelled', cancelled_at = NOW(), updated_at = NOW() WHERE id = $1 AND user_id = $2`,
        [existingRow.id, userId],
      );
    }
    return;
  }
  if (!isBusyGoogleEvent(event)) return;
  const fields = googleEventToLocalAppointmentFields(event);
  if (!fields) return;
  const internalNotes = [
    GOOGLE_IMPORTED_MARKER,
    `Evento Google: ${eventId}`,
    event.htmlLink ? `Link: ${event.htmlLink}` : "",
    event.updated ? `Atualizado Google: ${event.updated}` : "",
  ].filter(Boolean).join("\n");

  if (existingRow) {
    const preserveServiceName = !isGoogleImportedAppointment(existingRow.internal_notes) && Boolean(existingRow.conversation_id);
    await getPool().query(
      `
        UPDATE appointments
        SET client_name = $3,
            client_phone = COALESCE(NULLIF(client_phone, ''), $4),
            service_name = CASE WHEN $12::boolean THEN service_name ELSE $5 END,
            appointment_date = $6,
            start_time = $7,
            end_time = $8,
            duration_minutes = $9,
            location = $10,
            client_notes = $11,
            google_event_id = $2,
            google_calendar_synced = true,
            updated_at = NOW()
        WHERE id = $1 AND user_id = $13
      `,
      [
        existingRow.id,
        eventId,
        fields.clientName,
        fields.clientPhone,
        fields.serviceName,
        fields.appointmentDate,
        fields.startTime,
        fields.endTime,
        fields.durationMinutes,
        fields.location,
        fields.clientNotes,
        preserveServiceName,
        userId,
      ],
    );
    return;
  }

  if (internalAppointmentId) return;
  await getPool().query(
    `
      INSERT INTO appointments (
        user_id, client_name, client_phone, service_name, appointment_date,
        start_time, end_time, duration_minutes, location, location_type,
        status, google_event_id, google_calendar_synced, client_notes,
        internal_notes, created_by_ai, created_at, updated_at
      )
      VALUES ($1,$2,$3,$4,$5,$6,$7,$8,$9,'google','confirmed',$10,true,$11,$12,false,NOW(),NOW())
      ON CONFLICT DO NOTHING
    `,
    [
      userId,
      fields.clientName,
      fields.clientPhone,
      fields.serviceName,
      fields.appointmentDate,
      fields.startTime,
      fields.endTime,
      fields.durationMinutes,
      fields.location,
      eventId,
      fields.clientNotes,
      internalNotes,
    ],
  );
}

async function getGoogleCalendarSyncState(userId: string) {
  const result = await getPool().query(
    `SELECT * FROM google_calendar_sync_state WHERE user_id = $1 LIMIT 1`,
    [userId],
  );
  return result.rows[0] || null;
}

async function upsertGoogleCalendarSyncState(params: {
  userId: string;
  calendarId: string | null;
  lastGoogleUpdatedAt: Date | null;
  lastSyncStatus: string;
  lastError: string | null;
}) {
  await getPool().query(
    `
      INSERT INTO google_calendar_sync_state (
        user_id, calendar_id, last_google_updated_at, last_sync_at,
        last_sync_status, last_error, updated_at
      )
      VALUES ($1,$2,$3,NOW(),$4,$5,NOW())
      ON CONFLICT (user_id) DO UPDATE SET
        calendar_id = EXCLUDED.calendar_id,
        last_google_updated_at = EXCLUDED.last_google_updated_at,
        last_sync_at = NOW(),
        last_sync_status = EXCLUDED.last_sync_status,
        last_error = EXCLUDED.last_error,
        updated_at = NOW()
    `,
    [params.userId, params.calendarId, params.lastGoogleUpdatedAt, params.lastSyncStatus, params.lastError],
  );
}

async function clearImportedGoogleAppointments(userId: string) {
  await getPool().query(
    `DELETE FROM appointments WHERE user_id = $1 AND internal_notes LIKE $2`,
    [userId, `${GOOGLE_IMPORTED_MARKER}%`],
  );
}

async function synchronizeGoogleCalendarForUserVercel(userId: string, options?: { forceFullSync?: boolean }) {
  const selectedCalendarBefore = await getSelectedGoogleCalendarId(userId);
  const previousState = await getGoogleCalendarSyncState(userId);
  const calendarChanged = previousState?.calendar_id && selectedCalendarBefore && previousState.calendar_id !== selectedCalendarBefore;
  if (calendarChanged) {
    await clearImportedGoogleAppointments(userId);
  }

  const now = new Date();
  const start = new Date(now);
  start.setDate(start.getDate() - (options?.forceFullSync || calendarChanged ? 30 : 2));
  const end = new Date(now);
  end.setDate(end.getDate() + 180);
  const updatedMin = !options?.forceFullSync && !calendarChanged && previousState?.last_google_updated_at
    ? new Date(new Date(previousState.last_google_updated_at).getTime() - 2 * 60 * 1000)
    : undefined;
  const { calendarId, events } = await listGoogleCalendarEventsForUser(userId, start, end, { updatedMin });
  for (const event of events) {
    await applyGoogleEventToLocalSchedule(userId, event);
  }
  await upsertGoogleCalendarSyncState({
    userId,
    calendarId,
    lastGoogleUpdatedAt: new Date(),
    lastSyncStatus: "ok",
    lastError: null,
  });
  return { userId, calendarId, processedEvents: events.length };
}

async function handleGoogleCalendarSyncCron(req: any, res: any) {
  const expected = String(process.env.CRON_SECRET || "").trim();
  const authHeader = String(req.headers.authorization || "").trim();
  if (expected && authHeader !== `Bearer ${expected}`) {
    return sendJson(res, 401, { success: false, message: "Unauthorized" });
  }
  try {
    const result = await getPool().query(
      `
        SELECT DISTINCT gct.user_id
        FROM google_calendar_tokens gct
        INNER JOIN scheduling_config sc ON sc.user_id = gct.user_id
        WHERE COALESCE(sc.google_calendar_enabled, false) = true
          AND (NULLIF(gct.access_token, '') IS NOT NULL OR NULLIF(gct.refresh_token, '') IS NOT NULL)
        LIMIT 100
      `,
    );
    const details: any[] = [];
    for (const row of result.rows) {
      const userId = String(row.user_id || "");
      try {
        const oauthTokenRow = await getGoogleCalendarTokenRow(userId);
        if (!oauthTokenRow) {
          details.push({ userId, skipped: "google_oauth_not_connected" });
          continue;
        }
        details.push(await synchronizeGoogleCalendarForUserVercel(userId));
      } catch (error: any) {
        await upsertGoogleCalendarSyncState({
          userId,
          calendarId: await getSelectedGoogleCalendarId(userId) || null,
          lastGoogleUpdatedAt: (await getGoogleCalendarSyncState(userId))?.last_google_updated_at || null,
          lastSyncStatus: "error",
          lastError: error?.message || "Google sync failed",
        }).catch(() => undefined);
        details.push({ userId, error: error?.message || "Google sync failed" });
      }
    }
    return sendJson(res, 200, { success: true, processedUsers: result.rows.length, details });
  } catch (error: any) {
    if (isPgConnectionAcquireTimeout(error)) {
      console.warn("[vercel-http] google calendar sync cron deferred because database connection was unavailable:", error);
      return sendJson(res, 202, {
        success: true,
        processedUsers: 0,
        reason: "database_connection_timeout",
      });
    }
    console.error("[vercel-http] google calendar sync cron failed:", error);
    return sendJson(res, 500, { success: false, message: error?.message || "Failed to sync Google Calendar" });
  }
}

async function handleSchedulingGoogleCalendar(req: any, res: any, action: "connect" | "status" | "calendar" | "disconnect") {
  const user = await requireJwtUser(req, res);
  if (!user) return;
  try {
    if (action === "connect" && req.method === "GET") {
      const oauth2Client = await createGoogleOAuthClient();
      const returnTo = inferGoogleCalendarReturnTo(req);
      const authUrl = oauth2Client.generateAuthUrl({
        access_type: "offline",
        prompt: "consent select_account",
        scope: GOOGLE_SCOPES,
        state: encodeGoogleCalendarState(user.id, {
          returnTo,
          appOrigin: getMetaFormRequestOrigin(req),
        }),
      });
      return sendJson(res, 200, { authUrl });
    }
    if (action === "status" && req.method === "GET") {
      return sendJson(res, 200, await getGoogleCalendarStatusForUser(user.id));
    }
    if (action === "calendar" && req.method === "PUT") {
      const body = await readJsonBody(req);
      const calendarId = String(body.calendarId || "").trim();
      if (!calendarId) return sendJson(res, 400, { message: "Selecione uma agenda valida." });
      const oauth2Client = await getGoogleCalendarClientForUser(user.id);
      const calendars = await listGoogleCalendars(oauth2Client);
      const target = calendars.find((calendar: any) => calendar.id === calendarId);
      if (!target || !canWriteGoogleCalendar(target)) {
        return sendJson(res, 400, { message: "A agenda escolhida nao possui permissao de escrita." });
      }
      await upsertSchedulingConfigForUser(user.id, {
        google_calendar_enabled: true,
        google_calendar_id: calendarId,
      });
      await clearImportedGoogleAppointments(user.id);
      await synchronizeGoogleCalendarForUserVercel(user.id, { forceFullSync: true }).catch((error) => {
        console.error("[vercel-http] full sync after calendar switch failed:", error);
      });
      return sendJson(res, 200, await getGoogleCalendarStatusForUser(user.id));
    }
    if (action === "disconnect" && req.method === "POST") {
      await getPool().query(`DELETE FROM google_calendar_tokens WHERE user_id = $1`, [user.id]);
      await upsertSchedulingConfigForUser(user.id, {
        google_calendar_enabled: false,
        google_calendar_id: null,
      });
      return sendJson(res, 200, { message: "Google Calendar desconectado com sucesso" });
    }
    return sendJson(res, 405, { message: "Method not allowed" });
  } catch (error: any) {
    console.error("[vercel-http] scheduling Google Calendar failed:", error);
    return sendJson(res, action === "connect" ? 500 : 400, {
      message: error?.message || "Falha na integracao Google Calendar.",
    });
  }
}

async function handleGoogleCalendarCallback(req: any, res: any) {
  try {
    const parsedUrl = new URL(req.url || "", "https://agentezap.online");
    const code = parsedUrl.searchParams.get("code") || "";
    const rawState = parsedUrl.searchParams.get("state") || "";
    const oauthError = parsedUrl.searchParams.get("error") || "";
    const decodedState = decodeGoogleCalendarState(rawState);
    const sendPopupResult = (success: boolean, message: string) => {
      const returnTo = normalizeGoogleCalendarReturnTo(decodedState?.returnTo);
      const redirectUrl = success
        ? appendGoogleCalendarOAuthResult(returnTo, { googleCalendarConnected: "1" })
        : appendGoogleCalendarOAuthResult(returnTo, { googleCalendarError: message || "Falha Google" });
      const payload = {
        type: "google-calendar-connected",
        source: "google-calendar-connected",
        success,
        message: message || null,
        error: message || null,
        returnTo,
      };
      const targetOrigin = normalizeMetaFormText(decodedState?.appOrigin) || getMetaFormRequestOrigin(req);
      res.statusCode = 200;
      res.setHeader("Content-Type", "text/html; charset=utf-8");
      res.end(`<!DOCTYPE html><html><head><title>Google Calendar</title></head><body>
        <h2>${success ? "Conectado com sucesso" : `Erro: ${message}`}</h2>
        <script>(function(){const payload=${JSON.stringify(payload)};const targetOrigin=${JSON.stringify(targetOrigin)};const redirectUrl=${JSON.stringify(redirectUrl)};try{if(window.opener&&typeof window.opener.postMessage==="function"){window.opener.postMessage(payload,targetOrigin);window.close();setTimeout(function(){window.location.replace(redirectUrl)},400);return}}catch(error){console.error(error)}window.location.replace(redirectUrl)})();</script>
      </body></html>`);
    };
    if (oauthError) return sendPopupResult(false, oauthError);
    if (!code || !decodedState?.userId) return sendPopupResult(false, "Parametros ausentes ou invalidos.");

    const oauth2Client = await createGoogleOAuthClient();
    const tokenResponse = await oauth2Client.getToken(code);
    oauth2Client.setCredentials(tokenResponse.tokens);
    const googleEmail = await getGoogleUserEmail(oauth2Client);
    await persistGoogleCalendarTokens(decodedState.userId, tokenResponse.tokens, { googleEmail });
    const calendars = await listGoogleCalendars(oauth2Client);
    const selectedCalendarId = pickDefaultGoogleCalendarId(calendars);
    await upsertSchedulingConfigForUser(decodedState.userId, {
      google_calendar_enabled: true,
      google_calendar_id: selectedCalendarId,
    });
    await synchronizeGoogleCalendarForUserVercel(decodedState.userId, { forceFullSync: true }).catch((error) => {
      console.error("[vercel-http] initial Google sync failed:", error);
    });
    return sendPopupResult(true, "");
  } catch (error: any) {
    console.error("[vercel-http] google callback failed:", error);
    const fallbackUrl = appendGoogleCalendarOAuthResult("/agendamento-3", {
      googleCalendarError: error?.message || "Falha Google",
    });
    res.statusCode = 200;
    res.setHeader("Content-Type", "text/html; charset=utf-8");
    res.end(`<!DOCTYPE html><html><body><h2>Erro: ${String(error?.message || "Falha Google").replace(/</g, "&lt;")}</h2><script>
      if (window.opener) window.opener.postMessage({ type: 'google-calendar-connected', success: false, error: ${JSON.stringify(error?.message || "Falha Google")} }, '*');
      setTimeout(function(){ window.location.replace(${JSON.stringify(fallbackUrl)}); }, 2000);
    </script></body></html>`);
  }
}

