async function handleGoogleCalendarSyncAppointment(req: any, res: any, appointmentId: string) {
  const user = await requireJwtUser(req, res);
  if (!user) return;
  try {
    const appointment = await getPool().query(`SELECT * FROM appointments WHERE id = $1 AND user_id = $2 LIMIT 1`, [appointmentId, user.id]);
    const row = appointment.rows[0];
    if (!row) return sendJson(res, 404, { message: "Agendamento nao encontrado" });
    const config = await getPool().query(`SELECT slot_duration, service_name FROM scheduling_config WHERE user_id = $1 LIMIT 1`, [user.id]);
    const sync = await syncAppointmentToGoogleCalendar(user.id, {
      id: row.id,
      clientName: row.client_name,
      clientPhone: row.client_phone,
      appointmentDate: String(row.appointment_date).slice(0, 10),
      appointmentTime: String(row.start_time).slice(0, 5),
      serviceName: row.service_name || config.rows[0]?.service_name,
      notes: row.client_notes,
      googleEventId: row.google_event_id,
      location: row.location,
    }, row.duration_minutes || config.rows[0]?.slot_duration || 60);
    if (!sync.success || !sync.eventId) return sendJson(res, 400, { message: sync.error || "Falha ao sincronizar" });
    await getPool().query(
      `UPDATE appointments SET google_event_id = $2, google_calendar_synced = true, updated_at = NOW() WHERE id = $1 AND user_id = $3`,
      [appointmentId, sync.eventId, user.id],
    );
    return sendJson(res, 200, { message: "Sincronizado com Google Calendar", eventId: sync.eventId });
  } catch (error: any) {
    return sendJson(res, 500, { message: error?.message || "Failed to sync appointment" });
  }
}

