type Agendamento3Intent = "book" | "check_availability" | "cancel" | "reschedule" | "unknown";

type Agendamento3Plan = {
  intent: Agendamento3Intent;
  date?: string | null;
  time?: string | null;
  durationMinutes?: number | null;
  clientName?: string | null;
  clientPhone?: string | null;
  serviceName?: string | null;
  confidence: number;
  missing: string[];
  summary?: string | null;
};

type Agendamento3TraceStep = {
  tool: string;
  ok: boolean;
  detail?: string;
  data?: Record<string, unknown>;
};

type Agendamento3AgentResult = {
  handled: boolean;
  response: string;
  plan: Agendamento3Plan;
  trace: Agendamento3TraceStep[];
  available?: boolean;
  appointment?: Record<string, unknown> | null;
  dryRun?: boolean;
};

const AGENDAMENTO3_AGENTIC_MARKER = "agendamento3_agentic";

function buildAgendamento3ConfigDefaults(userId: string): Record<string, unknown> {
  return {
    user_id: userId,
    is_active: false,
    display_name: "Agendamento 3.0",
    agentic_mode_enabled: true,
    require_google_validation: true,
    auto_confirm: true,
    reminder_enabled: false,
    reminder_hours_before: 1,
    reminder_flow: [],
    notes: null,
  };
}

function normalizeAgendamento3Text(value: unknown): string {
  return String(value || "")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase();
}

function addDaysToDateKey(dateKey: string, days: number): string {
  const date = parseCalendarDateTimeWithZone(`${dateKey}T12:00:00`, DEFAULT_CALENDAR_TIMEZONE);
  date.setUTCDate(date.getUTCDate() + days);
  return formatBrazilDateKey(date);
}

function getBrazilTodayDateKey(): string {
  return formatBrazilDateKey(new Date());
}

function parseAgendamento3DateFromText(text: string): string | null {
  const normalized = normalizeAgendamento3Text(text);
  const today = getBrazilTodayDateKey();
  if (/\bdepois de amanha\b/.test(normalized)) return addDaysToDateKey(today, 2);
  if (/\bamanha\b/.test(normalized)) return addDaysToDateKey(today, 1);
  if (/\bhoje\b/.test(normalized)) return today;

  const iso = normalized.match(/\b(20\d{2})-(\d{2})-(\d{2})\b/);
  if (iso) return `${iso[1]}-${iso[2]}-${iso[3]}`;

  const slash = normalized.match(/\b(\d{1,2})\/(\d{1,2})(?:\/(\d{2,4}))?\b/);
  if (slash) {
    const day = Number(slash[1]);
    const month = Number(slash[2]);
    const currentYear = Number(today.slice(0, 4));
    const rawYear = slash[3] ? Number(slash[3]) : currentYear;
    const year = rawYear < 100 ? 2000 + rawYear : rawYear;
    if (day >= 1 && day <= 31 && month >= 1 && month <= 12) {
      return `${year}-${String(month).padStart(2, "0")}-${String(day).padStart(2, "0")}`;
    }
  }

  return null;
}

function parseAgendamento3TimeFromText(text: string): string | null {
  const value = normalizeAgendamento3Text(text);
  const regex = /\b([01]?\d|2[0-3])(?:(?:[:h])([0-5]\d))?\s*(?:h|hora|horas|hrs)?\b/g;
  let match: RegExpExecArray | null;
  while ((match = regex.exec(value))) {
    const raw = match[0] || "";
    const start = match.index;
    const end = start + raw.length;
    const before = start > 0 ? value[start - 1] : "";
    const after = end < value.length ? value[end] : "";
    if (before === "/" || after === "/" || before === "-" || after === "-") continue;
    const hasExplicitTimeMarker = raw.includes(":") || raw.includes("h") || raw.includes("hora") || raw.includes("hrs");
    if (!hasExplicitTimeMarker) continue;
    const hour = Number(match[1]);
    const minute = match[2] ? Number(match[2]) : 0;
    if (hour >= 0 && hour <= 23 && minute >= 0 && minute <= 59) {
      return `${String(hour).padStart(2, "0")}:${String(minute).padStart(2, "0")}`;
    }
  }
  return null;
}

function inferAgendamento3Intent(text: string): Agendamento3Intent {
  const normalized = normalizeAgendamento3Text(text);
  if (/\b(cancelar|cancela|desmarcar|remover)\b/.test(normalized)) return "cancel";
  if (/\b(remarcar|reagendar|mudar horario|trocar horario|alterar horario)\b/.test(normalized)) return "reschedule";
  if (/\b(disponivel|disponibilidade|tem horario|tem vaga|horarios|agenda livre|esta livre)\b/.test(normalized)) {
    return "check_availability";
  }
  if (/\b(agendar|agenda|marcar|reservar|confirmar horario|visita|reuniao|consulta|atendimento)\b/.test(normalized)) {
    return "book";
  }
  return "unknown";
}

function hasAgendamento3SchedulingSignal(text: string): boolean {
  const normalized = normalizeAgendamento3Text(text);
  return /\b(agendar|agenda|marcar|remarcar|cancelar|desmarcar|horario|horarios|disponibilidade|visita|reuniao|consulta|atendimento|amanha|hoje)\b/.test(normalized);
}

function normalizeAgendamento3Plan(input: Partial<Agendamento3Plan> | null | undefined, message: string, fallbackName?: string | null, fallbackPhone?: string | null): Agendamento3Plan {
  const deterministicDate = parseAgendamento3DateFromText(message);
  const deterministicTime = parseAgendamento3TimeFromText(message);
  const deterministicIntent = inferAgendamento3Intent(message);
  const candidateIntent = typeof input?.intent === "string" ? input.intent : deterministicIntent;
  const intent = (["book", "check_availability", "cancel", "reschedule", "unknown"].includes(candidateIntent)
    ? candidateIntent
    : deterministicIntent) as Agendamento3Intent;
  const date = typeof input?.date === "string" && /^\d{4}-\d{2}-\d{2}$/.test(input.date) ? input.date : deterministicDate;
  const rawTime = typeof input?.time === "string" ? input.time : null;
  const time = rawTime && /^\d{1,2}:\d{2}$/.test(rawTime)
    ? `${rawTime.split(":")[0].padStart(2, "0")}:${rawTime.split(":")[1]}`
    : deterministicTime;
  const durationMinutes = toNumberValue(input?.durationMinutes, 0) || null;
  const missing: string[] = [];
  if ((intent === "book" || intent === "check_availability" || intent === "reschedule") && !date) missing.push("date");
  if ((intent === "book" || intent === "check_availability" || intent === "reschedule") && !time) missing.push("time");
  return {
    intent,
    date,
    time,
    durationMinutes,
    clientName: typeof input?.clientName === "string" && input.clientName.trim() ? input.clientName.trim() : fallbackName || null,
    clientPhone: typeof input?.clientPhone === "string" && input.clientPhone.trim() ? input.clientPhone.trim() : fallbackPhone || null,
    serviceName: typeof input?.serviceName === "string" && input.serviceName.trim() ? input.serviceName.trim() : null,
    confidence: Math.max(0, Math.min(1, toNumberValue(input?.confidence, deterministicIntent === "unknown" ? 0.35 : 0.72) || 0.5)),
    missing,
    summary: typeof input?.summary === "string" ? input.summary : null,
  };
}

async function parseAgendamento3PlanWithLlm(input: {
  userId: string;
  message: string;
  history?: Array<{ role?: string; content?: string }>;
  contactName?: string | null;
  contactPhone?: string | null;
  trace: Agendamento3TraceStep[];
}): Promise<Agendamento3Plan> {
  const fallback = normalizeAgendamento3Plan(null, input.message, input.contactName, input.contactPhone);
  if (!hasAgendamento3SchedulingSignal(input.message)) return fallback;
  try {
    const today = getBrazilTodayDateKey();
    const historyText = Array.isArray(input.history)
      ? input.history.slice(-8).map((entry) => `${entry.role || "user"}: ${String(entry.content || "").slice(0, 280)}`).join("\n")
      : "";
    const systemPrompt = [
      "Voce e o planejador inteligente de agenda do AgenteZap. Extraia somente JSON valido.",
      `Hoje no Brasil e ${today}. Timezone: ${DEFAULT_CALENDAR_TIMEZONE}.`,
      "Campos: intent(book|check_availability|cancel|reschedule|unknown), date(YYYY-MM-DD|null), time(HH:mm|null), durationMinutes(number|null), clientName, clientPhone, serviceName, confidence(0-1), summary.",
      "Nao invente data ou horario. Se faltar, use null.",
      historyText ? `Historico recente:\n${historyText}` : "",
    ].filter(Boolean).join("\n\n");
    const agenticRun = await runWebOnlyAgenticTask({
      userId: input.userId,
      task: "agendamento3_plan",
      model: "mistral-small-latest",
      system: "Return compact JSON only. No markdown.",
      systemExtra: systemPrompt,
      message: input.message,
      history: [],
      temperature: 0,
      maxTokens: 420,
      maxSteps: 2,
      tools: [
        {
          name: "ler_historico_de_agenda",
          purpose: "Usa historico recente, mensagem atual e dados do contato para decidir intencao, data, horario e servico sem inventar informacao.",
          result: {
            today,
            timezone: DEFAULT_CALENDAR_TIMEZONE,
            historyText,
            contactName: input.contactName || null,
            contactPhone: input.contactPhone || null,
            deterministicFallback: fallback,
          },
        },
      ],
      legacyFallback: () => callWebOnlyLlm({
        userId: input.userId,
        model: "mistral-small-latest",
        prompt: "Return compact JSON only. No markdown.",
        systemExtra: systemPrompt,
        message: input.message,
        history: [],
        temperature: 0,
        maxTokens: 420,
      }),
    });
    const raw = agenticRun.text;
    const parsed = parseFirstJsonObject(raw);
    input.trace.push({
      tool: "agendamento3_plan",
      ok: !!parsed,
      detail: parsed ? "Plano extraido pelo planejador inteligente." : "A interpretacao nao retornou JSON parseavel.",
      data: {
        engine: agenticRun.agentTrace?.engine,
        provider: agenticRun.provider,
        model: agenticRun.model,
        fallback: agenticRun.agentTrace?.fallback === true,
      },
    });
    return normalizeAgendamento3Plan((parsed || {}) as Partial<Agendamento3Plan>, input.message, input.contactName, input.contactPhone);
  } catch (error: any) {
    input.trace.push({ tool: "agendamento3_plan", ok: false, detail: error?.message || String(error) });
    return fallback;
  }
}

async function getAgendamento3ConfigForUser(userId: string): Promise<Record<string, unknown>> {
  const result = await getPool().query(`SELECT * FROM agendamento3_config WHERE user_id = $1 LIMIT 1`, [userId]);
  return result.rows[0] ? { ...buildAgendamento3ConfigDefaults(userId), ...result.rows[0] } : buildAgendamento3ConfigDefaults(userId);
}

async function upsertAgendamento3ConfigForUser(userId: string, updates: Record<string, unknown>): Promise<Record<string, unknown>> {
  const current = await getAgendamento3ConfigForUser(userId);
  const next = { ...current, ...updates, user_id: userId };
  const result = await getPool().query(
    `INSERT INTO agendamento3_config (
       user_id, is_active, display_name, agentic_mode_enabled, require_google_validation, auto_confirm,
       reminder_enabled, reminder_hours_before, reminder_flow, notes, updated_at
     ) VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $9::jsonb, $10, NOW())
     ON CONFLICT (user_id) DO UPDATE SET
       is_active = EXCLUDED.is_active,
       display_name = EXCLUDED.display_name,
       agentic_mode_enabled = EXCLUDED.agentic_mode_enabled,
       require_google_validation = EXCLUDED.require_google_validation,
       auto_confirm = EXCLUDED.auto_confirm,
       reminder_enabled = EXCLUDED.reminder_enabled,
       reminder_hours_before = EXCLUDED.reminder_hours_before,
       reminder_flow = EXCLUDED.reminder_flow,
       notes = EXCLUDED.notes,
       updated_at = NOW()
     RETURNING *`,
    [
      userId,
      Boolean(next.is_active),
      String(next.display_name || "Agendamento 3.0"),
      next.agentic_mode_enabled !== false,
      next.require_google_validation !== false,
      next.auto_confirm !== false,
      Boolean(next.reminder_enabled),
      Math.max(1, Math.min(168, Math.round(toNumberValue(next.reminder_hours_before, 1) || 1))),
      JSON.stringify(Array.isArray(next.reminder_flow) ? next.reminder_flow : []),
      next.notes == null ? null : String(next.notes),
    ],
  );

  if (Boolean(next.is_active)) {
    await getPool().query(
      `INSERT INTO agendamento2_config (user_id, is_active, send_to_ai, scheduling_tracker_enabled, updated_at)
       VALUES ($1, false, false, false, NOW())
       ON CONFLICT (user_id) DO UPDATE SET
         is_active = false,
         send_to_ai = false,
         scheduling_tracker_enabled = false,
         updated_at = NOW()`,
      [userId],
    );
  }

  return result.rows[0] || next;
}

async function getSchedulingConfigForAgendamento3(userId: string): Promise<Record<string, unknown>> {
  const result = await getPool().query(`SELECT * FROM scheduling_config WHERE user_id = $1 LIMIT 1`, [userId]);
  return result.rows[0] || {};
}

function parseAvailableDays(value: unknown): number[] {
  if (Array.isArray(value)) return value.map((item) => Number(item)).filter((item) => Number.isFinite(item));
  if (typeof value === "string") {
    try {
      const parsed = JSON.parse(value);
      if (Array.isArray(parsed)) return parsed.map((item) => Number(item)).filter((item) => Number.isFinite(item));
    } catch {
      return value.split(",").map((item) => Number(item.trim())).filter((item) => Number.isFinite(item));
    }
  }
  return [1, 2, 3, 4, 5];
}

function isTimeWithinRange(time: string, start: string, end: string): boolean {
  const current = normalizeCalendarTimeValue(time).slice(0, 5);
  const startValue = normalizeCalendarTimeValue(start || "00:00").slice(0, 5);
  const endValue = normalizeCalendarTimeValue(end || "23:59").slice(0, 5);
  return current >= startValue && current < endValue;
}

function doAgendamento3TimeRangesOverlap(startA: string, endA: string, startB: string, endB: string): boolean {
  const aStart = normalizeCalendarTimeValue(startA).slice(0, 5);
  const aEnd = normalizeCalendarTimeValue(endA).slice(0, 5);
  const bStart = normalizeCalendarTimeValue(startB).slice(0, 5);
  const bEnd = normalizeCalendarTimeValue(endB).slice(0, 5);
  return aStart < bEnd && aEnd > bStart;
}

async function checkAgendamento3Availability(input: {
  userId: string;
  date: string;
  time: string;
  durationMinutes: number;
  schedulingConfig: Record<string, unknown>;
  agendamento3Config: Record<string, unknown>;
  trace: Agendamento3TraceStep[];
}): Promise<{ available: boolean; reason?: string; startTime: string; endTime: string; googleChecked: boolean }> {
  const startTime = normalizeCalendarTimeValue(input.time || "09:00").slice(0, 5);
  const endTime = addMinutesToCalendarDateTimeValue(input.date, startTime, input.durationMinutes).slice(11, 16);
  const day = parseCalendarDateTimeWithZone(`${input.date}T12:00:00`, DEFAULT_CALENDAR_TIMEZONE).getUTCDay();
  const availableDays = parseAvailableDays(input.schedulingConfig.available_days);
  if (availableDays.length && !availableDays.includes(day)) {
    input.trace.push({ tool: "business_hours", ok: false, detail: "Dia fora da agenda de atendimento.", data: { day, availableDays } });
    return { available: false, reason: "Este dia esta fora da agenda de atendimento.", startTime, endTime, googleChecked: false };
  }

  const workStart = normalizeCalendarTimeValue(String(input.schedulingConfig.work_start_time || "09:00")).slice(0, 5);
  const workEnd = normalizeCalendarTimeValue(String(input.schedulingConfig.work_end_time || "18:00")).slice(0, 5);
  if (!isTimeWithinRange(startTime, workStart, workEnd) || endTime > workEnd) {
    input.trace.push({ tool: "business_hours", ok: false, detail: "Horário fora do expediente.", data: { workStart, workEnd, startTime, endTime } });
    return { available: false, reason: `esse horário fica fora do expediente (${workStart} às ${workEnd})`, startTime, endTime, googleChecked: false };
  }

  if (input.schedulingConfig.has_break) {
    const breakStart = normalizeCalendarTimeValue(String(input.schedulingConfig.break_start_time || "12:00")).slice(0, 5);
    const breakEnd = normalizeCalendarTimeValue(String(input.schedulingConfig.break_end_time || "13:00")).slice(0, 5);
    if (doAgendamento3TimeRangesOverlap(startTime, endTime, breakStart, breakEnd)) {
      input.trace.push({ tool: "business_hours", ok: false, detail: "Horário cruza intervalo.", data: { breakStart, breakEnd } });
      return { available: false, reason: `esse horário cruza o intervalo (${breakStart} às ${breakEnd})`, startTime, endTime, googleChecked: false };
    }
  }
  input.trace.push({ tool: "business_hours", ok: true, detail: "Horario permitido pela configuracao interna." });

  const conflict = await getPool().query(
    `SELECT id, client_name, start_time, end_time, status
       FROM appointments
      WHERE user_id = $1
        AND appointment_date = $2::date
        AND COALESCE(status, 'pending') IN ('pending', 'confirmed')
        AND start_time < $4::time
        AND end_time > $3::time
      ORDER BY start_time ASC
      LIMIT 1`,
    [input.userId, input.date, startTime, endTime],
  );
  if (conflict.rows[0]) {
    input.trace.push({ tool: "appointments_overlap", ok: false, detail: "Conflito com agendamento interno.", data: { appointmentId: conflict.rows[0].id } });
    return { available: false, reason: "já existe um agendamento nesse intervalo", startTime, endTime, googleChecked: false };
  }
  input.trace.push({ tool: "appointments_overlap", ok: true, detail: "Sem conflito nos agendamentos internos." });

  const maxPerDay = toNumberValue(input.schedulingConfig.max_appointments_per_day, 0);
  if (maxPerDay && maxPerDay > 0) {
    const count = await getPool().query(
      `SELECT COUNT(*)::int AS total
         FROM appointments
        WHERE user_id = $1
          AND appointment_date = $2::date
          AND COALESCE(status, 'pending') IN ('pending', 'confirmed')`,
      [input.userId, input.date],
    );
    const total = Number(count.rows[0]?.total || 0);
    if (total >= maxPerDay) {
      input.trace.push({ tool: "daily_capacity", ok: false, detail: "Limite diario atingido.", data: { total, maxPerDay } });
      return { available: false, reason: "A agenda ja atingiu o limite de atendimentos desse dia.", startTime, endTime, googleChecked: false };
    }
  }

  let googleChecked = false;
  if (input.schedulingConfig.google_calendar_enabled !== false) {
    const googleResult = await checkGoogleCalendarAvailabilityForUser(
      input.userId,
      buildCalendarDateTimeValue(input.date, startTime),
      buildCalendarDateTimeValue(input.date, endTime),
      { failOpen: input.agendamento3Config.require_google_validation === false },
    );
    googleChecked = Boolean(googleResult.checked);
    input.trace.push({
      tool: "google_calendar_freebusy",
      ok: googleResult.available,
      detail: googleResult.available ? "Google Calendar sem conflito." : (googleResult.error || "Google Calendar retornou conflito."),
      data: { conflictEvent: googleResult.conflictEvent, checked: googleResult.checked },
    });
    if (!googleResult.available) {
      const reason = googleResult.checked
        ? "já existe outro compromisso nesse horário"
        : "a agenda Google precisa ser reconectada para confirmar esse horário";
      return { available: false, reason, startTime, endTime, googleChecked };
    }
  }

  return { available: true, startTime, endTime, googleChecked };
}

async function createAgendamento3Appointment(input: {
  userId: string;
  conversationId?: string | null;
  clientName?: string | null;
  clientPhone?: string | null;
  serviceName?: string | null;
  date: string;
  startTime: string;
  endTime: string;
  durationMinutes: number;
  schedulingConfig: Record<string, unknown>;
  agendamento3Config: Record<string, unknown>;
  plan: Agendamento3Plan;
  trace: Agendamento3TraceStep[];
}): Promise<Record<string, unknown>> {
  const status = input.agendamento3Config.auto_confirm === false ? "pending" : "confirmed";
  const clientName = trimForAgenda(input.clientName || input.clientPhone || "Cliente", 120);
  const serviceName = trimForAgenda(input.serviceName || String(input.schedulingConfig.service_name || "Atendimento"), 160);
  const inserted = await getPool().query(
    `INSERT INTO appointments (
       user_id, conversation_id, client_name, client_phone, service_name,
       appointment_date, start_time, end_time, duration_minutes, status,
       location, created_by_ai, ai_conversation_context, internal_notes,
       created_at, updated_at
     ) VALUES ($1, $2, $3, $4, $5, $6::date, $7::time, $8::time, $9, $10, $11, true, $12::jsonb, $13, NOW(), NOW())
     RETURNING *`,
    [
      input.userId,
      input.conversationId || null,
      clientName,
      input.clientPhone || null,
      serviceName,
      input.date,
      input.startTime,
      input.endTime,
      input.durationMinutes,
      status,
      input.schedulingConfig.location || null,
      JSON.stringify({ module: AGENDAMENTO3_AGENTIC_MARKER, plan: input.plan, trace: input.trace.slice(-12) }),
      AGENDAMENTO3_AGENTIC_MARKER,
    ],
  );
  let appointment = inserted.rows[0];
  input.trace.push({ tool: "appointments_insert", ok: true, detail: "Agendamento salvo no banco.", data: { appointmentId: appointment.id } });

  if (input.schedulingConfig.google_calendar_enabled !== false) {
    const sync = await syncAppointmentToGoogleCalendar(input.userId, {
      id: appointment.id,
      clientName,
      clientPhone: input.clientPhone || null,
      serviceName,
      appointmentDate: input.date,
      appointmentTime: input.startTime,
      durationMinutes: input.durationMinutes,
      location: input.schedulingConfig.location || null,
      notes: "Criado pelo Agendamento 3.0.",
      googleEventId: appointment.google_event_id || null,
    }, input.durationMinutes);
    if (sync.success) {
      const updated = await getPool().query(
        `UPDATE appointments
            SET google_event_id = $2,
                google_calendar_synced = true,
                updated_at = NOW()
          WHERE id = $1
          RETURNING *`,
        [appointment.id, sync.eventId || appointment.google_event_id || null],
      );
      appointment = updated.rows[0] || appointment;
    }
    input.trace.push({ tool: "google_calendar_sync", ok: sync.success, detail: sync.success ? "Evento sincronizado no Google." : sync.error || "Falha ao sincronizar Google.", data: { eventId: sync.eventId } });
  }

  return appointment;
}

async function cancelAgendamento3Appointment(input: {
  userId: string;
  conversationId?: string | null;
  date?: string | null;
  time?: string | null;
  trace: Agendamento3TraceStep[];
}): Promise<Record<string, unknown> | null> {
  const params: unknown[] = [input.userId];
  const filters = [`user_id = $1`, `COALESCE(status, 'pending') IN ('pending', 'confirmed')`];
  if (input.conversationId) {
    params.push(input.conversationId);
    filters.push(`conversation_id = $${params.length}`);
  }
  if (input.date) {
    params.push(input.date);
    filters.push(`appointment_date = $${params.length}::date`);
  }
  if (input.time) {
    params.push(normalizeCalendarTimeValue(input.time || "09:00").slice(0, 5));
    filters.push(`start_time = $${params.length}::time`);
  }
  const found = await getPool().query(
    `SELECT * FROM appointments WHERE ${filters.join(" AND ")} ORDER BY appointment_date DESC, start_time DESC LIMIT 1`,
    params,
  );
  const appointment = found.rows[0];
  if (!appointment) {
    input.trace.push({ tool: "appointments_cancel", ok: false, detail: "Nenhum agendamento encontrado para cancelar." });
    return null;
  }
  if (appointment.google_event_id) {
    await removeAppointmentFromGoogleCalendar(input.userId, appointment.google_event_id).catch((error: any) => {
      input.trace.push({ tool: "google_calendar_remove", ok: false, detail: error?.message || String(error) });
    });
  }
  const updated = await getPool().query(
    `UPDATE appointments
        SET status = 'cancelled',
            google_calendar_synced = false,
            updated_at = NOW()
      WHERE id = $1
      RETURNING *`,
    [appointment.id],
  );
  input.trace.push({ tool: "appointments_cancel", ok: true, detail: "Agendamento cancelado.", data: { appointmentId: appointment.id } });
  return updated.rows[0] || appointment;
}

function formatAgendamento3DateTime(date: string, time: string): string {
  const [year, month, day] = date.split("-");
  return `${day}/${month}/${year} às ${time}`;
}

function formatAgendamento3UnavailableResponse(reason?: string | null): string {
  const cleanReason = String(reason || "conflito na agenda")
    .trim()
    .replace(/[.\s]+$/g, "");
  return `Esse horário não está disponível: ${cleanReason}. Posso verificar outro horário.`;
}

async function runAgendamento3AgentForUser(input: {
  userId: string;
  message: string;
  history?: Array<{ role?: string; content?: string }>;
  contactName?: string | null;
  contactPhone?: string | null;
  conversationId?: string | null;
  commit?: boolean;
}): Promise<Agendamento3AgentResult | null> {
  const trace: Agendamento3TraceStep[] = [];
  const config = await getAgendamento3ConfigForUser(input.userId);
  if (!config.is_active || config.agentic_mode_enabled === false) return null;
  if (!hasAgendamento3SchedulingSignal(input.message)) return null;

  const plan = await parseAgendamento3PlanWithLlm({
    userId: input.userId,
    message: input.message,
    history: input.history,
    contactName: input.contactName,
    contactPhone: input.contactPhone,
    trace,
  });

  if (plan.intent === "unknown") return null;
  if (plan.intent === "cancel") {
    if (!input.commit) {
      return {
        handled: true,
        response: "Consigo cancelar. Para executar de verdade, confirme qual agendamento devo cancelar com data e horario.",
        plan,
        trace,
        dryRun: true,
      };
    }
    const cancelled = await cancelAgendamento3Appointment({
      userId: input.userId,
      conversationId: input.conversationId,
      date: plan.date,
      time: plan.time,
      trace,
    });
    return {
      handled: true,
      response: cancelled ? "Agendamento cancelado e agenda sincronizada." : "Nao encontrei um agendamento correspondente para cancelar. Me envie a data e o horario exatos.",
      plan,
      trace,
      appointment: cancelled,
    };
  }

  if (plan.intent === "reschedule") {
    return {
      handled: true,
      response: "Consigo remarcar. Me envie o novo dia e horario desejados para eu validar na agenda antes de alterar.",
      plan,
      trace,
    };
  }

  if (!plan.date || !plan.time) {
    const missingText = !plan.date && !plan.time ? "do dia e do horário" : !plan.date ? "do dia" : "do horário";
    return {
      handled: true,
      response: `Para consultar a agenda corretamente, preciso ${missingText}. Qual prefere?`,
      plan,
      trace,
    };
  }

  const schedulingConfig = await getSchedulingConfigForAgendamento3(input.userId);
  trace.push({ tool: "scheduling_config", ok: !!Object.keys(schedulingConfig).length, detail: Object.keys(schedulingConfig).length ? "Configuracao de agenda carregada." : "Sem configuracao de agenda; usando padroes." });
  const durationMinutes = plan.durationMinutes || toNumberValue(schedulingConfig.service_duration_minutes, 0) || toNumberValue(schedulingConfig.slot_duration, 0) || 60;
  const availability = await checkAgendamento3Availability({
    userId: input.userId,
    date: plan.date,
    time: plan.time,
    durationMinutes,
    schedulingConfig,
    agendamento3Config: config,
    trace,
  });

  if (!availability.available) {
    return {
      handled: true,
      response: formatAgendamento3UnavailableResponse(availability.reason),
      plan,
      trace,
      available: false,
    };
  }

  if (plan.intent === "check_availability" || !input.commit) {
    return {
      handled: true,
      response: `Sim, ${formatAgendamento3DateTime(plan.date, availability.startTime)} está disponível. Posso confirmar esse agendamento para você.`,
      plan,
      trace,
      available: true,
      dryRun: !input.commit,
    };
  }

  const appointment = await createAgendamento3Appointment({
    userId: input.userId,
    conversationId: input.conversationId,
    clientName: plan.clientName,
    clientPhone: plan.clientPhone,
    serviceName: plan.serviceName,
    date: plan.date,
    startTime: availability.startTime,
    endTime: availability.endTime,
    durationMinutes,
    schedulingConfig,
    agendamento3Config: config,
    plan,
    trace,
  });

  return {
    handled: true,
    response: `Agendamento confirmado para ${formatAgendamento3DateTime(plan.date, availability.startTime)}.`,
    plan,
    trace,
    available: true,
    appointment,
  };
}

async function handleAgendamento3Config(req: any, res: any) {
  const user = await requireJwtUser(req, res);
  if (!user) return;
  try {
    if (req.method === "GET") {
      const [config, agendamento2] = await Promise.all([
        getAgendamento3ConfigForUser(user.id),
        getPool().query(`SELECT is_active, send_to_ai, scheduling_tracker_enabled, updated_at FROM agendamento2_config WHERE user_id = $1 LIMIT 1`, [user.id]),
      ]);
      return sendJson(res, 200, { config, agendamento2: agendamento2.rows[0] || null });
    }
    if (req.method === "PUT") {
      const body = await readJsonBody(req);
      const updates: Record<string, unknown> = {};
      for (const key of ["is_active", "display_name", "agentic_mode_enabled", "require_google_validation", "auto_confirm", "reminder_enabled", "reminder_hours_before", "reminder_flow", "notes"]) {
        if (Object.prototype.hasOwnProperty.call(body, key)) updates[key] = body[key];
      }
      const config = await upsertAgendamento3ConfigForUser(user.id, updates);
      return sendJson(res, 200, { success: true, config, agendamento2_disabled: Boolean(config.is_active) });
    }
    return sendJson(res, 405, { message: "Method not allowed" });
  } catch (error: any) {
    console.error("[vercel-http] agendamento3 config failed:", error);
    return sendJson(res, 500, { message: error?.message || "Failed to process Agendamento 3.0" });
  }
}

async function handleAgendamento3Status(req: any, res: any) {
  const user = await requireJwtUser(req, res);
  if (!user) return;
  try {
    const [config, schedulingConfig, googleStatus, appointments] = await Promise.all([
      getAgendamento3ConfigForUser(user.id),
      getSchedulingConfigForAgendamento3(user.id),
      getGoogleCalendarStatusForUser(user.id),
      getPool().query(
        `SELECT id, client_name, client_phone, service_name, appointment_date, start_time, end_time, status, google_event_id, google_calendar_synced
           FROM appointments
          WHERE user_id = $1
            AND appointment_date >= CURRENT_DATE
            AND COALESCE(status, 'pending') IN ('pending', 'confirmed')
          ORDER BY appointment_date ASC, start_time ASC
          LIMIT 200`,
        [user.id],
      ),
    ]);
    return sendJson(res, 200, {
      config,
      schedulingConfig,
      google: googleStatus,
      appointments: appointments.rows,
    });
  } catch (error: any) {
    console.error("[vercel-http] agendamento3 status failed:", error);
    return sendJson(res, 500, { message: error?.message || "Failed to load Agendamento 3.0 status" });
  }
}

async function handleAgendamento3Agent(req: any, res: any) {
  const user = await requireJwtUser(req, res);
  if (!user) return;
  if (req.method !== "POST") return sendJson(res, 405, { message: "Method not allowed" });
  try {
    const body = await readJsonBody(req);
    const message = typeof body.message === "string" ? body.message : "";
    if (!message.trim()) return sendJson(res, 400, { message: "Mensagem obrigatoria" });
    const result = await runAgendamento3AgentForUser({
      userId: user.id,
      message,
      history: Array.isArray(body.history) ? body.history : [],
      contactName: typeof body.contactName === "string" ? body.contactName : null,
      contactPhone: typeof body.contactPhone === "string" ? body.contactPhone : null,
      conversationId: typeof body.conversationId === "string" ? body.conversationId : null,
      commit: body.commit === true,
    });
    if (!result) return sendJson(res, 200, { handled: false, response: "Nao identifiquei uma acao de agenda nessa mensagem." });
    return sendJson(res, 200, result);
  } catch (error: any) {
    console.error("[vercel-http] agendamento3 agent failed:", error);
    return sendJson(res, 500, { message: error?.message || "Failed to run Agendamento 3.0 agent" });
  }
}

async function buildWebOnlyAgendamento2PromptBlock(userId: string) {
  const configResult = await getPool().query(
    `
      SELECT is_active, send_to_ai, display_name, agenda_prompt, agenda_hours_context, scheduling_tracker_enabled
      FROM agendamento2_config
      WHERE user_id = $1
      LIMIT 1
    `,
    [userId],
  );
  const config = configResult.rows[0];
  if (!config || config.send_to_ai === false || !(config.is_active === true || config.scheduling_tracker_enabled === true)) {
    return "";
  }

  const entriesResult = await getPool().query(
    `
      SELECT contact_name, contact_number, agreed_schedule, scheduled_date, scheduled_time, summary
      FROM agendamento2_insights
      WHERE user_id = $1
        AND status = 'scheduled'
        AND scheduled_date IS NOT NULL
        AND to_date(scheduled_date, 'YYYY-MM-DD') BETWEEN (CURRENT_TIMESTAMP AT TIME ZONE 'America/Sao_Paulo')::date
          AND ((CURRENT_TIMESTAMP AT TIME ZONE 'America/Sao_Paulo')::date + INTERVAL '30 days')::date
      ORDER BY scheduled_date ASC NULLS LAST, scheduled_time ASC NULLS LAST, updated_at DESC
      LIMIT 60
    `,
    [userId],
  );
  const internalAppointments = await getPool().query(
    `
      SELECT client_name, client_phone, service_name, appointment_date, start_time, end_time, status, google_event_id
      FROM appointments
      WHERE user_id = $1
        AND appointment_date BETWEEN (CURRENT_TIMESTAMP AT TIME ZONE 'America/Sao_Paulo')::date
          AND ((CURRENT_TIMESTAMP AT TIME ZONE 'America/Sao_Paulo')::date + INTERVAL '14 days')::date
        AND status IN ('pending', 'confirmed')
      ORDER BY appointment_date ASC, start_time ASC
      LIMIT 24
    `,
    [userId],
  );
  const internalEventIds = new Set(internalAppointments.rows.map((row) => String(row.google_event_id || "").trim()).filter(Boolean));
  const syncedSections: string[] = [];
  if (internalAppointments.rows.length > 0) {
    syncedSections.push(`AGENDA INTERNA ATUAL:\n${internalAppointments.rows.map((row, index) => {
      const start = `${String(row.appointment_date).slice(0, 10)} ${String(row.start_time).slice(0, 5)}`;
      const end = row.end_time ? `-${String(row.end_time).slice(0, 5)}` : "";
      return `${index + 1}. interno | ${start}${end} | ${row.client_name || row.client_phone || "Cliente"} | ${trimForAgenda(row.service_name || "agendamento", 80)}`;
    }).join("\n")}`);
  }
  if ((await getGoogleCalendarTokenRow(userId))) {
    const nowParts = readCalendarTimeZoneParts(new Date(), DEFAULT_CALENDAR_TIMEZONE);
    const start = `${String(nowParts.year).padStart(4, "0")}-${String(nowParts.month).padStart(2, "0")}-${String(nowParts.day).padStart(2, "0")}T00:00:00`;
    const endDate = new Date();
    endDate.setDate(endDate.getDate() + 14);
    const end = `${formatBrazilDateKey(endDate)}T23:59:59`;
    const busy = await listGoogleCalendarBusyWindowsForUser(userId, start, end).catch((error) => ({ success: false, error: error?.message, windows: [] as any[] }));
    const windows = ((busy as any).windows || []).filter((window: any) => !window.eventId || !internalEventIds.has(String(window.eventId))).slice(0, 24);
    if (windows.length > 0) {
      syncedSections.push(`EVENTOS E BLOQUEIOS EXTERNOS (GOOGLE DIRETO):\n${windows.map((window: any, index: number) => {
        const startDate = new Date(window.startDateTime);
        const endDateValue = new Date(window.endDateTime);
        const startLabel = Number.isNaN(startDate.getTime()) ? String(window.startDateTime) : startDate.toLocaleString("pt-BR", { timeZone: DEFAULT_CALENDAR_TIMEZONE, weekday: "short", day: "2-digit", month: "2-digit", hour: "2-digit", minute: "2-digit" });
        const endLabel = Number.isNaN(endDateValue.getTime()) ? String(window.endDateTime) : endDateValue.toLocaleString("pt-BR", { timeZone: DEFAULT_CALENDAR_TIMEZONE, hour: "2-digit", minute: "2-digit" });
        return `${index + 1}. google-direto | ${startLabel}-${endLabel} | ${trimForAgenda(window.summary || "bloqueio externo", 90)}`;
      }).join("\n")}`);
    } else {
      syncedSections.push("EVENTOS E BLOQUEIOS EXTERNOS (GOOGLE DIRETO):\nSem bloqueios extras no periodo.");
    }
  }
  const entriesText = entriesResult.rows.length > 0
    ? entriesResult.rows.map((entry, index) => {
      const leadName = String(entry.contact_name || entry.contact_number || "Cliente").trim();
      const phone = String(entry.contact_number || "").trim();
      return [
        `${index + 1}. ${leadName}`,
        phone && !phone.startsWith("sim-") ? `telefone: ${phone}` : "",
        entry.agreed_schedule ? `combinado: ${entry.agreed_schedule}` : "",
        entry.scheduled_date ? `data: ${entry.scheduled_date}` : "",
        entry.scheduled_time ? `horario: ${entry.scheduled_time}` : "",
        entry.summary ? `resumo: ${entry.summary}` : "",
      ].filter(Boolean).join(" | ");
    }).join("\n")
    : "Nenhum agendamento confirmado foi registrado ainda.";

  return `
------------------------------------------------------------
${String(config.display_name || "Agendamento 2.0").toUpperCase()} - CONTEXTO DE AGENDA VIVA
------------------------------------------------------------

Este modulo nao cria logica operacional fora do prompt.
Quem continua mandando na conversa e o prompt principal do Meu Agente IA.
Use este bloco apenas como contexto adicional para interpretar agenda, horarios, datas e combinados ja fechados.
Nao exponha ao cliente que existe agenda interna, memoria paralela ou modulo auxiliar.
Se houver qualquer conflito entre este bloco e o prompt principal do negocio, respeite o prompt principal do negocio.

PROMPT DE AGENDA DO CLIENTE:
${String(config.agenda_prompt || "").trim() || "Sem prompt adicional configurado."}

HORARIO ATUAL DE BRASILIA:
${formatBrazilNowLabel()}

HORARIOS DE FUNCIONAMENTO DO NEGOCIO:
${String(config.agenda_hours_context || "").trim() || "Sem horarios informados."}

AGENDA SINCRONIZADA DO NEGOCIO:
${syncedSections.join("\n\n") || "Sem agenda sincronizada adicional no momento."}

AGENDA VIVA REGISTRADA EM PARALELO:
${entriesText}

REGRAS DE USO:
- Interprete a agenda viva com bom senso e contexto.
- Considere sempre a hora atual do Brasil antes de sugerir datas e horarios.
- Nao trate horario passado como disponivel para hoje.
- Use os combinados anteriores como memoria operacional para evitar contradicoes.

------------------------------------------------------------
`.trim();
}

async function handleProductMediaUpload(req: any, res: any, productId: string) {
  const user = await requireJwtUser(req, res);
  if (!user) return;

  try {
    const product = await getPool().query("SELECT id FROM products WHERE user_id = $1 AND id = $2 LIMIT 1", [user.id, productId]);
    if (!product.rows[0]) return sendJson(res, 404, { message: "Product not found" });

    const formData = await readMultipartFormData(req);
    const files = [...formData.getAll("files"), ...formData.getAll("file")].filter(Boolean) as any[];
    if (!files.length) return sendJson(res, 400, { message: "No files uploaded" });
    if (files.some((file) => !String(file?.type || "").startsWith("image/"))) {
      return sendJson(res, 400, { message: "Only image files are allowed for product gallery" });
    }

    const [orderResult, variationResult] = await Promise.all([
      getPool().query("SELECT COALESCE(MAX(display_order), -1)::int AS value FROM product_media WHERE product_id = $1 AND user_id = $2", [productId, user.id]),
      getPool().query("SELECT COALESCE(MAX(variation_code), 0)::int AS value FROM product_media WHERE user_id = $1", [user.id]),
    ]);
    let nextOrder = Number(orderResult.rows[0]?.value || -1) + 1;
    let nextVariationCode = Number(variationResult.rows[0]?.value || 0) + 1;
    const supabase = getSupabaseAdminClient();
    const inserted: any[] = [];

    for (const [index, file] of files.entries()) {
      const safeName = String(file?.name || `image-${index + 1}.png`).replace(/[^a-zA-Z0-9.\-_]/g, "_");
      const storagePath = `products/${user.id}/${productId}/${Date.now()}_${index}_${safeName}`;
      const buffer = Buffer.from(await file.arrayBuffer());
      let upload = await supabase.storage.from("product-media").upload(storagePath, buffer, {
        contentType: String(file.type || "application/octet-stream"),
        upsert: false,
      });
      if (upload.error?.message?.includes("Bucket not found")) {
        const createBucket = await supabase.storage.createBucket("product-media", {
          public: true,
          fileSizeLimit: 52428800,
        });
        if (createBucket.error && !createBucket.error.message?.includes("already exists")) {
          throw new Error(createBucket.error.message);
        }
        upload = await supabase.storage.from("product-media").upload(storagePath, buffer, {
          contentType: String(file.type || "application/octet-stream"),
          upsert: false,
        });
      }
      if (upload.error) throw new Error(upload.error.message);
      const { data: publicUrl } = supabase.storage.from("product-media").getPublicUrl(storagePath);
      const row = await getPool().query(
        `
          INSERT INTO product_media (
            product_id, user_id, storage_url, storage_path, file_name, file_size,
            mime_type, variation_code, variation_is_active, display_order
          )
          VALUES ($1,$2,$3,$4,$5,$6,$7,$8,true,$9)
          RETURNING *
        `,
        [
          productId,
          user.id,
          publicUrl.publicUrl,
          storagePath,
          safeName,
          Number(file.size || buffer.length),
          String(file.type || "application/octet-stream"),
          nextVariationCode++,
          nextOrder++,
        ],
      );
      inserted.push(toCamelRecord(row.rows[0]));
    }

    return sendJson(res, 200, { items: inserted });
  } catch (error) {
    console.error("[vercel-http] product media upload failed:", error);
    return sendJson(res, 500, { message: "Failed to upload product media" });
  }
}

async function handleProductMediaReorder(req: any, res: any, productId: string) {
  const user = await requireJwtUser(req, res);
  if (!user) return;

  try {
    const body = await readJsonBody(req);
    const orderedIds = Array.isArray(body.orderedIds) ? body.orderedIds.map((id: unknown) => String(id)) : [];
    for (const [index, mediaId] of orderedIds.entries()) {
      await getPool().query(
        "UPDATE product_media SET display_order = $1, updated_at = NOW() WHERE id = $2 AND product_id = $3 AND user_id = $4",
        [index, mediaId, productId, user.id],
      );
    }
    return sendJson(res, 200, { success: true });
  } catch (error) {
    console.error("[vercel-http] product media reorder failed:", error);
    return sendJson(res, 500, { message: "Failed to reorder product media" });
  }
}

async function handleProductMediaById(req: any, res: any, productId: string, mediaId: string) {
  const user = await requireJwtUser(req, res);
  if (!user) return;

  try {
    if (req.method === "DELETE") {
      const deleted = await getPool().query(
        "DELETE FROM product_media WHERE id = $1 AND product_id = $2 AND user_id = $3 RETURNING storage_path",
        [mediaId, productId, user.id],
      );
      const storagePath = deleted.rows[0]?.storage_path;
      if (storagePath) {
        await getSupabaseAdminClient().storage.from("product-media").remove([storagePath]);
      }
      return sendJson(res, 200, { success: true, deleted: Boolean(deleted.rows[0]) });
    }

    const body = await readJsonBody(req);
    const result = await getPool().query(
      `
        UPDATE product_media
        SET caption = $4,
            variation_name = $5,
            variation_price = $6,
            variation_stock = $7,
            variation_is_active = $8,
            updated_at = NOW()
        WHERE id = $1 AND product_id = $2 AND user_id = $3
        RETURNING *
      `,
      [
        mediaId,
        productId,
        user.id,
        body.caption || null,
        body.variationName || body.variation_name || null,
        body.variationPrice === "" || body.variationPrice == null ? null : String(body.variationPrice),
        body.variationStock === "" || body.variationStock == null ? null : Number(body.variationStock),
        body.variationIsActive !== false && body.variation_is_active !== false,
      ],
    );
    return result.rows[0]
      ? sendJson(res, 200, toCamelRecord(result.rows[0]))
      : sendJson(res, 404, { message: "Product media not found" });
  } catch (error) {
    console.error("[vercel-http] product media update failed:", error);
    return sendJson(res, 500, { message: "Failed to update product media" });
  }
}

async function handleNotificationConfig(req: any, res: any) {
  const user = await requireJwtUser(req, res);
  if (!user) return;

  try {
    if (req.method === "POST") {
      const body = await readJsonBody(req);
      const notificationPhoneNumber = serializeNotificationPhoneNumbers(
        body.notificationPhoneNumbers ?? body.notificationPhoneNumber,
      );
      await getPool().query(
        `
          INSERT INTO business_agent_configs (
            user_id, agent_name, agent_role, company_name,
            notification_phone_number, notification_trigger,
            notification_enabled, notification_mode, notification_manual_keywords,
            updated_at
          )
          VALUES ($1,'Assistente','Assistente Virtual','Minha Empresa',$2,$3,$4,$5,$6,NOW())
          ON CONFLICT (user_id) DO UPDATE SET
            notification_phone_number = EXCLUDED.notification_phone_number,
            notification_trigger = EXCLUDED.notification_trigger,
            notification_enabled = EXCLUDED.notification_enabled,
            notification_mode = EXCLUDED.notification_mode,
            notification_manual_keywords = EXCLUDED.notification_manual_keywords,
            updated_at = NOW()
        `,
        [
          user.id,
          notificationPhoneNumber,
          body.notificationTrigger || null,
          body.notificationEnabled === true,
          body.notificationMode || "ai",
          body.notificationManualKeywords || null,
        ],
      );
    }
    const result = await getPool().query("SELECT * FROM business_agent_configs WHERE user_id = $1 LIMIT 1", [user.id]);
    const row = result.rows[0];
    return sendJson(res, 200, mapWebOnlyNotificationConfig(row));
  } catch (error) {
    console.error("[vercel-http] notification config failed:", error);
    return sendJson(res, 500, { message: "Failed to process notification config" });
  }
}

async function handleFunnelList(req: any, res: any) {
  const user = await requireJwtUser(req, res);
  if (!user) return;

  try {
    const funnels = await getPool().query(
      `
        SELECT f.*,
          COALESCE(json_agg(json_build_object(
            'id', s.id, 'funnelId', s.funnel_id, 'name', s.name,
            'description', s.description, 'color', s.color, 'bgColor', s.bg_color,
            'borderColor', s.border_color, 'iconColor', s.icon_color,
            'position', s.position
          ) ORDER BY s.position ASC) FILTER (WHERE s.id IS NOT NULL), '[]'::json) AS stages
        FROM sales_funnels f
        LEFT JOIN funnel_stages s ON s.funnel_id = f.id
        WHERE f.user_id = $1
        GROUP BY f.id
        ORDER BY f.created_at DESC
      `,
      [user.id],
    );
    return sendJson(res, 200, funnels.rows.map((row) => ({
      id: row.id,
      userId: row.user_id,
      name: row.name,
      product: row.product,
      manager: row.manager,
      isActive: row.is_active !== false,
      stages: row.stages || [],
      createdAt: row.created_at,
      updatedAt: row.updated_at,
    })));
  } catch (error) {
    console.error("[vercel-http] funnels failed:", error);
    return sendJson(res, 500, { message: "Failed to fetch funnels" });
  }
}

