  "das",
  "e",
  "em",
  "esse",
  "essa",
  "esta",
  "este",
  "estou",
  "fica",
  "frente",
  "informacao",
  "informacoes",
  "imovel",
  "imoveis",
  "lhe",
  "me",
  "mais",
  "nome",
  "na",
