async function handleKanbanBoards(req: any, res: any) {
  const user = await requireJwtUser(req, res);
  if (!user) return;

  try {
    const result = await getPool().query(
      `
        SELECT
          kb.*,
          COALESCE(
            json_agg(kbm.member_id) FILTER (WHERE kbm.member_id IS NOT NULL),
            '[]'::json
          ) AS "memberIds"
        FROM kanban_boards kb
        LEFT JOIN kanban_board_members kbm
          ON kbm.board_id = kb.id
        WHERE kb.owner_id = $1
          AND kb.is_active = true
        GROUP BY kb.id
        ORDER BY kb.is_default DESC, kb.created_at ASC
      `,
      [user.id],
    );
    return sendJson(
      res,
      200,
      result.rows.map((row) => ({
        ...row,
        memberIds: Array.isArray(row.memberIds) ? row.memberIds : [],
      })),
    );
  } catch (error) {
    console.error("[vercel-http] kanban boards failed:", error);
    return sendJson(res, 500, { message: "Failed to fetch kanban boards" });
  }
}

async function saveKanbanBoardMembers(ownerId: string, boardId: string, memberIds: string[]) {
  await getPool().query("DELETE FROM kanban_board_members WHERE board_id = $1", [boardId]);
  const uniqueMemberIds = [...new Set(memberIds.map((id) => String(id || "").trim()).filter(Boolean))];
  for (const memberId of uniqueMemberIds) {
    await getPool().query(
      `
        INSERT INTO kanban_board_members (board_id, member_id)
        SELECT $1, tm.id
        FROM team_members tm
        WHERE tm.id = $2
          AND tm.owner_id = $3
        ON CONFLICT DO NOTHING
      `,
      [boardId, memberId, ownerId],
    );
  }
}

async function handleCreateKanbanBoard(req: any, res: any) {
  const user = await requireJwtUser(req, res);
  if (!user) return;

  try {
    const body = await readJsonBody(req);
    const name = String(body.name || "").trim();
    const description = String(body.description || "").trim();
    const memberIds = Array.isArray(body.memberIds)
      ? body.memberIds.map((value: unknown) => String(value || "").trim()).filter(Boolean)
      : [];

    if (!name) {
      return sendJson(res, 400, { message: "Nome do kanban e obrigatorio." });
    }

    const result = await getPool().query(
      `
        INSERT INTO kanban_boards (owner_id, name, description, kind, is_default, is_active)
        VALUES ($1, $2, $3, 'custom', false, true)
        RETURNING *
      `,
      [user.id, name, description || null],
    );
    const board = result.rows[0];
    await saveKanbanBoardMembers(user.id, board.id, memberIds);
    return sendJson(res, 200, { ...board, memberIds });
  } catch (error: any) {
    console.error("[vercel-http] create kanban board failed:", error);
    return sendJson(res, 500, { message: error?.message || "Failed to create kanban board" });
  }
}

async function handleUpdateKanbanBoard(req: any, res: any) {
  const user = await requireJwtUser(req, res);
  if (!user) return;

  try {
    const boardId = String(req.params?.boardId || "").trim();
    const body = await readJsonBody(req);
    const name = String(body.name || "").trim();
    const description = String(body.description || "").trim();
    const memberIds = Array.isArray(body.memberIds)
      ? body.memberIds.map((value: unknown) => String(value || "").trim()).filter(Boolean)
      : [];

    const boardCheck = await getPool().query(
      "SELECT id, kind FROM kanban_boards WHERE id = $1 AND owner_id = $2 LIMIT 1",
      [boardId, user.id],
    );
    if (!boardCheck.rows[0]) {
      return sendJson(res, 404, { message: "Kanban nao encontrado." });
    }

    if (name) {
      await getPool().query(
        `
          UPDATE kanban_boards
          SET name = $3,
              description = $4,
              updated_at = NOW()
          WHERE id = $1
            AND owner_id = $2
        `,
        [boardId, user.id, name, description || null],
      );
    }

    if (boardCheck.rows[0].kind !== "personal") {
      await saveKanbanBoardMembers(user.id, boardId, memberIds);
    }

    const result = await getPool().query(
      "SELECT * FROM kanban_boards WHERE id = $1 AND owner_id = $2 LIMIT 1",
      [boardId, user.id],
    );
    return sendJson(res, 200, { ...result.rows[0], memberIds });
  } catch (error: any) {
    console.error("[vercel-http] update kanban board failed:", error);
    return sendJson(res, 500, { message: error?.message || "Failed to update kanban board" });
  }
}

