async function handleMoveKanbanConversation(req: any, res: any) {
  const user = await requireUserOrTeamMember(req, res);
  if (!user) return;
  if (!ensureTeamMemberPermission(user, res, "canMoveKanban", "Permissao insuficiente para mover no Kanban.")) return;

  try {
    const conversationId = String(req.params?.conversationId || "").trim();
    const body = await readJsonBody(req);
    const stageId = String(body.stageId || "").trim() || null;
    const requestedBoardId = String(body.boardId || req.query?.boardId || "").trim();
    const boardId = requestedBoardId || (await getDefaultKanbanBoardId(user.id));

    if (!boardId) {
      return sendJson(res, 404, { message: "Kanban nao encontrado." });
    }

    const conversation = await getConversationForActor(user, conversationId);
    if (!conversation) {
      return sendJson(res, 404, { message: "Conversation not found" });
    }

    if (stageId) {
      const stageCheck = await getPool().query(
        "SELECT id FROM kanban_stages WHERE id = $1 AND user_id = $2 AND board_id = $3 LIMIT 1",
        [stageId, user.id, boardId],
      );
      if (!stageCheck.rows[0]) {
        return sendJson(res, 400, { message: "Etapa invalida para este kanban." });
      }
    }

    const result = await getPool().query(
      `
        UPDATE conversations
        SET kanban_board_id = $2,
            kanban_stage_id = $3,
            updated_at = NOW()
        WHERE id = $1
        RETURNING *
      `,
      [conversationId, boardId, stageId],
    );

    return sendJson(res, 200, result.rows[0] || { id: conversationId, kanban_board_id: boardId, kanban_stage_id: stageId });
  } catch (error: any) {
    console.error("[vercel-http] move kanban conversation failed:", error);
    return sendJson(res, 500, { message: error?.message || "Failed to move conversation" });
  }
}

async function handleUpdateKanbanConversation(req: any, res: any) {
  const user = await requireUserOrTeamMember(req, res);
  if (!user) return;
  if (!ensureTeamMemberPermission(user, res, "canMoveKanban", "Permissao insuficiente para editar no Kanban.")) return;

  try {
    const conversationId = String(req.params?.conversationId || "").trim();
    const body = await readJsonBody(req);
    const conversation = await getConversationForActor(user, conversationId);
    if (!conversation) {
      return sendJson(res, 404, { message: "Conversation not found" });
    }

    const updates: string[] = ["updated_at = NOW()"];
    const params: unknown[] = [conversationId];

    if (Object.prototype.hasOwnProperty.call(body, "kanban_notes")) {
      params.push(body.kanban_notes == null ? null : String(body.kanban_notes));
      updates.push(`kanban_notes = $${params.length}`);
    }
    if (Object.prototype.hasOwnProperty.call(body, "priority")) {
      params.push(String(body.priority || "normal"));
      updates.push(`priority = $${params.length}`);
    }
    if (Object.prototype.hasOwnProperty.call(body, "contact_name")) {
      if (!ensureTeamMemberPermission(user, res, "canEditContacts", "Permissao insuficiente para editar contatos.")) return;
      params.push(body.contact_name == null ? null : String(body.contact_name));
      updates.push(`contact_name = $${params.length}`);
    }

    const result = await getPool().query(
      `UPDATE conversations SET ${updates.join(", ")} WHERE id = $1 RETURNING *`,
      params,
    );
    return sendJson(res, 200, result.rows[0] || { id: conversationId });
  } catch (error: any) {
    console.error("[vercel-http] update kanban conversation failed:", error);
    return sendJson(res, 500, { message: error?.message || "Failed to update conversation" });
  }
}

async function handleCreateKanbanStage(req: any, res: any) {
  const user = await requireJwtUser(req, res);
  if (!user) return;

  try {
    const body = await readJsonBody(req);
    const name = String(body.name || "").trim();
    const boardId = String(body.boardId || "").trim() || (await getDefaultKanbanBoardId(user.id));
    if (!name || !boardId) {
      return sendJson(res, 400, { message: "Nome e kanban sao obrigatorios." });
    }

    const positionResult = await getPool().query(
      "SELECT COALESCE(MAX(position), -1) + 1 AS position FROM kanban_stages WHERE user_id = $1 AND board_id = $2",
      [user.id, boardId],
    );
    const position = Number(positionResult.rows[0]?.position || 0);
    const result = await getPool().query(
      `
        INSERT INTO kanban_stages (user_id, board_id, name, description, color, position)
        VALUES ($1, $2, $3, $4, $5, $6)
        RETURNING *, position AS "order"
      `,
      [
        user.id,
        boardId,
        name,
        String(body.description || "").trim() || null,
        String(body.color || "#0f766e").trim(),
        position,
      ],
    );
    return sendJson(res, 200, result.rows[0]);
  } catch (error: any) {
    console.error("[vercel-http] create kanban stage failed:", error);
    return sendJson(res, 500, { message: error?.message || "Failed to create kanban stage" });
  }
}

async function handleUpdateKanbanStage(req: any, res: any) {
  const user = await requireJwtUser(req, res);
  if (!user) return;

  try {
    const stageId = String(req.params?.stageId || "").trim();
    const body = await readJsonBody(req);
    const updates: string[] = ["updated_at = NOW()"];
    const params: unknown[] = [stageId, user.id];

    for (const [key, column] of [
      ["name", "name"],
      ["description", "description"],
      ["color", "color"],
      ["position", "position"],
      ["order", "position"],
    ] as const) {
      if (Object.prototype.hasOwnProperty.call(body, key)) {
        params.push(key === "position" || key === "order" ? Number(body[key]) : String(body[key] || ""));
        updates.push(`${column} = $${params.length}`);
      }
    }

    const result = await getPool().query(
      `UPDATE kanban_stages SET ${updates.join(", ")} WHERE id = $1 AND user_id = $2 RETURNING *, position AS "order"`,
      params,
    );
    if (!result.rows[0]) {
      return sendJson(res, 404, { message: "Etapa nao encontrada." });
    }
    return sendJson(res, 200, result.rows[0]);
  } catch (error: any) {
    console.error("[vercel-http] update kanban stage failed:", error);
    return sendJson(res, 500, { message: error?.message || "Failed to update kanban stage" });
  }
}

async function handleDeleteKanbanStage(req: any, res: any) {
  const user = await requireJwtUser(req, res);
  if (!user) return;

  try {
    const stageId = String(req.params?.stageId || "").trim();
    await getPool().query(
      "UPDATE conversations SET kanban_stage_id = NULL, updated_at = NOW() WHERE kanban_stage_id = $1 AND connection_id IN (SELECT id FROM whatsapp_connections WHERE user_id = $2)",
      [stageId, user.id],
    );
    const result = await getPool().query(
      "DELETE FROM kanban_stages WHERE id = $1 AND user_id = $2 RETURNING id",
      [stageId, user.id],
    );
    if (!result.rows[0]) {
      return sendJson(res, 404, { message: "Etapa nao encontrada." });
    }
    return sendJson(res, 200, { success: true });
  } catch (error: any) {
    console.error("[vercel-http] delete kanban stage failed:", error);
    return sendJson(res, 500, { message: error?.message || "Failed to delete kanban stage" });
  }
}

function toConversationPayload(row: ConversationSummaryRow, tags: ConversationTagRow[] = []) {
  return {
    id: row.id,
    connectionId: row.connectionId,
    contactNumber: row.contactNumber,
    remoteJid: row.remoteJid,
    jidSuffix: row.jidSuffix || "s.whatsapp.net",
    contactName: repairWebOnlyOutgoingText(row.contactName),
    contactAvatar: row.contactAvatar,
    lastMessageText: repairWebOnlyOutgoingText(row.lastMessageText),
    lastMessageTime: row.lastMessageTime,
    lastMessageFromMe: row.lastMessageFromMe === true,
    unreadCount: Number(row.unreadCount || 0),
    isArchived: row.isArchived === true,
    hasReplied: row.hasReplied === true,
    followupActive: row.followupActive !== false,
    followupStage: Number(row.followupStage || 0),
    nextFollowupAt: row.nextFollowupAt,
    followupDisabledReason: row.followupDisabledReason,
    shareToken: row.shareToken,
    kanbanStageId: row.kanbanStageId,
    kanbanNotes: row.kanbanNotes,
    priority: row.priority || "normal",
    attentionPriority: row.attentionPriority,
    attentionReason: repairWebOnlyOutgoingText(row.attentionReason),
    attentionConfidence: normalizeNumeric(row.attentionConfidence),
    needsHumanAttention: row.needsHumanAttention === true,
    attentionQualifiedAt: row.attentionQualifiedAt,
    sectorId: row.sectorId,
    assignedToMemberId: row.assignedToMemberId,
    routingIntent: row.routingIntent,
    routingConfidence: normalizeNumeric(row.routingConfidence),
    routingAt: row.routingAt,
    orchestrationMode: row.orchestrationMode || "ai",
    handoffReason: row.handoffReason,
    handedOffAt: row.handedOffAt,
    handedOffBy: row.handedOffBy,
    isClosed: row.isClosed === true,
    closedAt: row.closedAt,
    closedBy: row.closedBy,
    closureReason: row.closureReason,
    ticketNumber: row.ticketNumber,
    createdAt: row.createdAt,
    updatedAt: row.updatedAt,
    connectionName: repairWebOnlyOutgoingText(row.connectionName),
    connectionType: row.connectionType,
    connectionPhoneNumber: row.connectionPhoneNumber,
    provider: row.provider,
    connectionMethod: row.connectionMethod,
    providerStatus: row.providerStatus,
    connectionIsConnected: row.connectionIsConnected === true,
    tags: tags.map((tag) => ({
      id: tag.id,
      conversationId: tag.conversationId,
      name: tag.name,
      color: tag.color || "#6b7280",
      icon: tag.icon,
      description: tag.description,
      position: Number(tag.position || 0),
    })),
  };
}

function canActorViewPhoneNumbers(user: AuthenticatedUser) {
  return !isTeamMemberUser(user) || user.memberData.permissions.canViewPhoneNumbers === true;
}

function sanitizeConversationPayloadForActor<T extends Record<string, any>>(payload: T, user: AuthenticatedUser): T {
  if (canActorViewPhoneNumbers(user)) {
    return payload;
  }

  return {
    ...payload,
    contactNumber: "",
    contact_number: "",
    remoteJid: null,
    remote_jid: null,
    connectionPhoneNumber: null,
    connection_phone_number: null,
    conversationOwnerPhoneNumber: null,
    owner_phone_number: null,
  };
}

function toConversationPayloadForActor(user: AuthenticatedUser, row: ConversationSummaryRow, tags: ConversationTagRow[] = []) {
  return sanitizeConversationPayloadForActor(toConversationPayload(row, tags), user);
}

function toMessagePayload(row: MessageRow) {
  return {
    id: row.id,
    messageId: row.messageId,
    fromMe: row.fromMe === true,
    text: row.text,
    timestamp: row.timestamp,
    status: row.status,
    isFromAgent: row.isFromAgent === true,
    mediaType: row.mediaType,
    mediaUrl: row.mediaUrl,
    mediaMimeType: row.mediaMimeType,
    mediaDuration: row.mediaDuration == null ? null : Number(row.mediaDuration),
    mediaCaption: row.mediaCaption,
    mediaKey: row.mediaKey,
    directPath: row.directPath,
    mediaUrlOriginal: row.mediaUrlOriginal,
    createdAt: row.createdAt,
  };
}

function conversationConnectionLabel(
  conversation: Pick<ConversationSummaryRow, "connectionName" | "connectionPhoneNumber" | "connectionId">,
) {
  return [conversation.connectionName, conversation.connectionPhoneNumber]
    .map((item) => String(item || "").trim())
    .filter(Boolean)
    .join(" - ") || `Conexao ${String(conversation.connectionId || "").slice(0, 8)}`;
}

function conversationConnectionLooksConnected(
  conversation: Pick<ConversationSummaryRow, "connectionIsConnected" | "providerStatus">,
) {
  return (
    conversation.connectionIsConnected === true ||
    String(conversation.providerStatus || "").trim().toLowerCase() === "connected"
  );
}

function gatewayStatusLooksConnected(status: GatewayStatus | null | undefined) {
  return (
    status?.isConnected === true ||
    String(status?.providerStatus || "").trim().toLowerCase() === "connected"
  );
}

function gatewayStatusIsReadyForSend(status: GatewayStatus | null | undefined) {
  if (!status) return false;
  return status.isConnected === true;
}

function gatewayStatusLooksRecoverableForSend(status: GatewayStatus | null | undefined) {
  if (!status) return false;
  return String(status.providerStatus || "").trim().toLowerCase() === "connected";
}

async function waitForGatewayInstanceReadyForSend(connectionId: string, attempts = 5): Promise<GatewayStatus | null> {
  let latestStatus: GatewayStatus | null = null;
  for (let attempt = 0; attempt < attempts; attempt += 1) {
    if (attempt > 0) {
      await wait(Math.min(400 * attempt, 1200));
    }
    latestStatus = await getGatewayInstanceStatus(connectionId).catch((error) => {
      console.warn("[vercel-http] failed to poll gateway status after reconnect:", connectionId, error);
      return null;
    });
    if (gatewayStatusIsReadyForSend(latestStatus)) {
      return latestStatus;
    }
  }
  return latestStatus;
}

async function ensureConversationGatewayReadyForSend(
  conversation: ConversationSummaryRow,
  source: string,
  options: { allowReconnectWhenPersistedDisconnected?: boolean; reconnectTimeoutMs?: number } = {},
): Promise<GatewayStatus | null> {
  let gatewayStatus = await getGatewayInstanceStatus(conversation.connectionId).catch((error) => {
    console.warn("[vercel-http] failed to check gateway status before send:", conversation.connectionId, error);
    return null;
  });

  if (gatewayStatusIsReadyForSend(gatewayStatus)) {
    await syncConnectionStateFromGatewayStatus(conversation.connectionId, gatewayStatus, `${source}:ready`);
    return gatewayStatus;
  }

  const shouldAttemptReconnect =
    gatewayStatusLooksRecoverableForSend(gatewayStatus) ||
    conversation.connectionIsConnected === true ||
    String(conversation.providerStatus || "").trim().toLowerCase() === "connected" ||
    options.allowReconnectWhenPersistedDisconnected === true;

  if (!shouldAttemptReconnect) {
    return gatewayStatus;
  }

  console.warn("[vercel-http] gateway status inconsistent before send, reconnecting", {
    source,
    connectionId: conversation.connectionId,
    dbIsConnected: conversation.connectionIsConnected === true,
    dbProviderStatus: conversation.providerStatus || null,
    gatewayIsConnected: gatewayStatus?.isConnected === true,
    gatewayProviderStatus: gatewayStatus?.providerStatus || null,
  });

  await connectGatewayInstance(conversation.connectionId, options.reconnectTimeoutMs).catch((error) => {
    console.warn("[vercel-http] gateway reconnect before send failed:", conversation.connectionId, error);
  });
  gatewayStatus = await waitForGatewayInstanceReadyForSend(conversation.connectionId);
  if (gatewayStatusIsReadyForSend(gatewayStatus)) {
    await syncConnectionStateFromGatewayStatus(conversation.connectionId, gatewayStatus, `${source}:reconnected`);
  }
  return gatewayStatus;
}

function buildConversationConnectionUnavailablePayload(conversation: ConversationSummaryRow, status?: GatewayStatus | null) {
  const label = conversationConnectionLabel(conversation);
  return {
    success: false,
    message: `A conversa pertence a conexao ${label}, mas essa conexao nao esta conectada. Reconecte essa linha para responder aqui ou inicie uma nova conversa por uma linha conectada.`,
    code: "conversation_connection_disconnected",
    connection: {
      id: conversation.connectionId,
      name: conversation.connectionName,
      phoneNumber: conversation.connectionPhoneNumber,
      isConnected: conversation.connectionIsConnected === true,
      providerStatus: conversation.providerStatus,
      gatewayIsConnected: status?.isConnected === true,
      gatewayProviderStatus: status?.providerStatus || null,
    },
  };
}

function createManualOutgoingMessageId(prefix = "manual") {
  return `${prefix}:${Date.now()}:${randomBytes(8).toString("hex")}`;
}

function getManualGatewaySendAcceptTimeoutMs() {
  return getEnvInt("WA_GATEWAY_MANUAL_SEND_ACCEPT_TIMEOUT_MS", 15_000, 3_000);
}

function isGatewayRequestTimeoutError(error: unknown) {
  return /Gateway request timed out after \d+ms/i.test(String((error as any)?.message || ""));
}

async function insertManualOutgoingMessage(params: {
  conversationId: string;
  messageId?: string | null;
  text?: string | null;
  status?: string | null;
  isFromAgent?: boolean;
  mediaType?: string | null;
  mediaUrl?: string | null;
  mediaMimeType?: string | null;
  mediaDuration?: number | null;
  mediaCaption?: string | null;
}): Promise<ReturnType<typeof toMessagePayload>> {
  const result = await getPool().query(
    `
      INSERT INTO messages (
        conversation_id,
        message_id,
        from_me,
        text,
        timestamp,
        status,
        is_from_agent,
        media_type,
        media_url,
        media_mime_type,
        media_duration,
        media_caption,
        created_at
      )
      VALUES ($1, $2, true, $3, NOW(), $4, $5, $6, $7, $8, $9, $10, NOW())
      RETURNING
        id,
        message_id AS "messageId",
        from_me AS "fromMe",
        text,
        timestamp,
        status,
        is_from_agent AS "isFromAgent",
        media_type AS "mediaType",
        media_url AS "mediaUrl",
        media_mime_type AS "mediaMimeType",
        media_duration AS "mediaDuration",
        media_caption AS "mediaCaption",
        media_key AS "mediaKey",
        direct_path AS "directPath",
        media_url_original AS "mediaUrlOriginal",
        created_at AS "createdAt"
    `,
    [
      params.conversationId,
      params.messageId || createManualOutgoingMessageId(params.mediaType ? `manual-${params.mediaType}` : "manual-text"),
      params.text || null,
      params.status || "sending",
      params.isFromAgent === true,
      params.mediaType || null,
      params.mediaUrl || null,
      params.mediaMimeType || null,
      Number.isFinite(Number(params.mediaDuration)) ? Number(params.mediaDuration) : null,
      params.mediaCaption || null,
    ],
  );
  return toMessagePayload(result.rows[0] as MessageRow);
}

async function updateManualOutgoingMessageStatus(
  messageDbId: string,
  params: { status: string; messageId?: string | null },
): Promise<ReturnType<typeof toMessagePayload> | null> {
  if (!messageDbId) return null;
  const pool = getPool();
  const returningColumns = [
    'id',
    'message_id AS "messageId"',
    'from_me AS "fromMe"',
    'text',
    'timestamp',
    'status',
    'is_from_agent AS "isFromAgent"',
    'media_type AS "mediaType"',
    'media_url AS "mediaUrl"',
    'media_mime_type AS "mediaMimeType"',
    'media_duration AS "mediaDuration"',
    'media_caption AS "mediaCaption"',
    'media_key AS "mediaKey"',
    'direct_path AS "directPath"',
    'media_url_original AS "mediaUrlOriginal"',
    'created_at AS "createdAt"',
  ].join(",\n          ");
  const qualifiedReturningColumns = [
    'm.id',
    'm.message_id AS "messageId"',
    'm.from_me AS "fromMe"',
    'm.text',
    'm.timestamp',
    'm.status',
    'm.is_from_agent AS "isFromAgent"',
    'm.media_type AS "mediaType"',
    'm.media_url AS "mediaUrl"',
    'm.media_mime_type AS "mediaMimeType"',
    'm.media_duration AS "mediaDuration"',
    'm.media_caption AS "mediaCaption"',
    'm.media_key AS "mediaKey"',
    'm.direct_path AS "directPath"',
    'm.media_url_original AS "mediaUrlOriginal"',
    'm.created_at AS "createdAt"',
  ].join(",\n          ");
  try {
    const result = await pool.query(
      `
        UPDATE messages
        SET
          status = $2,
          message_id = CASE WHEN $3::text IS NOT NULL AND $3::text <> '' THEN $3 ELSE message_id END
        WHERE id = $1
        RETURNING ${returningColumns}
      `,
      [messageDbId, params.status, params.messageId || null],
    );
    return result.rows[0] ? toMessagePayload(result.rows[0] as MessageRow) : null;
  } catch (error: any) {
    const confirmedMessageId = typeof params.messageId === "string" ? params.messageId.trim() : "";
    if (error?.code !== "23505" || !confirmedMessageId) {
      throw error;
    }

    const duplicateResult = await pool.query(
      `
        WITH current_message AS (
          SELECT conversation_id
          FROM messages
          WHERE id = $1
          LIMIT 1
        ),
        confirmed_message AS (
          UPDATE messages m
          SET status = $3
          FROM current_message c
          WHERE m.conversation_id = c.conversation_id
            AND m.message_id = $2
            AND m.id <> $1
          RETURNING ${qualifiedReturningColumns}
        ),
        removed_local_draft AS (
          DELETE FROM messages
          WHERE id = $1
            AND EXISTS (SELECT 1 FROM confirmed_message)
        )
        SELECT *
        FROM confirmed_message
        LIMIT 1
      `,
      [messageDbId, confirmedMessageId, params.status],
    );
    return duplicateResult.rows[0] ? toMessagePayload(duplicateResult.rows[0] as MessageRow) : null;
  }
}

async function applyManualOutgoingConversationState(params: {
  userId: string;
  conversationId: string;
  lastMessageText: string;
  ownerPhoneNumber?: string | null;
}) {
  const configResult = await getPool().query(
    `
      SELECT
        COALESCE(pause_on_manual_reply, true) AS "pauseOnManualReply",
        auto_reactivate_minutes AS "autoReactivateMinutes"
      FROM ai_agent_config
      WHERE user_id = $1
      LIMIT 1
    `,
    [params.userId],
  );
  const config = configResult.rows[0] || {};
  const shouldPause = config.pauseOnManualReply !== false;
  const autoReactivateMinutes = normalizeAutoReactivateMinutes(config.autoReactivateMinutes);

  if (shouldPause) {
    await getPool().query(
      `
        INSERT INTO agent_disabled_conversations (
          conversation_id,
          owner_last_reply_at,
          auto_reactivate_after_minutes,
          client_has_pending_message,
          client_last_message_at
        )
        VALUES ($1, NOW(), $2, false, NULL)
        ON CONFLICT (conversation_id) DO UPDATE SET
          owner_last_reply_at = NOW(),
          auto_reactivate_after_minutes = EXCLUDED.auto_reactivate_after_minutes,
          client_has_pending_message = false
      `,
      [
        params.conversationId,
        Number.isFinite(autoReactivateMinutes) ? autoReactivateMinutes : null,
      ],
    );
  }

  await getPool().query(
    `
      UPDATE conversations
      SET
        owner_phone_number = CASE WHEN owner_phone_number IS NULL AND $3::text IS NOT NULL THEN $3 ELSE owner_phone_number END,
        owner_phone_verified_at = CASE WHEN owner_phone_number IS NULL AND $3::text IS NOT NULL THEN NOW() ELSE owner_phone_verified_at END,
        owner_phone_source = CASE WHEN owner_phone_number IS NULL AND $3::text IS NOT NULL THEN 'manual_outgoing_current_connection' ELSE owner_phone_source END,
        last_message_text = $2,
        last_message_time = NOW(),
        last_message_from_me = true,
        has_replied = true,
        unread_count = 0,
        is_archived = false,
        updated_at = NOW()
      WHERE id = $1
    `,
    [params.conversationId, params.lastMessageText, params.ownerPhoneNumber || null],
  );

  await scheduleWebOnlyFollowupAfterCompanyMessage(params.userId, params.conversationId);
  return { shouldPause };
}

function buildConversationFilters(
  userId: string,
  options: {
    connectionId?: string;
    tagId?: string;
    search?: string;
    attentionMode?: "all" | "critical" | "high" | "needsHumanAttention";
    conversationId?: string;
    archived?: boolean | "all";
    memberScope?: MemberSectorScope | null;
    canSearchPhoneNumbers?: boolean;
  } = {},
) {
  const params: unknown[] = [userId];
  const filters = ["wc.user_id = $1"];

  if (options.connectionId) {
    params.push(options.connectionId);
    filters.push(`c.connection_id = $${params.length}`);
  }

  if (options.conversationId) {
    params.push(options.conversationId);
    filters.push(`c.id = $${params.length}`);
  }

  if (options.archived === true) {
    filters.push(`COALESCE(c.is_archived, false) = true`);
  } else if (options.archived !== "all") {
    filters.push(`COALESCE(c.is_archived, false) = false`);
    filters.push(`NOT (COALESCE(c.is_closed, false) = true AND c.last_message_time IS NULL)`);
  }

  if (options.tagId) {
    params.push(options.tagId);
    filters.push(
      `EXISTS (
        SELECT 1
        FROM conversation_tags ct
        WHERE ct.conversation_id = c.id
          AND ct.tag_id = $${params.length}
      )`,
    );
  }

  if (options.attentionMode === "critical") {
    filters.push(`c.attention_priority = 'critica'`);
  } else if (options.attentionMode === "high") {
    filters.push(`c.attention_priority IN ('critica', 'alta')`);
  } else if (options.attentionMode === "needsHumanAttention") {
    filters.push(`c.needs_human_attention = true`);
  }

  const search = String(options.search || "").trim();
  if (search) {
    params.push(`%${search}%`);
    const searchPlaceholder = `$${params.length}`;
    filters.push(
      `(
        COALESCE(c.contact_name, '') ILIKE ${searchPlaceholder}
        ${options.canSearchPhoneNumbers === false ? "" : `OR COALESCE(c.contact_number, '') ILIKE ${searchPlaceholder}`}
        OR COALESCE(c.last_message_text, '') ILIKE ${searchPlaceholder}
        OR COALESCE(c.attention_reason, '') ILIKE ${searchPlaceholder}
        OR EXISTS (
          SELECT 1
          FROM messages m
          WHERE m.conversation_id = c.id
            AND COALESCE(m.text, '') ILIKE ${searchPlaceholder}
        )
      )`,
    );
  }

  appendMemberConversationScopeFilter(params, filters, options.memberScope || null);

  return { params, filters };
}

function appendMemberConversationScopeFilter(
  params: unknown[],
  filters: string[],
  scope: MemberSectorScope | null,
) {
  if (!scope) {
    return;
  }

  params.push(scope.memberId);
  const memberPlaceholder = `$${params.length}`;
  const allowedBranches = [`c.assigned_to_member_id = ${memberPlaceholder}`];

  for (const sectorId of scope.sectorIds) {
    const cleanSectorId = String(sectorId || "").trim();
    if (!cleanSectorId) continue;

    params.push(cleanSectorId);
    const sectorPlaceholder = `$${params.length}`;
    const sectorMatch =
      cleanSectorId === scope.defaultSectorId
        ? `(c.sector_id = ${sectorPlaceholder} OR c.sector_id IS NULL)`
        : `c.sector_id = ${sectorPlaceholder}`;
    const settings = scope.sectorSettings.get(cleanSectorId);
    const humanReplyGuard =
      settings?.controlledHandoffEnabled === false || settings?.memberReplyScope === "shared"
        ? "TRUE"
        : `NOT EXISTS (
            SELECT 1
            FROM messages m_scope
            WHERE m_scope.conversation_id = c.id
              AND m_scope.from_me = true
              AND COALESCE(m_scope.is_from_agent, false) = false
              AND (c.handed_off_at IS NULL OR m_scope.timestamp >= c.handed_off_at)
          )`;

    allowedBranches.push(`(${sectorMatch} AND ${humanReplyGuard})`);
  }

  filters.push(`(${allowedBranches.join(" OR ")})`);
}

async function queryConversationRows(
  userId: string,
  options: {
    connectionId?: string;
    tagId?: string;
    search?: string;
    attentionMode?: "all" | "critical" | "high" | "needsHumanAttention";
    conversationId?: string;
    archived?: boolean | "all";
    limit?: number;
    offset?: number;
    memberScope?: MemberSectorScope | null;
    canSearchPhoneNumbers?: boolean;
  } = {},
) {
  const { params, filters } = buildConversationFilters(userId, options);
  const queryParams = [...params];
  let suffix = options.attentionMode
    ? `
      ORDER BY
        c.needs_human_attention DESC,
        CASE c.attention_priority
          WHEN 'critica' THEN 4
          WHEN 'alta' THEN 3
          WHEN 'media' THEN 2
          WHEN 'baixa' THEN 1
          ELSE 0
        END DESC,
        c.attention_qualified_at DESC NULLS LAST,
        c.last_message_time DESC NULLS LAST,
        c.updated_at DESC NULLS LAST
    `
    : `
      ORDER BY COALESCE(c.last_message_time, c.updated_at, c.created_at) DESC NULLS LAST, c.updated_at DESC NULLS LAST
    `;

  if (options.limit != null) {
    queryParams.push(Math.max(1, Math.floor(options.limit)));
    suffix += ` LIMIT $${queryParams.length}`;

    queryParams.push(Math.max(0, Math.floor(options.offset || 0)));
    suffix += ` OFFSET $${queryParams.length}`;
  }

  const result = await getPool().query(
    `
      SELECT
        COUNT(*) OVER() AS "__totalCount",
        ${CONVERSATION_BASE_SELECT.replace(/^(\s*SELECT\s*)/i, "")}
      WHERE ${filters.join(" AND ")}
      ${suffix}
    `,
    queryParams,
  );

  const rows = result.rows as ConversationSummaryRow[];
  const total = rows[0] ? Number(rows[0].__totalCount || rows.length) : 0;
  return { rows, total };
}

async function getConversationTagsMap(conversationIds: string[], userId: string) {
  if (conversationIds.length === 0) {
    return new Map<string, ConversationTagRow[]>();
  }

  const result = await getPool().query(
    `
      SELECT
        ct.conversation_id AS "conversationId",
        t.id,
        t.name,
        t.color,
        t.icon,
        t.description,
        t.position
      FROM conversation_tags ct
      INNER JOIN tags t
        ON t.id = ct.tag_id
      WHERE ct.conversation_id = ANY($1::varchar[])
        AND t.user_id = $2
      ORDER BY t.position ASC NULLS LAST, t.name ASC
    `,
    [conversationIds, userId],
  );

  const tagMap = new Map<string, ConversationTagRow[]>();
  for (const row of result.rows as ConversationTagRow[]) {
    const existing = tagMap.get(row.conversationId) || [];
    existing.push(row);
    tagMap.set(row.conversationId, existing);
  }
  return tagMap;
}

async function handleConversationTags(req: any, res: any, conversationId: string) {
  const user = await requireUserOrTeamMember(req, res);
  if (!user) return;
  if (!ensureTeamMemberPermission(user, res, "canViewConversations", "Permissão insuficiente para ver conversas.")) return;

  try {
    const conversation = await getConversationForActor(user, conversationId);
    if (!conversation) {
      return sendJson(res, 404, { message: "Conversa não encontrada." });
    }

    if (req.method === "GET") {
      const result = await getPool().query(
        `
          SELECT t.*
          FROM conversation_tags ct
          INNER JOIN tags t
            ON t.id = ct.tag_id
          WHERE ct.conversation_id = $1
            AND t.user_id = $2
          ORDER BY t.position ASC, t.name ASC
        `,
        [conversation.id, user.id],
      );
      return sendJson(res, 200, result.rows.map((row) => toCamelRecord(row)));
    }

    if (!ensureTeamMemberPermission(user, res, "canEditContacts", "Permissão insuficiente para editar contatos.")) return;

    const body = await readJsonBody(req);
    const requestedTagIds = Array.isArray(body?.tagIds)
      ? body.tagIds.map((id: unknown) => String(id || "").trim()).filter(Boolean)
      : [];

    const validTagsResult = requestedTagIds.length > 0
      ? await getPool().query(
          "SELECT id FROM tags WHERE user_id = $1 AND id = ANY($2::varchar[])",
          [user.id, requestedTagIds],
        )
      : { rows: [] as Array<{ id: string }> };
    const validTagIds = validTagsResult.rows.map((row) => String(row.id));

    await getPool().query("DELETE FROM conversation_tags WHERE conversation_id = $1", [conversation.id]);
    if (validTagIds.length > 0) {
      const values: string[] = [];
      const params: unknown[] = [];
      for (const tagId of validTagIds) {
        params.push(conversation.id, tagId);
        values.push(`($${params.length - 1}, $${params.length}, NOW())`);
      }
      await getPool().query(
        `
          INSERT INTO conversation_tags (conversation_id, tag_id, assigned_at)
          VALUES ${values.join(", ")}
          ON CONFLICT (conversation_id, tag_id) DO NOTHING
        `,
        params,
      );
    }

    const updated = await getPool().query(
      `
        SELECT t.*
        FROM conversation_tags ct
        INNER JOIN tags t
          ON t.id = ct.tag_id
        WHERE ct.conversation_id = $1
          AND t.user_id = $2
        ORDER BY t.position ASC, t.name ASC
      `,
      [conversation.id, user.id],
    );
    return sendJson(res, 200, updated.rows.map((row) => toCamelRecord(row)));
  } catch (error: any) {
    console.error("[vercel-http] conversation tags failed:", error);
    return sendJson(res, 500, { message: error?.message || "Falha ao atualizar etiquetas da conversa." });
  }
}

async function getConversationForUser(userId: string, conversationId: string) {
  const result = await queryConversationRows(userId, { conversationId, limit: 1, offset: 0 });
  return result.rows[0] || null;
}

async function getConversationForUserIncludingArchived(userId: string, conversationId: string) {
  const result = await queryConversationRows(userId, { conversationId, archived: "all", limit: 1, offset: 0 });
  return result.rows[0] || null;
}

async function ensureActiveConversationForIncomingGatewayEvent(
  userId: string,
  conversation: ConversationSummaryRow,
): Promise<ConversationSummaryRow> {
  if (conversation.isClosed !== true) {
    return conversation;
  }

  const existingActive = await getPool().query(
    `
      SELECT c.id
      FROM conversations c
      INNER JOIN whatsapp_connections wc ON wc.id = c.connection_id
      WHERE wc.user_id = $1
        AND c.connection_id = $2
        AND c.id <> $3
        AND COALESCE(c.is_closed, false) = false
        AND (
          c.contact_number = $4
          OR (c.remote_jid IS NOT NULL AND c.remote_jid = $5)
        )
      ORDER BY c.updated_at DESC NULLS LAST, c.created_at DESC NULLS LAST
      LIMIT 1
    `,
    [
      userId,
      conversation.connectionId,
      conversation.id,
      conversation.contactNumber,
      conversation.remoteJid || null,
    ],
  );

  const existingId = existingActive.rows[0]?.id ? String(existingActive.rows[0].id) : "";
  if (existingId) {
    const existing = await getConversationForUserIncludingArchived(userId, existingId);
    if (existing) return existing;
  }

  const inserted = await getPool().query(
    `
      INSERT INTO conversations (
        connection_id,
        contact_number,
        owner_phone_number,
        owner_phone_verified_at,
        owner_phone_source,
        remote_jid,
        jid_suffix,
        contact_name,
        contact_avatar,
        last_message_text,
        last_message_time,
        last_message_from_me,
        unread_count,
        is_archived,
        has_replied,
        followup_active,
        followup_stage,
        orchestration_mode,
        created_at,
        updated_at
      )
      VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $9, NULL, NULL, NULL, 0, false, false, true, 0, 'ai', NOW(), NOW())
      RETURNING id
    `,
    [
      conversation.connectionId,
      conversation.contactNumber || "",
      conversation.conversationOwnerPhoneNumber || null,
      conversation.conversationOwnerPhoneVerifiedAt || null,
      conversation.conversationOwnerPhoneSource || null,
      conversation.remoteJid || null,
      conversation.jidSuffix || "s.whatsapp.net",
      conversation.contactName || conversation.contactNumber,
      conversation.contactAvatar || null,
    ],
  );

  const nextConversation = await getConversationForUserIncludingArchived(userId, String(inserted.rows[0].id));
  return nextConversation || conversation;
}

function getGatewayEventConnectionId(data: any): string {
  const messageData = getGatewayEventMessageData(data);
  return String(
    data?.connectionId ||
      data?.instanceId ||
      data?.conversation?.connectionId ||
      messageData?.connectionId ||
      messageData?.instanceId ||
      "",
  ).trim();
}

function getGatewayEventRemoteJid(data: any): string {
  const messageData = getGatewayEventMessageData(data);
  return String(
    data?.remoteJid ||
      data?.remote_jid ||
      data?.jid ||
      data?.conversation?.remoteJid ||
      data?.conversation?.remote_jid ||
      messageData?.remoteJid ||
      messageData?.remote_jid ||
      messageData?.jid ||
      "",
  ).trim();
}

function getGatewayEventJidSuffix(data: any): string {
  const messageData = getGatewayEventMessageData(data);
  const configured = String(data?.jidSuffix || data?.jid_suffix || messageData?.jidSuffix || messageData?.jid_suffix || "").trim();
  if (configured) return configured;
  const remoteJid = getGatewayEventRemoteJid(data);
  return remoteJid.split("@")[1]?.split(":")[0] || "s.whatsapp.net";
}

function getGatewayEventContactNumber(data: any): string {
  const messageData = getGatewayEventMessageData(data);
  const explicit = String(
    data?.contactNumber ||
      data?.contact_number ||
      data?.conversation?.contactNumber ||
      data?.conversation?.contact_number ||
      messageData?.contactNumber ||
      messageData?.contact_number ||
      "",
  ).trim();
  if (explicit) return explicit.replace(/\D/g, "");
  const remoteJid = getGatewayEventRemoteJid(data);
  return remoteJid.split("@")[0]?.split(":")[0]?.replace(/\D/g, "") || "";
}

function getGatewayEventContactName(data: any): string {
  const messageData = getGatewayEventMessageData(data);
  return String(
    data?.contactName ||
      data?.pushName ||
      data?.conversation?.contactName ||
      messageData?.contactName ||
      messageData?.pushName ||
      "",
  ).trim();
}

async function resolveGatewayEventConversation(
  userId: string,
  data: any,
): Promise<ConversationSummaryRow | null> {
  const conversationId = getGatewayEventConversationId(data);
  if (conversationId) {
    return getConversationForUserIncludingArchived(userId, conversationId);
  }

  const connectionId = getGatewayEventConnectionId(data);
  const remoteJid = getGatewayEventRemoteJid(data);
  const contactNumber = getGatewayEventContactNumber(data);
  if (!connectionId || (!remoteJid && !contactNumber)) {
    return null;
  }

  const connectionResult = await getPool().query(
    `
      SELECT id
      FROM whatsapp_connections
      WHERE id = $1
        AND user_id::text = $2::text
      LIMIT 1
    `,
    [connectionId, userId],
  );
  if (connectionResult.rows.length === 0) {
    return null;
  }

  const existing = await getPool().query(
    `
      SELECT id
      FROM conversations
      WHERE connection_id = $1
        AND COALESCE(is_closed, false) = false
        AND (
          ($2::text <> '' AND remote_jid = $2)
          OR ($3::text <> '' AND contact_number = $3)
        )
      ORDER BY updated_at DESC NULLS LAST, created_at DESC NULLS LAST
      LIMIT 1
    `,
    [connectionId, remoteJid || "", contactNumber || ""],
  );
  const existingId = existing.rows[0]?.id ? String(existing.rows[0].id) : "";
  if (existingId) {
    return getConversationForUserIncludingArchived(userId, existingId);
  }

  const messageText = getGatewayIncomingMessageText(data) || getGatewayManualOutgoingMessageText(data);
  const timestampRaw = getGatewayEventMessageData(data)?.timestamp || data?.timestamp || new Date().toISOString();
  const timestamp = Number.isNaN(new Date(timestampRaw).getTime())
    ? new Date().toISOString()
    : new Date(timestampRaw).toISOString();
  const contactName = getGatewayEventContactName(data) || contactNumber || remoteJid;
  const inserted = await getPool().query(
    `
      INSERT INTO conversations (
        connection_id,
        contact_number,
        remote_jid,
        jid_suffix,
        contact_name,
        last_message_text,
        last_message_time,
        last_message_from_me,
        unread_count,
        is_archived,
        has_replied,
        followup_active,
        followup_stage,
        orchestration_mode,
        created_at,
        updated_at
      )
      VALUES ($1, $2, $3, $4, $5, $6, $7, false, 0, false, false, true, 0, 'ai', NOW(), NOW())
      RETURNING id
    `,
    [
      connectionId,
      contactNumber || "",
      remoteJid || null,
      getGatewayEventJidSuffix(data),
      contactName,
      messageText || null,
      timestamp,
    ],
  );

  const nextConversation = await getConversationForUserIncludingArchived(userId, String(inserted.rows[0]?.id || ""));
  return nextConversation || null;
}

async function getMemberSectorScope(user: AuthenticatedUser): Promise<MemberSectorScope | null> {
  if (!isTeamMemberUser(user)) {
    return null;
  }

  const result = await getPool().query(
    `
      SELECT
        sm.sector_id,
        COALESCE(s.controlled_handoff_enabled, true) AS controlled_handoff_enabled,
        CASE WHEN s.member_reply_scope = 'shared' THEN 'shared' ELSE 'assigned_only' END AS member_reply_scope
      FROM sector_members sm
      JOIN sectors s ON s.id = sm.sector_id
      WHERE sm.member_id = $1
        AND s.owner_id = $2
    `,
    [user.memberData.id, user.id],
  );

  const sectorIds = result.rows.map((row) => String(row.sector_id)).filter(Boolean);
  const sectorSettings = new Map<string, { controlledHandoffEnabled: boolean; memberReplyScope: "assigned_only" | "shared" }>();
  for (const row of result.rows) {
    sectorSettings.set(String(row.sector_id), {
      controlledHandoffEnabled: row.controlled_handoff_enabled !== false,
      memberReplyScope: row.member_reply_scope === "shared" ? "shared" : "assigned_only",
    });
  }

  return {
    memberId: user.memberData.id,
    sectorIds,
    defaultSectorId: sectorIds.length === 1 ? sectorIds[0] : null,
    sectorSettings,
  };
}

async function getHumanReplySinceHandoffMap(conversationIds: string[]) {
  const ids = Array.from(new Set(conversationIds.map(String).filter(Boolean)));
  if (ids.length === 0) {
    return new Map<string, boolean>();
  }

  const result = await getPool().query(
    `
      SELECT
        c.id,
        EXISTS (
          SELECT 1
          FROM messages m
          WHERE m.conversation_id = c.id
            AND m.from_me = true
            AND COALESCE(m.is_from_agent, false) = false
            AND (c.handed_off_at IS NULL OR m.timestamp >= c.handed_off_at)
        ) AS has_manual_human_reply_since_handoff
      FROM conversations c
      WHERE c.id = ANY($1::varchar[])
    `,
    [ids],
  );

  return new Map(result.rows.map((row) => [String(row.id), row.has_manual_human_reply_since_handoff === true]));
}

function canMemberAccessConversationRow(
  conversation: Pick<ConversationSummaryRow, "id" | "sectorId" | "assignedToMemberId">,
  scope: MemberSectorScope,
  humanReplySinceHandoff: boolean,
) {
  if (conversation.assignedToMemberId && conversation.assignedToMemberId === scope.memberId) {
    return true;
  }

  const sectorId = conversation.sectorId || scope.defaultSectorId;
  if (!sectorId || !scope.sectorIds.includes(sectorId)) {
    return false;
  }

  const settings = scope.sectorSettings.get(sectorId);
  if (settings?.memberReplyScope === "shared") {
    return true;
  }

  if (settings?.controlledHandoffEnabled === false) {
    return true;
  }

  return !humanReplySinceHandoff;
}

async function filterConversationRowsForMember(user: AuthenticatedUser, rows: ConversationSummaryRow[]) {
  if (!isTeamMemberUser(user)) {
    return rows;
  }

  if (user.memberData.permissions.canViewConversations === false) {
    return [];
  }

  const scope = await getMemberSectorScope(user);
  if (!scope) {
    return [];
  }

  const replyMap = await getHumanReplySinceHandoffMap(rows.map((row) => row.id));
  return rows.filter((row) => canMemberAccessConversationRow(row, scope, replyMap.get(row.id) === true));
}

async function getConversationForActor(user: AuthenticatedUser, conversationId: string, requireSendPermission = false) {
  const conversation = await getConversationForUser(user.id, conversationId);
  if (!conversation) {
    return null;
  }

  if (!isTeamMemberUser(user)) {
    return conversation;
  }

  if (user.memberData.permissions.canViewConversations === false) {
    return null;
  }
  if (requireSendPermission && user.memberData.permissions.canSendMessages === false) {
    return null;
  }

  const scope = await getMemberSectorScope(user);
  if (!scope) {
    return null;
  }

  const replyMap = await getHumanReplySinceHandoffMap([conversation.id]);
  if (!canMemberAccessConversationRow(conversation, scope, replyMap.get(conversation.id) === true)) {
    return null;
  }

  if (requireSendPermission) {
    const assignedToMemberId = conversation.assignedToMemberId || null;
    const sectorId = conversation.sectorId || scope.defaultSectorId;
    const settings = sectorId ? scope.sectorSettings.get(sectorId) : null;
    const canReply =
      assignedToMemberId === scope.memberId ||
      (sectorId && settings?.memberReplyScope === "shared") ||
      (!assignedToMemberId && Boolean(sectorId));
    if (!canReply) {
      return null;
    }

    if (sectorId && assignedToMemberId !== scope.memberId) {
      await getPool().query(
        `
          UPDATE conversations
          SET sector_id = COALESCE(sector_id, $2),
              assigned_to_member_id = COALESCE(assigned_to_member_id, $3),
              updated_at = NOW()
          WHERE id = $1
        `,
        [conversation.id, sectorId, scope.memberId],
      );
      conversation.sectorId = sectorId;
      conversation.assignedToMemberId = scope.memberId;
    }
  }

  return conversation;
}

function looksLikeWhatsappGroupIdentifier(value: unknown) {
  const digits = String(value || "").replace(/\D/g, "");
  return digits.startsWith("120363") && digits.length >= 15;
}

function isGroupConversationRow(conversation: (Pick<ConversationSummaryRow, "remoteJid" | "jidSuffix"> & { contactNumber?: string | null }) | null | undefined) {
  return Boolean(
    conversation?.jidSuffix === "g.us" ||
      String(conversation?.remoteJid || "").trim().endsWith("@g.us") ||
      looksLikeWhatsappGroupIdentifier(conversation?.contactNumber) ||
      looksLikeWhatsappGroupIdentifier(conversation?.remoteJid),
  );
}

function isLidConversationRow(conversation: any) {
  const suffix = String(conversation?.jidSuffix || conversation?.jid_suffix || "").trim().toLowerCase();
  const remoteJid = String(conversation?.remoteJid || conversation?.remote_jid || "").trim().toLowerCase();
  return suffix === "lid" || remoteJid.endsWith("@lid");
}

async function findWebOnlyCanonicalPhoneSibling(conversation: any) {
  if (!isLidConversationRow(conversation)) return null;
  const connectionId = String(conversation?.connectionId || conversation?.connection_id || "").trim();
  const conversationId = String(conversation?.id || "").trim();
  const remoteJid = String(conversation?.remoteJid || conversation?.remote_jid || "").trim();
  if (!connectionId || !conversationId || !remoteJid) return null;

  const result = await getPool().query(
    `
      WITH latest_lid_alt AS (
        SELECT NULLIF(
                 regexp_replace(COALESCE(raw_message #>> '{key,remoteJidAlt}', ''), '\\D', '', 'g'),
                 ''
               ) AS phone
        FROM pending_incoming_messages
        WHERE connection_id = $1
          AND remote_jid = $2
          AND COALESCE(raw_message #>> '{key,addressingMode}', '') = 'lid'
          AND COALESCE(raw_message #>> '{key,remoteJidAlt}', '') ILIKE '%@s.whatsapp.net'
        ORDER BY received_at DESC NULLS LAST, processed_at DESC NULLS LAST
        LIMIT 1
      )
      SELECT c.id,
             c.contact_number AS "contactNumber",
             c.contact_name AS "contactName",
             c.remote_jid AS "remoteJid",
             c.jid_suffix AS "jidSuffix",
             c.last_message_time AS "lastMessageTime"
      FROM latest_lid_alt l
      INNER JOIN conversations c
        ON c.connection_id = $1
       AND c.contact_number = l.phone
       AND COALESCE(c.jid_suffix, 's.whatsapp.net') = 's.whatsapp.net'
       AND c.id <> $3
      WHERE l.phone IS NOT NULL
      ORDER BY COALESCE(c.last_message_time, c.updated_at, c.created_at) DESC NULLS LAST
      LIMIT 1
    `,
    [connectionId, remoteJid, conversationId],
  );
  return result.rows[0] || null;
}

async function disableDuplicateLidFollowup(conversation: any, canonicalSibling: any) {
  const reason = canonicalSibling?.id
    ? `${WEB_ONLY_FOLLOWUP_DUPLICATE_LID_REASON} Canonical=${canonicalSibling.id}`.slice(0, 240)
    : WEB_ONLY_FOLLOWUP_DUPLICATE_LID_REASON;
  await getPool().query(
    `
      UPDATE conversations
      SET followup_active = false,
          next_followup_at = NULL,
          followup_disabled_reason = $2,
          updated_at = NOW()
      WHERE id = $1
    `,
    [conversation.id, reason],
  );
  return reason;
}

async function listSyncedContacts(
  userId: string,
  options: { search?: string; limit?: number; page?: number } = {},
) {
  const page = Math.max(1, Math.floor(options.page || 1));
  const limit = Math.max(1, Math.min(50, Math.floor(options.limit || 50)));
  const offset = (page - 1) * limit;
  const params: unknown[] = [userId];
  const searchFilters: string[] = [];

  const search = String(options.search || "").trim();
  if (search) {
    params.push(`%${search}%`);
    searchFilters.push(
      `(
        COALESCE(name, '') ILIKE $${params.length}
        OR COALESCE(phone, '') ILIKE $${params.length}
      )`,
    );
  }

  params.push(limit);
  const limitPlaceholder = `$${params.length}`;
  params.push(offset);
  const offsetPlaceholder = `$${params.length}`;

  const result = await getPool().query(
    `
      WITH whatsapp_raw AS (
        SELECT
          c.contact_number AS phone,
          MAX(NULLIF(c.contact_name, '')) AS name,
          MAX(COALESCE(c.last_message_time, c.updated_at, c.created_at)) AS "lastMessageAt",
          COUNT(*)::int AS "conversationCount",
          FALSE AS "googleImported"
        FROM conversations c
        INNER JOIN whatsapp_connections wc
          ON wc.id = c.connection_id
        WHERE wc.user_id = $1
          AND COALESCE(c.contact_number, '') <> ''
          AND COALESCE(c.jid_suffix, 's.whatsapp.net') <> 'g.us'
        GROUP BY c.contact_number
      ),
      google_raw AS (
        SELECT
          gce.normalized_phone AS phone,
          MAX(NULLIF(gce.display_name, '')) AS name,
          MAX(gce.last_synced_at) AS "lastMessageAt",
          0::int AS "conversationCount",
          TRUE AS "googleImported"
        FROM google_contacts_entries gce
        WHERE gce.user_id = $1
          AND COALESCE(gce.normalized_phone, '') <> ''
        GROUP BY gce.normalized_phone
      ),
      aggregated AS (
        SELECT
          phone,
          MAX(name) AS name,
          MAX("lastMessageAt") AS "lastMessageAt",
          SUM("conversationCount")::int AS "conversationCount",
          BOOL_OR("googleImported") AS "googleImported"
        FROM (
          SELECT * FROM whatsapp_raw
          UNION ALL
          SELECT * FROM google_raw
        ) raw
        GROUP BY phone
      )
      SELECT
        COUNT(*) OVER() AS "__totalCount",
        phone,
        name,
        "lastMessageAt",
        "conversationCount",
        "googleImported"
      FROM aggregated
      ${searchFilters.length ? `WHERE ${searchFilters.join(" AND ")}` : ""}
      ORDER BY "lastMessageAt" DESC NULLS LAST, phone ASC
      LIMIT ${limitPlaceholder}
      OFFSET ${offsetPlaceholder}
    `,
    params,
  );

  const rows = result.rows as Array<SyncedContactRow & { __totalCount?: number | string | null }>;
  const total = rows[0] ? Number(rows[0].__totalCount || rows.length) : 0;
  return {
    contacts: rows.map((row) => ({
      id: row.phone,
      jid: row.phone,
      phone: row.phone,
      name: row.name || row.phone,
      pushName: row.name || row.phone,
      isGroup: false,
      hasResponded: Number(row.conversationCount || 0) > 0,
      conversationCount: Number(row.conversationCount || 0),
      lastMessageAt: row.lastMessageAt,
      googleImported: Boolean((row as any).googleImported),
    })),
    total,
    page,
    totalPages: total > 0 ? Math.ceil(total / limit) : 0,
  };
}

async function handleConversationsList(req: any, res: any, withTags: boolean) {
  const user = await requireUserOrTeamMember(req, res);
  if (!user) return;
  if (!ensureTeamMemberPermission(user, res, "canViewConversations", "Permissao insuficiente para ver conversas.")) return;

  try {
    const tagId = typeof req.query?.tagId === "string" ? req.query.tagId.trim() : "";
    const connectionId = typeof req.query?.connectionId === "string" ? req.query.connectionId.trim() : "";
    const archivedRaw = typeof req.query?.archived === "string" ? req.query.archived.trim().toLowerCase() : "";
    const archived =
      archivedRaw === "true" ? true : archivedRaw === "all" ? "all" : false;
    const limit = req.query?.limit ? Number.parseInt(String(req.query.limit), 10) : null;
    const offset = req.query?.offset ? Number.parseInt(String(req.query.offset), 10) : 0;
    const payload = await buildConversationsListPayloadForUser(user, {
      tagId: tagId || undefined,
      connectionId: connectionId || undefined,
      archived,
      limit: limit == null ? undefined : limit,
      offset: Number.isFinite(offset) ? Math.max(0, offset) : 0,
      withTags,
    });

    if (limit != null && Number.isFinite(limit)) {
      return sendJson(res, 200, payload);
    }

    return sendJson(res, 200, payload.data);
  } catch (error) {
    console.error("[vercel-http] list conversations failed:", error);
    return sendJson(res, 500, { message: "Failed to fetch conversations" });
  }
}

async function buildConversationsListPayloadForUser(
  user: AuthenticatedUser,
  options: {
    tagId?: string;
    connectionId?: string;
    archived?: boolean | "all";
    limit?: number;
    offset?: number;
    withTags?: boolean;
  } = {},
) {
  const limit = options.limit == null ? 200 : Math.max(1, Math.min(Number(options.limit), 200));
  const offset = Number.isFinite(options.offset as number) ? Math.max(0, Number(options.offset)) : 0;
  const memberScope = isTeamMemberUser(user) ? await getMemberSectorScope(user) : null;
  if (isTeamMemberUser(user) && !memberScope) {
    return { data: [], total: 0, hasMore: false, offset, limit };
  }

  const result = await queryConversationRows(user.id, {
    tagId: options.tagId,
    connectionId: options.connectionId,
    archived: options.archived,
    limit,
    offset,
    memberScope,
  });

  const visibleRows = await filterConversationRowsForMember(user, result.rows);
  const tagMap = options.withTags !== false
    ? await getConversationTagsMap(visibleRows.map((row) => row.id), user.id)
    : new Map<string, ConversationTagRow[]>();
  const data = visibleRows.map((row) => toConversationPayloadForActor(user, row, tagMap.get(row.id) || []));

  return {
    data,
    total: result.total,
    hasMore: offset + data.length < result.total,
    offset,
    limit,
  };
}

async function handleConversationDetails(req: any, res: any) {
  const user = await requireUserOrTeamMember(req, res);
  if (!user) return;
  if (!ensureTeamMemberPermission(user, res, "canViewConversations", "Permissao insuficiente para ver conversas.")) return;

  try {
    const conversationId = String(req.params?.conversationId || "").trim();
    const conversation = await getConversationForActor(user, conversationId);
    if (!conversation) {
      return sendJson(res, 404, { message: "Conversation not found" });
    }

    if (Number(conversation.unreadCount || 0) > 0) {
      await getPool().query(
        "UPDATE conversations SET unread_count = 0, updated_at = NOW() WHERE id = $1",
        [conversationId],
      );
      conversation.unreadCount = 0;
    }

    return sendJson(res, 200, toConversationPayloadForActor(user, conversation));
  } catch (error) {
    console.error("[vercel-http] conversation details failed:", error);
    return sendJson(res, 500, { message: "Failed to fetch conversation" });
  }
}

async function handleConversationSearch(req: any, res: any) {
  const user = await requireUserOrTeamMember(req, res);
  if (!user) return;
  if (!ensureTeamMemberPermission(user, res, "canViewConversations", "Permissao insuficiente para ver conversas.")) return;

  try {
    const search = String(req.query?.q || "").trim();
    const limitRaw = Number.parseInt(String(req.query?.limit || "30"), 10);
    const connectionId = typeof req.query?.connectionId === "string" ? req.query.connectionId.trim() : "";

    if (search.length < 2) {
      return sendJson(res, 200, []);
    }

    const { rows } = await queryConversationRows(user.id, {
      search,
      connectionId: connectionId || undefined,
      limit: Math.max(1, Math.min(Number.isFinite(limitRaw) ? limitRaw : 30, 100)),
      offset: 0,
      memberScope: isTeamMemberUser(user) ? await getMemberSectorScope(user) : null,
      canSearchPhoneNumbers: canActorViewPhoneNumbers(user),
    });
    const visibleRows = await filterConversationRowsForMember(user, rows);
    const tagMap = await getConversationTagsMap(visibleRows.map((row) => row.id), user.id);
    return sendJson(
      res,
      200,
      visibleRows.map((row) => toConversationPayloadForActor(user, row, tagMap.get(row.id) || [])),
    );
  } catch (error) {
    console.error("[vercel-http] conversation search failed:", error);
    return sendJson(res, 500, { message: "Failed to search conversations" });
  }
}

async function handleAttentionQueue(req: any, res: any) {
  const user = await requireUserOrTeamMember(req, res);
  if (!user) return;
  if (!ensureTeamMemberPermission(user, res, "canViewConversations", "Permissao insuficiente para ver conversas.")) return;

  try {
    const requestedMode = typeof req.query?.filter === "string" ? req.query.filter.trim() : "all";
    const mode =
      requestedMode === "critical" ||
      requestedMode === "high" ||
      requestedMode === "needsHumanAttention" ||
      requestedMode === "all"
        ? requestedMode
        : "all";
    const search = typeof req.query?.q === "string" ? req.query.q.trim() : "";
    const connectionId = typeof req.query?.connectionId === "string" ? req.query.connectionId.trim() : "";
    const limit = Math.max(1, Math.min(Number.parseInt(String(req.query?.limit || "100"), 10) || 100, 200));
    const offset = Math.max(0, Number.parseInt(String(req.query?.offset || "0"), 10) || 0);

    const result = await queryConversationRows(user.id, {
      attentionMode: mode as "all" | "critical" | "high" | "needsHumanAttention",
      search: search || undefined,
      connectionId: connectionId || undefined,
      limit,
      offset,
      memberScope: isTeamMemberUser(user) ? await getMemberSectorScope(user) : null,
      canSearchPhoneNumbers: canActorViewPhoneNumbers(user),
    });
    const visibleRows = await filterConversationRowsForMember(user, result.rows);
    const tagMap = await getConversationTagsMap(visibleRows.map((row) => row.id), user.id);
    const data = visibleRows.map((row) => toConversationPayloadForActor(user, row, tagMap.get(row.id) || []));

    return sendJson(res, 200, {
      data,
      total: result.total,
      hasMore: offset + data.length < result.total,
      offset,
      limit,
    });
  } catch (error) {
    console.error("[vercel-http] attention queue failed:", error);
    return sendJson(res, 500, { message: "Failed to fetch attention queue" });
  }
}

function normalizeBulkConversationIds(value: unknown) {
  if (!Array.isArray(value)) {
    return [];
  }

  return Array.from(new Set(
    value
      .map((item) => String(item || "").trim())
      .filter(Boolean),
  )).slice(0, 2000);
}

function normalizeBulkTagIds(value: unknown) {
  if (!Array.isArray(value)) {
    return [];
  }

  return Array.from(new Set(
    value
      .map((item) => String(item || "").trim())
      .filter(Boolean),
  )).slice(0, 200);
}

async function getBulkConversationRowsForActor(user: AuthenticatedUser, conversationIds: string[]) {
  if (conversationIds.length === 0) {
    return [];
  }

  const result = await getPool().query(
    `
      ${CONVERSATION_BASE_SELECT}
      WHERE wc.user_id = $1
        AND c.id = ANY($2::varchar[])
    `,
    [user.id, conversationIds],
  );

  return filterConversationRowsForMember(user, result.rows as ConversationSummaryRow[]);
}

async function handleBulkConversationAction(req: any, res: any, action: "read" | "unread" | "archive" | "tags" | "ai-enable" | "ai-disable") {
  const user = await requireUserOrTeamMember(req, res);
  if (!user) return;
  if (!ensureTeamMemberPermission(user, res, "canViewConversations", "Permiss\u00e3o insuficiente para alterar conversas.")) return;

  try {
    const body = await readJsonBody(req);
    const conversationIds = normalizeBulkConversationIds(body?.conversationIds);
    if (conversationIds.length === 0) {
      return sendJson(res, 400, { message: "Selecione pelo menos uma conversa." });
    }

    const rows = await getBulkConversationRowsForActor(user, conversationIds);
    const validIds = rows.map((row) => row.id).filter(Boolean);
    if (validIds.length === 0) {
      return sendJson(res, 200, { updated: 0, skipped: conversationIds.length });
    }

    if (action === "read") {
      const result = await getPool().query(
        `
          UPDATE conversations
          SET unread_count = 0,
              updated_at = NOW()
          WHERE id = ANY($1::varchar[])
          RETURNING id
        `,
        [validIds],
      );
      return sendJson(res, 200, { updated: result.rowCount || 0, skipped: conversationIds.length - validIds.length });
    }

    if (action === "unread") {
      const result = await getPool().query(
        `
          UPDATE conversations
          SET unread_count = GREATEST(COALESCE(unread_count, 0), 1),
              updated_at = NOW()
          WHERE id = ANY($1::varchar[])
          RETURNING id
        `,
        [validIds],
      );
      return sendJson(res, 200, { updated: result.rowCount || 0, skipped: conversationIds.length - validIds.length });
    }

    if (action === "archive") {
      const archived = body?.archived === false ? false : true;
      const result = await getPool().query(
        `
          UPDATE conversations
          SET is_archived = $2,
              updated_at = NOW()
          WHERE id = ANY($1::varchar[])
          RETURNING id
        `,
        [validIds, archived],
      );
      return sendJson(res, 200, { updated: result.rowCount || 0, archived, skipped: conversationIds.length - validIds.length });
    }

    if (action === "tags") {
      const requestedTagIds = normalizeBulkTagIds(body?.tagIds);
      if (requestedTagIds.length === 0) {
        return sendJson(res, 400, { message: "Selecione pelo menos uma etiqueta." });
      }

      const tagsResult = await getPool().query(
        `
          SELECT id
          FROM tags
          WHERE user_id = $1
            AND id = ANY($2::varchar[])
        `,
        [user.id, requestedTagIds],
      );
      const validTagIds = tagsResult.rows.map((row) => String(row.id)).filter(Boolean);
      if (validTagIds.length === 0) {
        return sendJson(res, 400, { message: "Nenhuma etiqueta valida foi encontrada." });
      }

      const insertValues: string[] = [];
      const params: unknown[] = [];
      for (const conversationId of validIds) {
        for (const tagId of validTagIds) {
          params.push(conversationId, tagId);
          insertValues.push(`($${params.length - 1}, $${params.length}, NOW())`);
        }
      }

      if (insertValues.length > 0) {
        await getPool().query(
          `
            INSERT INTO conversation_tags (conversation_id, tag_id, assigned_at)
            VALUES ${insertValues.join(", ")}
            ON CONFLICT (conversation_id, tag_id) DO NOTHING
          `,
          params,
        );
      }

      return sendJson(res, 200, {
        updated: validIds.length,
        tagsApplied: validTagIds.length,
        skipped: conversationIds.length - validIds.length,
      });
    }

    if (action === "ai-enable") {
      await getPool().query(
        "DELETE FROM agent_disabled_conversations WHERE conversation_id = ANY($1::varchar[])",
        [validIds],
      );
      return sendJson(res, 200, { updated: validIds.length, aiEnabled: true, skipped: conversationIds.length - validIds.length });
    }

    await getPool().query(
      `
        INSERT INTO agent_disabled_conversations (
          conversation_id,
          owner_last_reply_at,
          auto_reactivate_after_minutes,
          client_has_pending_message,
          client_last_message_at
        )
        SELECT
          unnest($1::varchar[]),
          NOW(),
          NULL::integer,
          false,
          NULL::timestamp
        ON CONFLICT (conversation_id) DO UPDATE
        SET owner_last_reply_at = NOW(),
            auto_reactivate_after_minutes = NULL,
            client_has_pending_message = false,
            client_last_message_at = NULL
      `,
      [validIds],
    );
    return sendJson(res, 200, { updated: validIds.length, aiEnabled: false, skipped: conversationIds.length - validIds.length });
  } catch (error: any) {
    console.error(`[vercel-http] bulk conversation ${action} failed:`, error);
    return sendJson(res, 500, { message: error?.message || "Erro ao executar acao em massa." });
  }
}

async function handleMessagesList(req: any, res: any) {
  const user = await requireUserOrTeamMember(req, res);
  if (!user) return;
  if (!ensureTeamMemberPermission(user, res, "canViewConversations", "Permissao insuficiente para ver conversas.")) return;

  try {
    const conversationId = String(req.params?.conversationId || "").trim();
    const conversation = await getConversationForActor(user, conversationId);
    if (!conversation) {
      return sendJson(res, 404, { message: "Conversation not found" });
    }

    const afterRaw = typeof req.query?.after === "string" ? req.query.after.trim() : "";
    const beforeRaw = typeof req.query?.before === "string" ? req.query.before.trim() : "";
    const paginated = String(req.query?.paginated || "").trim().toLowerCase() === "true";
    const parsedLimit = Number.parseInt(String(req.query?.limit || (paginated ? "50" : "500")), 10);
    const limit = Math.max(1, Math.min(Number.isFinite(parsedLimit) ? parsedLimit : 50, 2000));

    if (afterRaw) {
      const afterDate = new Date(afterRaw);
      if (Number.isNaN(afterDate.getTime())) {
        return sendJson(res, 400, { message: "Invalid 'after' timestamp" });
      }

      const afterResult = await getPool().query(
        `
          SELECT
            id,
            message_id AS "messageId",
            from_me AS "fromMe",
            text,
            timestamp,
            status,
            is_from_agent AS "isFromAgent",
            media_type AS "mediaType",
            media_url AS "mediaUrl",
            media_mime_type AS "mediaMimeType",
            media_duration AS "mediaDuration",
            media_caption AS "mediaCaption",
            media_key AS "mediaKey",
            direct_path AS "directPath",
            media_url_original AS "mediaUrlOriginal",
            created_at AS "createdAt"
          FROM messages
          WHERE conversation_id = $1
            AND timestamp > $2
          ORDER BY timestamp ASC, created_at ASC, id ASC
          LIMIT $3
        `,
        [conversationId, afterDate.toISOString(), limit],
      );

      return sendJson(res, 200, (afterResult.rows as MessageRow[]).map(toMessagePayload));
    }

    if (paginated) {
      let beforeDate: Date | null = null;
      if (beforeRaw) {
        beforeDate = new Date(beforeRaw);
        if (Number.isNaN(beforeDate.getTime())) {
          return sendJson(res, 400, { message: "Invalid 'before' timestamp" });
        }
      }

      const pagedResult = beforeDate
        ? await getPool().query(
            `
              SELECT
                id,
                message_id AS "messageId",
                from_me AS "fromMe",
                text,
                timestamp,
                status,
                is_from_agent AS "isFromAgent",
                media_type AS "mediaType",
                media_url AS "mediaUrl",
                media_mime_type AS "mediaMimeType",
                media_duration AS "mediaDuration",
                media_caption AS "mediaCaption",
                media_key AS "mediaKey",
                direct_path AS "directPath",
                media_url_original AS "mediaUrlOriginal",
                created_at AS "createdAt"
              FROM messages
              WHERE conversation_id = $1
                AND timestamp < $2
              ORDER BY timestamp DESC, created_at DESC, id DESC
              LIMIT $3
            `,
            [conversationId, beforeDate.toISOString(), limit + 1],
          )
        : await getPool().query(
            `
              SELECT
                id,
                message_id AS "messageId",
                from_me AS "fromMe",
                text,
                timestamp,
                status,
                is_from_agent AS "isFromAgent",
                media_type AS "mediaType",
                media_url AS "mediaUrl",
                media_mime_type AS "mediaMimeType",
                media_duration AS "mediaDuration",
                media_caption AS "mediaCaption",
                media_key AS "mediaKey",
                direct_path AS "directPath",
                media_url_original AS "mediaUrlOriginal",
                created_at AS "createdAt"
              FROM messages
              WHERE conversation_id = $1
              ORDER BY timestamp DESC, created_at DESC, id DESC
              LIMIT $2
            `,
            [conversationId, limit + 1],
          );

      const pageRows = pagedResult.rows as MessageRow[];
      const hasMore = pageRows.length > limit;
      const visibleRows = hasMore ? pageRows.slice(0, limit) : pageRows;
      return sendJson(res, 200, {
        messages: visibleRows.reverse().map(toMessagePayload),
        hasMore,
      });
    }

    const fullResult = await getPool().query(
      `
        SELECT *
        FROM (
          SELECT
            id,
            message_id AS "messageId",
            from_me AS "fromMe",
            text,
            timestamp,
            status,
            is_from_agent AS "isFromAgent",
            media_type AS "mediaType",
            media_url AS "mediaUrl",
            media_mime_type AS "mediaMimeType",
            media_duration AS "mediaDuration",
            media_caption AS "mediaCaption",
            media_key AS "mediaKey",
            direct_path AS "directPath",
            media_url_original AS "mediaUrlOriginal",
            created_at AS "createdAt"
          FROM messages
          WHERE conversation_id = $1
          ORDER BY timestamp DESC, created_at DESC, id DESC
          LIMIT $2
        ) recent_messages
        ORDER BY timestamp ASC, "createdAt" ASC, id ASC
      `,
      [conversationId, limit],
    );

    return sendJson(res, 200, (fullResult.rows as MessageRow[]).map(toMessagePayload));
  } catch (error) {
    console.error("[vercel-http] messages list failed:", error);
    return sendJson(res, 500, { message: "Failed to fetch messages" });
  }
}

async function handleSendMessage(req: any, res: any) {
  const user = await requireUserOrTeamMember(req, res);
  if (!user) return;
  if (!ensureTeamMemberPermission(user, res, "canSendMessages", "Permissao insuficiente para enviar mensagens.")) return;

  try {
    const body = await readJsonBody(req);
    const conversationId = String(body.conversationId || "").trim();
    const text = String(body.text || "").trim();

    if (!conversationId || !text) {
      return sendJson(res, 400, { message: "conversationId and text are required" });
    }

    const userStatus = await getPool().query(
      `
        SELECT suspended_at AS "suspendedAt", suspension_reason AS "suspensionReason"
        FROM users
        WHERE id = $1
        LIMIT 1
      `,
      [user.id],
    );
    if (userStatus.rows[0]?.suspendedAt) {
      return sendJson(res, 403, {
        success: false,
        message: "Sua conta esta suspensa. Nao e possivel enviar mensagens.",
        suspended: true,
        reason: userStatus.rows[0]?.suspensionReason || null,
      });
    }

    const accessPayload = await buildAccessStatusPayloadForUser(user.id);
    if (accessPayload.shouldBlock) {
      return sendJson(res, 402, {
        success: false,
        blocked: true,
        blockReason: accessPayload.blockReason || "access_blocked",
        message: accessPayload.message || "Regularize sua assinatura para reativar os envios pelo WhatsApp.",
      });
    }

    const conversation = await getConversationForActor(user, conversationId, true);
    if (!conversation) {
      return sendJson(res, 404, { message: "Conversation not found" });
    }

    if (!shouldUseGateway(conversation)) {
      return sendJson(res, 409, {
        success: false,
        message: "Esta conexao ainda nao esta disponivel no runtime Vercel + gateway.",
      });
    }

    const gatewayStatus = await ensureConversationGatewayReadyForSend(conversation, "manual_text");
    if (
      (gatewayStatus && !gatewayStatusIsReadyForSend(gatewayStatus)) ||
      (!conversationConnectionLooksConnected(conversation) && !gatewayStatusLooksConnected(gatewayStatus))
    ) {
      return sendJson(res, 409, buildConversationConnectionUnavailablePayload(conversation, gatewayStatus));
    }

    const currentOwnerPhoneNumber = normalizeFollowupPhone(gatewayStatus?.phoneNumber || conversation.connectionPhoneNumber) || null;
    let persistedMessage = await insertManualOutgoingMessage({
      conversationId,
      text,
      status: "sending",
      isFromAgent: false,
    });
    const manualState = await applyManualOutgoingConversationState({
      userId: user.id,
      conversationId,
      lastMessageText: text,
      ownerPhoneNumber: currentOwnerPhoneNumber,
    });

    let sendResult: Awaited<ReturnType<typeof sendGatewayInstanceText>>;
    try {
      sendResult = await sendGatewayInstanceText(conversation.connectionId, {
        conversationId,
        text,
        to: conversation.contactNumber || undefined,
        contactName: conversation.contactName || undefined,
        source: "owner",
        acceptQueued: true,
        clientMessageId: persistedMessage.messageId,
        existingMessageDbId: persistedMessage.id,
      }, getManualGatewaySendAcceptTimeoutMs());
    } catch (error: any) {
      if (isGatewayRequestTimeoutError(error)) {
        persistedMessage = (await updateManualOutgoingMessageStatus(persistedMessage.id, { status: "queued" })) || persistedMessage;
        return sendJson(res, 202, {
          success: true,
          queued: true,
          pendingDelivery: true,
          agentPaused: manualState.shouldPause,
          messageId: persistedMessage.messageId,
          message: persistedMessage,
        });
      }

      persistedMessage = (await updateManualOutgoingMessageStatus(persistedMessage.id, { status: "failed" })) || persistedMessage;
      const message = String(error?.message || "");
      if (/not connected|desconectad|nao esta conectad|n\u00e3o est\u00e1 conectad/i.test(message)) {
        return sendJson(res, 409, buildConversationConnectionUnavailablePayload(conversation, gatewayStatus));
      }
      throw error;
    }

    if (sendResult?.success === false) {
      persistedMessage = (await updateManualOutgoingMessageStatus(persistedMessage.id, { status: "failed" })) || persistedMessage;
      const reason = sendResult.reason || "Falha ao enviar mensagem.";
      if (/not connected|desconectad|nao esta conectad|n\u00e3o est\u00e1 conectad/i.test(reason)) {
        return sendJson(res, 409, buildConversationConnectionUnavailablePayload(conversation, gatewayStatus));
      }
      return sendJson(res, sendResult.blocked ? 409 : 502, {
        success: false,
        message: reason,
        blocked: sendResult.blocked === true,
        messageRecord: persistedMessage,
      });
    }

    persistedMessage =
      (await updateManualOutgoingMessageStatus(persistedMessage.id, {
        status: sendResult?.queued === true ? "queued" : "sent",
        messageId: sendResult?.queued === true ? persistedMessage.messageId : sendResult?.messageId || null,
      })) || persistedMessage;

    return sendJson(res, 200, {
      success: true,
      agentPaused: manualState.shouldPause,
      messageId: persistedMessage.messageId || sendResult?.messageId || null,
      message: persistedMessage,
    });
  } catch (error: any) {
    console.error("[vercel-http] send message failed:", error);
    return sendJson(res, 500, { message: error?.message || "Failed to send message" });
  }
}

async function handleCreateNewContactConversation(req: any, res: any) {
  const user = await requireUserOrTeamMember(req, res);
  if (!user) return;
  if (!ensureTeamMemberPermission(user, res, "canSendMessages", "Permissao insuficiente para iniciar conversas.")) return;

  try {
    const body = await readJsonBody(req);
    const phoneNumber = String(body.phoneNumber || "").replace(/\D/g, "");
    const requestedName = String(body.name || body.contactName || "").trim();
    const requestedConnectionId = String(body.connectionId || "").trim();

    if (!phoneNumber) {
      return sendJson(res, 400, { success: false, message: "Numero de telefone e obrigatorio." });
    }

    let connection: ConnectionRow | null = null;
    if (requestedConnectionId) {
      connection = await getConnectionByIdForUser(user.id, requestedConnectionId);
      if (!connection || isInternalOnlySimulatorConnection(connection)) {
        return sendJson(res, 404, { success: false, message: "Conexao nao encontrada." });
      }
    } else {
      const visibleConnections = getAppVisibleConnections(await getConnectionsByUserId(user.id));
      if (visibleConnections.length > 1) {
        return sendJson(res, 400, {
          success: false,
          message: "Selecione qual linha deve iniciar a nova conversa.",
          requiresConnectionSelection: true,
        });
      }
      connection = visibleConnections[0] || null;
    }

    if (!connection) {
      return sendJson(res, 409, { success: false, message: "Nenhuma linha de WhatsApp encontrada." });
    }
    if (!shouldUseGateway(connection)) {
      return sendJson(res, 409, { success: false, message: "Esta conexao ainda nao esta disponivel no runtime Vercel + gateway." });
    }

    const gatewayStatus = await getGatewayInstanceStatus(connection.id).catch((error) => {
      console.warn("[vercel-http] failed to check gateway status before new contact:", connection?.id, error);
      return null;
    });
    const operationalConnection = applyGatewayStatus(connection, gatewayStatus);
    if (operationalConnection.isConnected !== true) {
      const label = [connection.connectionName, connection.phoneNumber].map((item) => String(item || "").trim()).filter(Boolean).join(" - ");
      return sendJson(res, 409, {
        success: false,
        message: `A conexao ${label || connection.id} nao esta conectada. Conecte essa linha antes de iniciar a conversa.`,
        code: "target_connection_disconnected",
      });
    }
    const currentOwnerPhoneNumber = normalizeFollowupPhone(gatewayStatus?.phoneNumber || operationalConnection.phoneNumber || connection.phoneNumber) || null;

    const existingResult = await getPool().query(
      `
        SELECT id, owner_phone_number AS "ownerPhoneNumber"
        FROM conversations
        WHERE connection_id = $1
          AND (
            contact_number = $2
            OR remote_jid = $3
          )
          AND (
            $4::text IS NULL
            OR owner_phone_number IS NULL
            OR regexp_replace(COALESCE(owner_phone_number, ''), '\\D', '', 'g') = $4
          )
        ORDER BY is_closed ASC NULLS FIRST, updated_at DESC NULLS LAST, created_at DESC NULLS LAST
        LIMIT 1
      `,
      [connection.id, phoneNumber, `${phoneNumber}@s.whatsapp.net`, currentOwnerPhoneNumber],
    );

    let conversationId = existingResult.rows[0]?.id ? String(existingResult.rows[0].id) : "";
    if (!conversationId) {
      const insertResult = await getPool().query(
        `
          INSERT INTO conversations (
            connection_id,
            contact_number,
            owner_phone_number,
            owner_phone_verified_at,
            owner_phone_source,
            remote_jid,
            jid_suffix,
            contact_name,
            last_message_text,
            last_message_time,
            unread_count,
            created_at,
            updated_at
          )
          VALUES ($1, $2, $3, CASE WHEN $3 IS NULL THEN NULL ELSE NOW() END, CASE WHEN $3 IS NULL THEN NULL ELSE 'new_contact_current_connection' END, $4, 's.whatsapp.net', $5, NULL, NULL, 0, NOW(), NOW())
          RETURNING id
        `,
        [connection.id, phoneNumber, currentOwnerPhoneNumber, `${phoneNumber}@s.whatsapp.net`, requestedName || phoneNumber],
      );
      conversationId = String(insertResult.rows[0].id);
    } else if (currentOwnerPhoneNumber && !normalizeFollowupPhone(existingResult.rows[0]?.ownerPhoneNumber)) {
      await getPool().query(
        `
          UPDATE conversations
          SET owner_phone_number = $2,
              owner_phone_verified_at = NOW(),
              owner_phone_source = 'new_contact_current_connection',
              updated_at = NOW()
          WHERE id = $1
            AND owner_phone_number IS NULL
        `,
        [conversationId, currentOwnerPhoneNumber],
      );
    }

    const initialMessage = String(body.message || "").trim();
    if (initialMessage) {
      await sendGatewayInstanceText(connection.id, {
        conversationId,
        text: initialMessage,
        to: phoneNumber,
        contactName: requestedName || undefined,
        source: "owner",
      });
      await getPool().query(
        `
          UPDATE conversations
          SET last_message_text = $2,
              last_message_time = NOW(),
              last_message_from_me = true,
              has_replied = true,
              updated_at = NOW()
          WHERE id = $1
        `,
        [conversationId, initialMessage],
      );
      await scheduleWebOnlyFollowupAfterCompanyMessage(user.id, conversationId);
    }

    return sendJson(res, 200, {
      success: true,
      conversationId,
      connectionId: connection.id,
      message: "Conversa criada com sucesso.",
    });
  } catch (error: any) {
    console.error("[vercel-http] create new contact conversation failed:", error);
    return sendJson(res, 500, { success: false, message: error?.message || "Erro ao criar conversa." });
  }
}

async function handleAgentConversationStatus(req: any, res: any) {
  const user = await requireJwtUser(req, res);
  if (!user) return;

  try {
    const conversationId = String(req.params?.conversationId || "").trim();
    const conversation = await getConversationForUser(user.id, conversationId);
    if (!conversation) {
      return sendJson(res, 404, { message: "Conversation not found" });
    }

    const accessPayload = await buildAccessStatusPayloadForUser(user.id);
    const disabledResult = await getPool().query(
      "SELECT conversation_id FROM agent_disabled_conversations WHERE conversation_id = $1 LIMIT 1",
      [conversationId],
    );
    const agentConfigResult = await getPool().query(
      "SELECT is_active AS \"isActive\" FROM ai_agent_config WHERE user_id = $1 LIMIT 1",
      [user.id],
    );
    const businessConfigResult = await getPool().query(
      "SELECT is_active AS \"isActive\" FROM business_agent_configs WHERE user_id = $1 LIMIT 1",
      [user.id],
    );
    const flow2Result = await getPool().query(
      `SELECT id
         FROM flow2_leona_flows
        WHERE user_id = $1
          AND is_active = true
          AND COALESCE(is_archived, false) = false
        LIMIT 1`,
      [user.id],
    );

    const isGroup = isGroupConversationRow(conversation);
    const isDisabled = disabledResult.rows.length > 0 || isGroup;
    const isExcluded = await isNumberExcludedForUser(user.id, conversation.contactNumber, false);
    const isConnectionAiEnabled = conversation.aiEnabled !== false;
    const isGlobalAgentActive = agentConfigResult.rows[0]?.isActive === true;
    const isBusinessAgentActive = businessConfigResult.rows[0]?.isActive === true;
    const isFlow2Active = flow2Result.rows.length > 0;
    const canRespond =
      !accessPayload.shouldBlock &&
      !isDisabled &&
      !isExcluded &&
      isConnectionAiEnabled &&
      (isFlow2Active || (isGlobalAgentActive && isBusinessAgentActive));

    let blockSource: string | null = null;
    let blockReason: string | null = null;
    if (accessPayload.shouldBlock) {
      blockSource = String(accessPayload.blockReason || "access_blocked");
      blockReason = String(accessPayload.message || "Regularize a assinatura para reativar a IA.");
    } else if (isGroup) {
      blockSource = "group";
      blockReason = "Grupos ficam em modo manual. A IA nao responde nesse tipo de conversa.";
    } else if (isExcluded) {
      blockSource = "exclusion_list";
      blockReason = "Numero na lista de exclusao. A IA nao responde automaticamente para este contato.";
    } else if (isDisabled) {
      blockSource = "conversation";
      blockReason = "A IA esta desativada somente nesta conversa.";
    } else if (!isConnectionAiEnabled) {
      blockSource = "connection";
      blockReason = "A IA esta desligada nesta conexao do WhatsApp.";
    } else if (!isFlow2Active && !isGlobalAgentActive) {
      blockSource = "global_agent";
      blockReason = "O agente global esta desativado em Meu Agente IA.";
    } else if (!isFlow2Active && !isBusinessAgentActive) {
      blockSource = "business_agent";
      blockReason = "A IA operacional esta desativada nas configuracoes do agente.";
    }

    return sendJson(res, 200, {
      isDisabled,
      isConnectionAiEnabled,
      isGlobalAgentActive,
      isBusinessAgentActive,
      isFlow2Active,
      isExcluded,
      canRespond,
      blockSource,
      blockReason,
      accessStatus: accessPayload.accessStatus,
      accessBlockReason: accessPayload.blockReason,
      conversationId,
    });
  } catch (error: any) {
    console.error("[vercel-http] agent status failed:", error);
    return sendJson(res, 500, { message: error?.message || "Failed to get agent status" });
  }
}

async function handleAgentConversationToggle(req: any, res: any) {
  const user = await requireJwtUser(req, res);
  if (!user) return;

  try {
    const conversationId = String(req.params?.conversationId || "").trim();
    const body = await readJsonBody(req);
    const disable = body.disable === true;
    const conversation = await getConversationForUser(user.id, conversationId);
    if (!conversation) {
      return sendJson(res, 404, { message: "Conversation not found" });
    }
    if (isGroupConversationRow(conversation)) {
      return sendJson(res, 400, { message: "Grupos ficam em modo manual. A IA nao pode ser alterada neles." });
    }

    if (disable) {
      const configResult = await getPool().query(
        "SELECT auto_reactivate_minutes AS \"autoReactivateMinutes\" FROM ai_agent_config WHERE user_id = $1 LIMIT 1",
        [user.id],
      );
      const autoReactivateMinutes = normalizeAutoReactivateMinutes(configResult.rows[0]?.autoReactivateMinutes);
      await getPool().query(
        `
          INSERT INTO agent_disabled_conversations (
            conversation_id,
            owner_last_reply_at,
            auto_reactivate_after_minutes,
            client_has_pending_message,
            client_last_message_at
          )
          VALUES ($1, NOW(), $2, false, NULL)
          ON CONFLICT (conversation_id) DO UPDATE SET
            owner_last_reply_at = NOW(),
            auto_reactivate_after_minutes = EXCLUDED.auto_reactivate_after_minutes,
            client_has_pending_message = false
        `,
        [conversationId, autoReactivateMinutes],
      );
    } else {
      await getPool().query("DELETE FROM agent_disabled_conversations WHERE conversation_id = $1", [conversationId]);
    }

    return sendJson(res, 200, { success: true, isDisabled: disable });
  } catch (error: any) {
    console.error("[vercel-http] agent toggle failed:", error);
    return sendJson(res, 500, { message: error?.message || "Failed to toggle agent" });
  }
}

function extractSentMediaNamesFromRows(rows: MessageRow[], mediaLibrary?: any[]) {
  const names = new Set<string>();
  const addMatches = (value: unknown) => {
    const text = String(value || "");
    const patterns = [
      /\[FLOW:([^:\]\s]+)(?::[^\]]*)?\]/gi,
      /\[(?:MEDIA|MIDIA|ENVIAR_MIDIA):([^\]\s]+)\]/gi,
    ];
    for (const pattern of patterns) {
      let match: RegExpExecArray | null;
      while ((match = pattern.exec(text))) {
        const name = normalizeSimulatorMediaName(match[1]);
        if (name) names.add(name);
      }
    }

    const codeMatch = text.match(/\bC[oó]digo\s*[:#-]?\s*(\d{1,4})\b/i);
    if (codeMatch) {
      const code = codeMatch[1];
      const label = text
        .split(/\r?\n/g)
        .map((line) => repairWebOnlyOutgoingText(line).trim())
        .find((line) => line && !/\bC[oó]digo\b/i.test(line) && !/^valor\b/i.test(line));
      if (label) {
        names.add(normalizeSimulatorMediaName(`CODIGO_${code}_${label}`));
      }
      names.add(normalizeSimulatorMediaName(`CODIGO_${code}`));
    }
  };
  const mediaItemsByUrl = new Map<string, string>();
  const mediaItemsByTextFragment: Array<{ fragment: string; name: string }> = [];
  for (const media of mediaLibrary || []) {
    const name = normalizeSimulatorMediaName(media?.name);
    const url = normalizeWebOnlyOpeningMediaUrl(media?.storageUrl || media?.storage_url);
    if (name && url) {
      mediaItemsByUrl.set(url, name);
    }
    const flowItems = Array.isArray(media?.flowItems || media?.flow_items)
      ? (media?.flowItems || media?.flow_items)
      : [];
    for (const item of flowItems) {
      const itemUrl = normalizeWebOnlyOpeningMediaUrl(item?.storageUrl || item?.storage_url || item?.media_url || item?.mediaUrl);
      if (name && itemUrl) {
        mediaItemsByUrl.set(itemUrl, name);
      }
      const rawTextFragment = String(item?.text || item?.transcription || "")
        .replace(/\{\{[^}]+\}\}/g, " ")
        .replace(/\{[^}]+\}/g, " ")
        .trim();
      const fragment = normalizeWebOnlyOperationalMediaText(rawTextFragment);
      if (name && fragment.length >= 24) {
        mediaItemsByTextFragment.push({ fragment, name });
      }
    }
  }

  for (const row of rows) {
    addMatches(row.text);
    addMatches(row.mediaCaption);
    if (row.fromMe === true && row.isFromAgent === true) {
      const rowText = normalizeWebOnlyOperationalMediaText([row.text, row.mediaCaption].filter(Boolean).join(" "));
      for (const item of mediaItemsByTextFragment) {
        if (rowText.includes(item.fragment)) {
          names.add(item.name);
        }
      }
    }
    if (row.fromMe === true && row.isFromAgent === true && row.mediaUrl) {
      const sentName = mediaItemsByUrl.get(normalizeWebOnlyOpeningMediaUrl(row.mediaUrl));
      if (sentName) names.add(sentName);
    }
  }

  return Array.from(names);
}

function inferWebOnlyAgenteZapFunnelSentMediasFromPriorInbound(params: {
  config: any;
  rowsBeforeTarget: MessageRow[];
  targetText: string;
  sentMedias: string[];
}) {
  const sentMedias = [...(params.sentMedias || [])];
  if (hasWebOnlyGreetingOpeningAlreadySent(sentMedias)) {
    return sentMedias;
  }

  const prompt = normalizeWebOnlyOperationalMediaText(params.config?.prompt || "");
  if (!/\bagente\s*zap\b|\bagentezap\b/.test(prompt)) {
    return sentMedias;
  }

  const hasPriorClientMessage = (params.rowsBeforeTarget || []).some((row) =>
    row.fromMe !== true &&
    Boolean(getWebOnlyIncomingMessageContent(row)),
  );
  if (!hasPriorClientMessage) {
    return sentMedias;
  }

  return [...sentMedias, WEB_ONLY_GREETING_FLOW_NAME];
}

function normalizeOutgoingWhatsAppMediaMimeType(mediaType: string, mimeType?: string | null) {
  const raw = String(mimeType || "").trim();
  if (!raw) return undefined;
  if (String(mediaType || "").toLowerCase() !== "audio") {
    return raw;
  }
  const normalized = raw.toLowerCase().replace(/\s+/g, " ");
  if (
    normalized === "audio/ogg" ||
    normalized === "application/ogg" ||
    normalized === "audio/opus" ||
    normalized === "audio/ogg;codecs=opus" ||
    normalized === "audio/ogg; codecs=opus"
  ) {
    return "audio/ogg; codecs=opus";
  }
  return raw;
}

async function hasRecentlyPersistedWebOnlyAgentMediaAction(conversationId: string, action: any) {
  const mediaUrl = normalizeWebOnlyOpeningMediaUrl(action?.media_url || action?.mediaUrl || "");
  if (!conversationId || !mediaUrl) return false;
  try {
    const result = await getPool().query(
      `
        SELECT id, media_url
        FROM messages
        WHERE conversation_id = $1
          AND from_me = true
          AND COALESCE(is_from_agent, false) = true
          AND media_url IS NOT NULL
          AND created_at >= NOW() - INTERVAL '10 minutes'
        ORDER BY created_at DESC
        LIMIT 20
      `,
      [conversationId],
    );
    return result.rows.some((row) => normalizeWebOnlyOpeningMediaUrl(row?.media_url) === mediaUrl);
  } catch (error) {
    console.warn("[vercel-http] failed to verify persisted media before retry", {
      conversationId,
      error,
    });
    return false;
  }
}

function isWebOnlyStrictFunnelMediaAction(action: any) {
  const mediaName = normalizeSimulatorMediaName(action?.media_name || action?.mediaName);
  return (
    mediaName === WEB_ONLY_GREETING_FLOW_NAME ||
    mediaName === "MENSAGEM_DE_INICIO_QUANDO_O_CLIENTE_VEM_CONVERSAR" ||
    mediaName === "AUDIO_EXPLICACAO_AGENTEZAP" ||
    mediaName === "TERCEIRA_ETAPA"
  );
}

function getWebOnlyStrictFunnelMediaLockKey(conversationId: string, action: any) {
  const mediaUrl = normalizeWebOnlyOpeningMediaUrl(action?.media_url || action?.mediaUrl || "");
  const mediaName = normalizeSimulatorMediaName(action?.media_name || action?.mediaName);
  const rawKey = `${conversationId}:${mediaName}:${mediaUrl}`;
  return `strict-funnel-media:${createHash("sha256").update(rawKey).digest("hex").slice(0, 48)}`;
}

async function tryClaimWebOnlyStrictFunnelMediaLock(userId: string, conversationId: string, action: any) {
  if (!isWebOnlyStrictFunnelMediaAction(action)) {
    return true;
  }
  const mediaUrl = normalizeWebOnlyOpeningMediaUrl(action?.media_url || action?.mediaUrl || "");
  if (!conversationId || !mediaUrl) {
    return true;
  }
  try {
    const dedupKey = getWebOnlyStrictFunnelMediaLockKey(conversationId, action);
    const result = await getPool().query(
      `
        INSERT INTO message_deduplication (
          dedup_key,
          user_id,
          conversation_id,
          message_type,
          source,
          content_hash,
          created_at,
          expires_at
        )
        VALUES ($1, $2, $3, 'strict_funnel_media', 'vercel_strict_funnel_media', $4, NOW(), NOW() + INTERVAL '10 minutes')
        ON CONFLICT (dedup_key) DO UPDATE
        SET user_id = EXCLUDED.user_id,
            conversation_id = EXCLUDED.conversation_id,
            content_hash = EXCLUDED.content_hash,
            created_at = NOW(),
            expires_at = NOW() + INTERVAL '10 minutes'
        WHERE message_deduplication.expires_at <= NOW()
        RETURNING dedup_key
      `,
      [dedupKey, userId, conversationId, createHash("sha256").update(dedupKey).digest("hex")],
    );
    return result.rows.length > 0;
  } catch (error: any) {
    if (error?.code === "42P01" || error?.code === "42703" || error?.code === "42P10") {
      console.warn("[vercel-http] strict funnel media lock unavailable; continuing without lock:", error);
      return true;
    }
    throw error;
  }
}

function isRetryableGatewaySendError(error: unknown) {
  const message = error instanceof Error ? error.message : String(error);
  const normalized = message.toLowerCase();
  return (
    normalized.includes("fetch failed") ||
    normalized.includes("timed out") ||
    normalized.includes("timeout") ||
    normalized.includes("socket hang up") ||
    normalized.includes("econnreset") ||
    normalized.includes("502") ||
    normalized.includes("503") ||
    normalized.includes("504") ||
    normalized.includes("bad gateway")
  );
}

async function sendWebOnlyAgentTextViaGateway(
  connectionId: string,
  conversation: ConversationSummaryRow,
  text: string,
  source = "agent",
) {
  const normalizedText = repairWebOnlyOutgoingText(text);
  if (!normalizedText) return null;
  const maxAttempts = 3;
  for (let attempt = 1; attempt <= maxAttempts; attempt += 1) {
    try {
      return await sendGatewayInstanceText(connectionId, {
        conversationId: conversation.id,
        text: normalizedText,
        to: conversation.contactNumber || undefined,
        contactName: conversation.contactName || undefined,
        isFromAgent: true,
        source,
        acceptQueued: false,
      });
    } catch (error) {
      if (!isRetryableGatewaySendError(error) || attempt >= maxAttempts) {
        throw error;
      }
      await wait(1000 * attempt);
      console.warn("[vercel-http] retrying gateway text action after transient failure", {
        conversationId: conversation.id,
        connectionId,
        attempt,
        maxAttempts,
        message: error instanceof Error ? error.message : String(error),
      });
    }
  }
  return null;
}

async function persistWebOnlyAgentSentTextFallback(
  conversation: ConversationSummaryRow,
  text: string,
  sendResult: any,
) {
  const normalizedText = repairWebOnlyOutgoingText(text).trim();
  if (!normalizedText) return;
  const providedMessageId = String(sendResult?.messageId || sendResult?.id || "").trim();
  const fallbackHash = createHash("sha256")
    .update(`${conversation.id}:${normalizedText}:${Date.now()}`)
    .digest("hex")
    .slice(0, 18);
  const messageId = providedMessageId || `agent-text-${fallbackHash}`;
  const timestamp = new Date().toISOString();

  await getPool().query(
    `
      INSERT INTO messages (
        conversation_id,
        message_id,
        from_me,
        text,
        timestamp,
        status,
        is_from_agent,
        created_at
      )
      SELECT $1, $2, true, $3, $4, 'sent', true, NOW()
      WHERE NOT EXISTS (
        SELECT 1 FROM messages WHERE conversation_id = $1 AND message_id = $2
      )
    `,
    [conversation.id, messageId, normalizedText, timestamp],
  );

  await getPool().query(
    `
      UPDATE conversations
      SET last_message_text = $2,
          last_message_time = $3,
          last_message_from_me = true,
          has_replied = true,
          updated_at = NOW()
      WHERE id = $1
    `,
    [conversation.id, normalizedText, timestamp],
  );
}

async function sendWebOnlyAgentActionViaGateway(
  userId: string,
  connectionId: string,
  conversation: ConversationSummaryRow,
  action: any,
) {
  if (action?.type === "send_text") {
    const result = await sendWebOnlyAgentTextViaGateway(connectionId, conversation, action.text, "agent");
    await persistWebOnlyAgentSentTextFallback(conversation, String(action.text || ""), result).catch((error) => {
      console.warn("[vercel-http] failed to persist sent agent text action fallback:", error);
    });
    return result;
  }

  const mediaUrl = String(action?.media_url || action?.mediaUrl || "").trim();
  if (!mediaUrl) return null;
  const mediaType = String(action?.media_type || action?.mediaType || "image").toLowerCase();
  const normalizedType =
    mediaType === "audio" || mediaType === "video" || mediaType === "document" ? mediaType : "image";
  const rawMimeType = String(action?.mime_type || action?.mimeType || "").trim();
  const mediaUrlPath = mediaUrl.split("?", 1)[0].toLowerCase();
  const inferredAudioMimeType =
    mediaUrlPath.endsWith(".mp3")
      ? "audio/mpeg"
      : mediaUrlPath.endsWith(".m4a")
        ? "audio/mp4"
        : mediaUrlPath.endsWith(".aac")
          ? "audio/aac"
          : mediaUrlPath.endsWith(".amr")
            ? "audio/amr"
            : mediaUrlPath.endsWith(".ogg") || mediaUrl.startsWith("data:audio/ogg")
              ? "audio/ogg; codecs=opus"
              : undefined;
  const mediaMimeType = normalizeOutgoingWhatsAppMediaMimeType(
    normalizedType,
    rawMimeType || inferredAudioMimeType,
  );
  const explicitIsPtt =
    action?.is_ptt === undefined && action?.isPtt === undefined
      ? null
      : normalizeBoolean(action?.isPtt ?? action?.is_ptt);
  const shouldUsePtt =
    normalizedType === "audio"
      ? explicitIsPtt ?? String(mediaMimeType || "").toLowerCase() === "audio/ogg; codecs=opus"
      : false;
  const payload = {
    conversationId: conversation.id,
    type: normalizedType,
    data: mediaUrl,
    mimetype: mediaMimeType,
    filename: action?.file_name || action?.fileName || undefined,
    caption: repairWebOnlyOutgoingText(action?.caption) || undefined,
    trackingMediaName: action?.media_name || action?.mediaName || undefined,
    ptt: shouldUsePtt,
    to: conversation.contactNumber || undefined,
    contactName: conversation.contactName || undefined,
    isFromAgent: true,
    source: "agent",
  };
  const mediaName = String(action?.media_name || action?.mediaName || "").trim() || null;
  if (isWebOnlyStrictFunnelMediaAction(action)) {
    if (await hasRecentlyPersistedWebOnlyAgentMediaAction(conversation.id, action)) {
      return {
        success: true,
        alreadyPersisted: true,
        skippedDuplicateStrictFunnelMedia: true,
        mediaName,
      };
    }
    const claimed = await tryClaimWebOnlyStrictFunnelMediaLock(userId, conversation.id, action);
    if (!claimed) {
      await wait(2000);
      return {
        success: true,
        alreadyClaimed: true,
        skippedDuplicateStrictFunnelMedia: true,
        mediaName,
      };
    }
  }
  const maxAttempts = 3;
  for (let attempt = 1; attempt <= maxAttempts; attempt += 1) {
    try {
      return await sendGatewayInstanceMedia(connectionId, payload);
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      const retryable = isRetryableGatewaySendError(error);
      if (!retryable || attempt >= maxAttempts) {
        throw error;
      }
      if (isWebOnlyStrictFunnelMediaAction(action)) {
        for (let check = 0; check < 10; check += 1) {
          await wait(2000);
          if (await hasRecentlyPersistedWebOnlyAgentMediaAction(conversation.id, action)) {
            return {
              success: true,
              alreadyPersisted: true,
              skippedRetryAfterTimeout: true,
              mediaName,
            };
          }
        }
        console.warn("[vercel-http] strict funnel media timed out; skipping immediate retry to avoid duplicate send", {
          conversationId: conversation.id,
          connectionId,
          mediaName,
          attempt,
          message,
        });
        return {
          success: true,
          assumedGatewayProcessing: true,
          skippedRetryAfterTimeout: true,
          mediaName,
        };
      }
      await wait(1500 * attempt);
      if (await hasRecentlyPersistedWebOnlyAgentMediaAction(conversation.id, action)) {
        return {
          success: true,
          alreadyPersisted: true,
          skippedRetryAfterTimeout: true,
          mediaName,
        };
      }
      console.warn("[vercel-http] retrying gateway media action after transient failure", {
        conversationId: conversation.id,
        connectionId,
        mediaName,
        attempt,
        maxAttempts,
        message,
      });
    }
  }
  return null;
}

function isSuccessfulGatewaySendResult(result: unknown): boolean {
  if (!result || typeof result !== "object") {
    return false;
  }
  const payload = result as Record<string, unknown>;
  return payload.success !== false && payload.blocked !== true;
}

function isNonFatalVisualFlowActionBlock(action: any, result: unknown): boolean {
  if (!result || typeof result !== "object") {
    return false;
  }
  const payload = result as Record<string, unknown>;
  if (payload.blocked !== true) {
    return false;
  }
  if (String(action?.type || "") !== "send_text") {
    return false;
  }
  return String(action?.opening_flow_source || "") !== "greeting";
}

function hasWebOnlyActionTiming(action: any): boolean {
  return (
    resolveWebOnlyRangeSeconds(action?.delay_seconds) !== null ||
    resolveWebOnlyRangeSeconds(action?.delaySeconds) !== null ||
    resolveWebOnlyRangeSeconds(action?.delay_range_seconds) !== null ||
    resolveWebOnlyRangeSeconds(action?.delayRangeSeconds) !== null ||
    resolveWebOnlyRangeSeconds(action?.typing_seconds) !== null ||
    resolveWebOnlyRangeSeconds(action?.typingSeconds) !== null ||
    resolveWebOnlyRangeSeconds(action?.typing_range_seconds) !== null ||
    resolveWebOnlyRangeSeconds(action?.typingRangeSeconds) !== null
  );
}

function getWebOnlyActionDelaySeconds(action: any): number {
  return (
    resolveWebOnlyRangeSeconds(action?.delay_seconds) ??
    resolveWebOnlyRangeSeconds(action?.delaySeconds) ??
    resolveWebOnlyRangeSeconds(action?.delay_range_seconds) ??
    resolveWebOnlyRangeSeconds(action?.delayRangeSeconds) ??
    0
  );
}

function getWebOnlyActionTypingSeconds(action: any): number {
  return (
    resolveWebOnlyRangeSeconds(action?.typing_seconds) ??
    resolveWebOnlyRangeSeconds(action?.typingSeconds) ??
    resolveWebOnlyRangeSeconds(action?.typing_range_seconds) ??
    resolveWebOnlyRangeSeconds(action?.typingRangeSeconds) ??
    0
  );
}

async function applyWebOnlyAgentActionTimingViaGateway(
  connectionId: string,
  conversation: ConversationSummaryRow,
  action: any,
) {
  const delaySeconds = getWebOnlyActionDelaySeconds(action);
  if (delaySeconds > 0) {
    await wait(delaySeconds * 1000);
  }

  const typingSeconds = getWebOnlyActionTypingSeconds(action);
  if (typingSeconds <= 0) {
    return;
  }

  const phoneNumber = String(conversation.contactNumber || "").trim();
  if (!phoneNumber) {
    await wait(typingSeconds * 1000);
    return;
  }

  const mediaType = String(action?.media_type || action?.mediaType || "").toLowerCase();
  const presence = mediaType === "audio" ? "recording" : "composing";
  try {
    await sendGatewayInstanceContactPresence(connectionId, { phoneNumber, presence });
    await wait(typingSeconds * 1000);
    await sendGatewayInstanceContactPresence(connectionId, { phoneNumber, presence: "paused" });
  } catch (error) {
    console.warn("[vercel-http] failed to apply flow action presence timing:", error);
    await wait(typingSeconds * 1000);
  }
}

async function runWebOnlyActionBatchWithConcurrency(
  actions: any[],
  limit: number,
  worker: (action: any) => Promise<unknown>,
) {
  let nextIndex = 0;
  let sentCount = 0;
  const failures: any[] = [];
  const concurrency = Math.max(1, Math.min(Number.isFinite(limit) ? limit : 4, 8));

  await Promise.all(
    Array.from({ length: Math.min(concurrency, actions.length) }, async () => {
      while (nextIndex < actions.length) {
        const action = actions[nextIndex++];
        try {
          const sent = await worker(action);
          if (isSuccessfulGatewaySendResult(sent)) {
            sentCount += 1;
          } else {
            failures.push({
              type: action?.type || null,
              mediaName: action?.media_name || action?.mediaName || null,
              result: sent || null,
            });
          }
        } catch (error) {
          console.warn("[vercel-http] failed to send agent action via gateway:", error);
          failures.push({
            type: action?.type || null,
            mediaName: action?.media_name || action?.mediaName || null,
            error: error instanceof Error ? error.message : String(error),
          });
        }
      }
    }),
  );

  return { sentCount, failures };
}

async function sendWebOnlyAgentActionsViaGateway(
  userId: string,
  connectionId: string,
  conversation: ConversationSummaryRow,
  actions: any[],
  options: { sendGuard?: WebOnlyAgentSendGuard } = {},
) {
  const mediaConcurrency = Number.parseInt(process.env.AGENT_MEDIA_SEND_CONCURRENCY || "2", 10) || 2;
  const catalogMediaConcurrency = Number.parseInt(process.env.AGENT_CATALOG_MEDIA_SEND_CONCURRENCY || "3", 10) || 3;
  let sentCount = 0;
  let pendingMediaActions: any[] = [];
  const failures: any[] = [];
  let abortedOpeningFlow = false;
  let skipped: string | null = null;
  const hasGreetingOpeningFlow = hasWebOnlyGreetingOpeningActions(actions);

  const blockIfGuarded = async (phase: string, action?: any) => {
    if (!options.sendGuard) return false;
    const guard = await options.sendGuard({ phase, action });
    if (!guard.blocked) return false;
    skipped = guard.skipped || "agent_send_guard_blocked";
    failures.push({
      type: action?.type || null,
      mediaName: action?.media_name || action?.mediaName || null,
      blocked: true,
      phase,
      reason: guard.reason || skipped,
    });
    console.info("[vercel-http] blocked agent action before gateway send", {
      conversationId: conversation.id,
      connectionId,
      phase,
      skipped,
      reason: guard.reason || null,
    });
    return true;
  };

  if (hasGreetingOpeningFlow) {
    const claimed = await tryClaimWebOnlyOpeningFlowLock(userId, conversation.id);
    if (!claimed) {
      return {
        sentCount: 0,
        failures,
        abortedOpeningFlow: false,
        skipped: "opening_flow_locked",
      };
    }
  }

  try {
    if (actions.some(hasWebOnlyActionTiming)) {
      for (const action of actions) {
        try {
          if (await blockIfGuarded("timed_action_before_delay", action)) {
            break;
          }
          await applyWebOnlyAgentActionTimingViaGateway(connectionId, conversation, action);
          if (await blockIfGuarded("timed_action_before_send", action)) {
            break;
          }
          const sent = await sendWebOnlyAgentActionViaGateway(userId, connectionId, conversation, action);
          if (isSuccessfulGatewaySendResult(sent)) {
            sentCount += 1;
            continue;
          }
          if (isNonFatalVisualFlowActionBlock(action, sent)) {
            console.info("[vercel-http] ignoring blocked visual flow text action for state progression", {
              conversationId: conversation.id,
              connectionId,
              mediaName: action?.media_name || action?.mediaName || null,
              textPreview: String(action?.text || "").slice(0, 80),
              result: sent,
            });
            continue;
          }

          failures.push({
            type: action?.type || null,
            mediaName: action?.media_name || action?.mediaName || null,
            result: sent || null,
            abortedOpeningFlow: action?.type === "send_text" && action?.opening_flow_source === "greeting",
          });

          if (action?.type === "send_text" && action?.opening_flow_source === "greeting") {
            abortedOpeningFlow = true;
            break;
          }
        } catch (error) {
          console.warn("[vercel-http] failed to send timed agent action via gateway:", error);
          failures.push({
            type: action?.type || null,
            mediaName: action?.media_name || action?.mediaName || null,
            error: error instanceof Error ? error.message : String(error),
            abortedOpeningFlow: action?.type === "send_text" && action?.opening_flow_source === "greeting",
          });
          if (action?.type === "send_text" && action?.opening_flow_source === "greeting") {
            abortedOpeningFlow = true;
            break;
          }
        }
      }

      return { sentCount, failures, abortedOpeningFlow, skipped };
    }

    const flushPendingMedia = async () => {
      if (pendingMediaActions.length === 0) return;
      const batch = pendingMediaActions;
      pendingMediaActions = [];
      const batchHasCatalogMedia = batch.some((action) => String(action?.source || "") === "product_catalog");
      const effectiveCatalogConcurrency = batchHasCatalogMedia && batch.length > 10
        ? Math.max(1, Math.min(catalogMediaConcurrency, 4))
        : 1;

      if (options.sendGuard) {
        if (batchHasCatalogMedia && effectiveCatalogConcurrency > 1) {
          if (await blockIfGuarded("catalog_media_batch_before_send", batch[0])) {
            return;
          }
          const batchResult = await runWebOnlyActionBatchWithConcurrency(batch, effectiveCatalogConcurrency, async (action) => {
            if (skipped) {
              return { skipped };
            }
            return sendWebOnlyAgentActionViaGateway(userId, connectionId, conversation, action);
          });
          sentCount += batchResult.sentCount;
          failures.push(...batchResult.failures);
          return;
        }

        for (const action of batch) {
          if (await blockIfGuarded("media_action_before_send", action)) {
            break;
          }
          try {
            const sent = await sendWebOnlyAgentActionViaGateway(userId, connectionId, conversation, action);
            if (isSuccessfulGatewaySendResult(sent)) {
              sentCount += 1;
            } else {
              failures.push({
                type: action?.type || null,
                mediaName: action?.media_name || action?.mediaName || null,
                result: sent || null,
              });
            }
          } catch (error) {
            console.warn("[vercel-http] failed to send agent action via gateway:", error);
            failures.push({
              type: action?.type || null,
              mediaName: action?.media_name || action?.mediaName || null,
              error: error instanceof Error ? error.message : String(error),
            });
          }
        }
        return;
      }

      const batchResult = await runWebOnlyActionBatchWithConcurrency(batch, batchHasCatalogMedia ? effectiveCatalogConcurrency : mediaConcurrency, (action) =>
        sendWebOnlyAgentActionViaGateway(userId, connectionId, conversation, action),
      );
      sentCount += batchResult.sentCount;
      failures.push(...batchResult.failures);
    };

    for (const action of actions) {
      if (action?.type === "send_text") {
        await flushPendingMedia();
        if (skipped) {
          break;
        }
        if (await blockIfGuarded("text_action_before_send", action)) {
          break;
        }
        try {
          const sent = await sendWebOnlyAgentActionViaGateway(userId, connectionId, conversation, action);
          if (isSuccessfulGatewaySendResult(sent)) {
            sentCount += 1;
          } else if (isNonFatalVisualFlowActionBlock(action, sent)) {
            console.info("[vercel-http] ignoring blocked visual flow text action for state progression", {
              conversationId: conversation.id,
              connectionId,
              mediaName: action?.media_name || action?.mediaName || null,
              textPreview: String(action?.text || "").slice(0, 80),
              result: sent,
            });
          } else if (action?.opening_flow_source === "greeting") {
            console.warn("[vercel-http] opening flow text was not sent; skipping remaining opening flow media", {
              conversationId: conversation.id,
              connectionId,
              mediaName: action?.media_name || action?.mediaName || null,
              result: sent,
            });
            pendingMediaActions = [];
            failures.push({
              type: action?.type || null,
              mediaName: action?.media_name || action?.mediaName || null,
              result: sent || null,
              abortedOpeningFlow: true,
            });
            abortedOpeningFlow = true;
            break;
          }
        } catch (error) {
          console.warn("[vercel-http] failed to send agent text action via gateway:", error);
          failures.push({
            type: action?.type || null,
            mediaName: action?.media_name || action?.mediaName || null,
            error: error instanceof Error ? error.message : String(error),
            abortedOpeningFlow: action?.opening_flow_source === "greeting",
          });
          if (action?.opening_flow_source === "greeting") {
            pendingMediaActions = [];
            abortedOpeningFlow = true;
            break;
          }
        }
        continue;
      }

      pendingMediaActions.push(action);
    }

    if (!skipped) {
      await flushPendingMedia();
    }
    return { sentCount, failures, abortedOpeningFlow, skipped };
  } finally {
    if (hasGreetingOpeningFlow) {
      await releaseWebOnlyOpeningFlowLock(conversation.id);
    }
  }
}

async function persistVisualFlowStateFromAgentPayload(params: {
  userId: string;
  conversationId: string;
  payload: any;
  history: any[];
}) {
  const flowState = params.payload?.flowState;
  if (!flowState || typeof flowState !== "object") {
    return;
  }
  await persistWebOnlyVisualFlowState({
    userId: params.userId,
    conversationId: params.conversationId,
    flowId: String(flowState.flowId || ""),
    selectedStepId: flowState.selectedStepId || null,
    pendingStepId: flowState.pendingStepId || null,
    completed: flowState.completed === true,
    history: params.history,
  });
}

async function handleAgentRespond(req: any, res: any) {
  const user = await requireJwtUser(req, res);
  if (!user) return;

  try {
    const conversationId = String(req.params?.conversationId || "").trim();
    const conversation = await getConversationForUser(user.id, conversationId);
    if (!conversation) {
      return sendJson(res, 404, { success: false, message: "Conversa nao encontrada" });
    }
    if (isGroupConversationRow(conversation)) {
      return sendJson(res, 400, { success: false, message: "Grupos ficam em modo manual." });
    }
    if (!shouldUseGateway(conversation)) {
      return sendJson(res, 409, { success: false, message: "Conexao fora do runtime Vercel + gateway." });
    }

    const statusResult = await handleAgentConversationStatusForInternal(user.id, conversationId, conversation);
    if (!statusResult.canRespond) {
      return sendJson(res, 400, {
        success: false,
        message: statusResult.blockReason || "A IA nao esta habilitada para esta conversa.",
      });
    }

    const messagesResult = await getPool().query(
      `
        SELECT
          id,
          message_id AS "messageId",
          from_me AS "fromMe",
          text,
          timestamp,
          status,
          is_from_agent AS "isFromAgent",
          media_type AS "mediaType",
          media_url AS "mediaUrl",
          media_mime_type AS "mediaMimeType",
          media_duration AS "mediaDuration",
          media_caption AS "mediaCaption",
          media_key AS "mediaKey",
          direct_path AS "directPath",
          media_url_original AS "mediaUrlOriginal",
          created_at AS "createdAt"
        FROM (
          SELECT
            id,
            message_id,
            from_me,
            text,
            timestamp,
            status,
            is_from_agent,
            media_type,
            media_url,
            media_mime_type,
            media_duration,
            media_caption,
            media_key,
            direct_path,
            media_url_original,
            created_at
          FROM messages
          WHERE conversation_id = $1
          ORDER BY timestamp DESC NULLS LAST, created_at DESC NULLS LAST, id DESC
          LIMIT 80
        ) recent_messages
        ORDER BY timestamp ASC NULLS FIRST, created_at ASC NULLS FIRST, id ASC
      `,
      [conversationId],
    );
    const rows = messagesResult.rows as MessageRow[];
    const lastIncoming = [...rows].reverse().find((row) => {
      if (row.fromMe) return false;
      const content = getWebOnlyIncomingMessageContent(row);
      return Boolean(
        content &&
          (!isIgnorableGatewayIncomingText(content) || isInitialMetaStubFallbackCandidate(content)),
      );
    });
    if (!lastIncoming) {
      return sendJson(res, 400, { success: false, message: "Nao ha mensagens do cliente para processar." });
    }

    const targetIndex = rows.findIndex((row) => row.id === lastIncoming.id);
    const rowsBeforeTarget = targetIndex >= 0
      ? rows.slice(0, targetIndex)
      : rows.filter((row) => compareMessageRows(row, lastIncoming) < 0);
    const incomingBurst = buildWebOnlyIncomingBurstForAgent(rows, lastIncoming);
    const rowsBeforePrompt = incomingBurst.firstIndex >= 0
      ? rows.slice(0, incomingBurst.firstIndex)
      : rowsBeforeTarget;
    const history = mapMessageRowsToWebOnlyHistory(rowsBeforePrompt.slice(-16));
    const rawTargetText = incomingBurst.text || getWebOnlyIncomingMessageContent(lastIncoming);
    const normalizedTarget = normalizeGatewayIncomingStubTextForAI(rawTargetText, rowsBeforeTarget);
    if (isIgnorableGatewayIncomingText(normalizedTarget.text)) {
      return sendJson(res, 400, { success: false, message: "A mensagem mais recente do cliente e tecnica e nao acionavel." });
    }
    if (normalizedTarget.wasNormalized) {
      await persistNormalizedGatewayStubText({
        conversationId,
        targetIncoming: lastIncoming,
        originalText: rawTargetText,
        normalizedText: normalizedTarget.text,
      });
    }
    const manualReplySendGuard = createWebOnlyManualReplySendGuard(user.id, conversation, lastIncoming);

    const openingConfigResult = await getPool().query(
      `
        SELECT
          prompt,
          message_split_chars,
          custom_greeting,
          greeting_variation,
          greeting_enabled,
          business_hours_enabled,
          business_hours,
          off_hours_message_enabled,
          off_hours_variation,
          off_hours_message,
          ai_signature_enabled,
          ai_signature
        FROM ai_agent_config
        WHERE user_id = $1
        LIMIT 1
      `,
      [user.id],
    );
    const mediaLibraryForOpening = await loadWebOnlyAgentMediaLibrary(user.id);
    const pendingOpeningFlow = resolveWebOnlyPendingOpeningFlowActions({
    config: openingConfigResult.rows[0] || null,
    mediaLibrary: mediaLibraryForOpening,
    contactName: conversation.contactName || undefined,
    rowsBeforeTarget,
    currentTargetIsIncomingReply: true,
  });
    if (pendingOpeningFlow?.skipped) {
      return sendJson(res, 409, {
        success: false,
        message: "A abertura da aba Info ainda esta em andamento. Tente novamente em alguns instantes.",
        skipped: pendingOpeningFlow.skipped,
        openingFlowProgress: pendingOpeningFlow.progress,
        resumeAfterSeconds: pendingOpeningFlow.resumeAfterSeconds,
      });
    }
    if (pendingOpeningFlow && pendingOpeningFlow.actions.length > 0) {
      const actionSendResult = await sendWebOnlyAgentActionsViaGateway(
        user.id,
        conversation.connectionId,
        conversation,
        pendingOpeningFlow.actions,
        { sendGuard: manualReplySendGuard },
      );
      if (actionSendResult.sentCount > 0) {
        await scheduleWebOnlyFollowupAfterCompanyMessage(user.id, conversationId);
      }
      return sendJson(res, actionSendResult.sentCount > 0 ? 200 : 409, {
        success: actionSendResult.sentCount > 0,
        message: actionSendResult.sentCount > 0
          ? "Sequencia da aba Info retomada."
          : "Nao foi possivel retomar a sequencia da aba Info agora.",
        sentCount: actionSendResult.sentCount,
        skipped: actionSendResult.skipped || null,
        actionSendFailures: actionSendResult.failures,
        abortedOpeningFlow: actionSendResult.abortedOpeningFlow,
        openingFlowProgress: pendingOpeningFlow.progress,
      });
    }

    const sentMediasForAgent = inferWebOnlyAgenteZapFunnelSentMediasFromPriorInbound({
      config: openingConfigResult.rows[0] || null,
      rowsBeforeTarget,
      targetText: normalizedTarget.text,
      sentMedias: extractSentMediaNamesFromRows(rowsBeforeTarget, mediaLibraryForOpening),
    });

    const result = await runWebOnlyAgentTestForUser(user.id, {
      message: normalizedTarget.text,
      history,
      contactName: conversation.contactName || undefined,
      contactPhone: conversation.contactNumber || undefined,
      sentMedias: sentMediasForAgent,
      conversationId,
      agendamento3Commit: true,
      flow2DeferStatePersistence: true,
    });
    if (result.status >= 400) {
      return sendJson(res, result.status, { success: false, ...(result.payload as Record<string, unknown>) });
    }

    const payload: any = result.payload || {};
    await persistWebOnlyConversationAttentionAssessment({
      userId: user.id,
      conversation,
      attention: payload.attention,
      sourceLabel: "manual_agent_response",
    });
    const splitResponses = Array.isArray(payload.splitResponses)
      ? payload.splitResponses.map((item: unknown) => repairWebOnlyOutgoingText(item)).filter(Boolean)
      : [];
    const mediaActions = Array.isArray(payload.mediaActions) ? payload.mediaActions : [];

    await persistVisualFlowStateFromAgentPayload({
      userId: user.id,
      conversationId,
      payload,
      history,
    });

    let sentCount = 0;
    let manualReplySkipped: string | null = null;
    for (const text of splitResponses) {
      const guard = await manualReplySendGuard({ phase: "manual_agent_split_text_before_send" });
      if (guard.blocked) {
        manualReplySkipped = guard.skipped || "manual_reply_before_agent_send";
        console.info("[vercel-http] blocked manual-triggered agent text before gateway send", {
          conversationId,
          connectionId: conversation.connectionId,
          skipped: manualReplySkipped,
          reason: guard.reason || null,
        });
        break;
      }
      try {
        await sendWebOnlyAgentTextViaGateway(conversation.connectionId, conversation, text, "agent");
        sentCount += 1;
      } catch (error) {
        console.warn("[vercel-http] failed to send agent text via gateway:", error);
      }
    }
    const actionSendResult = await sendWebOnlyAgentActionsViaGateway(
      user.id,
      conversation.connectionId,
      conversation,
      mediaActions,
      { sendGuard: manualReplySendGuard },
    );
    sentCount += actionSendResult.sentCount;
    if (!manualReplySkipped && actionSendResult.skipped) {
      manualReplySkipped = actionSendResult.skipped;
    }

    if (sentCount === 0) {
      return sendJson(res, 400, {
        success: false,
        message: manualReplySkipped
          ? "A IA nao enviou porque uma resposta manual foi detectada antes do envio."
          : "A IA nao gerou uma resposta utilizavel.",
        skipped: manualReplySkipped,
        actionSendFailures: actionSendResult.failures,
        abortedOpeningFlow: actionSendResult.abortedOpeningFlow,
      });
    }

    if (actionSendResult.failures.length === 0 && actionSendResult.abortedOpeningFlow !== true) {
      await persistFlow2PendingStateFromPayload(payload);
    }

    await analyzeDelivery2ConversationOrderWebOnly({
      conversationId,
      latestAgentReply: [
        ...splitResponses,
        ...mediaActions.map((action: any) => String(action?.text || action?.caption || "").trim()).filter(Boolean),
      ].join("\n"),
    }).catch((error) => {
      console.error("[vercel-http] delivery 2 order decision after manual agent response failed:", error);
    });

    if (!manualReplySkipped) {
      await scheduleWebOnlyFollowupAfterCompanyMessage(user.id, conversationId);
    }

    return sendJson(res, 200, {
      success: true,
      message: manualReplySkipped
        ? "A IA enviou parte da resposta e parou ao detectar resposta manual."
        : "Resposta manual enviada pela IA.",
      skipped: manualReplySkipped,
    });
  } catch (error: any) {
    console.error("[vercel-http] agent respond failed:", error);
    return sendJson(res, 500, { success: false, message: error?.message || "Falha ao responder com IA" });
  }
}

function isInternalGatewayEventAuthorized(req: any): boolean {
  const headerValue =
    req.headers?.["x-wa-gateway-token"] ||
    req.headers?.["X-WA-Gateway-Token"] ||
    "";
  return String(headerValue).trim() === getGatewayInternalToken();
}

function getGatewayEventType(data: any): string {
  return String(data?.event || data?.type || data?.name || "").trim();
}

function getGatewayEventMessageData(data: any): any {
  const direct = data?.messageData || data?.message || data?.data?.message || data?.payload?.message;
  return direct && typeof direct === "object" ? direct : {};
}

function getGatewayEventMessageId(data: any): string {
  const messageData = getGatewayEventMessageData(data);
  return String(messageData?.messageId || messageData?.id || data?.messageId || data?.id || "").trim();
}

function getGatewayEventConversationId(data: any): string {
  return String(
    data?.conversationId ||
      data?.conversation?.id ||
      data?.conversationUpdate?.id ||
      getGatewayEventMessageData(data)?.conversationId ||
      "",
  ).trim();
}

function getGatewayIncomingMessageText(data: any): string {
  const messageData = getGatewayEventMessageData(data);
  return String(
    messageData?.text ||
      messageData?.mediaCaption ||
      data?.text ||
      data?.message ||
      data?.mediaCaption ||
      "",
  ).trim();
}

function isIgnorableGatewayIncomingText(value: unknown): boolean {
  const normalized = String(value || "").trim().toLowerCase();
  if (!normalized) return false;

  const bracketless =
    normalized.startsWith("[") && normalized.endsWith("]")
      ? normalized.slice(1, -1).trim()
      : normalized;

  return (
    bracketless === "mensagem de protocolo" ||
    normalized.startsWith("[whatsapp] mensagem incompleta") ||
    normalized.startsWith("whatsapp mensagem incompleta") ||
    normalized.startsWith("[mensagem nao suportada") ||
    bracketless.startsWith("mensagem nao suportada")
  );
}

function isIncomingGatewayMessageEvent(data: any): boolean {
  const eventType = getGatewayEventType(data);
  const messageData = getGatewayEventMessageData(data);
  const fromMe = messageData?.fromMe ?? data?.fromMe;
  return (
    (eventType === "new_message" || eventType === "message.received" || eventType === "message_received") &&
    fromMe !== true &&
      fromMe !== "true"
  );
}

function isGatewayEventFromAgent(data: any): boolean {
  const messageData = getGatewayEventMessageData(data);
  if (normalizeBoolean(messageData?.isFromAgent ?? messageData?.is_from_agent ?? data?.isFromAgent ?? data?.is_from_agent)) {
    return true;
  }

  const source = String(messageData?.source || data?.source || data?.origin || "").trim().toLowerCase();
  if (!source) {
    return false;
  }

  return (
    source.includes("agent") ||
    source.includes("followup") ||
    source.includes("follow_up") ||
    source.includes("automation") ||
    source.includes("automatic") ||
    source.includes("notification") ||
    source.includes("broadcast") ||
    source.includes("scheduled")
  );
}

function isOutgoingGatewayOwnerMessageEvent(data: any): boolean {
  const eventType = getGatewayEventType(data);
  const messageData = getGatewayEventMessageData(data);
  const fromMe = messageData?.fromMe ?? data?.fromMe;

  return (
    (eventType === "new_message" || eventType === "message.received" || eventType === "message_received") &&
    normalizeBoolean(fromMe) &&
    !isGatewayEventFromAgent(data)
  );
}

function isOutgoingGatewayAgentMessageEvent(data: any): boolean {
  const eventType = getGatewayEventType(data);
  const messageData = getGatewayEventMessageData(data);
  const fromMe = messageData?.fromMe ?? data?.fromMe;

  return (
    (eventType === "new_message" || eventType === "message.received" || eventType === "message_received") &&
    normalizeBoolean(fromMe) &&
    isGatewayEventFromAgent(data)
  );
}

async function persistOutgoingGatewayAgentEventIfNeeded(
  conversation: ConversationSummaryRow,
  data: any,
) {
  const messageData = getGatewayEventMessageData(data);
  const messageId = String(messageData?.messageId || data?.messageId || "").trim();
  if (!messageId) {
    return { inserted: false, reason: "missing_message_id" };
  }

  const rawText = getGatewayManualOutgoingMessageText(data);
  const mediaType = String(messageData?.mediaType || data?.mediaType || "").trim() || null;
  const mediaCaption = messageData?.mediaCaption || data?.mediaCaption || null;
  const mediaLabel =
    mediaType === "audio"
      ? "Audio enviado"
      : mediaType === "image"
        ? "Imagem enviada"
        : mediaType === "video"
          ? "Video enviado"
          : mediaType === "document"
            ? "Documento enviado"
            : "Mensagem do agente";
  const lastMessageText = rawText || String(mediaCaption || "").trim() || mediaLabel;
  const timestampRaw = messageData?.timestamp || data?.timestamp || new Date().toISOString();
  const timestamp = Number.isNaN(new Date(timestampRaw).getTime())
    ? new Date().toISOString()
    : new Date(timestampRaw).toISOString();

  const insertResult = await getPool().query(
    `
      INSERT INTO messages (
        conversation_id,
        message_id,
        from_me,
        text,
        timestamp,
        status,
        is_from_agent,
        media_type,
        media_url,
        media_mime_type,
        media_duration,
        media_caption,
        created_at
      )
      SELECT $1, $2, true, $3, $4, $5, true, $6, $7, $8, $9, $10, NOW()
      WHERE NOT EXISTS (
        SELECT 1 FROM messages WHERE conversation_id = $1 AND message_id = $2
      )
      RETURNING id
    `,
    [
      conversation.id,
      messageId,
      rawText || null,
      timestamp,
      String(messageData?.status || data?.status || "sent"),
      mediaType,
      messageData?.mediaUrl || data?.mediaUrl || null,
      messageData?.mediaMimeType || data?.mediaMimeType || null,
      Number.isFinite(Number(messageData?.mediaDuration)) ? Number(messageData.mediaDuration) : null,
      mediaCaption,
    ],
  );

  await getPool().query(
    `
      UPDATE conversations
      SET last_message_text = $2,
          last_message_time = $3,
          last_message_from_me = true,
          has_replied = true,
          updated_at = NOW()
      WHERE id = $1
    `,
    [conversation.id, lastMessageText, timestamp],
  );

  return {
    inserted: insertResult.rows.length > 0,
    reason: "agent_outgoing_echo",
  };
}

async function isLikelyRecentWebOnlyAgentOutboundEcho(params: {
  conversationId: string;
  messageId: string;
  mediaType: string | null;
}): Promise<boolean> {
  try {
    const existing = await getPool().query(
      `
        SELECT is_from_agent
        FROM messages
        WHERE conversation_id = $1
          AND message_id = $2
          AND from_me = true
        LIMIT 1
      `,
      [params.conversationId, params.messageId],
    );
    if (existing.rows.some((row) => row?.is_from_agent === true)) {
      return true;
    }

    const normalizedMediaType = String(params.mediaType || "").trim().toLowerCase();
    if (!normalizedMediaType) {
      return false;
    }

    const recentAgentJob = await getPool().query(
      `
        SELECT id
        FROM vercel_agent_response_jobs
        WHERE conversation_id = $1
          AND status IN ('pending', 'processing', 'completed')
          AND COALESCE(updated_at, created_at) >= NOW() - INTERVAL '5 minutes'
          AND COALESCE(execute_at, created_at) <= NOW() + INTERVAL '1 minute'
        ORDER BY COALESCE(updated_at, created_at) DESC
        LIMIT 1
      `,
      [params.conversationId],
    );

    return recentAgentJob.rows.length > 0;
  } catch (error: any) {
    if (error?.code === "42P01" || error?.code === "42703") {
      return false;
    }
    console.warn("[vercel-http] failed to infer outbound gateway echo source:", error);
    return false;
  }
}

async function markPausedAgentConversationHasPendingClientMessage(conversationId: string, timestamp: string) {
  await getPool().query(
    `
      UPDATE agent_disabled_conversations
      SET client_has_pending_message = true,
          client_last_message_at = CASE
            WHEN client_last_message_at IS NULL OR client_last_message_at < $2::timestamp THEN $2::timestamp
            ELSE client_last_message_at
          END
      WHERE conversation_id = $1
    `,
    [conversationId, timestamp],
  );
}

function getGatewayManualOutgoingMessageText(data: any): string {
  const messageData = getGatewayEventMessageData(data);
  return String(
    messageData?.text ||
      messageData?.mediaCaption ||
      data?.text ||
      data?.message ||
      data?.mediaCaption ||
      "",
  ).trim();
}

async function persistOutgoingGatewayOwnerEventAndPauseIfNeeded(
  userId: string,
  conversation: ConversationSummaryRow,
  data: any,
) {
  const messageData = getGatewayEventMessageData(data);
  const messageId = String(messageData?.messageId || data?.messageId || "").trim();
  if (!messageId) {
    return { inserted: false, paused: false, reason: "missing_message_id" };
  }

  const rawText = getGatewayManualOutgoingMessageText(data);
  const mediaType = String(messageData?.mediaType || data?.mediaType || "").trim() || null;
  const mediaCaption = messageData?.mediaCaption || data?.mediaCaption || null;
  const mediaLabel =
    mediaType === "audio"
      ? "Audio enviado"
      : mediaType === "image"
        ? "Imagem enviada"
        : mediaType === "video"
          ? "Video enviado"
          : mediaType === "document"
            ? "Documento enviado"
            : "Mensagem manual";
  const lastMessageText = rawText || String(mediaCaption || "").trim() || mediaLabel;
  const timestampRaw = messageData?.timestamp || data?.timestamp || new Date().toISOString();
  const timestamp = Number.isNaN(new Date(timestampRaw).getTime())
    ? new Date().toISOString()
    : new Date(timestampRaw).toISOString();
  const likelyAgentEcho = await isLikelyRecentWebOnlyAgentOutboundEcho({
    conversationId: conversation.id,
    messageId,
    mediaType,
  });

  if (likelyAgentEcho) {
    const insertResult = await getPool().query(
      `
        INSERT INTO messages (
          conversation_id,
          message_id,
          from_me,
          text,
          timestamp,
          status,
          is_from_agent,
          media_type,
          media_url,
          media_mime_type,
          media_duration,
          media_caption,
          created_at
        )
        SELECT $1, $2, true, $3, $4, $5, true, $6, $7, $8, $9, $10, NOW()
        WHERE NOT EXISTS (
          SELECT 1 FROM messages WHERE conversation_id = $1 AND message_id = $2
        )
        RETURNING id
      `,
      [
        conversation.id,
        messageId,
        rawText || null,
        timestamp,
        String(messageData?.status || data?.status || "sent"),
        mediaType,
        messageData?.mediaUrl || data?.mediaUrl || null,
        messageData?.mediaMimeType || data?.mediaMimeType || null,
        Number.isFinite(Number(messageData?.mediaDuration)) ? Number(messageData.mediaDuration) : null,
        mediaCaption,
      ],
    );

    await getPool().query(
      `
        UPDATE messages
        SET is_from_agent = true,
            status = COALESCE(NULLIF($3, ''), status),
            text = COALESCE(text, $4),
            media_type = COALESCE(media_type, $5),
            media_url = COALESCE(media_url, $6),
            media_mime_type = COALESCE(media_mime_type, $7),
            media_duration = COALESCE(media_duration, $8),
            media_caption = COALESCE(media_caption, $9)
        WHERE conversation_id = $1
          AND message_id = $2
          AND from_me = true
      `,
      [
        conversation.id,
        messageId,
        String(messageData?.status || data?.status || "sent"),
        rawText || null,
        mediaType,
        messageData?.mediaUrl || data?.mediaUrl || null,
        messageData?.mediaMimeType || data?.mediaMimeType || null,
        Number.isFinite(Number(messageData?.mediaDuration)) ? Number(messageData.mediaDuration) : null,
        mediaCaption,
      ],
    );

    await getPool().query(
      `
        UPDATE conversations
        SET last_message_text = $2,
            last_message_time = $3,
            last_message_from_me = true,
            has_replied = true,
            updated_at = NOW()
        WHERE id = $1
      `,
      [conversation.id, lastMessageText, timestamp],
    );

    return {
      inserted: insertResult.rows.length > 0,
      paused: false,
      reason: "agent_outgoing_echo",
    };
  }

  const insertResult = await getPool().query(
    `
      INSERT INTO messages (
        conversation_id,
        message_id,
        from_me,
        text,
        timestamp,
        status,
        is_from_agent,
        media_type,
        media_url,
        media_mime_type,
        media_duration,
        media_caption,
        created_at
      )
      SELECT $1, $2, true, $3, $4, $5, false, $6, $7, $8, $9, $10, NOW()
      WHERE NOT EXISTS (
        SELECT 1 FROM messages WHERE conversation_id = $1 AND message_id = $2
      )
      RETURNING id
    `,
    [
      conversation.id,
      messageId,
      rawText || null,
      timestamp,
      String(messageData?.status || data?.status || "sent"),
      mediaType,
      messageData?.mediaUrl || data?.mediaUrl || null,
      messageData?.mediaMimeType || data?.mediaMimeType || null,
      Number.isFinite(Number(messageData?.mediaDuration)) ? Number(messageData.mediaDuration) : null,
      mediaCaption,
    ],
  );

  const manualState = await applyManualOutgoingConversationState({
    userId,
    conversationId: conversation.id,
    lastMessageText,
    ownerPhoneNumber: normalizeFollowupPhone(conversation.connectionPhoneNumber) || null,
  });

  return {
    inserted: insertResult.rows.length > 0,
    paused: manualState.shouldPause,
    reason: manualState.shouldPause ? "owner_manual_outgoing_paused" : "pause_on_manual_reply_disabled",
  };
}

async function persistIncomingGatewayEventIfNeeded(
  userId: string,
  conversation: ConversationSummaryRow,
  data: any,
) {
  const messageData = getGatewayEventMessageData(data);
  const messageId = String(messageData?.messageId || data?.messageId || "").trim();
  if (!messageId) {
    return { inserted: false, messageId: null, text: "" };
  }

  const rawText = String(messageData?.text || data?.message || data?.text || "").trim();
  const mediaType = String(messageData?.mediaType || data?.mediaType || "").trim() || null;
  const mediaUrl = messageData?.mediaUrl || data?.mediaUrl || null;
  const mediaUrlOriginal = messageData?.mediaUrlOriginal || data?.mediaUrlOriginal || null;
  const mediaCaption = messageData?.mediaCaption || data?.mediaCaption || null;
  const mediaKey = messageData?.mediaKey || data?.mediaKey || null;
  const directPath = messageData?.directPath || data?.directPath || null;
  const text = await buildWebOnlyIncomingImageText({
    userId,
    conversationId: conversation.id,
    mediaType,
    mediaUrl,
    mediaUrlOriginal,
    text: rawText,
    mediaCaption,
  }).catch((error) => {
    console.warn("[vercel-http] failed to enrich incoming gateway image:", error);
    return rawText || String(mediaCaption || "").trim() || (mediaType ? `*${mediaType}*` : "");
  });
  const timestampRaw = messageData?.timestamp || data?.timestamp || new Date().toISOString();
  const timestamp = Number.isNaN(new Date(timestampRaw).getTime())
    ? new Date().toISOString()
    : new Date(timestampRaw).toISOString();
  const currentOwnerPhoneNumber = normalizeFollowupPhone(conversation.connectionPhoneNumber);
  let ownerPhoneStampedForConversation = false;
  if (!normalizeFollowupPhone(conversation.conversationOwnerPhoneNumber) && currentOwnerPhoneNumber) {
    await getPool().query(
      `
        UPDATE conversations
        SET owner_phone_number = $2,
            owner_phone_verified_at = NOW(),
            owner_phone_source = 'gateway_incoming_current_connection',
            updated_at = NOW()
        WHERE id = $1
          AND owner_phone_number IS NULL
      `,
      [conversation.id, currentOwnerPhoneNumber],
    );
    conversation.conversationOwnerPhoneNumber = currentOwnerPhoneNumber;
    conversation.conversationOwnerPhoneVerifiedAt = new Date().toISOString();
    conversation.conversationOwnerPhoneSource = "gateway_incoming_current_connection";
    ownerPhoneStampedForConversation = true;
  }

  const insertResult = await getPool().query(
    `
      INSERT INTO messages (
        conversation_id,
        message_id,
        from_me,
        text,
        timestamp,
        status,
        is_from_agent,
        media_type,
        media_url,
        media_mime_type,
        media_duration,
        media_caption,
        media_key,
        direct_path,
        media_url_original
      )
      SELECT $1, $2, false, $3, $4, $5, false, $6, $7, $8, $9, $10, $11, $12, $13
      WHERE NOT EXISTS (
        SELECT 1 FROM messages WHERE conversation_id = $1 AND message_id = $2
      )
      RETURNING id
    `,
    [
      conversation.id,
      messageId,
      text || null,
      timestamp,
      String(messageData?.status || data?.status || "received"),
      mediaType,
      mediaUrl,
      messageData?.mediaMimeType || data?.mediaMimeType || null,
      Number.isFinite(Number(messageData?.mediaDuration)) ? Number(messageData.mediaDuration) : null,
      mediaCaption,
      mediaKey,
      directPath,
      mediaUrlOriginal,
    ],
  );

  await markPausedAgentConversationHasPendingClientMessage(conversation.id, timestamp);

  if (insertResult.rows.length === 0) {
    if (ownerPhoneStampedForConversation) {
      await scheduleWebOnlyFollowupAfterCompanyMessage(userId, conversation.id).catch((error) => {
        console.warn("[vercel-http] failed to schedule follow-up after owner phone confirmation:", {
          conversationId: conversation.id,
          error,
        });
      });
    }
    return { inserted: false, messageId, text };
  }

  await getPool().query(
    `
      UPDATE conversations
      SET last_message_text = $2,
          last_message_time = $3,
          last_message_from_me = false,
          followup_stage = 0,
          next_followup_at = NULL,
          followup_disabled_reason = CASE WHEN followup_active = true THEN $4 ELSE followup_disabled_reason END,
          unread_count = COALESCE(unread_count, 0) + 1,
          is_archived = false,
          updated_at = NOW()
      WHERE id = $1
    `,
    [
      conversation.id,
      text || mediaCaption || (mediaType ? `*${mediaType}*` : ""),
      timestamp,
      WEB_ONLY_FOLLOWUP_CLIENT_LAST_REASON,
    ],
  );

  return { inserted: true, messageId, text };
}

function buildAgentNotificationMessage(params: {
  reason: string;
  source: string;
  conversation: ConversationSummaryRow;
  clientMessage: string;
  agentMessage: string;
}) {
  const clientName = String(params.conversation.contactName || "Cliente").trim();
  const clientPhone = String(params.conversation.contactNumber || "").trim();
  const sourceLine = params.source ? `*Fonte:* ${params.source}` : "";
  const agentLine = params.agentMessage
    ? `\n*Resposta do agente:* "${params.agentMessage.slice(0, 500)}${params.agentMessage.length > 500 ? "..." : ""}"`
    : "";

  return [
    "*NOTIFICACAO DO AGENTE*",
    "",
    `*Motivo:* ${params.reason || "Gatilho configurado detectado"}`,
    sourceLine,
    "",
    `*Cliente:* ${clientName}${clientPhone ? ` (${clientPhone})` : ""}`,
    `*Conexao:* ${params.conversation.connectionName || params.conversation.connectionPhoneNumber || params.conversation.connectionId}`,
    `*Mensagem do cliente:* "${params.clientMessage.slice(0, 500)}${params.clientMessage.length > 500 ? "..." : ""}"${agentLine}`,
  ].filter((line) => line !== "").join("\n");
}

async function sendWebOnlyAgentNotificationsForGatewayEvent(params: {
  conversation: ConversationSummaryRow;
  payload: any;
  clientMessage: string;
  agentMessage: string;
}) {
  const notification = params.payload?.notification;
  if (!notification?.shouldNotify) {
    return { sent: 0, failed: 0, skipped: "not_triggered" };
  }

  const recipients = parseNotificationPhoneNumbers(notification.recipients || notification.recipient || []);
  if (recipients.length === 0) {
    return { sent: 0, failed: 0, skipped: "no_recipients" };
  }

  const message = buildAgentNotificationMessage({
    reason: String(notification.reason || ""),
    source: String(notification.source || ""),
    conversation: params.conversation,
    clientMessage: params.clientMessage,
    agentMessage: params.agentMessage,
  });

  let sent = 0;
  let failed = 0;
  const errors: Array<{ phone: string; message: string }> = [];

  for (const phone of recipients) {
    try {
      const result = await sendGatewayInstanceText(params.conversation.connectionId, {
        text: message,
        to: phone,
        validateDestination: true,
        source: "agent_notification",
      });
      if (result?.success === false || result?.blocked === true) {
        failed += 1;
        errors.push({ phone, message: result.reason || "Falha ao enviar notificacao" });
      } else {
        sent += 1;
      }
    } catch (error: any) {
      failed += 1;
      errors.push({ phone, message: error?.message || String(error) });
    }
  }

  return { sent, failed, errors };
}

function messageRowTime(value: unknown): number {
  const timestamp = new Date(value as any).getTime();
  return Number.isFinite(timestamp) ? timestamp : 0;
}

function compareMessageRows(left: MessageRow, right: MessageRow): number {
  const timestampDiff = messageRowTime(left.timestamp) - messageRowTime(right.timestamp);
  if (timestampDiff !== 0) return timestampDiff;
  const createdDiff = messageRowTime(left.createdAt) - messageRowTime(right.createdAt);
  if (createdDiff !== 0) return createdDiff;
  return String(left.id || "").localeCompare(String(right.id || ""));
}

function isWebOnlyTrivialGreetingOnlyResponse(value: unknown): boolean {
  const text = repairWebOnlyOutgoingText(value)
    .replace(/^\*?ASSISTENTE\s+VIRTUAL[\s\S]{0,80}?:\*?\s*/i, "")
    .trim();
  const normalized = normalizeWebOnlyCatalogText(text);
  return normalized.length > 0 &&
    normalized.length <= 40 &&
    /^(oi|ola|olá|bom dia|boa tarde|boa noite|tudo bem)[!.? ]*$/i.test(text);
}

function isWebOnlyHighIntentIncomingAfterGreeting(value: unknown): boolean {
  const normalized = normalizeWebOnlyCatalogText(value);
  if (!normalized) return false;
  if (looksLikeWebOnlyCatalogMediaRequest(normalized)) return true;
  return /\b(?:cilindro|cilindros|painel|tema|temas|foto|fotos|catalogo|codigo|cod|pix|endereco|localizacao|retirar|retirada)\b/i.test(normalized);
}

function hasOutboundAfterIncomingMessage(rows: MessageRow[], targetIncoming: MessageRow): boolean {
  const targetCreatedAt = messageRowTime(targetIncoming.createdAt);
  const targetText = getWebOnlyIncomingMessageContent(targetIncoming);
  const targetNeedsRealAnswer = isWebOnlyHighIntentIncomingAfterGreeting(targetText);
  return rows.some((row) => {
    if (row.fromMe !== true) return false;
    if (compareMessageRows(row, targetIncoming) > 0) {
      if (targetNeedsRealAnswer && isWebOnlyTrivialGreetingOnlyResponse(row.text || row.mediaCaption)) {
        return false;
      }
      return true;
    }
    const outboundCreatedAt = messageRowTime(row.createdAt);
    if (targetCreatedAt > 0 && outboundCreatedAt > targetCreatedAt) {
      if (targetNeedsRealAnswer && isWebOnlyTrivialGreetingOnlyResponse(row.text || row.mediaCaption)) {
        return false;
      }
      return true;
    }
    return false;
  });
}

function hasWebOnlyCatalogMediaAfterIncomingMessage(rows: MessageRow[], targetIncoming: MessageRow): boolean {
  return rows.some((row) =>
    row.fromMe === true &&
    row.isFromAgent === true &&
    String(row.mediaType || "").toLowerCase() === "image" &&
    compareMessageRows(row, targetIncoming) > 0 &&
    /\bC[oó]digo\s*[:#-]?\s*\d{1,4}\b/i.test(String(row.text || row.mediaCaption || "")),
  );
}

function messageRowTimeForSql(value: unknown): string | null {
  const timestamp = messageRowTime(value);
  return timestamp > 0 ? new Date(timestamp).toISOString() : null;
}

async function checkWebOnlyManualReplyBlockBeforeAgentSend(params: {
  userId: string;
  conversationId: string;
  targetIncoming: MessageRow;
  phase?: string | null;
}): Promise<WebOnlyAgentSendGuardResult> {
  try {
    const targetTimestamp = messageRowTimeForSql(params.targetIncoming.timestamp);
    const targetCreatedAt = messageRowTimeForSql(params.targetIncoming.createdAt);
    const result = await getPool().query(
      `
        WITH config AS (
          SELECT COALESCE(pause_on_manual_reply, true) AS pause_on_manual_reply
          FROM ai_agent_config
          WHERE user_id = $1
          LIMIT 1
        ),
        manual_reply AS (
          SELECT
            m.id,
            m.timestamp,
            m.created_at
          FROM messages m
          WHERE m.conversation_id = $2
            AND m.from_me = true
            AND COALESCE(m.is_from_agent, false) = false
            AND (
              ($3::timestamp IS NOT NULL AND m.timestamp > $3::timestamp)
              OR ($4::timestamp IS NOT NULL AND COALESCE(m.created_at, m.timestamp) > $4::timestamp)
            )
          ORDER BY m.timestamp DESC NULLS LAST, m.created_at DESC NULLS LAST, m.id DESC
          LIMIT 1
        )
        SELECT
          COALESCE((SELECT pause_on_manual_reply FROM config), true) AS "pauseOnManualReply",
          EXISTS (
            SELECT 1
            FROM agent_disabled_conversations adc
            WHERE adc.conversation_id = $2
          ) AS "conversationPaused",
          (SELECT id FROM manual_reply LIMIT 1) AS "manualReplyId",
          (SELECT COALESCE(created_at, timestamp) FROM manual_reply LIMIT 1) AS "manualReplyAt"
      `,
      [params.userId, params.conversationId, targetTimestamp, targetCreatedAt],
    );

    const row = result.rows[0] || {};
    if (row.pauseOnManualReply === false) {
      return { blocked: false };
    }

    if (row.conversationPaused === true || row.manualReplyId) {
      return {
        blocked: true,
        skipped: "manual_reply_before_agent_send",
        reason: row.conversationPaused === true
          ? "Conversa pausada por resposta manual do dono"
          : "Resposta manual detectada antes do envio da IA",
      };
    }

    return { blocked: false };
  } catch (error) {
    console.warn("[vercel-http] failed to verify manual reply guard before agent send:", {
      conversationId: params.conversationId,
      phase: params.phase || null,
      error,
    });
    return {
      blocked: true,
      skipped: "manual_reply_guard_failed",
      reason: "Nao foi possivel confirmar se houve resposta manual antes do envio da IA",
    };
  }
}

function createWebOnlyManualReplySendGuard(
  userId: string,
  conversation: ConversationSummaryRow,
  targetIncoming: MessageRow,
): WebOnlyAgentSendGuard {
  return (context) =>
    checkWebOnlyManualReplyBlockBeforeAgentSend({
      userId,
      conversationId: conversation.id,
      targetIncoming,
      phase: context?.phase || null,
    });
}

function createWebOnlyManualReplyGenerationAbort(sendGuard: WebOnlyAgentSendGuard) {
  const controller = new AbortController();
  let stopped = false;
  let checking = false;
  let blockedResult: WebOnlyAgentSendGuardResult | null = null;
  const pollMs = Math.max(
    500,
    Math.min(Number(process.env.AGENT_MANUAL_REPLY_ABORT_POLL_MS || 1500), 5000),
  );

  const poll = async () => {
    if (stopped || checking || controller.signal.aborted) return;
    checking = true;
    try {
      const guard = await sendGuard({ phase: "generation_abort_poll" });
      if (guard.blocked && !controller.signal.aborted) {
        blockedResult = guard;
        const reason = guard.reason || guard.skipped || "manual_reply_before_agent_send";
        try {
          controller.abort(new Error(reason));
        } catch {
          controller.abort();
        }
      }
    } catch (error) {
      blockedResult = {
        blocked: true,
        skipped: "manual_reply_guard_failed",
        reason: "Nao foi possivel confirmar se houve resposta manual durante a geracao da IA",
      };
      if (!controller.signal.aborted) {
        try {
          controller.abort(error instanceof Error ? error : new Error(String(error)));
        } catch {
          controller.abort();
        }
      }
    } finally {
      checking = false;
    }
  };

  const timer = setInterval(() => {
    void poll();
  }, pollMs);

  return {
    signal: controller.signal,
    getBlockedResult: () => blockedResult,
    stop: () => {
      stopped = true;
      clearInterval(timer);
    },
  };
}

function getWebOnlyIncomingMessageContent(row: MessageRow | null | undefined): string {
  if (!row) return "";
  const text = repairWebOnlyOutgoingText(row.text).trim();
  const caption = repairWebOnlyOutgoingText(row.mediaCaption).trim();
  const parts = [text];
  if (caption && caption !== text) {
    parts.push(caption);
  }
  const content = parts.filter(Boolean).join("\n");
  if (isIgnorableGatewayIncomingText(content) || isTechnicalGatewayStubTextForVercel(content)) {
    return "";
  }
  if (content) return content;
  return row.mediaType ? `[${row.mediaType} recebido]` : "";
}

function buildWebOnlyIncomingBurstForAgent(rows: MessageRow[], targetIncoming: MessageRow): {
  text: string;
  rows: MessageRow[];
  firstIndex: number;
} {
  const targetIndex = rows.findIndex((row) => row.id === targetIncoming.id);
  if (targetIndex < 0) {
    return {
      text: getWebOnlyIncomingMessageContent(targetIncoming),
      rows: [targetIncoming],
      firstIndex: -1,
    };
  }

  let lastOutboundIndex = -1;
  for (let index = targetIndex - 1; index >= 0; index -= 1) {
    if (rows[index]?.fromMe === true) {
      lastOutboundIndex = index;
      break;
    }
  }

  const targetTime = messageRowTime(targetIncoming.timestamp) || messageRowTime(targetIncoming.createdAt);
  const burstRows = rows
    .slice(lastOutboundIndex + 1)
    .filter((row) => !row.fromMe)
    .filter((row) => {
      const content = getWebOnlyIncomingMessageContent(row);
      if (!content) return false;
      const rowTime = messageRowTime(row.timestamp) || messageRowTime(row.createdAt);
      if (targetTime > 0 && rowTime > 0 && Math.abs(rowTime - targetTime) > 180_000) {
        return false;
      }
      return true;
    })
    .slice(-10);

  if (burstRows.length <= 1 || !burstRows.some((row) => row.id === targetIncoming.id)) {
    return {
      text: getWebOnlyIncomingMessageContent(targetIncoming),
      rows: [targetIncoming],
      firstIndex: targetIndex,
    };
  }

  return {
    text: burstRows.map(getWebOnlyIncomingMessageContent).filter(Boolean).join("\n\n"),
    rows: burstRows,
    firstIndex: rows.findIndex((row) => row.id === burstRows[0]?.id),
  };
}

const INITIAL_META_STUB_FALLBACK_TEXT_FOR_VERCEL = "Oi, tenho interesse.";

function normalizeGatewayStubTextForVercel(text?: string | null): string {
  return String(text || "")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .trim()
    .toLowerCase();
}

function isTechnicalGatewayStubTextForVercel(text?: string | null): boolean {
  const normalized = normalizeGatewayStubTextForVercel(text);
  if (!normalized) return true;

  return (
    normalized.includes("mensagem incompleta") ||
    normalized.includes("[mensagem de protocolo]") ||
    normalized.includes("[mensagem nao suportada]")
  );
}

function isInitialMetaStubFallbackCandidate(text?: string | null): boolean {
  const normalized = normalizeGatewayStubTextForVercel(text);
  if (!normalized || !normalized.includes("mensagem incompleta")) {
    return false;
  }

  return (
    normalized.includes("stubtype=2") ||
    normalized.startsWith("[whatsapp] mensagem incompleta") ||
    normalized.startsWith("whatsapp mensagem incompleta") ||
    normalized === "mensagem incompleta"
  );
}

function normalizeInitialGatewayStubMessageForVercel(
  currentText: string,
  conversationHistory: Array<{ fromMe?: boolean; isFromAgent?: boolean; text?: string | null }>,
): { text: string; wasNormalized: boolean; reason: string | null } {
  if (!isTechnicalGatewayStubTextForVercel(currentText)) {
    return { text: currentText, wasNormalized: false, reason: null };
  }

  const hasAgentReplies = conversationHistory.some(
    (message) => message.fromMe === true || message.isFromAgent === true,
  );
  if (hasAgentReplies) {
    return { text: currentText, wasNormalized: false, reason: "conversation_already_started" };
  }

  const hasMeaningfulClientText = conversationHistory.some((message) => {
    if (message.fromMe === true || message.isFromAgent === true) return false;
    return !isTechnicalGatewayStubTextForVercel(message.text);
  });
  if (hasMeaningfulClientText) {
    return { text: currentText, wasNormalized: false, reason: "real_client_text_already_exists" };
  }

  return {
    text: INITIAL_META_STUB_FALLBACK_TEXT_FOR_VERCEL,
    wasNormalized: true,
    reason: "initial_meta_stub",
  };
}

function normalizeGatewayIncomingStubTextForAI(
  currentText: string,
  rowsBeforeTarget: MessageRow[],
): { text: string; wasNormalized: boolean; reason: string | null } {
  if (!isInitialMetaStubFallbackCandidate(currentText)) {
    return { text: currentText, wasNormalized: false, reason: null };
  }

  return normalizeInitialGatewayStubMessageForVercel(
    currentText,
    rowsBeforeTarget.map((row) => ({
      fromMe: row.fromMe,
      isFromAgent: row.isFromAgent,
      text: getWebOnlyIncomingMessageContent(row),
    })),
  );
}

async function persistNormalizedGatewayStubText(params: {
  conversationId: string;
  targetIncoming: MessageRow;
  originalText: string;
  normalizedText: string;
}) {
  const originalText = String(params.originalText || "").trim();
  const normalizedText = String(params.normalizedText || "").trim();
  if (!params.targetIncoming?.id || !originalText || !normalizedText || originalText === normalizedText) {
    return;
  }

  await getPool().query(
    `
      UPDATE messages
      SET text = $2
      WHERE id = $1
        AND COALESCE(text, '') = $3
    `,
    [params.targetIncoming.id, normalizedText, originalText],
  );

  await getPool().query(
    `
      UPDATE conversations
      SET last_message_text = $2,
          updated_at = NOW()
      WHERE id = $1
        AND COALESCE(last_message_text, '') = $3
    `,
    [params.conversationId, normalizedText, originalText],
  );

  params.targetIncoming.text = normalizedText;
}

function roundWebOnlyAttentionConfidence(value: unknown): number | null {
  return clampWebOnlyAttentionConfidence(value);
}

function hasWebOnlyAttentionStateChanged(
  conversation: Pick<ConversationSummaryRow, "attentionPriority" | "attentionReason" | "attentionConfidence" | "needsHumanAttention">,
  nextAttention: WebOnlyAttentionAssessment,
) {
  const nextReason = nextAttention.reason?.trim() || null;
  const currentReason = conversation.attentionReason?.trim() || null;
  return (
    conversation.attentionPriority !== nextAttention.priority ||
    conversation.needsHumanAttention !== nextAttention.needsHumanAttention ||
    currentReason !== nextReason ||
    roundWebOnlyAttentionConfidence(conversation.attentionConfidence) !== roundWebOnlyAttentionConfidence(nextAttention.confidence)
  );
}

async function persistWebOnlyConversationAttentionAssessment(params: {
  userId: string;
  conversation: ConversationSummaryRow;
  attention: WebOnlyAttentionAssessment | null | undefined;
  sourceLabel: string;
}) {
  const { userId, conversation, attention } = params;
  if (!attention) {
    return;
  }

  if (!hasWebOnlyAttentionStateChanged(conversation, attention) && conversation.attentionQualifiedAt) {
    return;
  }

  const updateResult = await getPool().query(
    `
      UPDATE conversations c
      SET
        attention_priority = $3,
        attention_reason = $4,
        attention_confidence = $5,
        needs_human_attention = $6,
        attention_qualified_at = NOW(),
        updated_at = NOW()
      FROM whatsapp_connections wc
      WHERE c.id = $1
        AND c.connection_id = wc.id
        AND wc.user_id = $2
      RETURNING
        c.attention_priority AS "attentionPriority",
        c.attention_reason AS "attentionReason",
        c.attention_confidence AS "attentionConfidence",
        c.needs_human_attention AS "needsHumanAttention",
        c.attention_qualified_at AS "attentionQualifiedAt"
    `,
    [
      conversation.id,
      userId,
      attention.priority,
      attention.reason,
      attention.confidence,
      attention.needsHumanAttention,
    ],
  );

  const updated = updateResult.rows[0];
  if (updated) {
    conversation.attentionPriority = updated.attentionPriority;
    conversation.attentionReason = updated.attentionReason;
    conversation.attentionConfidence = updated.attentionConfidence;
    conversation.needsHumanAttention = updated.needsHumanAttention;
    conversation.attentionQualifiedAt = updated.attentionQualifiedAt;
  }
}

function extractFirstJsonObject(value: string): string | null {
  const text = String(value || "");
  const start = text.indexOf("{");
  const end = text.lastIndexOf("}");
  if (start === -1 || end === -1 || end <= start) return null;
  return text.slice(start, end + 1);
}

function parseFirstJsonObject(value: string): any | null {
  const json = extractFirstJsonObject(value);
  if (!json) return null;
  try {
    return JSON.parse(json);
  } catch {
    try {
      return JSON.parse(json.replace(/[\u0000-\u001F]+/g, " "));
    } catch {
      return null;
    }
  }
}

async function classifyWebOnlyConversationAttentionOnly(params: {
  userId: string;
  model?: string | null;
  message: string;
  history: Array<{ role: "user" | "assistant"; content: string }>;
}) {
  const rawResponse = await callWebOnlyLlm({
    userId: params.userId,
    model: String(params.model || "mistral-small-latest"),
    prompt: `
Voce atua como classificador interno da fila de atencao humana do AgenteZap.
Analise a conversa e responda somente um JSON no formato:
{"priority":"alta","needsHumanAttention":true,"reason":"Cliente pronto para fechamento humano.","confidence":0.91}

Regras:
- Use priority "critica", "alta", "media", "baixa" ou null.
- Marque needsHumanAttention=true quando uma acao humana rapida fizer diferenca relevante.
- Se nao houver motivo real para subir na fila, use needsHumanAttention=false e priority=null.
- confidence deve ser numero entre 0 e 1.
- reason deve ser curto, objetivo e operacional.
`.trim(),
    message: params.message,
    history: params.history,
    temperature: 0.1,
    maxTokens: 260,
  });
  const json = extractFirstJsonObject(rawResponse);
  if (!json) {
    return null;
  }
  try {
    return sanitizeWebOnlyAttentionAssessment(JSON.parse(json));
  } catch (error) {
    console.warn("[vercel-http] failed to parse attention-only JSON:", error);
    return null;
  }
}

function getWebOnlyMessageHistoryContent(row: MessageRow): string {
  const text = repairWebOnlyOutgoingText(row.text).trim();
  const caption = repairWebOnlyOutgoingText(row.mediaCaption).trim();
  const mediaType = String(row.mediaType || "").trim();
  const textContent = [text, caption].filter(Boolean).join("\n");
  if (isIgnorableGatewayIncomingText(textContent) || isTechnicalGatewayStubTextForVercel(textContent)) {
    return "";
  }

  if (mediaType) {
    const contentParts = [text];
    if (caption && caption !== text) {
      contentParts.push(caption);
    }

    const content = contentParts.filter(Boolean).join(" | ");
    const direction = row.fromMe ? "enviado" : "recebido";
    return content ? `[${mediaType} ${direction}] ${content}` : `[${mediaType} ${direction}]`;
  }

  return text || caption || (mediaType ? `[${mediaType}]` : "");
}

function mapMessageRowsToWebOnlyHistory(rows: MessageRow[]): Array<{ role: "user" | "assistant"; content: string }> {
  return rows
    .map((row): { role: "user" | "assistant"; content: string } => ({
      role: row.fromMe ? ("assistant" as const) : ("user" as const),
      content: getWebOnlyMessageHistoryContent(row),
    }))
    .filter((entry) => entry.content);
}

function normalizeWebOnlyOpeningCompareText(value: unknown): string {
  const repaired = repairWebOnlyOutgoingText(value).replace(/\r\n/g, "\n");
  const withoutSignature = repaired.replace(/^\s*\*[^*\n]{1,80}:\*\s*/u, "");
  return withoutSignature
    .normalize("NFC")
    .replace(/[ \t]+\n/g, "\n")
    .replace(/\n{3,}/g, "\n\n")
    .trim();
}

function normalizeWebOnlyOpeningMediaUrl(value: unknown): string {
  return String(value || "").trim().split("?", 1)[0];
}

function doesMessageRowMatchOpeningAction(row: MessageRow, action: any): boolean {
  if (row.fromMe !== true || row.isFromAgent !== true) {
    return false;
  }

  if (action?.type === "send_text") {
    if (row.mediaType) return false;
    const expected = normalizeWebOnlyOpeningCompareText(action.text);
    const actual = normalizeWebOnlyOpeningCompareText(row.text);
    return Boolean(expected && actual && expected === actual);
  }

  if (action?.type === "send_media_url") {
    const expectedUrl = normalizeWebOnlyOpeningMediaUrl(action.media_url || action.mediaUrl);
    const actualUrl = normalizeWebOnlyOpeningMediaUrl(row.mediaUrl);
    if (expectedUrl && actualUrl && expectedUrl === actualUrl) {
      return true;
    }
    const mediaCaption = normalizeSimulatorMediaName(row.mediaCaption);
    const actionMediaName = normalizeSimulatorMediaName(action.media_name || action.mediaName);
    const expectedType = String(action.media_type || action.mediaType || "").toLowerCase();
    const actualType = String(row.mediaType || "").toLowerCase();
    return Boolean(
      actionMediaName &&
        mediaCaption === actionMediaName &&
        expectedType &&
        actualType === expectedType,
    );
  }

  return false;
}

function getWebOnlyOpeningFlowProgress(actions: any[], rows: MessageRow[]) {
  const matchedActionIndexes = new Set<number>();
  let lastMatchedRowIndex = -1;

  for (let rowIndex = 0; rowIndex < rows.length; rowIndex += 1) {
    for (let actionIndex = 0; actionIndex < actions.length; actionIndex += 1) {
      if (matchedActionIndexes.has(actionIndex)) continue;
      if (!doesMessageRowMatchOpeningAction(rows[rowIndex], actions[actionIndex])) continue;
      matchedActionIndexes.add(actionIndex);
      lastMatchedRowIndex = Math.max(lastMatchedRowIndex, rowIndex);
      break;
    }
  }

  const matchedIndexes = Array.from(matchedActionIndexes).sort((left, right) => left - right);
  const missingIndexes = actions
    .map((_, index) => index)
    .filter((index) => !matchedActionIndexes.has(index));

  return {
    sentActions: matchedIndexes.length,
    totalActions: actions.length,
    lastMatchedRowIndex,
    lastMatchedRow: lastMatchedRowIndex >= 0 ? rows[lastMatchedRowIndex] : null,
    matchedActionIndexes: matchedIndexes,
    missingActionIndexes: missingIndexes,
  };
}

function hasNonOpeningAgentReplyAfterIndex(rows: MessageRow[], startIndex: number, openingActions: any[]) {
  if (startIndex < 0) return false;
  return rows.slice(startIndex + 1).some((row) => {
    if (row.fromMe !== true || row.isFromAgent !== true) return false;
    return !openingActions.some((action) => doesMessageRowMatchOpeningAction(row, action));
  });
}

function hasIncomingReplyAfterIndex(rows: MessageRow[], startIndex: number) {
  if (startIndex < 0) return false;
  return rows.slice(startIndex + 1).some((row) =>
    row.fromMe !== true &&
    Boolean(getWebOnlyIncomingMessageContent(row)),
  );
}

function getWebOnlyOpeningFlowResumeMinAgeSeconds() {
  return Math.max(0, Math.min(getEnvInt("AGENT_OPENING_FLOW_RESUME_MIN_AGE_SECONDS", 90, 0), 900));
}

function resolveWebOnlyPendingOpeningFlowActions(params: {
  config: any;
  mediaLibrary: any[];
  contactName?: string | null;
  rowsBeforeTarget: MessageRow[];
  currentTargetIsIncomingReply?: boolean;
}) {
  if (params.config?.greeting_enabled !== true) {
    return null;
  }

  const openingRule = resolveWebOnlyOpeningRule(params.config, params.contactName || undefined) || {
    source: "greeting" as const,
    text: "",
    variationEnabled: params.config?.greeting_variation === true,
  };
  if (openingRule.source !== "greeting") {
    return null;
  }

  const openingActions = applyWebOnlyActionTextSettings(
    buildWebOnlyGreetingOpeningFlowActions({
      mediaLibrary: params.mediaLibrary,
      openingText: openingRule.text,
      contactName: params.contactName || undefined,
    }),
    params.config,
  );
  if (openingActions.length === 0) {
    return null;
  }

  const progress = getWebOnlyOpeningFlowProgress(openingActions, params.rowsBeforeTarget);
  const missingActionIndexes = Array.isArray(progress.missingActionIndexes)
    ? progress.missingActionIndexes
    : [];
  if (progress.sentActions <= 0 || missingActionIndexes.length === 0) {
    return null;
  }

  if (hasNonOpeningAgentReplyAfterIndex(params.rowsBeforeTarget, progress.lastMatchedRowIndex, openingActions)) {
    return null;
  }

  if (hasIncomingReplyAfterIndex(params.rowsBeforeTarget, progress.lastMatchedRowIndex)) {
    return null;
  }

  if (params.currentTargetIsIncomingReply === true) {
    return null;
  }

  const lastSentAt = progress.lastMatchedRow?.createdAt || progress.lastMatchedRow?.timestamp || null;
  const ageMs = lastSentAt ? Date.now() - messageRowTime(lastSentAt) : Number.POSITIVE_INFINITY;
  const minAgeMs = getWebOnlyOpeningFlowResumeMinAgeSeconds() * 1000;
  if (Number.isFinite(ageMs) && ageMs >= 0 && ageMs < minAgeMs) {
    return {
      actions: [] as any[],
      progress,
      skipped: "opening_flow_in_progress",
      resumeAfterSeconds: Math.ceil((minAgeMs - ageMs) / 1000),
    };
  }

  return {
    actions: missingActionIndexes.map((index) => openingActions[index]).filter(Boolean),
    progress,
    skipped: null,
    resumeAfterSeconds: 0,
  };
}

function hasWebOnlyGreetingOpeningActions(actions: any[]) {
  return actions.some((action) => action?.opening_flow_source === "greeting");
}

function getWebOnlyOpeningFlowLockKey(conversationId: string) {
  return `opening-flow:${conversationId}`;
}

function getWebOnlyOpeningFlowLockSeconds() {
  return Math.max(30, Math.min(getEnvInt("AGENT_OPENING_FLOW_LOCK_SECONDS", 90, 30), 300));
}

async function tryClaimWebOnlyOpeningFlowLock(userId: string, conversationId: string) {
  try {
    const dedupKey = getWebOnlyOpeningFlowLockKey(conversationId);
    const lockSeconds = getWebOnlyOpeningFlowLockSeconds();
    const result = await getPool().query(
      `
        INSERT INTO message_deduplication (
          dedup_key,
          user_id,
          conversation_id,
          message_type,
          source,
          content_hash,
          created_at,
          expires_at
        )
        VALUES ($1, $2, $3, 'opening_flow', 'vercel_opening_flow', $4, NOW(), NOW() + ($5::int * INTERVAL '1 second'))
        ON CONFLICT (dedup_key) DO UPDATE
        SET user_id = EXCLUDED.user_id,
            conversation_id = EXCLUDED.conversation_id,
            content_hash = EXCLUDED.content_hash,
            created_at = NOW(),
            expires_at = NOW() + ($5::int * INTERVAL '1 second')
        WHERE message_deduplication.expires_at <= NOW()
           OR message_deduplication.created_at <= NOW() - ($5::int * INTERVAL '1 second')
        RETURNING dedup_key
      `,
      [
        dedupKey,
        userId,
        conversationId,
        createHash("sha256").update(dedupKey).digest("hex"),
        lockSeconds,
      ],
    );
    return result.rows.length > 0;
  } catch (error: any) {
    if (error?.code === "42P01" || error?.code === "42703" || error?.code === "42P10") {
      console.warn("[vercel-http] opening flow lock unavailable; continuing without lock:", error);
      return true;
    }
    throw error;
  }
}

async function releaseWebOnlyOpeningFlowLock(conversationId: string) {
  try {
    await getPool().query(
      `DELETE FROM message_deduplication WHERE dedup_key = $1`,
      [getWebOnlyOpeningFlowLockKey(conversationId)],
    );
  } catch (error) {
    console.warn("[vercel-http] failed to release opening flow lock:", error);
  }
}

function getWebOnlyAgentResponseLockKey(conversationId: string) {
  return `agent-response:${conversationId}`;
}

function getWebOnlyAgentResponseLockTtlSeconds() {
  return Math.min(getEnvInt("WEB_ONLY_AGENT_RESPONSE_LOCK_TTL_SECONDS", 180, 30), 600);
}

function getWebOnlyAgentResponseLockStaleSeconds() {
  return Math.min(getEnvInt("WEB_ONLY_AGENT_RESPONSE_LOCK_STALE_SECONDS", 180, 45), 600);
}

async function tryClaimWebOnlyAgentResponseLock(userId: string, conversationId: string) {
  try {
    const dedupKey = getWebOnlyAgentResponseLockKey(conversationId);
    const result = await getPool().query(
      `
        INSERT INTO message_deduplication (
          dedup_key,
          user_id,
          conversation_id,
          message_type,
          source,
          content_hash,
          created_at,
          expires_at
        )
        VALUES ($1, $2, $3, 'agent_response', 'vercel_agent_response', $4, NOW(), NOW() + ($5::int * INTERVAL '1 second'))
        ON CONFLICT (dedup_key) DO UPDATE
        SET user_id = EXCLUDED.user_id,
            conversation_id = EXCLUDED.conversation_id,
            content_hash = EXCLUDED.content_hash,
            created_at = NOW(),
            expires_at = NOW() + ($5::int * INTERVAL '1 second')
        WHERE message_deduplication.expires_at <= NOW()
           OR message_deduplication.created_at <= NOW() - ($6::int * INTERVAL '1 second')
        RETURNING dedup_key
      `,
      [
        dedupKey,
        userId,
        conversationId,
        createHash("sha256").update(dedupKey).digest("hex"),
        getWebOnlyAgentResponseLockTtlSeconds(),
        getWebOnlyAgentResponseLockStaleSeconds(),
      ],
    );
    return result.rows.length > 0;
  } catch (error: any) {
    if (error?.code === "42P01" || error?.code === "42703" || error?.code === "42P10") {
      console.warn("[vercel-http] agent response lock unavailable; continuing without lock:", error);
      return true;
    }
    throw error;
  }
}

async function refreshWebOnlyAgentResponseLock(userId: string, conversationId: string) {
  try {
    await getPool().query(
      `
        UPDATE message_deduplication
        SET user_id = $2,
            conversation_id = $3,
            created_at = NOW(),
            expires_at = NOW() + ($4::int * INTERVAL '1 second')
        WHERE dedup_key = $1
      `,
      [
        getWebOnlyAgentResponseLockKey(conversationId),
        userId,
        conversationId,
        getWebOnlyAgentResponseLockTtlSeconds(),
      ],
    );
  } catch (error: any) {
    if (error?.code === "42P01" || error?.code === "42703") {
      return;
    }
    console.warn("[vercel-http] failed to refresh agent response lock:", error);
  }
}

async function releaseWebOnlyAgentResponseLock(conversationId: string) {
  try {
    await getPool().query(
      `DELETE FROM message_deduplication WHERE dedup_key = $1`,
      [getWebOnlyAgentResponseLockKey(conversationId)],
    );
  } catch (error) {
    console.warn("[vercel-http] failed to release agent response lock:", error);
  }
}

async function markLegacyPendingAIResponsesSupersededByVercel(params: {
  userId: string;
  conversationId: string;
  reason: string;
}) {
  const userId = String(params.userId || "").trim();
  const conversationId = String(params.conversationId || "").trim();
  if (!userId || !conversationId) return 0;

  try {
    const result = await getPool().query(
      `
        UPDATE pending_ai_responses
        SET status = 'cancelled',
            failure_reason = $3,
            last_attempt_at = NOW(),
            updated_at = NOW()
        WHERE conversation_id = $1
          AND user_id::text = $2
          AND status IN ('pending', 'processing')
          AND COALESCE(failure_reason, '') NOT LIKE 'queued:vercel_gateway_agent%'
        RETURNING id
      `,
      [conversationId, userId, `cancelled:${params.reason}`],
    );
    const count = Number(result.rowCount || 0);
    if (count > 0) {
      console.info("[vercel-http] superseded legacy pending ai responses", {
        userId,
        conversationId,
        count,
        reason: params.reason,
      });
    }
    return count;
  } catch (error: any) {
    if (error?.code === "42P01" || error?.code === "42703") {
      console.warn("[vercel-http] legacy pending ai response table unavailable; continuing:", error);
      return 0;
    }
    throw error;
  }
}

function getVercelAgentQueueLimit() {
  return Math.min(getEnvInt("VERCEL_AGENT_QUEUE_LIMIT", 6, 1), 12);
}

function getVercelAgentQueueDeadlineMs() {
  return Math.min(getEnvInt("VERCEL_AGENT_QUEUE_DEADLINE_MS", 45_000, 10_000), 120_000);
}

function getVercelAgentQueueVisibilitySeconds() {
  return Math.min(getEnvInt("VERCEL_AGENT_QUEUE_VISIBILITY_SECONDS", 900, 30), 1800);
}

function getVercelAgentQueueDebounceSeconds() {
  return Math.min(getEnvInt("VERCEL_AGENT_QUEUE_DEBOUNCE_SECONDS", 5, 0), 20);
}

function getVercelAgentQueueMaxRetryCount() {
  return Math.min(getEnvInt("VERCEL_AGENT_QUEUE_MAX_RETRIES", 8, 3), 20);
}

function resolveVercelAgentQueueRetryDelaySeconds(retryCount: number) {
  const safeRetry = Math.max(0, Math.min(Number(retryCount || 0), 12));
  return Math.min(300, Math.max(10, Math.floor(10 * Math.pow(1.7, safeRetry))));
}

function getVercelAgentQueueReasonRetryLimit(reason: unknown) {
  const value = String(reason || "").trim();
  if (value === "empty_agent_response") return 2;
  if (value === "connection_not_ready") return 4;
  if (value === "agent_response_locked" || value === "opening_flow_locked") return 4;
  if (value === "deadline_deferred") return 3;
  return getVercelAgentQueueMaxRetryCount();
}

function shouldRetryVercelAgentQueueSkip(reason: unknown, retryCount = 0) {
  const value = String(reason || "").trim();
  const retryable = [
    "agent_response_locked",
    "opening_flow_locked",
    "connection_not_ready",
    "agent_generation_failed",
    "empty_agent_response",
  ].includes(value);
  return retryable && Number(retryCount || 0) < getVercelAgentQueueReasonRetryLimit(value);
}

function logVercelAgentQueue(event: string, payload: Record<string, unknown> = {}) {
  console.info("[vercel-agent-queue]", {
    event,
    ts: new Date().toISOString(),
    ...payload,
  });
}

async function enqueueVercelAgentResponseJob(params: {
  userId: string;
  conversation: ConversationSummaryRow;
  messageId?: string | null;
  text?: string | null;
  reason?: string;
}) {
  const userId = String(params.userId || "").trim();
  const conversationId = String(params.conversation?.id || "").trim();
  if (!userId || !conversationId) {
    return { queued: false, reason: "missing_user_or_conversation" };
  }

  const messageId = String(params.messageId || "").trim();
  const text = String(params.text || "").trim();
  const messages = [text || messageId || "gateway-inbound"].filter(Boolean);
  const marker = `queued:vercel_gateway_agent${messageId ? `:${messageId.slice(0, 80)}` : ""}`;

  try {
    const result = await getPool().query(
      `
        INSERT INTO vercel_agent_response_jobs (
          conversation_id,
          user_id,
          contact_number,
          jid_suffix,
          message_id,
          messages,
          scheduled_at,
          execute_at,
          status,
          retry_count,
          failure_reason,
          last_error,
          last_attempt_at,
          updated_at
        )
        VALUES (
          $1, $2, $3, $4, $5, $6::jsonb, NOW(), NOW() + ($9::int * INTERVAL '1 second'), 'pending', 0, $7, NULL, NULL, NOW()
        )
        ON CONFLICT (conversation_id) DO UPDATE
        SET user_id = EXCLUDED.user_id,
            contact_number = EXCLUDED.contact_number,
            jid_suffix = EXCLUDED.jid_suffix,
            message_id = EXCLUDED.message_id,
            messages = CASE
              WHEN vercel_agent_response_jobs.status = 'pending'
              THEN COALESCE(vercel_agent_response_jobs.messages, '[]'::jsonb) || EXCLUDED.messages
              WHEN vercel_agent_response_jobs.status = 'processing'
               AND COALESCE(vercel_agent_response_jobs.updated_at, vercel_agent_response_jobs.created_at, NOW())
                   > COALESCE(vercel_agent_response_jobs.last_attempt_at, vercel_agent_response_jobs.updated_at, NOW()) + INTERVAL '1 millisecond'
              THEN COALESCE(vercel_agent_response_jobs.messages, '[]'::jsonb) || EXCLUDED.messages
              WHEN vercel_agent_response_jobs.status = 'processing'
              THEN EXCLUDED.messages
              ELSE EXCLUDED.messages
            END,
            scheduled_at = NOW(),
            execute_at = CASE
              WHEN vercel_agent_response_jobs.status = 'processing'
               AND COALESCE(vercel_agent_response_jobs.last_attempt_at, vercel_agent_response_jobs.updated_at, NOW())
                   > NOW() - ($8::int * INTERVAL '1 second')
              THEN vercel_agent_response_jobs.execute_at
              ELSE NOW() + ($9::int * INTERVAL '1 second')
            END,
            status = CASE
              WHEN vercel_agent_response_jobs.status = 'processing'
               AND COALESCE(vercel_agent_response_jobs.last_attempt_at, vercel_agent_response_jobs.updated_at, NOW())
                   > NOW() - ($8::int * INTERVAL '1 second')
              THEN vercel_agent_response_jobs.status
              ELSE 'pending'
            END,
            retry_count = CASE
              WHEN vercel_agent_response_jobs.status = 'processing'
               AND COALESCE(vercel_agent_response_jobs.last_attempt_at, vercel_agent_response_jobs.updated_at, NOW())
                   > NOW() - ($8::int * INTERVAL '1 second')
              THEN vercel_agent_response_jobs.retry_count
              ELSE 0
            END,
            failure_reason = CASE
              WHEN vercel_agent_response_jobs.status = 'processing'
               AND COALESCE(vercel_agent_response_jobs.last_attempt_at, vercel_agent_response_jobs.updated_at, NOW())
                   > NOW() - ($8::int * INTERVAL '1 second')
              THEN vercel_agent_response_jobs.failure_reason
              ELSE EXCLUDED.failure_reason
            END,
            last_error = NULL,
            last_attempt_at = CASE
              WHEN vercel_agent_response_jobs.status = 'processing'
               AND COALESCE(vercel_agent_response_jobs.last_attempt_at, vercel_agent_response_jobs.updated_at, NOW())
                   > NOW() - ($8::int * INTERVAL '1 second')
              THEN vercel_agent_response_jobs.last_attempt_at
              ELSE NULL
            END,
            updated_at = NOW()
        RETURNING id, status, retry_count AS "retryCount", execute_at AS "executeAt"
      `,
      [
        conversationId,
        userId,
        params.conversation.contactNumber || "",
        params.conversation.jidSuffix || "s.whatsapp.net",
        messageId || null,
        JSON.stringify(messages),
        marker,
        getVercelAgentQueueVisibilitySeconds(),
        getVercelAgentQueueDebounceSeconds(),
      ],
    );
    logVercelAgentQueue("enqueue", {
      conversationId,
      userId,
      status: result.rows[0]?.status || null,
      retryCount: result.rows[0]?.retryCount ?? null,
      reason: params.reason || "queued",
      messageId: messageId || null,
    });
    return {
      queued: true,
      id: result.rows[0]?.id || null,
      status: result.rows[0]?.status || null,
      reason: params.reason || "queued",
    };
  } catch (error: any) {
    if (error?.code === "42P01" || error?.code === "42703" || error?.code === "23514") {
      console.warn("[vercel-http] durable agent queue unavailable; falling back to waitUntil only:", {
        conversationId,
        error: error?.message || String(error),
      });
      return { queued: false, reason: "queue_unavailable" };
    }
    throw error;
  }
}

type VercelAgentQueueJob = {
  id: string;
  conversationId: string;
  userId: string;
  retryCount: number;
};

async function claimDueVercelAgentResponseJobs(limit = getVercelAgentQueueLimit()) {
  try {
    await getPool().query(
      `
        UPDATE vercel_agent_response_jobs
        SET status = 'pending',
            execute_at = NOW(),
            failure_reason = COALESCE(NULLIF(failure_reason, ''), 'queued:vercel_gateway_agent:stale_processing'),
            updated_at = NOW()
        WHERE status = 'processing'
          AND COALESCE(failure_reason, '') LIKE 'queued:vercel_gateway_agent%'
          AND COALESCE(last_attempt_at, updated_at, NOW() - INTERVAL '1 hour')
              <= NOW() - ($1::int * INTERVAL '1 second')
      `,
      [getVercelAgentQueueVisibilitySeconds()],
    );

    const result = await getPool().query(
      `
        WITH due AS (
          SELECT id
          FROM vercel_agent_response_jobs
          WHERE status = 'pending'
            AND execute_at <= NOW()
            AND COALESCE(failure_reason, '') LIKE 'queued:vercel_gateway_agent%'
          ORDER BY
            CASE
              WHEN COALESCE(jid_suffix, '') IN ('g.us', 'broadcast', 'newsletter')
                OR COALESCE(contact_number, '') ILIKE '%status@broadcast%'
              THEN 1
              ELSE 0
            END ASC,
            COALESCE(retry_count, 0) ASC,
            execute_at ASC,
            updated_at ASC
          LIMIT $1
          FOR UPDATE SKIP LOCKED
        )
        UPDATE vercel_agent_response_jobs p
        SET status = 'processing',
            retry_count = COALESCE(p.retry_count, 0) + 1,
            last_attempt_at = NOW(),
            updated_at = NOW()
        FROM due
        WHERE p.id = due.id
        RETURNING
          p.id,
          p.conversation_id AS "conversationId",
          p.user_id AS "userId",
          COALESCE(p.retry_count, 0) AS "retryCount"
      `,
      [Math.max(1, limit)],
    );
    if ((result.rowCount || 0) > 0) {
      logVercelAgentQueue("claim", {
        count: result.rowCount || 0,
        limit: Math.max(1, limit),
        jobs: result.rows.map((row: any) => ({
          id: row.id,
          conversationId: row.conversationId,
          retryCount: row.retryCount,
        })),
      });
    }
    return result.rows as VercelAgentQueueJob[];
  } catch (error: any) {
    if (error?.code === "42P01" || error?.code === "42703" || error?.code === "23514") {
      console.warn("[vercel-http] durable agent queue claim unavailable:", error?.message || error);
      return [];
    }
    throw error;
  }
}

async function completeVercelAgentResponseJob(job: VercelAgentQueueJob, reason: string) {
  const rerun = await getPool().query(
    `
      UPDATE vercel_agent_response_jobs
      SET status = 'pending',
          execute_at = NOW(),
          failure_reason = 'queued:vercel_gateway_agent:rerun_after_processing',
          last_error = NULL,
          updated_at = NOW()
      WHERE id = $1
        AND status = 'processing'
        AND COALESCE(failure_reason, '') LIKE 'queued:vercel_gateway_agent%'
        AND updated_at > COALESCE(last_attempt_at, updated_at) + INTERVAL '1 millisecond'
      RETURNING id
    `,
    [job.id],
  );

  if ((rerun.rowCount || 0) > 0) {
    logVercelAgentQueue("complete_rerun_after_processing", {
      id: job.id,
      conversationId: job.conversationId,
      reason,
    });
    return;
  }

  await getPool().query(
    `
      UPDATE vercel_agent_response_jobs
      SET status = 'completed',
          failure_reason = $2,
          last_error = NULL,
          updated_at = NOW()
      WHERE id = $1
    `,
    [job.id, reason.slice(0, 240)],
  );
  logVercelAgentQueue("complete", {
    id: job.id,
    conversationId: job.conversationId,
    reason: reason.slice(0, 240),
  });
}

async function retryVercelAgentResponseJob(job: VercelAgentQueueJob, reason: string, error?: unknown) {
  const retryCount = Number(job.retryCount || 0);
  const reasonRetryLimit = getVercelAgentQueueReasonRetryLimit(reason);
  if (retryCount >= reasonRetryLimit) {
    await getPool().query(
      `
        UPDATE vercel_agent_response_jobs
        SET status = 'failed',
            failure_reason = $2,
            last_error = $3,
            updated_at = NOW()
        WHERE id = $1
      `,
      [
        job.id,
        `failed:${reason}:dead_letter`.slice(0, 240),
        String((error as any)?.message || error || `retry_limit_${reasonRetryLimit}`).slice(0, 500),
      ],
    );
    logVercelAgentQueue("dead_letter", {
      id: job.id,
      conversationId: job.conversationId,
      reason,
      retryCount,
      retryLimit: reasonRetryLimit,
      error: String((error as any)?.message || error || reason).slice(0, 240),
    });
    return;
  }

  const delaySeconds =
    reason === "deadline_deferred"
      ? 15
      : resolveVercelAgentQueueRetryDelaySeconds(retryCount);
  await getPool().query(
    `
      UPDATE vercel_agent_response_jobs
      SET status = 'pending',
          execute_at = NOW() + ($2::int * INTERVAL '1 second'),
          failure_reason = $3,
          last_error = $4,
          updated_at = NOW()
      WHERE id = $1
    `,
    [
      job.id,
      delaySeconds,
      `queued:vercel_gateway_agent:retry:${reason}`.slice(0, 240),
      String((error as any)?.message || error || reason).slice(0, 500),
    ],
  );
  logVercelAgentQueue("retry", {
    id: job.id,
    conversationId: job.conversationId,
    reason,
    retryCount,
    retryLimit: reasonRetryLimit,
    delaySeconds,
    error: String((error as any)?.message || error || reason).slice(0, 240),
  });
}

async function drainVercelAgentResponseQueue(options: {
  limit?: number;
  deadlineMs?: number;
  source?: string;
} = {}) {
  const startedAt = Date.now();
  const deadlineMs = Math.max(10_000, Math.min(Number(options.deadlineMs || getVercelAgentQueueDeadlineMs()), 120_000));
  const maxJobs = Math.max(1, Number(options.limit || getVercelAgentQueueLimit()));
  const source = options.source || "queue";
  const details: any[] = [];
  let claimed = 0;
  let processed = 0;
  let sent = 0;
  let skipped = 0;
  let failed = 0;

  logVercelAgentQueue("drain_start", {
    source,
    maxJobs,
    deadlineMs,
  });

  while (claimed < maxJobs) {
    if (Date.now() - startedAt > Math.max(0, deadlineMs - 5_000)) {
      details.push({ skipped: "deadline_reached_before_claim", claimed });
      break;
    }

    const jobs = await claimDueVercelAgentResponseJobs(1);
    if (jobs.length === 0) {
      break;
    }

    const job = jobs[0];
    if (!job) {
      break;
    }
    claimed += 1;

    try {
      const conversation = await getConversationForUser(job.userId, job.conversationId);
      if (!conversation) {
        await completeVercelAgentResponseJob(job, "completed:conversation_not_found");
        skipped += 1;
        details.push({ conversationId: job.conversationId, skipped: "conversation_not_found" });
        continue;
      }

      const result = await runVercelAgentForGatewayEvent(job.userId, conversation, {
        allowCatalogMediaResume: Number(job.retryCount || 0) > 1,
      });
      processed += 1;
      sent += Number(result.sentCount || 0);

      if (Number(result.sentCount || 0) > 0) {
        await completeVercelAgentResponseJob(job, "completed:sent");
      } else if (shouldRetryVercelAgentQueueSkip(result.skipped, Number(job.retryCount || 0))) {
        await retryVercelAgentResponseJob(job, String(result.skipped || "retryable_skip"));
        skipped += 1;
      } else {
        await completeVercelAgentResponseJob(job, `completed:${result.skipped || "no_send"}`);
        skipped += 1;
      }

      details.push({
        conversationId: job.conversationId,
        sentCount: result.sentCount || 0,
        skipped: result.skipped || null,
        retryCount: job.retryCount || 0,
        source,
      });
    } catch (error: any) {
      failed += 1;
      await retryVercelAgentResponseJob(job, "exception", error);
      details.push({
        conversationId: job.conversationId,
        error: error?.message || String(error),
      });
      console.warn("[vercel-http] durable agent queue job failed:", {
        conversationId: job.conversationId,
        source,
        error,
      });
    }
  }

  const result = {
    claimed,
    processed,
    sent,
    skipped,
    failed,
    details,
  };
  logVercelAgentQueue("drain_finish", {
    source,
    durationMs: Date.now() - startedAt,
    claimed,
    processed,
    sent,
    skipped,
    failed,
  });
  return result;
}

async function runVercelAgentForGatewayEvent(
  userId: string,
  conversation: ConversationSummaryRow,
  options: { messageId?: string | null; allowCatalogMediaResume?: boolean } = {},
) {
  if (isGroupConversationRow(conversation)) {
    return { sentCount: 0, skipped: "group_conversation" };
  }
  if (!shouldUseGateway(conversation)) {
    return { sentCount: 0, skipped: "not_gateway_connection" };
  }

  if (!conversationConnectionLooksConnected(conversation)) {
    const gatewayStatus = await ensureConversationGatewayReadyForSend(conversation, "agent_gateway_event", {
      allowReconnectWhenPersistedDisconnected: true,
      reconnectTimeoutMs: 12_000,
    });
    if (!gatewayStatusIsReadyForSend(gatewayStatus)) {
      return {
        sentCount: 0,
        skipped: "connection_not_ready",
        gatewayProviderStatus: gatewayStatus?.providerStatus || null,
      };
    }
  }

  if (await isNumberExcludedForUser(userId, conversation.contactNumber, false)) {
    return { sentCount: 0, skipped: "number_excluded" };
  }

  const statusResult = await handleAgentConversationStatusForInternal(userId, conversation.id, conversation);
  if (!statusResult.canRespond) {
    return { sentCount: 0, skipped: statusResult.blockReason || "agent_disabled" };
  }

  const agentResponseLockClaimed = await tryClaimWebOnlyAgentResponseLock(userId, conversation.id);
  if (!agentResponseLockClaimed) {
    return { sentCount: 0, skipped: "agent_response_locked" };
  }

  try {
    await markLegacyPendingAIResponsesSupersededByVercel({
      userId,
      conversationId: conversation.id,
      reason: "vercel_gateway_agent_runtime_active",
    });

  const messagesResult = await getPool().query(
    `
      SELECT
        id,
        message_id AS "messageId",
        from_me AS "fromMe",
        text,
        timestamp,
        status,
        is_from_agent AS "isFromAgent",
        media_type AS "mediaType",
        media_url AS "mediaUrl",
        media_mime_type AS "mediaMimeType",
        media_duration AS "mediaDuration",
        media_caption AS "mediaCaption",
        media_key AS "mediaKey",
        direct_path AS "directPath",
        media_url_original AS "mediaUrlOriginal",
        created_at AS "createdAt"
      FROM (
        SELECT
          id,
          message_id,
          from_me,
          text,
          timestamp,
          status,
          is_from_agent,
          media_type,
          media_url,
          media_mime_type,
          media_duration,
          media_caption,
          media_key,
          direct_path,
          media_url_original,
          created_at
        FROM messages
        WHERE conversation_id = $1
        ORDER BY timestamp DESC NULLS LAST, created_at DESC NULLS LAST, id DESC
        LIMIT 80
      ) recent_messages
      ORDER BY timestamp ASC NULLS FIRST, created_at ASC NULLS FIRST, id ASC
    `,
    [conversation.id],
  );
  const rows = messagesResult.rows as MessageRow[];
  const eventMessageId = String(options.messageId || "").trim();
  const targetIncoming =
    (eventMessageId
      ? rows.find((row) => !row.fromMe && String(row.messageId || "") === eventMessageId)
      : null) ||
    [...rows].reverse().find((row) => !row.fromMe && getWebOnlyIncomingMessageContent(row));
  if (!targetIncoming) {
    return { sentCount: 0, skipped: "no_incoming_message" };
  }

  const hasOutboundAfterTarget = hasOutboundAfterIncomingMessage(rows, targetIncoming);
  const canResumePartialCatalogMedia =
    options.allowCatalogMediaResume === true &&
    hasWebOnlyCatalogMediaAfterIncomingMessage(rows, targetIncoming);
  if (hasOutboundAfterTarget && !canResumePartialCatalogMedia) {
    return { sentCount: 0, skipped: "incoming_already_answered" };
  }

  const targetIndex = rows.findIndex((row) => row.id === targetIncoming.id);
  const rowsBeforeTarget = targetIndex >= 0
    ? rows.slice(0, targetIndex)
    : rows.filter((row) => compareMessageRows(row, targetIncoming) < 0);
  const incomingBurst = buildWebOnlyIncomingBurstForAgent(rows, targetIncoming);
  const rowsBeforePrompt = incomingBurst.firstIndex >= 0
    ? rows.slice(0, incomingBurst.firstIndex)
    : rowsBeforeTarget;
  const history = mapMessageRowsToWebOnlyHistory(rowsBeforePrompt.slice(-16));
  const rawTargetText = incomingBurst.text || getWebOnlyIncomingMessageContent(targetIncoming);
  const normalizedTarget = normalizeGatewayIncomingStubTextForAI(rawTargetText, rowsBeforeTarget);
  const targetText = normalizedTarget.text;
  if (isIgnorableGatewayIncomingText(targetText)) {
    return { sentCount: 0, skipped: "ignored_protocol_message" };
  }
  const manualReplySendGuard = createWebOnlyManualReplySendGuard(userId, conversation, targetIncoming);

  if (normalizedTarget.wasNormalized) {
    await persistNormalizedGatewayStubText({
      conversationId: conversation.id,
      targetIncoming,
      originalText: rawTargetText,
      normalizedText: targetText,
    });
  }

  if (!statusResult.canRespond) {
    const attentionAssessment = await classifyWebOnlyConversationAttentionOnly({
      userId,
      model: null,
      message: targetText,
      history,
    }).catch((error) => {
      console.warn("[vercel-http] attention-only classification failed:", error);
      return null;
    });
    await persistWebOnlyConversationAttentionAssessment({
      userId,
      conversation,
      attention: attentionAssessment,
      sourceLabel: statusResult.blockReason || "agent_disabled",
    });
    return {
      sentCount: 0,
      skipped: statusResult.blockReason || "agent_disabled",
      attention: attentionAssessment,
    };
  }

  await ensureGoogleContactBeforeReplyBestEffort(userId, conversation);

  const openingConfigResult = await getPool().query(
    `
      SELECT
        prompt,
        message_split_chars,
        custom_greeting,
        greeting_variation,
        greeting_enabled,
        business_hours_enabled,
        business_hours,
        off_hours_message_enabled,
        off_hours_variation,
        off_hours_message,
        ai_signature_enabled,
        ai_signature
      FROM ai_agent_config
      WHERE user_id = $1
      LIMIT 1
    `,
    [userId],
  );
  const openingConfig = openingConfigResult.rows[0] || null;
  const mediaLibraryForOpening = await loadWebOnlyAgentMediaLibrary(userId);
  const pendingOpeningFlow = resolveWebOnlyPendingOpeningFlowActions({
    config: openingConfig,
    mediaLibrary: mediaLibraryForOpening,
    contactName: conversation.contactName || undefined,
    rowsBeforeTarget,
    currentTargetIsIncomingReply: true,
  });
  if (pendingOpeningFlow?.skipped) {
    return {
      sentCount: 0,
      skipped: pendingOpeningFlow.skipped,
      openingFlowProgress: pendingOpeningFlow.progress,
      resumeAfterSeconds: pendingOpeningFlow.resumeAfterSeconds,
    };
  }
  if (pendingOpeningFlow && pendingOpeningFlow.actions.length > 0) {
    const actionSendResult = await sendWebOnlyAgentActionsViaGateway(
      userId,
      conversation.connectionId,
      conversation,
      pendingOpeningFlow.actions,
      { sendGuard: manualReplySendGuard },
    );
    if (actionSendResult.sentCount > 0) {
      await scheduleWebOnlyFollowupAfterCompanyMessage(userId, conversation.id);
    }
    return {
      sentCount: actionSendResult.sentCount,
      skipped: actionSendResult.sentCount > 0 ? null : (actionSendResult.skipped || "opening_flow_resume_empty"),
      actionSendFailures: actionSendResult.failures,
      abortedOpeningFlow: actionSendResult.abortedOpeningFlow,
      openingFlowProgress: pendingOpeningFlow.progress,
      openingFlowResumed: true,
    };
  }

  const generationStartGuard = await manualReplySendGuard({ phase: "generation_before_start" });
  if (generationStartGuard.blocked) {
    return {
      sentCount: 0,
      skipped: generationStartGuard.skipped || "manual_reply_before_agent_send",
    };
  }

  const generationAbort = createWebOnlyManualReplyGenerationAbort(manualReplySendGuard);
  const sentMediasForAgent = inferWebOnlyAgenteZapFunnelSentMediasFromPriorInbound({
    config: openingConfig,
    rowsBeforeTarget,
    targetText,
    sentMedias: extractSentMediaNamesFromRows(
      canResumePartialCatalogMedia ? rows : rowsBeforeTarget,
      mediaLibraryForOpening,
    ),
  });

  let result: Awaited<ReturnType<typeof runWebOnlyAgentTestForUser>>;
  try {
    result = await runWebOnlyAgentTestForUser(userId, {
      message: targetText,
      history,
      contactName: conversation.contactName || undefined,
      contactPhone: conversation.contactNumber || undefined,
      sentMedias: sentMediasForAgent,
      conversationId: conversation.id,
      agendamento3Commit: true,
      flow2DeferStatePersistence: true,
      skipAccessCheck: true,
      abortSignal: generationAbort.signal,
    });
  } catch (error: any) {
    const blockedDuringGeneration = generationAbort.getBlockedResult();
    if (blockedDuringGeneration?.blocked || generationAbort.signal.aborted) {
      const skipped = blockedDuringGeneration?.skipped || "manual_reply_before_agent_send";
      console.info("[vercel-http] aborted agent generation after manual reply", {
        conversationId: conversation.id,
        connectionId: conversation.connectionId,
        skipped,
        reason: blockedDuringGeneration?.reason || error?.message || null,
      });
      return { sentCount: 0, skipped };
    }
    throw error;
  } finally {
    generationAbort.stop();
  }

  const blockedAfterGeneration = generationAbort.getBlockedResult();
  if (blockedAfterGeneration?.blocked) {
    return {
      sentCount: 0,
      skipped: blockedAfterGeneration.skipped || "manual_reply_before_agent_send",
    };
  }

  if (result.status >= 400) {
    return { sentCount: 0, skipped: "agent_generation_failed", payload: result.payload };
  }
  await refreshWebOnlyAgentResponseLock(userId, conversation.id);

  const payload: any = result.payload || {};
  await persistWebOnlyConversationAttentionAssessment({
    userId,
    conversation,
    attention: payload.attention,
    sourceLabel: "gateway_event",
  });
  let splitResponses = Array.isArray(payload.splitResponses)
    ? payload.splitResponses.map((item: unknown) => String(item || "").trim()).filter(Boolean)
    : [];
  const mediaActions = Array.isArray(payload.mediaActions) ? payload.mediaActions : [];
  if (canResumePartialCatalogMedia && mediaActions.length > 0) {
    splitResponses = [];
  }
  const agentMessageForNotification = [
    ...splitResponses,
    ...mediaActions.map((action: any) => String(action?.text || action?.caption || "").trim()).filter(Boolean),
  ].join("\n");

  const rowsBeforeSendResult = await getPool().query(
    `
      SELECT
        id,
        message_id AS "messageId",
        from_me AS "fromMe",
        text,
        timestamp,
        status,
        is_from_agent AS "isFromAgent",
        media_type AS "mediaType",
        media_caption AS "mediaCaption",
        created_at AS "createdAt"
      FROM messages
      WHERE conversation_id = $1
      ORDER BY timestamp ASC NULLS FIRST, created_at ASC NULLS FIRST, id ASC
    `,
    [conversation.id],
  );
  const rowsBeforeSend = rowsBeforeSendResult.rows as MessageRow[];
  const freshTargetIncoming =
    (eventMessageId
      ? rowsBeforeSend.find((row) => !row.fromMe && String(row.messageId || "") === eventMessageId)
      : null) ||
    rowsBeforeSend.find((row) => row.id === targetIncoming.id) ||
    targetIncoming;
  if (
    hasOutboundAfterIncomingMessage(rowsBeforeSend, freshTargetIncoming) &&
    !(canResumePartialCatalogMedia && hasWebOnlyCatalogMediaAfterIncomingMessage(rowsBeforeSend, freshTargetIncoming))
  ) {
    return { sentCount: 0, skipped: "incoming_already_answered_before_send" };
  }

  await markLegacyPendingAIResponsesSupersededByVercel({
    userId,
    conversationId: conversation.id,
    reason: "vercel_gateway_agent_before_send",
  });

  let sentCount = 0;
  let manualReplySkipped: string | null = null;
  for (const text of splitResponses) {
    await refreshWebOnlyAgentResponseLock(userId, conversation.id);
    const guard = await manualReplySendGuard({ phase: "split_text_before_send" });
    if (guard.blocked) {
      manualReplySkipped = guard.skipped || "manual_reply_before_agent_send";
      console.info("[vercel-http] blocked agent text before gateway send", {
        conversationId: conversation.id,
        connectionId: conversation.connectionId,
        skipped: manualReplySkipped,
        reason: guard.reason || null,
      });
      break;
    }
    try {
      const sendResult = await sendWebOnlyAgentTextViaGateway(conversation.connectionId, conversation, text, "agent");
      await persistWebOnlyAgentSentTextFallback(conversation, text, sendResult).catch((error) => {
        console.warn("[vercel-http] failed to persist sent agent split text fallback:", error);
      });
      sentCount += 1;
    } catch (error) {
      console.warn("[vercel-http] failed to send gateway event text response:", error);
    }
  }
  await refreshWebOnlyAgentResponseLock(userId, conversation.id);
  const actionSendResult = await sendWebOnlyAgentActionsViaGateway(
    userId,
    conversation.connectionId,
    conversation,
    mediaActions,
    { sendGuard: manualReplySendGuard },
  );
  sentCount += actionSendResult.sentCount;
  if (!manualReplySkipped && actionSendResult.skipped) {
    manualReplySkipped = actionSendResult.skipped;
  }

  if (
    sentCount > 0 &&
    actionSendResult.failures.length === 0 &&
    actionSendResult.abortedOpeningFlow !== true
  ) {
    await persistFlow2PendingStateFromPayload(payload);
    await persistVisualFlowStateFromAgentPayload({
      userId,
      conversationId: conversation.id,
      payload,
      history,
    });
  }

  if (sentCount > 0 && !manualReplySkipped) {
    await scheduleWebOnlyFollowupAfterCompanyMessage(userId, conversation.id);
  }

  const notificationResult =
    manualReplySkipped && sentCount === 0
      ? { sent: 0, failed: 0, skipped: manualReplySkipped }
      : await sendWebOnlyAgentNotificationsForGatewayEvent({
          conversation,
          payload,
          clientMessage: targetText,
          agentMessage: agentMessageForNotification,
        });

  const delivery2Order = await analyzeDelivery2ConversationOrderWebOnly({
    conversationId: conversation.id,
    latestAgentReply: agentMessageForNotification,
  }).catch((error) => {
    console.error("[vercel-http] delivery 2 order decision after gateway event failed:", error);
    return null;
  });

  return {
    sentCount,
    notificationResult,
    delivery2OrderId: delivery2Order?.id || null,
    skipped: manualReplySkipped || (sentCount > 0 || notificationResult.sent > 0 ? null : "empty_agent_response"),
    actionSendFailures: actionSendResult.failures,
    abortedOpeningFlow: actionSendResult.abortedOpeningFlow,
  };
  } finally {
    await releaseWebOnlyAgentResponseLock(conversation.id);
  }
}

async function tryClaimIncomingGatewayEvent(
  userId: string,
  conversation: ConversationSummaryRow,
  data: any,
) {
  const messageId = getGatewayEventMessageId(data);
  if (!messageId) {
    return { claimed: true, duplicate: false, messageId: null };
  }

  try {
    const dedupKey = `vercel-agent-incoming:${messageId}`;
    const result = await getPool().query(
      `
        INSERT INTO message_deduplication (
          dedup_key,
          user_id,
          conversation_id,
          contact_number,
          message_type,
          source,
          content_hash,
          created_at,
          expires_at
        )
        VALUES ($1, $2, $3, $4, $5, $6, $7, NOW(), NOW() + INTERVAL '24 hours')
        ON CONFLICT (dedup_key) DO NOTHING
        RETURNING dedup_key
      `,
      [
        dedupKey,
        userId,
        conversation.id,
        conversation.contactNumber || null,
        "text",
        "vercel_agent_incoming",
        createHash("sha256").update(messageId).digest("hex"),
      ],
    );
    return { claimed: result.rows.length > 0, duplicate: result.rows.length === 0, messageId };
  } catch (error: any) {
    if (error?.code === "42P01" || error?.code === "42703" || error?.code === "42P10") {
      console.warn("[vercel-http] incoming message idempotency claim unavailable; continuing without claim:", error);
      return { claimed: true, duplicate: false, messageId };
    }
    throw error;
  }
}

async function handleInternalWhatsAppGatewayEvent(req: any, res: any) {
  if (!isInternalGatewayEventAuthorized(req)) {
    return sendJson(res, 401, { message: "Unauthorized gateway event" });
  }

  try {
    const body = await readJsonBody(req);
    const userId = String(body?.userId || "").trim();
    const data = body?.data;
    if (!userId || !data || typeof data !== "object" || Array.isArray(data)) {
      return sendJson(res, 400, { message: "Invalid gateway event payload" });
    }

    const agentOutgoingEvent = isOutgoingGatewayAgentMessageEvent(data);
    const ownerOutgoingEvent = isOutgoingGatewayOwnerMessageEvent(data);
    const incomingMessageEvent = isIncomingGatewayMessageEvent(data);
    if (!agentOutgoingEvent && !ownerOutgoingEvent && !incomingMessageEvent) {
      return sendJson(res, 200, {
        success: true,
        processed: false,
        reason: "non_incoming_message_event",
      });
    }

    const conversation = await resolveGatewayEventConversation(userId, data);
    if (!conversation) {
      return sendJson(res, 202, {
        success: true,
        processed: false,
        reason: getGatewayEventConversationId(data) ? "conversation_not_found" : "missing_gateway_conversation_scope",
      });
    }

    const activeConversation = await ensureActiveConversationForIncomingGatewayEvent(userId, conversation);

    if (agentOutgoingEvent) {
      const persistResult = await persistOutgoingGatewayAgentEventIfNeeded(activeConversation, data);
      return sendJson(res, 200, {
        success: true,
        processed: true,
        conversationId: activeConversation.id,
        previousConversationId: activeConversation.id !== conversation.id ? conversation.id : null,
        sentCount: 0,
        skipped: persistResult.reason,
        agentOutgoing: true,
        inserted: persistResult.inserted,
      });
    }

    if (ownerOutgoingEvent) {
      const pauseResult = await persistOutgoingGatewayOwnerEventAndPauseIfNeeded(userId, activeConversation, data);
      return sendJson(res, 200, {
        success: true,
        processed: true,
        conversationId: activeConversation.id,
        previousConversationId: activeConversation.id !== conversation.id ? conversation.id : null,
        sentCount: 0,
        skipped: pauseResult.reason,
        ownerManualOutgoing: true,
        inserted: pauseResult.inserted,
        agentPaused: pauseResult.paused,
      });
    }

    if (!incomingMessageEvent) {
      return sendJson(res, 200, {
        success: true,
        processed: false,
        reason: "non_incoming_message_event",
        conversationId: activeConversation.id,
      });
    }

    const incomingText = getGatewayIncomingMessageText(data);
    if (isIgnorableGatewayIncomingText(incomingText) && !isInitialMetaStubFallbackCandidate(incomingText)) {
      return sendJson(res, 200, {
        success: true,
        processed: false,
        reason: "ignored_protocol_message",
      });
    }

    const persistedIncomingMessage = await persistIncomingGatewayEventIfNeeded(userId, activeConversation, data);
    const claim = await tryClaimIncomingGatewayEvent(userId, activeConversation, data);
    if (!claim.claimed) {
      return sendJson(res, 200, {
        success: true,
        processed: false,
        reason: "duplicate_incoming_message",
        messageId: claim.messageId,
        conversationId: activeConversation.id,
      });
    }

    if (isGroupConversationRow(activeConversation)) {
      return sendJson(res, 202, {
        success: true,
        processed: true,
        queued: false,
        conversationId: activeConversation.id,
        previousConversationId: activeConversation.id !== conversation.id ? conversation.id : null,
        messageId: getGatewayEventMessageId(data),
        reason: "group_or_broadcast_persisted_without_ai_queue",
      });
    }

    const queuedMessageId = getGatewayEventMessageId(data);
    const queued = await enqueueVercelAgentResponseJob({
      userId,
      conversation: activeConversation,
      messageId: queuedMessageId,
      text: persistedIncomingMessage?.text || incomingText,
      reason: "gateway_event",
    });
    const queueDebounceMs = getVercelAgentQueueDebounceSeconds() * 1000;
    waitUntil(
      (async () => {
        if (queueDebounceMs > 0) {
          await new Promise((resolve) => setTimeout(resolve, queueDebounceMs));
        }
        return drainVercelAgentResponseQueue({
          limit: 2,
          deadlineMs: 35_000,
          source: "gateway_event_wait_until",
        });
      })().catch((error) => {
        console.error("[vercel-http] async durable gateway agent queue failed:", {
          userId,
          conversationId: activeConversation.id,
          messageId: queuedMessageId,
          error: error?.message || String(error),
        });
      }),
    );

    return sendJson(res, 202, {
      success: true,
      processed: true,
      queued: true,
      conversationId: activeConversation.id,
      previousConversationId: activeConversation.id !== conversation.id ? conversation.id : null,
      messageId: queuedMessageId,
      durableQueue: queued.queued,
    });
  } catch (error: any) {
    if (isPgConnectionAcquireTimeout(error)) {
      console.warn("[vercel-http] gateway event deferred because database connection was unavailable:", error);
      return sendJson(res, 202, {
        success: true,
        processed: false,
        reason: "database_connection_timeout",
      });
    }
    console.error("[vercel-http] gateway event processing failed:", error);
    return sendJson(res, 500, {
      message: error?.message || "Failed to process gateway event",
    });
  }
}

type GatewayReconcileCandidate = {
  userId: string;
  conversationId: string;
  messageId: string;
  timestamp: Date | string;
  createdAt: Date | string | null;
  text: string | null;
  mediaType: string | null;
};

function getGatewayReconcileLimit() {
  return Math.min(getEnvInt("WA_GATEWAY_RECONCILE_LIMIT", 6, 1), 30);
}

function getGatewayReconcileLookbackHours() {
  return Math.min(getEnvInt("WA_GATEWAY_RECONCILE_LOOKBACK_HOURS", 4, 1), 48);
}

function getGatewayFalseNegativeReconcileLookbackHours() {
  return Math.min(getEnvInt("WA_GATEWAY_FALSE_NEGATIVE_RECONCILE_LOOKBACK_HOURS", 24, 1), 48);
}

function getGatewayReconcileMinAgeSeconds() {
  return Math.min(getEnvInt("WA_GATEWAY_RECONCILE_MIN_AGE_SECONDS", 45, 15), 900);
}

function getGatewayReconcileLockMinutes() {
  return Math.min(getEnvInt("WA_GATEWAY_RECONCILE_LOCK_MINUTES", 3, 1), 120);
}

function getGatewayReconcileScanLimit() {
  return Math.min(getEnvInt("WA_GATEWAY_RECONCILE_SCAN_LIMIT", 1000, 25), 1000);
}

async function findUnansweredGatewayInboundMessagesForReconcile(limit = getGatewayReconcileLimit()) {
  const result = await getPool().query(
    `
      WITH recent_inbound AS MATERIALIZED (
        SELECT
          id,
          conversation_id,
          message_id,
          timestamp,
          created_at,
          text,
          media_caption,
          media_type
        FROM messages
        WHERE from_me = false
          AND NULLIF(BTRIM(message_id), '') IS NOT NULL
          AND timestamp >= NOW() - ($5::int * INTERVAL '1 hour')
          AND timestamp <= NOW() - ($2::int * INTERVAL '1 second')
          AND COALESCE(text, '') NOT ILIKE '[Mensagem nao suportada:%'
        ORDER BY timestamp DESC, created_at DESC, id DESC
        LIMIT $3
      ),
      latest_unanswered AS (
        SELECT DISTINCT ON (m.conversation_id)
          wc.user_id AS "userId",
          c.id AS "conversationId",
          m.message_id AS "messageId",
          m.timestamp,
          m.created_at AS "createdAt",
          m.text,
          m.media_type AS "mediaType"
        FROM recent_inbound m
        INNER JOIN conversations c
          ON c.id = m.conversation_id
        INNER JOIN whatsapp_connections wc
          ON wc.id = c.connection_id
        INNER JOIN ai_agent_config aic
          ON aic.user_id = wc.user_id
         AND aic.is_active = true
        INNER JOIN business_agent_configs bac
          ON bac.user_id = wc.user_id
         AND bac.is_active = true
        WHERE COALESCE(c.is_closed, false) = false
          AND COALESCE(wc.ai_enabled, true) = true
          AND (c.remote_jid IS NULL OR c.remote_jid NOT ILIKE '%@g.us')
          AND LOWER(COALESCE(wc.provider, 'baileys')) = 'baileys'
          AND LOWER(COALESCE(wc.connection_method, 'qr')) <> 'coexistence'
          AND (
            m.timestamp >= NOW() - ($1::int * INTERVAL '1 hour')
            OR (
              COALESCE(wc.is_connected, false) = false
              AND LOWER(COALESCE(wc.provider_status, '')) <> 'connected'
            )
          )
          AND LOWER(COALESCE(wc.provider_status, '')) NOT IN (
            'auth_failed',
            'deleted',
            'invalid_session',
            'logged_out',
            'logout',
            'pairing_required',
            'qr_required',
            'removed'
          )
          AND NOT EXISTS (
            SELECT 1
            FROM agent_disabled_conversations adc
            WHERE adc.conversation_id = c.id
          )
          AND NOT EXISTS (
            SELECT 1
            FROM messages outbound
            WHERE outbound.conversation_id = m.conversation_id
              AND outbound.from_me = true
              AND (
                outbound.timestamp > m.timestamp
                OR COALESCE(outbound.created_at, outbound.timestamp) > COALESCE(m.created_at, m.timestamp)
              )
          )
        ORDER BY m.conversation_id, m.timestamp DESC, m.created_at DESC, m.id DESC
      )
      SELECT *
      FROM latest_unanswered
      ORDER BY timestamp ASC, "createdAt" ASC, "conversationId" ASC
      LIMIT $4
    `,
    [
      getGatewayReconcileLookbackHours(),
      getGatewayReconcileMinAgeSeconds(),
      getGatewayReconcileScanLimit(),
      Math.max(1, limit),
      Math.max(getGatewayReconcileLookbackHours(), getGatewayFalseNegativeReconcileLookbackHours()),
    ],
  );

  return result.rows as GatewayReconcileCandidate[];
}

async function tryClaimGatewayReconcileMessage(candidate: GatewayReconcileCandidate) {
  const messageId = String(candidate.messageId || "").trim();
  if (!messageId) {
    return { claimed: false, duplicate: false, reason: "missing_message_id" };
  }

  const rawKey = `${candidate.conversationId}:${messageId}`;
  const contentHash = createHash("sha256").update(rawKey).digest("hex");
  const dedupKey = `vercel-agent-reconcile:${contentHash.slice(0, 48)}`;

  try {
    const result = await getPool().query(
      `
        INSERT INTO message_deduplication (
          dedup_key,
          user_id,
          conversation_id,
          contact_number,
          message_type,
          source,
          content_hash,
          created_at,
          expires_at
        )
        VALUES (
          $1, $2, $3, NULL, $4, $5, $6, NOW(),
          NOW() + ($7::int * INTERVAL '1 minute')
        )
        ON CONFLICT (dedup_key) DO UPDATE
        SET user_id = EXCLUDED.user_id,
            conversation_id = EXCLUDED.conversation_id,
            contact_number = EXCLUDED.contact_number,
            message_type = EXCLUDED.message_type,
            source = EXCLUDED.source,
            content_hash = EXCLUDED.content_hash,
            created_at = NOW(),
            expires_at = EXCLUDED.expires_at
        WHERE message_deduplication.expires_at <= NOW()
        RETURNING dedup_key
      `,
      [
        dedupKey,
        candidate.userId,
        candidate.conversationId,
        candidate.mediaType || "text",
        "vercel_agent_reconcile",
        contentHash,
        getGatewayReconcileLockMinutes(),
      ],
    );

    return {
      claimed: result.rows.length > 0,
      duplicate: result.rows.length === 0,
      reason: result.rows.length > 0 ? null : "recently_reconciled",
      dedupKey,
    };
  } catch (error: any) {
    if (error?.code === "42P01" || error?.code === "42703" || error?.code === "42P10") {
      console.warn("[vercel-http] gateway reconcile lock unavailable; continuing without claim:", error);
      return { claimed: true, duplicate: false, reason: null, dedupKey };
    }
    throw error;
  }
}

async function releaseGatewayReconcileMessageClaim(dedupKey?: string | null) {
  const key = String(dedupKey || "").trim();
  if (!key) return;
  try {
    await getPool().query(
      `DELETE FROM message_deduplication WHERE dedup_key = $1 AND source = 'vercel_agent_reconcile'`,
      [key],
    );
  } catch (error: any) {
    if (error?.code === "42P01" || error?.code === "42703") {
      return;
    }
    console.warn("[vercel-http] failed to release gateway reconcile claim:", error);
  }
}

async function runWaGatewayInboundReconciliation(options: { limit?: number; userId?: string | null } = {}) {
  const candidates = await findUnansweredGatewayInboundMessagesForReconcile(options.limit || getGatewayReconcileLimit());
  const scopedCandidates = options.userId
    ? candidates.filter((candidate) => candidate.userId === options.userId)
    : candidates;
  const details: any[] = [];
  let processed = 0;
  let sent = 0;
  let skipped = 0;
  let failed = 0;

  for (const candidate of scopedCandidates) {
    if (
      isIgnorableGatewayIncomingText(candidate.text || "") &&
      !isInitialMetaStubFallbackCandidate(candidate.text || "")
    ) {
      skipped += 1;
      details.push({
        conversationId: candidate.conversationId,
        messageId: candidate.messageId,
        skipped: "ignored_protocol_message",
      });
      continue;
    }

    const claim = await tryClaimGatewayReconcileMessage(candidate);
    if (!claim.claimed) {
      skipped += 1;
      details.push({
        conversationId: candidate.conversationId,
        messageId: candidate.messageId,
        skipped: claim.reason || "not_claimed",
      });
      continue;
    }

    const conversation = await getConversationForUser(candidate.userId, candidate.conversationId);
    if (!conversation) {
      skipped += 1;
      details.push({
        conversationId: candidate.conversationId,
        messageId: candidate.messageId,
        skipped: "conversation_not_found",
      });
      continue;
    }

    try {
      const result = await enqueueVercelAgentResponseJob({
        userId: candidate.userId,
        conversation,
        messageId: candidate.messageId,
        text: candidate.text || null,
        reason: "gateway_reconcile",
      });
      processed += 1;
      if (!result.queued) skipped += 1;
      details.push({
        conversationId: candidate.conversationId,
        messageId: candidate.messageId,
        queued: result.queued,
        skipped: result.queued ? null : result.reason,
      });
    } catch (error: any) {
      failed += 1;
      details.push({
        conversationId: candidate.conversationId,
        messageId: candidate.messageId,
        error: error?.message || String(error),
      });
      console.warn("[vercel-http] gateway reconcile failed for candidate:", {
        conversationId: candidate.conversationId,
        messageId: candidate.messageId,
        error,
      });
    }
  }

  return {
    candidates: candidates.length,
    scopedCandidates: scopedCandidates.length,
    processed,
    sent,
    skipped,
    failed,
    details,
  };
}

async function handleWaGatewayReconcileCron(req: any, res: any) {
  const secret = String(process.env.CRON_SECRET || "").trim();
  const authHeader = String(req.headers.authorization || "").trim();
  if (secret && authHeader !== `Bearer ${secret}`) {
    return sendJson(res, 401, { success: false, message: "Unauthorized" });
  }

  try {
    const queueResult = await drainVercelAgentResponseQueue({
      limit: getVercelAgentQueueLimit(),
      deadlineMs: 40_000,
      source: "wa_gateway_reconcile_pre_queue",
    });
    const result = await runWaGatewayInboundReconciliation();
    const queueResultAfter = await drainVercelAgentResponseQueue({
      limit: Math.max(1, Math.floor(getVercelAgentQueueLimit() / 2)),
      deadlineMs: 25_000,
      source: "wa_gateway_reconcile_post_queue",
    });
    return sendJson(res, 200, {
      success: true,
      queue: queueResult,
      ...result,
      queueAfterReconcile: queueResultAfter,
    });
  } catch (error: any) {
    if (isPgConnectionAcquireTimeout(error)) {
      console.warn("[vercel-http] gateway reconcile deferred because database connection was unavailable:", error);
      return sendJson(res, 202, {
        success: true,
        processed: false,
        reason: "database_connection_timeout",
      });
    }
    console.error("[vercel-http] gateway reconcile cron failed:", error);
    return sendJson(res, 500, {
      success: false,
      message: error?.message || "Failed to reconcile gateway messages",
    });
  }
}

async function handleVercelAgentQueueStatus(req: any, res: any) {
  const cronSecret = String(process.env.CRON_SECRET || "").trim();
  const gatewayToken = String(process.env.WA_GATEWAY_INTERNAL_TOKEN || "").trim();
  const authHeader = String(req.headers.authorization || "").trim();
  const gatewayHeader = String(req.headers["x-wa-gateway-token"] || "").trim();
  const authorized =
    (cronSecret && authHeader === `Bearer ${cronSecret}`) ||
    (gatewayToken && gatewayHeader === gatewayToken);

  if (!authorized) {
    return sendJson(res, 401, { success: false, message: "Unauthorized" });
  }

  try {
    const [queueSummary, reasonBuckets, activeJobs, pendingIncoming, directLatency] = await Promise.all([
      getPool().query(`
        SELECT
          COUNT(*) FILTER (WHERE status IN ('pending', 'processing'))::int AS active,
          COUNT(*) FILTER (WHERE status = 'pending')::int AS pending,
          COUNT(*) FILTER (WHERE status = 'processing')::int AS processing,
          COUNT(*) FILTER (
            WHERE status = 'processing'
              AND updated_at < NOW() - INTERVAL '3 minutes'
          )::int AS stale_processing,
          MIN(created_at) FILTER (WHERE status IN ('pending', 'processing')) AS oldest_active,
          MAX(updated_at) AS newest_updated
        FROM vercel_agent_response_jobs
      `),
      getPool().query(`
        SELECT
          status,
          regexp_replace(COALESCE(failure_reason, ''), '(:[A-F0-9]{8,}|:[0-9A-Za-z_-]{12,})$', ':<id>') AS reason_bucket,
          COUNT(*)::int AS total,
          MIN(created_at) AS oldest,
          MAX(updated_at) AS newest,
          MAX(COALESCE(retry_count, 0))::int AS max_retry
        FROM vercel_agent_response_jobs
        WHERE created_at >= NOW() - INTERVAL '2 hours'
           OR status IN ('pending', 'processing')
        GROUP BY status, reason_bucket
        ORDER BY
          CASE WHEN status IN ('pending', 'processing') THEN 0 ELSE 1 END,
          total DESC
        LIMIT 40
      `),
      getPool().query(`
        SELECT
          j.id,
          j.conversation_id AS "conversationId",
          j.status,
          COALESCE(j.retry_count, 0)::int AS "retryCount",
          LEFT(COALESCE(j.failure_reason, ''), 220) AS "failureReason",
          j.created_at AS "createdAt",
          j.execute_at AS "executeAt",
          j.updated_at AS "updatedAt",
          c.contact_number AS "contactNumber",
          c.contact_name AS "contactName",
          u.email
        FROM vercel_agent_response_jobs j
        LEFT JOIN conversations c ON c.id = j.conversation_id
        LEFT JOIN whatsapp_connections wc ON wc.id = c.connection_id
        LEFT JOIN auth.users u ON u.id::text = wc.user_id::text
        WHERE j.status IN ('pending', 'processing')
        ORDER BY j.created_at ASC
        LIMIT 25
      `),
      getPool().query(`
        SELECT
          status,
          COUNT(*)::int AS total,
          MIN(received_at) AS oldest_received,
          MAX(received_at) AS newest_received,
          MAX(COALESCE(process_attempts, 0))::int AS max_attempts
        FROM pending_incoming_messages
        WHERE status IN ('pending', 'processing', 'failed')
           OR received_at >= NOW() - INTERVAL '2 hours'
        GROUP BY status
        ORDER BY status
      `),
      getPool().query(`
        WITH direct_inbound AS (
          SELECT
            EXTRACT(EPOCH FROM (m.created_at - m.timestamp))::int AS persist_delay_seconds
          FROM messages m
          JOIN conversations c ON c.id = m.conversation_id
          WHERE m.created_at >= NOW() - INTERVAL '2 hours'
            AND m.from_me = false
            AND NOT (
              COALESCE(c.jid_suffix, '') = 'g.us'
              OR COALESCE(c.remote_jid, '') LIKE '%@g.us'
              OR COALESCE(c.remote_jid, '') LIKE '%@newsletter%'
              OR COALESCE(c.remote_jid, '') = 'status@broadcast'
            )
        )
        SELECT
          COUNT(*)::int AS direct_inbound,
          percentile_cont(0.5) WITHIN GROUP (ORDER BY persist_delay_seconds) AS p50_persist_s,
          percentile_cont(0.9) WITHIN GROUP (ORDER BY persist_delay_seconds) AS p90_persist_s,
          percentile_cont(0.95) WITHIN GROUP (ORDER BY persist_delay_seconds) AS p95_persist_s,
          MAX(persist_delay_seconds)::int AS max_persist_s,
          COUNT(*) FILTER (WHERE persist_delay_seconds > 120)::int AS persist_over_120s
        FROM direct_inbound
      `),
    ]);

    return sendJson(res, 200, {
      success: true,
      queue: queueSummary.rows[0] || {},
      reasonBuckets: reasonBuckets.rows,
      activeJobs: activeJobs.rows,
      pendingIncoming: pendingIncoming.rows,
      directLatency2h: directLatency.rows[0] || {},
    });
  } catch (error: any) {
    console.error("[vercel-agent-queue] status_failed", error);
    return sendJson(res, 500, {
      success: false,
      message: error?.message || "Failed to load queue status",
    });
  }
}

async function handleAgentConversationStatusForInternal(
  userId: string,
  conversationId: string,
  conversation: ConversationSummaryRow,
) {
  const accessPayload = await buildAccessStatusPayloadForUser(userId);
  if (accessPayload.shouldBlock) {
    return {
      canRespond: false,
      blockReason: String(accessPayload.message || "Regularize a assinatura para reativar a IA."),
      isExcluded: false,
      accessBlockReason: accessPayload.blockReason,
    };
  }

  const disabledResult = await getPool().query(
    "SELECT conversation_id FROM agent_disabled_conversations WHERE conversation_id = $1 LIMIT 1",
    [conversationId],
  );
  const agentConfigResult = await getPool().query(
    `
      SELECT
        is_active AS "isActive",
        flow_mode_active AS "flowModeActive",
        flow_script AS "flowScript"
      FROM ai_agent_config
      WHERE user_id = $1
      LIMIT 1
    `,
    [userId],
  );
  const businessConfigResult = await getPool().query(
    "SELECT is_active AS \"isActive\" FROM business_agent_configs WHERE user_id = $1 LIMIT 1",
    [userId],
  );
  const flow2Result = await getPool().query(
    `SELECT id
       FROM flow2_leona_flows
      WHERE user_id = $1
        AND is_active = true
        AND COALESCE(is_archived, false) = false
      LIMIT 1`,
    [userId],
  );
  const isDisabled = disabledResult.rows.length > 0;
  const isExcluded = await isNumberExcludedForUser(userId, conversation.contactNumber, false);
  const isConnectionAiEnabled = conversation.aiEnabled !== false;
  const isGlobalAgentActive = agentConfigResult.rows[0]?.isActive === true;
  const isFlowModeActive = agentConfigResult.rows[0]?.flowModeActive === true;
  const hasFlowScript = String(agentConfigResult.rows[0]?.flowScript || "").trim().length > 10;
  const isBusinessAgentActive = businessConfigResult.rows[0]?.isActive === true;
  const isFlow2Active = flow2Result.rows.length > 0;
  const canFlowRespond = isFlowModeActive && hasFlowScript;
  const canAiRespond = isGlobalAgentActive && isBusinessAgentActive;
  const canRespond = !isDisabled && !isExcluded && isConnectionAiEnabled && (isFlow2Active || canFlowRespond || canAiRespond);
  let blockReason: string | null = null;
  if (isExcluded) blockReason = "Numero na lista de exclusao.";
  else if (isDisabled) blockReason = "A IA esta desativada somente nesta conversa.";
  else if (!isConnectionAiEnabled) blockReason = "A IA esta desligada nesta conexao.";
  else if (!isFlow2Active && isFlowModeActive && !hasFlowScript) blockReason = "Fluxo Chat Bot ativo, mas sem roteiro salvo.";
  else if (!isFlow2Active && !isGlobalAgentActive) blockReason = "O agente global esta desativado.";
  else if (!isFlow2Active && !isBusinessAgentActive) blockReason = "A IA operacional esta desativada.";
  return { canRespond, blockReason, isExcluded };
}

async function handleFollowupConversationStatus(req: any, res: any) {
  const user = await requireJwtUser(req, res);
  if (!user) return;

  try {
    const conversationId = String(req.params?.conversationId || "").trim();
    const conversation = await getConversationForUser(user.id, conversationId);
    if (!conversation) {
      return sendJson(res, 404, { message: "Conversa nao encontrada" });
    }
    if (isGroupConversationRow(conversation)) {
      return sendJson(res, 200, {
        active: false,
        stage: 0,
        nextFollowupAt: null,
        disabledReason: "Follow-up automatico nao esta disponivel para grupos.",
      });
    }

    const connectionState = await resolveFollowupConversationConnectionState(conversation);
    return sendJson(res, 200, {
      active: conversation.followupActive === true,
      stage: Number(conversation.followupStage || 0),
      nextFollowupAt: conversation.nextFollowupAt || null,
      disabledReason: conversation.followupDisabledReason || null,
      connectionAvailable: connectionState.available,
      connectionUnavailableReason: connectionState.available ? null : connectionState.reason,
      connectionId: conversation.connectionId,
      connectionPhoneNumber: conversation.connectionPhoneNumber,
      connectionIsConnected: connectionState.dbConnected || connectionState.gatewayConnected,
    });
  } catch (error: any) {
    console.error("[vercel-http] followup status failed:", error);
    return sendJson(res, 500, { message: error?.message || "Erro ao buscar status" });
  }
}

async function handleFollowupConversationToggle(req: any, res: any) {
  const user = await requireJwtUser(req, res);
  if (!user) return;

  try {
    const conversationId = String(req.params?.conversationId || "").trim();
    const body = await readJsonBody(req);
    if (typeof body.active !== "boolean") {
      return sendJson(res, 400, { message: "active boolean is required" });
    }
    const conversation = await getConversationForUser(user.id, conversationId);
    if (!conversation) {
      return sendJson(res, 404, { message: "Conversa nao encontrada" });
    }
    if (isGroupConversationRow(conversation)) {
      return sendJson(res, 400, { message: "Follow-up automatico nao esta disponivel para grupos." });
    }
    if (body.active === true) {
      const connectionState = await resolveFollowupConversationConnectionState(conversation);
      if (!connectionState.available) {
        return sendJson(res, 409, {
          success: false,
          blocked: true,
          reason: "connection_unavailable",
          message: connectionState.reason,
          connectionId: conversation.connectionId,
          connectionPhoneNumber: conversation.connectionPhoneNumber,
          conversationOwnerPhoneNumber: conversation.conversationOwnerPhoneNumber,
        });
      }
    }

    await getPool().query(
      `
        UPDATE conversations
        SET followup_active = $2,
            followup_disabled_reason = CASE WHEN $2 THEN NULL ELSE $3 END,
            updated_at = NOW()
        WHERE id = $1
      `,
      [conversationId, body.active === true, body.reason ? String(body.reason) : "Desativado pelo usuario"],
    );

    return sendJson(res, 200, { success: true, active: body.active === true });
  } catch (error: any) {
    console.error("[vercel-http] followup toggle failed:", error);
    return sendJson(res, 500, { message: error?.message || "Erro ao alternar follow-up" });
  }
}

async function handleFollowupConversationSchedule(req: any, res: any) {
  const user = await requireJwtUser(req, res);
  if (!user) return;

  try {
    const conversationId = String(req.params?.conversationId || "").trim();
    const body = await readJsonBody(req);
    const scheduledFor = String(body.scheduledFor || "").trim();
    if (!scheduledFor) {
      return sendJson(res, 400, { message: "scheduledFor is required" });
    }
    const scheduledDate = new Date(scheduledFor);
    if (Number.isNaN(scheduledDate.getTime()) || scheduledDate <= new Date()) {
      return sendJson(res, 400, { message: "Data invalida" });
    }
    const conversation = await getConversationForUser(user.id, conversationId);
    if (!conversation) {
      return sendJson(res, 404, { message: "Conversa nao encontrada" });
    }
    if (isGroupConversationRow(conversation)) {
      return sendJson(res, 400, { message: "Lembrete manual nao esta disponivel para grupos." });
    }

    const connectionState = await resolveFollowupConversationConnectionState(conversation);
    if (!connectionState.available) {
      return sendJson(res, 409, {
        success: false,
        blocked: true,
        reason: "connection_unavailable",
        message: connectionState.reason,
        connectionId: conversation.connectionId,
        connectionPhoneNumber: conversation.connectionPhoneNumber,
      });
    }

    await getPool().query(
      `
        UPDATE conversations
        SET followup_active = true,
            next_followup_at = $2,
            followup_disabled_reason = $3,
            updated_at = NOW()
        WHERE id = $1
      `,
      [conversationId, scheduledDate.toISOString(), body.note ? String(body.note) : null],
    );

    return sendJson(res, 200, {
      success: true,
      message: "Follow-up agendado com sucesso",
      scheduledFor: scheduledDate.toISOString(),
    });
  } catch (error: any) {
    console.error("[vercel-http] followup schedule failed:", error);
    return sendJson(res, 500, { message: error?.message || "Erro ao agendar follow-up" });
  }
}

async function handleCloseConversationTicket(req: any, res: any) {
  const user = await requireUserOrTeamMember(req, res);
  if (!user) return;
  if (!ensureTeamMemberPermission(user, res, "canSendMessages", "Permissao insuficiente para encerrar atendimentos.")) return;

  try {
    const conversationId = String(req.params?.conversationId || "").trim();
    const body = await readJsonBody(req);
    const conversation = await getConversationForActor(user, conversationId, true);
    if (!conversation) {
      return sendJson(res, 404, { message: "Conversation not found" });
    }
    if (conversation.isClosed === true) {
      return sendJson(res, 400, { message: "Conversa ja esta fechada." });
    }

    const actorId = getActorAuditId(user);
    const actorName = getActorAuditName(user);
    const reason = body.reason ? String(body.reason) : "Encerrado pelo atendente";
    const result = await getPool().query(
      `
        UPDATE conversations
        SET is_closed = true,
            is_archived = true,
            closed_at = NOW(),
            closed_by = $2,
            closure_reason = $3,
            followup_active = false,
            followup_stage = 0,
            next_followup_at = NULL,
            followup_disabled_reason = 'Conversa encerrada pelo atendente.',
            orchestration_mode = 'ai',
            assigned_to_member_id = NULL,
            handoff_reason = 'Atendimento encerrado.',
            handed_off_at = NOW(),
            handed_off_by = $2,
            updated_at = NOW()
        WHERE id = $1
        RETURNING *
      `,
      [conversationId, actorId, reason],
    );
    try {
      await getPool().query(
        `
          INSERT INTO ticket_closure_logs (conversation_id, action, performed_by, performed_by_name, reason)
          VALUES ($1, 'closed', $2, $3, $4)
        `,
        [conversationId, actorId, actorName, body.reason ? String(body.reason) : null],
      );
    } catch (logError: any) {
      if (logError?.code !== "42P01") throw logError;
    }

    return sendJson(res, 200, { success: true, conversation: toCamelRecord(result.rows[0] || {}) });
  } catch (error: any) {
    console.error("[vercel-http] close ticket failed:", error);
    return sendJson(res, 500, { message: error?.message || "Failed to close ticket" });
  }
}

async function handleSendConversationMedia(req: any, res: any, audioOnly = false) {
  const user = await requireUserOrTeamMember(req, res);
  if (!user) return;
  if (!ensureTeamMemberPermission(user, res, "canSendMessages", "Permissao insuficiente para enviar midias.")) return;

  try {
    const conversationId = String(req.params?.conversationId || "").trim();
    const body = await readJsonBody(req);
    const conversation = await getConversationForActor(user, conversationId, true);
    if (!conversation) {
      return sendJson(res, 404, { message: "Conversation not found" });
    }
    if (!shouldUseGateway(conversation)) {
      return sendJson(res, 409, { message: "Conexao fora do runtime Vercel + gateway." });
    }

    const gatewayStatus = await ensureConversationGatewayReadyForSend(
      conversation,
      audioOnly ? "manual_audio" : "manual_media",
    );
    if (
      (gatewayStatus && !gatewayStatusIsReadyForSend(gatewayStatus)) ||
      (!conversationConnectionLooksConnected(conversation) && !gatewayStatusLooksConnected(gatewayStatus))
    ) {
      return sendJson(res, 409, buildConversationConnectionUnavailablePayload(conversation, gatewayStatus));
    }

    const mediaUrl = audioOnly ? "" : String(body.mediaUrl || body.fileUrl || "").trim();
    const data = audioOnly
      ? String(body.audioData || "").trim()
      : String(body.fileData || "").trim() || mediaUrl;
    if (!data) {
      return sendJson(res, 400, { message: audioOnly ? "Audio data is required" : "File data is required" });
    }

    const rawType = audioOnly ? "audio" : String(body.mediaType || "").trim().toLowerCase();
    const mediaType =
      rawType === "audio" || rawType === "video" || rawType === "document" || rawType === "image"
        ? rawType
        : "document";
    const outgoingMimeType = normalizeOutgoingWhatsAppMediaMimeType(mediaType, body.mimeType || undefined);
    const mediaDuration = audioOnly || mediaType === "audio" || mediaType === "video"
      ? Number(body.duration || body.mediaDuration || 0) || null
      : null;
    const mediaCaption = body.caption ? String(body.caption) : null;
    const fileName = body.fileName ? String(body.fileName) : undefined;
    const mediaLabel =
      mediaType === "image" ? "Imagem enviada" :
        mediaType === "video" ? "Video enviado" :
          mediaType === "audio" ? "Audio enviado" :
            fileName || "Documento enviado";
    const lastMessageText = mediaCaption || mediaLabel;
    const currentOwnerPhoneNumber = normalizeFollowupPhone(gatewayStatus?.phoneNumber || conversation.connectionPhoneNumber) || null;

    let persistedMessage = await insertManualOutgoingMessage({
      conversationId,
      text: mediaType === "document" ? fileName || mediaLabel : lastMessageText,
      status: "sending",
      isFromAgent: false,
      mediaType,
      mediaUrl: mediaUrl || (audioOnly ? data : null),
      mediaMimeType: outgoingMimeType || String(body.mimeType || "") || null,
      mediaDuration,
      mediaCaption,
    });
    const manualState = await applyManualOutgoingConversationState({
      userId: user.id,
      conversationId,
      lastMessageText,
      ownerPhoneNumber: currentOwnerPhoneNumber,
    });

    let sendResult: Awaited<ReturnType<typeof sendGatewayInstanceMedia>>;
    try {
      sendResult = await sendGatewayInstanceMedia(conversation.connectionId, {
        conversationId,
        type: mediaType,
        data,
        mimetype: outgoingMimeType,
        filename: fileName,
        caption: mediaCaption || undefined,
        ptt: audioOnly || mediaType === "audio",
        seconds: mediaDuration || undefined,
        to: conversation.contactNumber || undefined,
        contactName: conversation.contactName || undefined,
        isFromAgent: false,
        source: "owner",
      });
    } catch (error) {
      persistedMessage = (await updateManualOutgoingMessageStatus(persistedMessage.id, { status: "failed" })) || persistedMessage;
      throw error;
    }

    if (!isSuccessfulGatewaySendResult(sendResult)) {
      persistedMessage = (await updateManualOutgoingMessageStatus(persistedMessage.id, { status: "failed" })) || persistedMessage;
      return sendJson(res, sendResult?.blocked === true ? 409 : 502, {
        success: false,
        message: sendResult?.reason || "Falha ao confirmar envio da midia no WhatsApp.",
        reason: sendResult?.reason || null,
        blocked: sendResult?.blocked === true,
        messageRecord: persistedMessage,
      });
    }

    persistedMessage =
      (await updateManualOutgoingMessageStatus(persistedMessage.id, {
        status: "sent",
        messageId: sendResult?.messageId || null,
      })) || persistedMessage;

    return sendJson(res, 200, {
      success: true,
      agentPaused: manualState.shouldPause,
      messageId: persistedMessage.messageId || sendResult?.messageId || null,
      mediaUrl: mediaUrl || null,
      message: persistedMessage,
    });
  } catch (error: any) {
    console.error("[vercel-http] send conversation media failed:", error);
    return sendJson(res, 500, { message: error?.message || "Failed to send media" });
  }
}

async function handleRedownloadMessageMedia(req: any, res: any) {
  const user = await requireJwtUser(req, res);
  if (!user) return;

  try {
    const messageId = String(req.params?.messageId || "").trim();
    const result = await getPool().query(
      `
        SELECT
          m.id,
          m.conversation_id AS "conversationId",
          m.media_url AS "mediaUrl",
          c.connection_id AS "connectionId"
        FROM messages m
        INNER JOIN conversations c ON c.id = m.conversation_id
        INNER JOIN whatsapp_connections wc ON wc.id = c.connection_id
        WHERE m.id = $1
          AND wc.user_id = $2
        LIMIT 1
      `,
      [messageId, user.id],
    );
    const row = result.rows[0];
    if (!row) {
      return sendJson(res, 404, { success: false, message: "Mensagem nao encontrada" });
    }
    if (row.mediaUrl) {
      return sendJson(res, 200, { success: true, message: "Midia ja disponivel.", mediaUrl: row.mediaUrl });
    }

    const gatewayResult = await redownloadGatewayInstanceMessageMedia(
      String(row.connectionId),
      String(row.conversationId),
      messageId,
    );
    return sendJson(res, 200, {
      success: gatewayResult?.success !== false,
      message: gatewayResult?.message || "Midia recuperada.",
      mediaUrl: gatewayResult?.mediaUrl || null,
    });
  } catch (error: any) {
    console.error("[vercel-http] redownload media failed:", error);
    return sendJson(res, 500, { success: false, message: error?.message || "Erro ao tentar rebaixar midia" });
  }
}

async function safeDeleteConversationSideTable(tableName: string, conversationId: string) {
  try {
    await getPool().query(`DELETE FROM ${tableName} WHERE conversation_id = $1`, [conversationId]);
  } catch (error: any) {
    if (error?.code === "42P01" || error?.code === "42703") {
      return;
    }
    throw error;
  }
}

