async function getOwnerWorkspaceStats(ownerUserId: string) {
  const result = await getPool().query(
    `WITH managed AS (
       SELECT
         u.id,
         s.status AS subscription_status,
         s.data_fim,
         s.next_payment_date,
         COALESCE(wc.is_connected_effective, false) AS whatsapp_connected,
         EXISTS(SELECT 1 FROM subscriptions sh WHERE sh.user_id = u.id) AS has_subscription_history,
         EXISTS(SELECT 1 FROM reseller_clients rc WHERE rc.user_id = u.id) AS has_reseller_access,
         COALESCE(msg.agent_messages_count, 0) AS agent_messages_count
       FROM users u
       LEFT JOIN LATERAL (
         SELECT *
         FROM subscriptions sub
         WHERE sub.user_id = u.id
         ORDER BY sub.created_at DESC
         LIMIT 1
       ) s ON true
       LEFT JOIN LATERAL (
         SELECT
           CASE
             WHEN c.provider = 'baileys'
              AND COALESCE(NULLIF(c.connection_method, ''), 'qr') <> 'coexistence'
              AND COALESCE(NULLIF(c.provider_status, ''), 'inactive') = 'connected'
             THEN true
             ELSE COALESCE(c.is_connected, false)
           END AS is_connected_effective,
           c.id
         FROM whatsapp_connections c
         WHERE c.user_id = u.id
         ORDER BY c.created_at DESC
         LIMIT 1
       ) wc ON true
       LEFT JOIN LATERAL (
         SELECT COUNT(*)::int AS agent_messages_count
         FROM messages m
         JOIN conversations conv ON conv.id = m.conversation_id
         WHERE conv.connection_id = wc.id
           AND m.is_from_agent = true
       ) msg ON true
       WHERE u.id <> $1
         AND COALESCE(u.role, '') NOT IN ('owner', 'admin')
     )
     SELECT
       COUNT(*)::int AS total,
       COUNT(*) FILTER (WHERE subscription_status = 'active')::int AS with_plan,
       COUNT(*) FILTER (WHERE NOT whatsapp_connected)::int AS disconnected,
       COUNT(*) FILTER (
         WHERE NOT has_subscription_history
           AND NOT has_reseller_access
           AND agent_messages_count >= 25
       )::int AS trial_limit_reached,
       COUNT(*) FILTER (
         WHERE COALESCE(next_payment_date, data_fim) IS NOT NULL
           AND COALESCE(next_payment_date, data_fim) < NOW()
       )::int AS overdue_payments
     FROM managed`,
    [ownerUserId],
  );
  const row = result.rows[0] || {};
  const total = toInt(row.total);
  const withPlan = toInt(row.with_plan);
  return {
    total,
    withPlan,
    withoutPlan: Math.max(total - withPlan, 0),
    disconnected: toInt(row.disconnected),
    overduePayments: toInt(row.overdue_payments),
    trialLimitReached: toInt(row.trial_limit_reached),
  };
}

async function getOwnerWorkspaceHistory(ownerUserId: string, filters: { page: number; pageSize: number; type?: string; status?: string }) {
  const page = Math.max(1, toInt(filters.page, 1));
  const limit = Math.max(1, Math.min(toInt(filters.pageSize, 20), 100));
  const offset = (page - 1) * limit;
  const params: any[] = [ownerUserId];
  const where = ["owner_user_id = $1"];
  if (filters.type && filters.type !== "all") {
    params.push(filters.type);
    where.push(`notification_type = $${params.length}`);
  }
  if (filters.status && filters.status !== "all") {
    params.push(filters.status);
    where.push(`status = $${params.length}`);
  }
  const whereSql = where.join(" AND ");
  const [logs, count] = await Promise.all([
    getPool().query(
      `SELECT *
       FROM owner_notification_logs
       WHERE ${whereSql}
       ORDER BY created_at DESC
       LIMIT $${params.length + 1} OFFSET $${params.length + 2}`,
      [...params, limit, offset],
    ),
    getPool().query(`SELECT COUNT(*)::int AS total FROM owner_notification_logs WHERE ${whereSql}`, params),
  ]);
  const total = toInt(count.rows[0]?.total);
  return { logs: logs.rows, pagination: { page, limit, pageSize: limit, total, totalPages: Math.max(1, Math.ceil(total / limit)) } };
}

async function getOwnerWorkspaceScheduled(ownerUserId: string, startDate?: string, endDate?: string) {
  const params: any[] = [ownerUserId];
  const where = ["osn.owner_user_id = $1"];
  if (startDate || endDate) {
    params.push(startDate || endDate);
    where.push(`DATE(osn.scheduled_for AT TIME ZONE 'America/Sao_Paulo') >= $${params.length}::date`);
    params.push(endDate || startDate);
    where.push(`DATE(osn.scheduled_for AT TIME ZONE 'America/Sao_Paulo') <= $${params.length}::date`);
  } else {
    params.push(new Date(Date.now() + 14 * 24 * 60 * 60 * 1000).toISOString().slice(0, 10));
    where.push("osn.scheduled_for >= NOW()");
    where.push(`DATE(osn.scheduled_for AT TIME ZONE 'America/Sao_Paulo') <= $${params.length}::date`);
  }
  const result = await getPool().query(
    `SELECT osn.*, u.name AS user_name, u.email AS user_email
     FROM owner_scheduled_notifications osn
     LEFT JOIN users u ON u.id = osn.user_id
     WHERE ${where.join(" AND ")}
     ORDER BY osn.scheduled_for ASC
     LIMIT 1000`,
    params,
  );
  return result.rows;
}

async function deleteOwnerScheduledNotification(ownerUserId: string, id: string) {
  await getPool().query("DELETE FROM owner_scheduled_notifications WHERE owner_user_id = $1 AND id = $2", [ownerUserId, id]);
}

async function getOwnerWorkspaceCalendar(ownerUserId: string, month: number, year: number) {
  const start = new Date(Date.UTC(year, month - 1, 1, 0, 0, 0, 0));
  const end = new Date(Date.UTC(year, month, 0, 23, 59, 59, 999));
  const result = await getPool().query(
    `SELECT
       DATE(scheduled_for AT TIME ZONE 'America/Sao_Paulo') AS day,
       status,
       notification_type,
       COUNT(*)::int AS total
     FROM owner_scheduled_notifications
     WHERE owner_user_id = $1
       AND scheduled_for >= $2
       AND scheduled_for <= $3
     GROUP BY 1, 2, 3
     ORDER BY 1 ASC`,
    [ownerUserId, start.toISOString(), end.toISOString()],
  );
  const calendar: Record<string, { total: number; pending: number; sent: number; failed: number; byType: Record<string, number> }> = {};
  for (const row of result.rows) {
    const dayKey = row.day instanceof Date ? row.day.toISOString().slice(0, 10) : String(row.day || "").slice(0, 10);
    calendar[dayKey] ||= { total: 0, pending: 0, sent: 0, failed: 0, byType: {} };
    const total = toInt(row.total);
    calendar[dayKey].total += total;
    if (row.status === "pending" || row.status === "processing") calendar[dayKey].pending += total;
    if (row.status === "sent") calendar[dayKey].sent += total;
    if (row.status === "failed") calendar[dayKey].failed += total;
    calendar[dayKey].byType[row.notification_type] = (calendar[dayKey].byType[row.notification_type] || 0) + total;
  }
  return calendar;
}

async function reorganizeOwnerWorkspaceAgenda(ownerUserId: string) {
  const status = await getOwnerWorkspaceQueueStatus(ownerUserId);
  return { success: true, scheduled: status.breakdown?.reduce((sum: number, row: any) => sum + toInt(row.count), 0) || 0, reusedExistingAgenda: true };
}

async function processOwnerWorkspaceQueue(ownerUserId: string) {
  const status = await getOwnerWorkspaceQueueStatus(ownerUserId);
  return { success: true, total: status.pendingNow || 0, processed: 0, failed: 0, requeued: 0, deferredToStatefulWorker: true };
}

async function getOwnerWorkspaceQueueStatus(ownerUserId: string) {
  const [breakdown, pendingNow, next] = await Promise.all([
    getPool().query(
      `SELECT status, notification_type, COUNT(*)::int AS count
       FROM owner_scheduled_notifications
       WHERE owner_user_id = $1
       GROUP BY status, notification_type
       ORDER BY status, notification_type`,
      [ownerUserId],
    ),
    getPool().query(
      `SELECT COUNT(*)::int AS count
       FROM owner_scheduled_notifications
       WHERE owner_user_id = $1 AND status = 'pending' AND scheduled_for <= NOW()`,
      [ownerUserId],
    ),
    getPool().query(
      `SELECT id, notification_type, recipient_name, scheduled_for, status
       FROM owner_scheduled_notifications
       WHERE owner_user_id = $1 AND status = 'pending'
       ORDER BY scheduled_for ASC
       LIMIT 10`,
      [ownerUserId],
    ),
  ]);
  return { breakdown: breakdown.rows, pendingNow: toInt(pendingNow.rows[0]?.count), nextInQueue: next.rows };
}

function mapOwnerBroadcastStatus(status: string) {
  if (status === "pending") return "scheduled";
  if (status === "running") return "sending";
  if (status === "error") return "cancelled";
  return status || "scheduled";
}

async function listOwnerWorkspaceBroadcasts(ownerUserId: string) {
  const [campaignsResult, archivesResult] = await Promise.all([
    getPool().query(
      `SELECT *
       FROM broadcast_campaigns
       WHERE user_id = $1
       ORDER BY created_at DESC
       LIMIT 100`,
      [ownerUserId],
    ),
    getPool().query(
      `SELECT *
       FROM owner_broadcast_archives
       WHERE owner_user_id = $1
       ORDER BY created_at DESC
       LIMIT 100`,
      [ownerUserId],
    ),
  ]);
  const campaigns = campaignsResult.rows.map((row) => ({
    id: row.id,
    name: row.name,
    messageTemplate: row.message_template,
    targetType: row.metadata_json?.targetType || "all",
    targetFilter: row.metadata_json || {},
    aiVariation: row.use_ai === true,
    antibotEnabled: true,
    status: mapOwnerBroadcastStatus(row.status),
    scheduledAt: row.scheduled_at,
    totalRecipients: toInt(row.total_contacts),
    sentCount: toInt(row.sent_count),
    failedCount: toInt(row.failed_count),
    createdAt: row.created_at,
  }));
  const archives = archivesResult.rows.map((row) => mapBroadcast(row));
  return [...campaigns, ...archives].sort((left, right) => {
    return new Date(right.createdAt || 0).getTime() - new Date(left.createdAt || 0).getTime();
  });
}

